window.__SUPERCODE_LANG_PACKS__['vi'] = {"index":{"metaTitle":"Code Editor: SuperCode IDE — IDE Python, C, C++, Java, JS, SQL & PHP Offline cho Android","metaDesc":"Trình soạn thảo code offline chuẩn native và IDE full-stack cho Android. Mở file dung lượng GB, chạy Python, C17, C++20, Java 17, JavaScript, Lua, Shell, SQL và web PHP/WASM cục bộ cùng Git trực quan và SFTP.","hero_tag":"Trình soạn thảo Code Offline Native &amp; IDE Full-Stack","hero_h1":"<span class=\"text-gradient\">Trình soạn thảo Code</span> native &amp; IDE full-stack cho Android.","hero_desc":"Tối ưu cho kỹ sư phần mềm, sinh viên CNTT và đội ngũ DevOps trên Android. Trải nghiệm <strong>gợi ý code thông minh theo AST</strong>, <strong>phân trang file dung lượng GB</strong>, biên dịch và chạy offline <strong>Python, C17, C++20, Java 17, JS, SQL, PHP, Lua &amp; Shell</strong>, cùng <strong>Git</strong> trực quan và <strong>SFTP/FTPS</strong>.","table_h2":"So sánh SuperCode trên Android","snippet_p":"<strong>SuperCode IDE</strong> là trình soạn thảo code offline native và môi trường phát triển full-stack cho Android. Ứng dụng tích hợp gợi ý code theo AST, phân trang file cỡ GB, hơn 30 bộ định dạng code, trình biên dịch và runtime offline cho Python, C17, C++20, Java 17, JavaScript, SQL, PHP, HTML/CSS/WASM, Lua, Shell cùng Git trực quan và SFTP/FTPS.","table_caption":"BẢNG SO SÁNH MÔI TRƯỜNG LẬP TRÌNH DI ĐỘNG ANDROID","faq_lead":"Giải đáp trực tiếp về trình biên dịch offline, xử lý file lớn, ngôn ngữ hỗ trợ và quy trình Git/SFTP.","cta_h2":"Một ứng dụng Native. Mười bốn không gian làm việc kỹ thuật trong túi bạn.","cta_desc":"Tải SuperCode IDE trên Google Play hoặc khởi chạy hành trình hướng dẫn tương tác 13 bước ngay trên thiết bị Android của bạn.","th_0":"Tính năng","th_1":"SuperCode IDE","th_2":"IDE trình duyệt Cloud","th_3":"App đơn ngôn ngữ","th_4":"Trình sửa văn bản cơ bản","tr1_c0":"Ngôn ngữ Offline","tr1_c1":"Python, C17, C++20, Java 17, JS, SQL, PHP, Web/WASM, Lua &amp; Shell","tr1_c2":"Cần kết nối mạng liên tục","tr1_c3":"Chỉ 1 ngôn ngữ mỗi app","tr1_c4":"Không hỗ trợ","tr2_c0":"Trình soạn thảo thông minh","tr2_c1":"Gợi ý AST + Tô màu kép + 30+ bộ Format + Error Radar","tr2_c2":"Phụ thuộc độ trễ mạng","tr2_c3":"Tô màu cú pháp cơ bản","tr2_c4":"Văn bản thuần / tô màu regex","tr3_c0":"File lớn &amp; Thay thế","tr3_c1":"Phân trang GB 10MB + Thay thế Regex luồng toàn cục + 34 bảng mã","tr3_c2":"Tràn RAM sập tab trình duyệt","tr3_c3":"Lỗi khi file vượt vài MB","tr3_c4":"Đơ cứng với file log lớn","tr4_c0":"Web &amp; Database Studio","tr4_c1":"HTTP thực + PHP Offline + PDO SQLite + DevTools REPL + Xem .db","tr4_c2":"Cần thuê container trả phí","tr4_c3":"Phải cài nhiều app riêng lẻ","tr4_c4":"Chỉ xem HTML tĩnh","tr5_c0":"Git &amp; DevOps từ xa","tr5_c1":"Git Time Machine trực quan + UI gộp xung đột + Lưu nguyên tử SFTP/FTPS AES-256","tr5_c2":"Chỉ dùng workspace trên cloud","tr5_c3":"Không tích hợp Git hay SFTP","tr5_c4":"Cần phần mềm bên ngoài","faq1_q":"SuperCode IDE chạy offline được những ngôn ngữ lập trình nào trên Android?","faq1_a":"SuperCode chạy trực tiếp trên Android các ngôn ngữ Python (3.11 &amp; bản khoa học 3.12), C (GNU C17), C++ (GNU C++20), Java 17, JavaScript (ES2024), SQL, PHP, HTML5/CSS3/WebAssembly, Lua 5.4 và script Linux Shell, kèm tùy chọn cloud hỗ trợ Kotlin, MySQL 8.0 và các framework server nặng.","faq2_q":"SuperCode có mở được file log hay SQL dump dung lượng hàng gigabyte mà không bị đơ không?","faq2_a":"Có. Các file lớn hơn 30 MB sẽ tự động kích hoạt trình phân trang luồng cỡ GB, chia nhỏ file hàng trăm MB hoặc nhiều GB thành các phân đoạn 10 triệu ký tự trên ổ đĩa, cho phép nhảy trang tức thì, nhận diện 34 bảng mã và thay thế Regex luồng toàn cục.","faq3_q":"C và C++, hoặc SQL và Web/PHP có phải là các môi trường tách biệt chuyên dụng không?","faq3_a":"Đúng. C17 và C++20 đều có chuẩn biên dịch, thư viện header và template riêng; SQL sở hữu console 9 chế độ cùng trình kiểm tra nhị phân .db; còn Web Studio chạy server xem trước cục bộ thực thụ với HTTP + PHP + PDO SQLite + WebAssembly và DevTools tích hợp sẵn.","faq4_q":"SuperCode có tích hợp sẵn trình khách Git và trình chỉnh sửa từ xa SFTP/FTPS không?","faq4_a":"Có. Ứng dụng tích hợp trình khách Git trực quan độc lập (Clone bằng PAT, quản lý nhánh, Commit Time Machine xem diff hợp nhất và trình giải quyết xung đột Merge) cùng không gian làm việc SFTP, FTPS (TLS 1.3) và FTP mã hóa AES-256 với cơ chế lưu nguyên tử 3 pha.","faq5_q":"SuperCode có được tối ưu cho cả điện thoại và máy tính bảng Android không?","faq5_a":"Có. Trên điện thoại, thanh công cụ nằm trong tầm ngón tay cái kèm menu vuốt cạnh phải và console chia màn hình tự thu gọn; trên thiết bị gập và tablet, thanh công cụ neo dọc và terminal mở dạng trạm làm việc song song 55% / 45%.","wb_eyebrow":"Phoenix Global Studios · 14 Module kỹ thuật chuyên dụng","sec1_eyebrow":"13 KHÔNG GIAN LÀM VIỆC KỸ THUẬT CHUYÊN BIỆT","sec1_title":"Mọi ngôn ngữ, cơ sở dữ liệu &amp; công cụ từ xa — Chuyên biệt &amp; Native","sec1_lead":"Khám phá toàn bộ 13 module chuyên dụng được thiết kế gói gọn trong một ứng dụng Android gọn nhẹ chỉ 40.2 MB.","bc1_title":"Trình soạn thảo Code thông minh, Gợi ý AST &amp; Error Radar","bc1_desc":"Gợi ý theo ngữ cảnh khi gõ ., -&gt;, :: và :, tô màu cú pháp hai chế độ, hơn 30 bộ định dạng offline, Error Radar nhảy dòng trực tiếp, thống kê toàn diện, xuất PDF A4 và 29 thao tác thanh công cụ thích ứng.","bc1_foot":"Gợi ý AST · 30+ Bộ Format · 8 Giao diện","bc2_title":"Trình xem file cỡ GB &amp; Thay thế luồng toàn cục","bc2_desc":"Mở file log hay SQL dump hàng trăm MB hoặc nhiều GB mượt mà ở 120Hz nhờ phân trang ổ đĩa 10MB, chạy thay thế regex luồng toàn cục và giải mã chính xác 34 bảng mã ký tự.","bc2_foot":"Phân trang GB · Thay thế luồng · 34 Bảng mã","bc3_title":"Trình biên dịch GNU C17 Offline chuyên dụng","bc3_desc":"Bộ công cụ chuẩn GNU C17 thuần túy hỗ trợ &lt;math.h&gt;, liên kết đa file .c/.h không cần cấu hình, mẫu con trỏ/struct sẵn có và nhập liệu scanf/fgets tương tác trực tiếp.","bc3_foot":"GNU C17 · Đa file .c/.h · Stdin trực tiếp","bc4_title":"IDE Python 3.11 / 3.12 &amp; Trình quản lý PIP trực quan","bc4_desc":"Chạy dự án Python đa file offline, tự động cài gói từ PyPI, requirements.txt hoặc file .whl cục bộ, và xuất biểu đồ NumPy/Pandas/Matplotlib trực tiếp vào thư mục của bạn.","bc4_foot":"Python 3.11/3.12 · Auto-PIP · Khoa học dữ liệu","bc5_title":"Trình biên dịch C++20 hiện đại &amp; IDE thi đấu STL","bc5_desc":"Biên dịch offline đa file C++20 STL, template, con trỏ thông minh và thuật toán lập trình thi đấu với bộ nhớ đệm hash tăng dần cùng console chia đôi màn hình cho std::cin.","bc5_foot":"C++20 · Thư viện STL · Console chia đôi","bc6_title":"IDE Java 17 Offline, OOP đa lớp &amp; JDBC","bc6_desc":"Xây dựng record, sealed class, stream và dự án OOP đa package chuẩn Java 17 offline với bộ đệm bytecode 0ms, driver SQLite JDBC tích hợp và hỗ trợ file .jar tùy chỉnh.","bc6_foot":"Java 17 · Cache tức thì · JDBC tích hợp","bc7_title":"Trình chạy JavaScript (ES2024) độc lập &amp; Module","bc7_desc":"Thực thi async/await chuẩn ES2024, ESM import/export và module CommonJS trong luồng worker tách biệt khỏi UI với cơ chế chống lặp vô hạn &lt;1ms và đóng gói Node.js trên Cloud.","bc7_foot":"ES2024 · ESM + CommonJS · Worker Sandbox","bc8_title":"Web Full-Stack, PHP Cục bộ &amp; WASM Live Studio","bc8_desc":"Server xem trước HTTP cục bộ thực thụ hỗ trợ HTML5, CSS3, ES Modules, WebAssembly (.wasm), PHP offline + cơ sở dữ liệu PDO SQLite, khung nhìn Mobile/Tablet/Desktop, DevTools JS REPL và xem trước trực tiếp SFTP.","bc8_foot":"HTML/CSS/JS · WASM · PHP Offline · DevTools","bc9_title":"IDE SQL Offline &amp; Trình khám phá Database trực quan","bc9_desc":"Thực thi SQL hiện đại với window function, CTE, đường dẫn JSONB và tìm kiếm toàn văn qua 9 chế độ hiển thị, kiểm tra file .db/.sqlite chỉ với 1 chạm, nhập CSV/JSON hoặc chạy Cloud MySQL 8.0.","bc9_foot":"SQL Offline · Kiểm tra .db · CSV / JSON","bc10_title":"IDE kịch bản Lua 5.4 Offline &amp; Logic Game","bc10_desc":"Thực thi Lua 5.4.7 chuẩn native dưới một mili-giây với coroutine, metatable, toán tử bit, require() đa file và console io.read() tương tác.","bc10_foot":"Lua 5.4.7 · Coroutine · Đa file","bc11_title":"Trình chạy Linux Shell (.sh) &amp; Kotlin Studio","bc11_desc":"Chạy pipeline Linux Shell chuẩn native trên Android (grep, awk, sed, sort, find) đồng bộ với thư mục dự án, cùng Ubuntu Bash 5.2 và biên dịch Kotlin trên Cloud.","bc11_foot":"Shell Native · Bash 5.2 · Kotlin","bc12_title":"Trình khách Git trực quan, Time Machine &amp; Gộp xung đột","bc12_desc":"Clone repo HTTPS bằng token PAT, tự động stash khi Pull, xem Diff hợp nhất tô màu qua 120 commit, chuyển nhánh và giải quyết xung đột merge song song hai bên.","bc12_foot":"Git Clone · Time Machine Diff · UI Gộp xung đột","bc13_title":"Không gian làm việc Server từ xa SFTP, FTPS (TLS 1.3) &amp; FTP","bc13_desc":"Kết nối qua mật khẩu hoặc khóa riêng OpenSSH/PEM/Ed25519 lưu trong két sắt AES-256 của Android KeyStore. Sửa tab trên server với cơ chế lưu nguyên tử 3 pha (không lỗi file 0-byte) và truyền 4 luồng hàng đợi hỗ trợ nối tiếp theo byte.","bc13_foot":"SFTP (22) · FTPS TLS 1.3 · Két khóa SSH · Lưu nguyên tử từ xa","sec2_eyebrow":"THIẾT KẾ CHO TỐC ĐỘ THAO TÁC MỘT TAY","sec2_title":"Độ chính xác xúc giác từ thanh công cụ đến Terminal chia màn hình","sec2_lead":"Mọi cử chỉ, phím bấm và bảng điều khiển tự động thích ứng với điện thoại, máy gập và tablet xoay ngang.","keystrip_left":"BÀN PHÍM KÝ HIỆU 21 PHÍM TÁC VỤ KÉP (6 HỒ SƠ)","keystrip_right":"CHẠM · VUỐT LÊN KÍNH LÚP · KHÓA CON TRỎ","craft_foot":"8 Giao diện Studio + Ngày/Đêm tự động · 32 Ngôn ngữ UI · Console hai khung xoay ngang","pil1_sub":"5 CHẾ ĐỘ THANH CÔNG CỤ THEO NGỮ CẢNH","pil1_title":"Thanh công cụ thích ứng, Vuốt cạnh phải &amp; 5 ô thao tác nhanh","pil1_desc":"Tự động chuyển đổi giữa chế độ Code, Văn bản thuần, Chọn vùng, Tìm kiếm và File siêu lớn; neo dọc trên tablet và kết hợp menu vuốt cạnh phải 120Hz.","pil2_sub":"PHÂN TRANG 10MB · 34 BẢNG MÃ","pil2_title":"Phân trang file lớn tức thì &amp; Thay thế Regex luồng","pil2_desc":"Mở file log server khổng lồ và bản dump database mượt mà ở 120Hz, thay thế regex toàn cục theo luồng qua các phân đoạn ổ đĩa và sao chép tới 15 MB qua clipboard ảo.","pil3_sub":"DIFF TRỰC QUAN · KÉT SẮT AES-256","pil3_title":"Quản lý phiên bản chuẩn Production &amp; Đồng bộ từ xa nguyên tử","pil3_desc":"Chuyển mượt mà từ biên dịch cục bộ offline sang giải quyết xung đột Git trực quan và triển khai server SFTP/FTPS với cơ chế lưu nguyên tử 3 pha."},"code_editor":{"metaTitle":"Trình soạn thảo Code cho Android — Gợi ý AST, 30+ Bộ Format & Error Radar | SuperCode","metaDesc":"Trình soạn thảo code native chuyên nghiệp cho Android với gợi ý code thông minh AST offline, tô màu cú pháp kép trên 40+ định dạng file, format một chạm, Error Radar thời gian thực, thống kê từ/byte, thanh công cụ 29 nút thích ứng và 8 giao diện studio.","hero_tag":"TRÌNH SOẠN THẢO CODE THÔNG MINH &amp; TRÍ TUỆ AST","hero_h1":"<span class=\"text-gradient\">Trình soạn thảo Code thông minh AST</span> mượt mà chuẩn Native cho Android.","hero_desc":"Vượt xa những ô nhập văn bản di động sơ sài. SuperCode kết hợp <strong>gợi ý ngữ cảnh AST offline</strong>, <strong>tô màu cú pháp hai chế độ</strong>, <strong>hơn 30 bộ định dạng một chạm</strong>, <strong>chẩn đoán Error Radar</strong> và <strong>thanh công cụ thích ứng 29 nút</strong> tối ưu cho cảm ứng 120Hz.","table_h2":"SuperCode Editor vs. Trình sửa văn bản di động thông thường","snippet_p":"<strong>SuperCode Code Editor</strong> là trình soạn thảo mã nguồn native cho Android kết hợp gợi ý code theo ngữ cảnh AST offline, tô màu cú pháp hai chế độ cho hơn 40 loại file, định dạng offline một chạm cho hơn 30 ngôn ngữ, chẩn đoán Error Radar thời gian thực, thống kê UTF-8 chi tiết và thanh công cụ cảm ứng thích ứng 29 nút.","table_caption":"ĐÁNH GIÁ NĂNG LỰC TRÌNH SOẠN THẢO MÃ NGUỒN ANDROID","faq_lead":"Giải đáp về định dạng offline, ngôn ngữ được gợi ý code, tùy chỉnh thanh công cụ và công cụ PDF/ảnh.","cta_h2":"Trải nghiệm soạn thảo code đẳng cấp Desktop trên Android.","cta_desc":"Cài đặt SuperCode trên Google Play để tùy biến 8 giao diện studio, thanh ký hiệu 21 phím và thanh công cụ thích ứng.","th_0":"Tính năng Editor","th_1":"SuperCode Editor","th_2":"Editor bọc WebView","th_3":"App sửa text Android cơ bản","tr1_c0":"Gợi ý code thông minh","tr1_c1":"Phân giải Kiểu/Thành viên AST Offline (., -&gt;, ::, :)","tr1_c2":"Cần cài plugin hoặc cloud LSP","tr1_c3":"Không có hoặc chỉ danh sách từ cơ bản","tr2_c0":"Định dạng Code Offline","tr2_c1":"30+ loại file + HTML/JS/CSS đệ quy + Giữ thụt lề vùng chọn","tr2_c2":"Giới hạn ở JS/HTML/CSS","tr2_c3":"Không hỗ trợ","tr3_c0":"Kiểm tra lỗi cú pháp","tr3_c1":"Error Radar V2.0 trực tiếp, chạm 1 lần nhảy tới Dòng/Cột","tr3_c2":"Thường nhiễu hoặc không dùng được offline","tr3_c3":"Không có","tr4_c0":"Trải nghiệm cảm ứng","tr4_c1":"Thanh 29 nút 5 chế độ + Kính lúp vuốt 21 phím + Menu cạnh phải","tr4_c2":"Thanh dưới chật chội cố định","tr4_c3":"Chỉ dùng bàn phím hệ thống","tr5_c0":"Clipboard &amp; Xuất file","tr5_c1":"Clipboard ảo 15 MB + PDF A4 Native + Trình xem ảnh 10 định dạng","tr5_c2":"Sập app khi vượt giới hạn clipboard Android 800 KB","tr5_c3":"Chỉ chia sẻ văn bản thuần","faq1_q":"Gợi ý code thông minh và định dạng code có hoạt động 100% offline không?","faq1_a":"Có. Gợi ý code theo AST, tô màu cú pháp hai chế độ, kiểm tra lỗi Error Radar thời gian thực và hơn 30 bộ định dạng ngôn ngữ đều chạy hoàn toàn offline trên thiết bị Android mà không cần kết nối mạng.","faq2_q":"Bàn phím ký hiệu 21 phím giúp viết code nhanh hơn trên điện thoại như thế nào?","faq2_a":"Bàn phím tự động nạp 1 trong 6 hồ sơ ngôn ngữ (C/C++, Python, Java/Kotlin, JS/TS, Web, Shell/SQL), tự bọc ngoặc hoặc dấu nháy quanh vùng chọn, hỗ trợ vuốt lên gõ ký hiệu phụ kèm kính lúp phóng đại và có chế độ Khóa con trỏ giúp ẩn bàn phím hệ thống khi điều hướng.","faq3_q":"Tôi có thể sắp xếp lại thứ tự thanh công cụ dưới cùng và các nút menu nhanh không?","faq3_a":"Có. Vào Cài đặt -&gt; Tùy chỉnh Thanh công cụ &amp; Menu để kéo thả sắp xếp lại cả thanh công cụ chính lẫn 5 ô thao tác nhanh, hoặc khôi phục mặc định chỉ với một chạm.","faq4_q":"Tôi có thể xuất mã nguồn sang PDF hay xem file PDF và hình ảnh ngay trong IDE không?","faq4_a":"Có. Dùng tính năng In hoặc Lưu dạng .pdf để tạo file PDF A4 chữ đơn cách sắc nét, đồng thời xem trực tiếp file PDF dự án (thu phóng 1x–5x, nhảy trang) và 10 định dạng ảnh (gồm WEBP, HEIC, AVIF, ICO) ngay bên trong SuperCode.","wb_eyebrow":"DEMO TƯƠNG TÁC TRÍ TUỆ EDITOR","sec_cap_title":"Thiết kế từ thanh công cụ cho các dự án phần mềm thực thụ","sec_cap_lead":"Mọi tương tác nhỏ — từ nhảy qua ngoặc đóng đến định dạng giữ nguyên thụt lề vùng chọn — đều được tinh chỉnh cho tốc độ ngón cái và độ rõ nét thị giác.","f1_title":"Gợi ý Code theo ngữ cảnh AST lai","f1_desc":"Tự động kích hoạt khi gõ ., -&gt;, :: và : trên C/C++, Python, Java, Kotlin, JS/TS, HTML, CSS, PHP, Lua, Shell và SQL — phân giải kiểu cục bộ, thành viên struct/class, API STL/DOM và đoạn code mẫu offline.","f1_badge":"Toán tử: . · -&gt; · :: · :  |  10 Nhóm ngôn ngữ","f2_title":"Tô màu hai chế độ &amp; Tự nhận diện file không đuôi","f2_desc":"Tô màu tức thì các dòng đang hiển thị ở 120Hz mà vẫn giữ nguyên token định dạng bên trong (\\n, %d, {0}) và thẻ @param/TODO. Tự động nhận diện ngôn ngữ cho file chưa đặt tên qua #! Shebang và chấm điểm từ vựng.","f2_badge":"40+ Đuôi file · Nhận diện Shebang · 0 Rớt khung hình","f3_title":"30+ Bộ định dạng Offline &amp; Chú thích thông minh","f3_desc":"Làm đẹp code C/C++, Java, Kotlin, JS/TS, Python (PEP 8), JSON, CSS, PHP, SQL, Lua, Shell và HTML/Vue (định dạng đệ quy cả thẻ &lt;script&gt; và &lt;style&gt;!) mà vẫn bảo toàn thụt lề gốc của vùng chọn trong duy nhất một bước Undo.","f3_badge":"Nguyên tử 1 bước Undo · HTML/JS/CSS đệ quy","f4_title":"Error Radar V2.0 &amp; Thống kê tài liệu toàn diện","f4_desc":"Bắt lỗi thiếu ngoặc đóng, chuỗi/thẻ chưa đóng, TabError/thiếu dấu hai chấm Python và dấu phẩy JSON sai cú pháp với khả năng chạm 1 lần nhảy tới Dòng X, Cột Y — hiển thị ngay cạnh số dòng, từ, ký tự và byte UTF-8 chính xác toàn file lẫn vùng chọn.","f4_badge":"Nhảy Dòng/Cột · Byte UTF-8 Toàn file &amp; Vùng chọn","f5_title":"Thanh công cụ 29 nút 5 chế độ &amp; Menu vuốt cạnh phải","f5_desc":"Tự động thích ứng qua các chế độ Code, Văn bản thuần, Chọn vùng, Tìm kiếm và File siêu lớn; neo dọc khi xoay ngang; kết hợp menu vuốt ngón cái cạnh phải 120Hz với 5 ô thao tác nhanh giữ mở tùy chỉnh được.","f5_badge":"5 Chế độ tự động · 5 Ô nhanh · Clipboard ảo 15MB","f6_title":"Thanh ký hiệu vuốt 21 phím, 8 Giao diện &amp; Xuất PDF A4","f6_desc":"Chuyển đổi giữa 6 hồ sơ ký hiệu ngôn ngữ với thao tác chạm + vuốt lên hiện kính lúp và chế độ khóa con trỏ. Lập trình với 8 giao diện chuẩn WCAG AAA (có Ngày/Đêm tự động), Chế độ Tập trung (Zen Mode) hoặc xuất file PDF A4 sắc nét.","f6_badge":"6 Hồ sơ ký hiệu · AMOLED #000000 · Trình xem PDF/Ảnh Native","workflow_title":"Cách tùy chỉnh &amp; làm chủ không gian soạn thảo","workflow_lead":"Thiết lập luồng viết code di động cá nhân hóa ngang tầm desktop chỉ trong chưa đầy hai phút.","wf_foot_note":"Kéo ngang các tab để sắp xếp · Hot Exit tự động sao lưu các tab chưa lưu","wf1_title":"Tạo mới hoặc mở bất kỳ file mã nguồn nào","wf1_desc":"Mở nhiều tab từ bộ nhớ trong, thẻ SD/USB OTG, Git hoặc SFTP. Ngay cả file nháp chưa đặt tên cũng tự nhận diện cú pháp và gợi ý đúng phần mở rộng khi Lưu thông minh.","wf2_title":"Gõ nhanh hơn với phím tác vụ kép &amp; AST","wf2_desc":"Chạm để chèn cặp dấu phân cách hoặc bọc vùng chọn; vuốt lên trên bất kỳ phím nào để gõ toán tử phụ (===, /**/, giảm thụt lề) và kích hoạt gợi ý thành viên AST tức thì 0ms.","wf3_title":"Định dạng code &amp; kiểm tra Error Radar","wf3_desc":"Chạm nút Format để căn chỉnh thụt lề gọn gàng, sau đó chạm Count để xem tọa độ lỗi Error Radar trực tiếp cùng thống kê UTF-8 của vùng chọn và toàn tài liệu.","wf4_title":"Vuốt từ cạnh phải để mở 5 ô thao tác nhanh","wf4_desc":"Vuốt nhẹ từ cạnh phải màn hình bằng một tay để chạm liên tiếp Hoàn tác/Làm lại/Giao diện/Xuống dòng mà không bị đóng menu, bật Zen Mode hoặc xuất PDF A4."},"large_file":{"metaTitle":"Mở File Văn Bản Lớn & Log GB trên Android — Thay Thế Streaming & 34 Bảng Mã | SuperCode","metaDesc":"Mở tức thì file log, SQL dump và dữ liệu CSV hàng trăm MB đến hàng GB trên Android không giật lag. Tích hợp phân trang ổ đĩa 10MB, thay thế regex streaming toàn cục, clipboard ảo 15MB và 34 bảng mã ký tự.","hero_tag":"TRÌNH XEM FILE CỠ GB &amp; THAY THẾ STREAMING","hero_h1":"Mở Tức Thì <span class=\"text-gradient\">Log &amp; Dump Cỡ GB</span> với Thay Thế Stream Toàn Cục.","hero_desc":"Các trình soạn thảo di động thông thường dễ đơ hoặc văng khi mở file vài MB. SuperCode nạp <strong>file hàng trăm MB đến hàng GB</strong> qua phân trang ổ đĩa 10 triệu ký tự ở <strong>120Hz</strong>, chạy <strong>thay thế regex streaming</strong> trực tiếp trên ổ đĩa và giải mã an toàn <strong>34 bảng mã ký tự</strong>.","table_h2":"So Sánh Hiệu Năng Mở File Lớn &amp; Bảng Mã trên Android","snippet_p":"<strong>Trình Soạn Thảo File Lớn SuperCode</strong> giúp người dùng Android mở tức thì file văn bản, log, CSV và SQL hàng trăm MB đến hàng GB mà không bị đơ. Tích hợp phân trang ổ đĩa 10 triệu ký tự, tìm và thay thế regex streaming toàn cục, clipboard ảo 15 MB cùng khả năng tự động nhận diện 34 bảng mã không mất dữ liệu.","table_caption":"MA TRẬN ENGINE FILE VĂN BẢN LỚN &amp; BẢNG MÃ · ANDROID","faq_lead":"Giải đáp về mở file cỡ GB, thay thế regex, ổ USB và sửa lỗi font chữ CJK/bảng mã cũ.","cta_h2":"Mở File Log Khổng Lồ, Bản Dump &amp; File Mã Cũ Không Lo Văng App.","cta_desc":"Tải SuperCode IDE trên Google Play — studio xử lý code, log và văn bản cỡ GB mượt 120Hz trên Android.","th_0":"Tính năng","th_1":"Engine Siêu File SuperCode","th_2":"Trình Soạn Code Thường","th_3":"Trình Xem File Hệ Thống","tr1_c0":"File 500 MB – 2 GB+","tr1_c1":"Phân trang ổ đĩa 10MB tức thì + Nhảy trang 1..N","tr1_c2":"Văng app vì tràn RAM khi mở","tr1_c3":"Từ chối mở (&gt;2 MB–10 MB)","tr2_c0":"Tìm &amp; Thay Thế Toàn Cục","tr2_c1":"Thay thế toàn bộ Streaming ổ đĩa + Nhóm Regex $1..$99","tr2_c2":"Chỉ thay thế trên RAM, dễ tràn bộ nhớ","tr2_c3":"Chỉ đọc hoặc không hỗ trợ thay thế","tr3_c0":"Dòng Đơn Nén (Minified)","tr3_c1":"Tự động Hiển Thị Cơ Bản (&gt;4.000 ký tự) · Không đơ","tr3_c2":"Đơ giao diện khi gặp JS/JSON nén","tr3_c3":"Treo máy khi xuống dòng tự động","tr4_c0":"Sao Chép &amp; Dán Dung Lượng Lớn","tr4_c1":"Clipboard Ảo Nội Tiến Trình 15 MB (100k+ dòng)","tr4_c2":"Văng ở giới hạn ~800 KB của OS","tr4_c3":"Bị cắt xén hoặc lỗi","tr5_c0":"Bảng Mã Cũ","tr5_c1":"34 Bảng Mã (GB18030, Shift_JIS, EUC-KR, Win-125x) + Bảo vệ UTF-8","tr5_c2":"Chỉ UTF-8 (lỗi font CJK/Cyrillic)","tr5_c3":"Không có bộ chọn bảng mã","faq1_q":"Làm sao điện thoại Android có thể sửa file 1 GB mà không bị tràn RAM?","faq1_a":"Thay vì nạp toàn bộ 1 GB vào RAM, SuperCode chia luồng file thành các phân trang 10.000.000 ký tự (~10 MB) trên ổ đĩa. Chỉ trang đang xem được nạp vào khung hiển thị, còn Thay Thế Stream Toàn Cục xử lý tuần tự từng phần ngay trên đĩa.","faq2_q":"SuperCode có sửa được file văn bản tiếng Trung, Nhật, Hàn hoặc Nga bị lỗi font không?","faq2_a":"Có. Bộ dò bảng mã 5 giai đoạn nhận diện 34 bộ ký tự gồm GB18030, GBK, Big5, Shift_JIS, EUC-JP, EUC-KR, KOI8-R, Windows-1251/1252 và UTF-16 không BOM, cho phép tải lại hoặc chuyển sang UTF-8 không mất dữ liệu.","faq3_q":"Điều gì xảy ra nếu file chứa một dòng JSON hoặc JS nén dài tới 500 KB?","faq3_a":"Các dòng vượt quá 4.000 ký tự tự động chuyển sang Chế độ Hiển thị Cơ bản O(1) tốc độ cao và tắt tự động xuống dòng, giúp cuộn mượt các gói nén và dòng log mà không bị đơ.","faq4_q":"Tôi có thể mở file lớn trực tiếp từ USB hoặc thẻ nhớ SD không?","faq4_a":"Có. SuperCode hỗ trợ Bộ nhớ trong, Thẻ nhớ SD ngoài và ổ USB OTG cắm nóng trực tiếp từ Trình khám phá Không gian làm việc.","wb_eyebrow":"TRUNG TÂM ĐIỀU KHIỂN SIÊU FILE &amp; ENGINE STREAM","sec_cap_title":"Thiết Kế Chuyên Trị Log Production, Bản Dump CSDL &amp; Bảng Mã Cũ","sec_cap_lead":"Cơ chế bảo vệ bộ nhớ đa tầng giúp cuộn, tìm kiếm và lưu luôn mượt mà ngay cả với JSON một dòng khổng lồ hay log server nhiều GB.","f1_title":"Tự Động Phân Trang Ổ Đĩa 10MB Cho File Cỡ GB","f1_desc":"File vượt quá 30 MB tự động kích hoạt bộ phân trang streaming trên I/O nền — cắt các file log, CSV và bản sao lưu SQL lớn thành từng trang 10.000.000 ký tự và xử lý dòng nén &gt;4.000 ký tự không giật lag.","f1_badge":"10M Ký Tự / Trang · Mượt 120Hz · An Toàn Dòng Nén","f2_title":"Trung Tâm Siêu File &amp; Lưu Gộp Nguyên Tử","f2_desc":"Điều hướng bằng Trang trước, Trang sau hoặc nhảy thẳng Trang 1..N (tự động đẩy thay đổi ở phần hiện tại), rồi nhấn Gộp Tất Cả &amp; Lưu để ghép lại toàn bộ file GB an toàn trên ổ đĩa.","f2_badge":"Nhảy Trang [1/N] · Đẩy Trang Đã Sửa · Lưu Nguyên Tử","f3_title":"Thay Thế Stream Toàn Cục &amp; Nhóm Bắt Regex","f3_desc":"Chạy Thay Thế Stream Toàn Bộ trên mọi trang đĩa mà không cần nạp cả file vào RAM. Hỗ trợ nhóm bắt $1..$99 và ${name}, ký tự thoát \\n/\\t, tìm kiếm khóa theo vùng chọn và cầu chì giới hạn regex 1.200ms.","f3_badge":"Thay Thế Stream Tất Cả · Regex $1..$99 · Bộ Đệm 50.000+ Kết Quả","f4_title":"Siêu Clipboard Ảo 15 MB (100k+ Dòng)","f4_desc":"Clipboard gốc của Android thường lỗi ở mức ~800 KB. Clipboard ảo nội tiến trình của SuperCode giúp bạn sao chép, cắt và dán luồng tới 15 MB log hoặc lệnh SQL qua lại giữa các tab dễ dàng.","f4_badge":"Vượt Giới Hạn 800 KB OS · Dán Tới 15 MB","f5_title":"34 Bảng Mã Ký Tự &amp; Bảo Vệ Lưu Không Lỗi Dữ Liệu","f5_desc":"Tự động nhận diện 5 giai đoạn cho UTF-8/16/32, GB18030/GBK/Big5, Shift_JIS/EUC-JP, EUC-KR, KOI8-R, 11 bộ ISO-8859 và 9 trang mã Windows. Cảnh báo ký tự Unicode không ánh xạ được trước khi lưu để văn bản không bị biến thành dấu ?.","f5_badge":"34 Bảng Mã · Gỡ BOM An Toàn · LF / CRLF / CR","f6_title":"Tìm Mờ 50k File Trong Dự Án &amp; Tường Lửa Nhị Phân","f6_desc":"Tìm mọi file trên Bộ nhớ máy, Git, SD/USB OTG và SFTP với xếp hạng CamelCase/đường dẫn 7 tầng (tự động loại node_modules/.git), kết hợp kiểm tra 4 KB magic-byte chặn file nhị phân thô an toàn.","f6_badge":"50k Nút · Hỗ Trợ USB OTG · Bảo Vệ 4 KB Magic-Byte","workflow_title":"Cách Kiểm Tra &amp; Sửa Hàng Loạt File Hàng Trăm MB Đến GB","workflow_lead":"Chỉnh sửa an toàn các file log khổng lồ, file xuất CSV và file bảng mã cũ trên mọi điện thoại hoặc máy tính bảng Android.","wf_foot_note":"Hỗ Trợ Bộ Nhớ Trong, Thẻ Nhớ SD Ngoài &amp; Ổ USB OTG Cắm Nóng","wf1_title":"Mở Bất Kỳ File Log, CSV Hoặc SQL Dump Lớn Nào","wf1_desc":"Chọn file từ bộ nhớ trong hoặc ổ SD/USB OTG đã gắn. SuperCode tự động nhận diện bảng mã và nạp ngay các trang 10 triệu ký tự.","wf2_title":"Nhảy Thẳng Tới Bất Kỳ Phần Trang Nào","wf2_desc":"Chạm nút Trang trên thanh Siêu File tinh gọn 7 công cụ để nhảy tới số trang bất kỳ, bật Chế độ Văn bản hoặc vào Chế độ Zen tập trung.","wf3_title":"Tìm Kiếm Hoặc Chạy Thay Thế Stream Toàn Bộ","wf3_desc":"Thu gọn thanh tìm kiếm thành viên nang nổi khi duyệt kết quả, hoặc chạy Thay Thế Stream Toàn Bộ để biến đổi mẫu trên mọi trang đĩa.","wf4_title":"Ghi Thay Đổi Nguyên Tử Xuống Ổ Đĩa","wf4_desc":"Chạm Gộp Tất Cả &amp; Lưu để ghi toàn bộ phần đã sửa vào lại file gốc an toàn và giữ nguyên vẹn bảng mã ký tự."},"python_ide":{"metaTitle":"App Viết Code Python trên Android — Python IDE Offline, PIP, NumPy & Đa File | SuperCode","metaDesc":"App code Python offline miễn phí và Python 3.11/3.12 IDE cho Android. Chạy dự án Python đa file, cài gói PIP & .whl offline, dùng NumPy/Pandas/Matplotlib, input() tương tác và Git trực quan.","hero_tag":"APP CODE PYTHON 3.11 / 3.12 OFFLINE &amp; STUDIO PIP TRỰC QUAN","hero_h1":"Ứng Dụng <span class=\"text-gradient\">Code Python &amp; IDE Offline</span> Cho Android.","hero_desc":"Biến điện thoại hoặc máy tính bảng Android thành trạm làm việc Python độc lập. Chạy offline <strong>script Python 3.11 &amp; 3.12 đa file</strong>, cài hơn 250 thư viện qua <strong>PIP trực quan hoặc file <code>.whl</code> nội bộ</strong>, và vẽ biểu đồ <strong>NumPy, Pandas &amp; Matplotlib</strong> lưu thẳng vào thư mục dự án.","table_h2":"So Sánh SuperCode Python IDE với Các App Python Android Khác","snippet_p":"<strong>SuperCode Python IDE</strong> là ứng dụng lập trình Python 3.11 và 3.12 offline cho Android. App hỗ trợ chạy script đa file, trình quản lý gói PIP trực quan và .whl offline, xuất biểu đồ NumPy, Pandas và Matplotlib lưu đệm trên máy, console input() tương tác, định dạng PEP 8 và tích hợp Git/SFTP trực quan.","table_caption":"SO SÁNH MÔI TRƯỜNG LẬP TRÌNH PYTHON TRÊN ANDROID","faq_lead":"Giải đáp về chạy Python offline, cài thư viện pip/.whl, NumPy/Matplotlib và import đa file.","cta_h2":"Bắt Đầu Code Python Mọi Nơi — Kể Cả Khi Offline.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play để mang theo Python, PIP, NumPy và Git trong một studio Android chỉ 40.2 MB.","th_0":"Tính năng Python","th_1":"SuperCode Python IDE","th_2":"App Python Đơn Lẻ","th_3":"Trình Chạy Python Online","th_4":"Trình Giả Lập Terminal","tr1_c0":"Chạy Offline","tr1_c1":"Python 3.11 + Khoa Học 3.12 Lưu Đệm Offline","tr1_c2":"Chỉ có Python offline","tr1_c3":"Cần kết nối mạng","tr1_c4":"Cài gói thủ công qua CLI","tr2_c0":"Quản Lý Gói","tr2_c1":"Auto-PIP + requirements.txt + Giao diện .whl/.zip nội bộ","tr2_c2":"Plugin trả phí hoặc pip CLI","tr2_c3":"Gói cố định trên server","tr2_c4":"Lỗi biên dịch thủ công","tr3_c0":"Khoa Học Dữ Liệu &amp; Biểu Đồ","tr3_c1":"NumPy/Pandas/Matplotlib -&gt; Tự Lưu Vào Thư Mục","tr3_c2":"Cần plugin kho riêng","tr3_c3":"Không đồng bộ file nội bộ","tr3_c4":"Cấu hình X11/headless phức tạp","tr4_c0":"Đa Ngôn Ngữ &amp; Git","tr4_c1":"Gồm C/C++, Java, JS, SQL, PHP, Git &amp; SFTP","tr4_c2":"App chỉ hỗ trợ Python","tr4_c3":"Chỉ sandbox trình duyệt","tr4_c4":"Không có giao diện merge Git","tr5_c0":"Trình Soạn Thảo Thông Minh","tr5_c1":"Gợi Ý AST + Định Dạng PEP 8 + Radar Lỗi","tr5_c2":"Tự động hoàn thành cơ bản","tr5_c3":"Độ trễ mạng","tr5_c4":"Phải tự cấu hình Vim/Nano","faq1_q":"Tôi có thể viết và chạy code Python trên Android hoàn toàn offline không?","faq1_a":"Có. Các script Python 3.11 đa file, thư viện chuẩn, gói PIP/.whl đã cài trên máy và các thư viện Scientific Python 3.12 lưu đệm (NumPy, Pandas, Matplotlib, SciPy, scikit-learn) đều chạy 100% offline.","faq2_q":"Làm sao cài thư viện bên thứ ba như requests, bs4 hoặc file .whl offline?","faq2_a":"Mở Trình Quản Lý Gói PIP trực quan (hoặc chỉ cần chạy script để Auto-PIP tự phát hiện import còn thiếu). Bạn có thể cài từ PyPI, chạm thẻ requirements.txt được phát hiện, hoặc nhập gói .whl, .tar.gz và .zip từ bộ nhớ máy.","faq3_q":"Biểu đồ Matplotlib hoặc file tạo bởi open('data.csv', 'w') được lưu ở đâu?","faq3_a":"Mọi file ảnh, PDF, CSV hoặc JSON do script ghi ra đều được tự động đồng bộ vào thư mục dự án hiện tại và xem ngay trong trình xem ảnh hoặc trình soạn thảo tích hợp của SuperCode.","faq4_q":"SuperCode có hỗ trợ vòng lặp input() Python tương tác không?","faq4_a":"Có. Mỗi khi script gọi input(), console chia màn hình sẽ làm nổi bật thanh nhập để bạn gửi phản hồi tương tác theo thời gian thực.","wb_eyebrow":"BÀN LÀM VIỆC PYTHON TƯƠNG TÁC &amp; KHOA HỌC DỮ LIỆU","sec_cap_title":"Thực Thi Python 3 Tầng Từ Script Thuần Tới Khoa Học Dữ Liệu","sec_cap_lead":"Mọi quy trình — từ bài tập CS nhập môn đến vẽ biểu đồ khoa học và thu thập dữ liệu web — đều chạy mượt mà không cần thao tác terminal rườm rà.","f1_title":"Python 3.11 Đa File Offline &amp; Điều Hướng Điểm Vào Thông Minh","f1_desc":"Chạy dự án đa module gồm các file .py, .json, .csv, .yaml và .toml 100% offline. Nhấn Chạy trong một module phụ sẽ tự động tìm và thực thi script chính của dự án.","f1_badge":"Import Đa File · Phủ Tab Chưa Lưu · Đồng Bộ File","f2_title":"NumPy, Pandas &amp; Matplotlib Lưu Đệm Trên Máy","f2_desc":"Import numpy, scipy, pandas, matplotlib hoặc scikit-learn sẽ kích hoạt runtime khoa học trên thiết bị — lưu đệm gói wheel tại chỗ để phân tích dữ liệu và xuất biểu đồ plt.savefig() chạy offline.","f2_badge":"NumPy · Pandas · Matplotlib · Tự Lưu PNG/SVG/PDF","f3_title":"Quản Lý PIP Trực Quan, Auto-PIP &amp; Nhập .whl Offline","f3_desc":"Thiếu thư viện như bs4 hay yaml? Auto-PIP tự ánh xạ tên (bs4 -&gt; beautifulsoup4), cài từ PyPI và chạy lại script tự động — hoặc cài hàng loạt requirements.txt và file .whl/.zip nội bộ offline.","f3_badge":"Auto-PIP · requirements.txt · Trình Nhập .whl Offline","f4_title":"input() Tương Tác Thực &amp; Console Chia Đôi Tùy Chỉnh","f4_desc":"Hỗ trợ nhiều lời nhắc input() nối tiếp theo thời gian thực. Console gắn gọn dưới code (tự thu gọn khi gõ) hoặc song song 55%/45% ở chế độ ngang trên máy tính bảng.","f4_badge":"Stdin Trực Tiếp · ANSI TrueColor · Thu Phóng 7sp–26sp","f5_title":"Định Dạng PEP 8, Gợi Ý AST &amp; Radar Bắt Lỗi","f5_desc":"Viết code Python chuẩn với thanh 21 phím ký tự Python, gợi ý thành phần AST offline, căn lề chuẩn PEP 8 và phát hiện lỗi TabError / thiếu dấu hai chấm ngay trước khi nhấn Chạy.","f5_badge":"Tự Định Dạng PEP 8 · Chặn TabError · 8 Mẫu Khởi Đầu","f6_title":"Cụm Cloud Tùy Chọn Cho PyTorch, TensorFlow &amp; OpenCV","f6_desc":"Cần framework deep learning nặng (torch, tensorflow, keras, cv2) hoặc chạy # @cloud? SuperCode đóng gói các module nội bộ của bạn và trả về traceback khớp 1:1 theo số dòng trong trình soạn thảo.","f6_badge":"PyTorch · TensorFlow · OpenCV · Traceback Khớp 1:1","workflow_title":"Cách Code &amp; Quản Lý Gói Python Trong SuperCode","workflow_lead":"Từ thư mục trống thành dự án Python &amp; Matplotlib đa file chỉ với bốn chạm.","wf_foot_note":"Giới Hạn CPU 120s · Chặn Tràn Output 250KB · Quản Lý Gói Bền Vững Trên Đĩa","wf1_title":"Tạo Script Mới Hoặc Tải Mẫu Python Có Sẵn","wf1_desc":"Bắt đầu từ đầu với thanh 21 phím ký tự Python hoặc chọn một trong 8 mẫu Python dựng sẵn từ thư viện Ví Dụ Code.","wf2_title":"Cài Thư Viện PyPI Hoặc File Lưu Trữ .whl Offline","wf2_desc":"Chạm requirements.txt để cài hàng loạt một chạm, chọn thẻ gói phổ biến (requests, rich, bs4, flask) hoặc nhập gói .whl từ thư mục Tải xuống cho lớp học offline.","wf3_title":"Chạy Offline &amp; Tương Tác Qua input() Trực Tiếp","wf3_desc":"Xem ngay kết quả, mã thoát, thời gian tính bằng mili-giây và mức thay đổi bộ nhớ trên console chia màn hình trong khi nhập phản hồi trực tiếp cho input().","wf4_title":"Xem Biểu Đồ, File CSV &amp; JSON Được Tạo Ra","wf4_desc":"Mọi file ghi qua open() hoặc plt.savefig('plot.png') tự động đồng bộ thẳng vào thư mục dự án và mở được ngay bằng trình xem Ảnh hoặc PDF độ phân giải cao tích hợp trong SuperCode."},"c_compiler":{"metaTitle":"Ứng dụng Lập trình C & Trình biên dịch C Offline cho Android — GNU C17, Con trỏ & Đa tệp | SuperCode","metaDesc":"Trình biên dịch C17 và ứng dụng lập trình C offline chuyên biệt cho Android. Biên dịch dự án đa tệp .c/.h và CMake/Makefile không cần mạng, kiểm thử con trỏ và struct, nhập liệu trực tiếp scanf/fgets qua stdin và hỗ trợ header POSIX.","hero_tag":"TRÌNH BIÊN DỊCH GNU C17 OFFLINE CHUYÊN BIỆT","hero_h1":"<span class=\"text-gradient\">Trình biên dịch C17 Offline</span> Thuần túy cho Lập trình Hệ thống &amp; Học phần CS.","hero_desc":"Thiết kế riêng cho ngôn ngữ C — tách biệt hoàn toàn khỏi gánh nặng runtime của C++. Biên dịch chương trình <strong>GNU C17 (<code>-std=gnu17</code>)</strong> offline với <strong>liên kết đa tệp <code>.c/.h</code></strong> tự động, <strong><code>&lt;math.h&gt;</code></strong>, <strong>nhập liệu trực tiếp <code>scanf</code> / <code>fgets</code></strong> và đo lường hiệu năng theo micro giây.","table_h2":"Trình biên dịch SuperCode C17 so với Ứng dụng Di động Truyền thống","snippet_p":"<strong>SuperCode C Compiler</strong> là môi trường phát triển GNU C17 offline chuyên biệt cho Android. Công cụ cung cấp khả năng biên dịch C17 thuần túy kèm liên kết thư viện toán học, dựng dự án đa tệp .c và .h tự động không cần Makefile, nhập liệu console scanf/fgets trực tiếp, đồng bộ tệp I/O workspace và gợi ý AST cho struct.","table_caption":"SO SÁNH TRÌNH BIÊN DỊCH LẬP TRÌNH C TRÊN ANDROID","faq_lead":"Giải đáp về biên dịch C17 offline, header đa tệp, &lt;math.h&gt; và nhập liệu scanf trên Android.","cta_h2":"Làm chủ Lập trình C Mọi lúc Mọi nơi trên Android.","cta_desc":"Cài đặt SuperCode IDE trên Google Play để sở hữu trình biên dịch GNU C17 offline chuyên biệt, mẫu con trỏ và workspace đa tệp.","th_0":"Tính năng C","th_1":"SuperCode C17 Studio","th_2":"App C/C++ Gộp Chung Cơ bản","th_3":"Trình biên dịch C Online","th_4":"Thiết lập Terminal CLI","tr1_c0":"Chuẩn C &amp; Liên kết","tr1_c1":"GNU C17 chuyên biệt (-std=gnu17) + -lm","tr1_c2":"Ép biên dịch tệp .c bằng C++","tr1_c3":"Phụ thuộc máy chủ","tr1_c4":"Nhập cờ gcc thủ công","tr2_c0":"Đa tệp .c / .h","tr2_c1":"Tự động nhận diện không cần cấu hình + Bộ nhớ đệm gia tăng","tr2_c2":"Chỉ chạy đơn tệp main.c","tr2_c3":"Tải lên thủ công từng tệp","tr2_c4":"Yêu cầu Makefile","tr3_c0":"Nhập liệu Tương tác","tr3_c1":"Truyền trực tiếp scanf / fgets + Điều khiển [EOF]","tr3_c2":"Chỉ có hộp văn bản trước khi chạy","tr3_c3":"Chỉ hỗ trợ stdin theo lô","tr3_c4":"Có hỗ trợ","tr4_c0":"Bảo vệ Vòng lặp &amp; Tràn xuất","tr4_c1":"Bộ giám sát CPU 15 giây + Ngắt mạch đầu ra 250K","tr4_c2":"Treo ứng dụng khi gặp while(1)","tr4_c3":"Lỗi hết thời gian chờ máy chủ","tr4_c4":"Nhấn Ctrl+C thủ công","tr5_c0":"Trình soạn thảo &amp; Công cụ Git","tr5_c1":"Gợi ý AST -&gt;/. + Định dạng C + Git Trực quan","tr5_c2":"Văn bản thuần túy","tr5_c3":"Ô nhập liệu trình duyệt","tr5_c4":"Không có giao diện cảm ứng","faq1_q":"Trình biên dịch C trong SuperCode có tách biệt khỏi C++ không?","faq1_a":"Có. Khi mở tệp .c, ứng dụng sẽ kích hoạt console GNU C17 (-std=gnu17) chuyên biệt và liên kết thư viện chuẩn C thuần túy, thay vì biên dịch mã C như mã C++.","faq2_q":"Tôi có cần viết Makefile để biên dịch nhiều tệp .c và .h không?","faq2_a":"Không. SuperCode tự động quét các header #include \"...\" và tệp .c đi kèm trong workspace cũng như các tab đang mở, biên dịch gia tăng các tệp đã sửa và tự động liên kết &lt;math.h&gt; (-lm).","faq3_q":"scanf() và fgets() có hoạt động tương tác trực tiếp trên Android không?","faq3_a":"Có. Terminal chia đôi màn hình sẽ tạm dừng thực thi mỗi khi chương trình C đọc từ stdin, cho phép bạn nhập nhiều dòng dữ liệu trực tiếp và gửi EOF khi xác nhận dòng trống.","faq4_q":"Nếu mã C của tôi dùng header POSIX của Linux như &lt;pthread.h&gt; hay &lt;sys/socket.h&gt; thì sao?","faq4_a":"SuperCode tự động phát hiện các header đặc thù hệ điều hành/POSIX và biên dịch mượt mà dự án đa tệp trên chuỗi công cụ đám mây POSIX, đồng thời giữ nguyên tên tệp và số dòng chẩn đoán cục bộ chính xác.","wb_eyebrow":"MÔI TRƯỜNG BIÊN DỊCH GNU C17 CHUYÊN BIỆT","sec_cap_title":"Vì sao Kiến trúc C17 Chuyên biệt Quan trọng với Lập trình viên C","sec_cap_lead":"Ngữ nghĩa C17 chuẩn xác, quản lý header chặt chẽ và không rào cản Makefile cho bài thực hành đại học, tạo mẫu nhúng và thuật toán.","f1_title":"Chuẩn GNU C17 Thuần túy &amp; &lt;math.h&gt; Sẵn sàng Ngay","f1_desc":"Biên dịch nghiêm ngặt theo chuẩn -std=gnu17 với thư viện chuẩn C thuần túy và thư viện toán học (-lm), không bị biến dạng tên kiểu C++ hay phình runtime — lý tưởng cho môn học ANSI/ISO C và nền tảng hệ thống.","f1_badge":"-std=gnu17 &middot; &lt;stdio.h&gt; &middot; &lt;stdlib.h&gt; &middot; &lt;math.h&gt;","f2_title":"Liên kết Đa tệp .c / .h Không Cấu hình &amp; Bộ nhớ đệm Hash","f2_desc":"Tự động tìm kiếm các header #include \"...\" và tệp .c liên quan trong thư mục và tab đang mở — không cần Makefile. Bộ nhớ đệm hash gia tăng bỏ qua biên dịch lại các đơn vị .c không thay đổi.","f2_badge":"Tự nhận diện .c/.h &middot; Điều phối Header -&gt; main.c","f3_title":"Console scanf / fgets / getchar Tương tác Thực thụ","f3_desc":"Kiểm thử chương trình C tương tác tự nhiên: terminal nổi bật khi scanf hoặc fgets chờ dữ liệu, và gửi một dòng trống sẽ phát tín hiệu [EOF] để thoát gọn vòng lặp while(scanf(...) != EOF).","f3_badge":"Stdin Trực tiếp &middot; Tín hiệu [EOF] &middot; Thống kê Micro giây + KB","f4_title":"Đồng bộ Tệp I/O Workspace fopen / fwrite","f4_desc":"Tệp nhị phân và văn bản ghi qua fopen(), fprintf() và fwrite() được đồng bộ thẳng vào thư mục dự án kèm tự động làm mới Explorer để bạn kiểm tra tệp đầu ra ngay lập tức.","f4_badge":"Tệp I/O Thực &middot; Tự đồng bộ Cây Workspace","f5_title":"Ngắt mạch Vòng lặp Vô hạn &amp; Chẩn đoán Con trỏ","f5_desc":"Vô tình gặp vòng lặp while(1) hay printf chạy mất kiểm soát? Bộ giám sát CPU thông minh 15 giây và bộ chặn tràn 250.000 ký tự sẽ dừng tiến trình an toàn mà không làm đơ máy.","f5_badge":"Giám sát 15s &middot; Ngắt tràn 250K &middot; Chẩn đoán Theo dòng","f6_title":"6 Mẫu C Tích hợp Sẵn &amp; Dự phòng Đám mây POSIX","f6_desc":"Khởi đầu nhanh với 6 ví dụ C chọn lọc (Con trỏ &amp; Bộ nhớ, Struct, Phép toán Bit, Sóng Sin, Echo Stdin), kèm biên dịch C đám mây POSIX tự động (&lt;pthread.h&gt;, &lt;sys/socket.h&gt;, fork) khi cần.","f6_badge":"6 Mẫu C &middot; Trình định dạng C &middot; Hỗ trợ Đám mây POSIX","workflow_title":"Cách Dựng &amp; Gỡ lỗi Chương trình C Đa tệp trên Android","workflow_lead":"Viết bài tập đơn tệp hoặc dự án C đa mô-đun mà không cần cấu hình kịch bản dựng.","wf_foot_note":"Tải Toolchain Offline Một Lần &middot; Bộ nhớ đệm Dựng Gia tăng Từng Tệp","wf1_title":"Tạo Tệp Nguồn .c &amp; Tệp Header .h","wf1_desc":"Dùng thanh ký tự C/C++ 21 phím (-&gt;, *, &amp;, {}, ;, #include) và gợi ý thành viên struct theo AST để viết mã C17 mô-đun hóa.","wf2_title":"Kiểm tra Chỉ thị &amp; Định dạng Thụt lề Offline","wf2_desc":"Error Radar bắt lỗi #include sai cú pháp và thiếu ngoặc ngay lập tức; chạm Định dạng để căn chỉnh khối K&amp;R/Allman và macro cột 0.","wf3_title":"Biên dịch &amp; Liên kết Offline từ Mọi Tab Dự án","wf3_desc":"Ngay cả khi con trỏ đang ở trong utils.h, chạm Chạy sẽ tự động tìm main.c, biên dịch các đơn vị đã sửa, liên kết -lm và khởi chạy tệp nhị phân.","wf4_title":"Nhập Dữ liệu scanf Trực tiếp &amp; Kiểm tra Tệp Đầu ra","wf4_desc":"Nhập giá trị kiểm thử tương tác ngay trong terminal neo dưới hoặc chia đôi màn hình và xem mã thoát, thời gian chạy (ms), mức dùng bộ nhớ cùng các tệp đã tạo."},"cpp_ide":{"metaTitle":"C++ IDE & Ứng dụng Lập trình C++20 Offline cho Android — STL, 21 Mẫu & cin Nhanh | SuperCode","metaDesc":"Biên dịch và chạy C++20 hiện đại offline trên Android. Đầy đủ container và ranges của STL, 21 mẫu dự án C++ CMake đa tệp, gợi ý AST std::, console std::cin tỷ lệ 55:45 cho lập trình thi đấu và Git Trực quan.","hero_tag":"STUDIO C++20 &amp; STL OFFLINE HIỆN ĐẠI","hero_h1":"<span class=\"text-gradient\">IDE C++20 &amp; STL Offline</span> Hiện đại cho Thuật toán và OOP.","hero_desc":"Từ thuật toán đồ thị Olympiad và LeetCode đến kiến trúc hướng đối tượng đa lớp: dựng và chạy <strong>GNU C++20 (<code>-std=gnu++2a</code>)</strong> offline với <strong>đầy đủ STL</strong>, <strong>gợi ý AST <code>std::</code></strong> và <strong>console <code>std::cin</code> chia đôi màn hình</strong> siêu nhạy.","table_h2":"SuperCode C++20 IDE so với Các Ứng dụng C++ Di động Khác","snippet_p":"<strong>SuperCode C++ IDE</strong> là trình biên dịch và studio phát triển GNU C++20 offline thuần gốc cho Android. Ứng dụng kết hợp hỗ trợ đầy đủ container và thuật toán STL, biên dịch đa tệp .cpp/.hpp không cần cấu hình với bộ nhớ đệm gia tăng, tự động hoàn thành AST std:: offline, terminal chia đôi màn hình std::cin trực tiếp và Git trực quan tích hợp.","table_caption":"ĐÁNH GIÁ TRÌNH BIÊN DỊCH &amp; IDE C++20 TRÊN ANDROID","faq_lead":"Giải đáp về hỗ trợ C++20, lập trình thi đấu STL, header đa tệp và sử dụng offline.","cta_h2":"Biên dịch C++20 Hiện đại Offline trên Điện thoại &amp; Máy tính bảng.","cta_desc":"Tải SuperCode IDE trên Google Play để trải nghiệm biên dịch C++20 STL chuyên biệt, tự động hoàn thành AST và Git trực quan.","th_0":"Năng lực C++","th_1":"SuperCode C++20 IDE","th_2":"App C++ Di động Cũ","th_3":"Sandbox C++ Trên Web","th_4":"Trình biên dịch Terminal","tr1_c0":"Chuẩn Ngôn ngữ","tr1_c1":"GNU C++20 Hiện đại (-std=gnu++2a) Offline","tr1_c2":"C++11/14 cũ hoặc plugin nặng nề","tr1_c3":"Yêu cầu kết nối Internet","tr1_c4":"Cài đặt toolchain CLI thủ công","tr2_c0":"OOP Đa tệp","tr2_c1":"Liên kết .cpp/.hpp Tự động + Bộ nhớ đệm Hash Gia tăng","tr2_c2":"Đơn tệp hoặc cấu hình dự án thủ công","tr2_c3":"Dán mã một tệp duy nhất","tr2_c4":"CMake/Make thủ công","tr3_c0":"Thông minh Mã nguồn","tr3_c1":"Gợi ý AST std:: / -&gt; / :: Offline + Trình định dạng","tr3_c2":"Tô màu từ khóa cơ bản","tr3_c3":"Độ trễ mạng cao","tr3_c4":"Cấu hình LSP bên ngoài","tr4_c0":"UX Terminal Chia đôi","tr4_c1":"Tự thu gọn Màn hình dọc + Ngang 55:45 + Đo lường","tr4_c2":"Chuyển màn hình toàn phần","tr4_c3":"Bố cục di động chật hẹp","tr4_c4":"Không có tab soạn thảo mã","tr5_c0":"Kiểm soát Phiên bản","tr5_c1":"Giao diện Git Diff, Nhánh &amp; Xung đột Trực quan Tích hợp","tr5_c2":"Không có","tr5_c3":"Không có","tr5_c4":"Chỉ dùng git CLI","faq1_q":"SuperCode có biên dịch C++20 và các container STL offline không cần mạng không?","faq1_a":"Có. Sau khi gói toolchain C++ offline được khởi tạo ở lần dùng đầu tiên, GNU C++20 (-std=gnu++2a) và toàn bộ STL (vector, map, priority_queue, ranges, smart pointer, lambda) biên dịch và chạy 100% offline.","faq2_q":"SuperCode có phù hợp cho lập trình thi đấu (Codeforces, LeetCode, Olympiad) trên điện thoại hoặc máy tính bảng không?","faq2_a":"Có. Tốc độ biên dịch nhanh nhờ bộ nhớ đệm gia tăng, nhập std::cin nhiều dòng trực tiếp, đo thời gian chạy (ms) và bộ nhớ (KB), cùng chế độ chia đôi màn hình ngang 55%/45% giúp luyện thuật toán lý tưởng mọi nơi.","faq3_q":"Dự án đa tệp .cpp và .hpp hoạt động như thế nào?","faq3_a":"Chỉ cần đặt các tệp .hpp và .cpp trong cùng thư mục dự án (hoặc mở sẵn trên các tab). SuperCode tự động tìm các include cục bộ, liên kết mọi tệp triển khai và tự tìm hàm main() ngay cả khi bạn nhấn Chạy từ tab header.","faq4_q":"Tôi có thể dùng &lt;thread&gt; của C++ hoặc các API mạng không?","faq4_a":"Có. Khi phát hiện header đa luồng mức hệ điều hành hoặc socket, SuperCode tự động biên dịch dự án đa tệp qua cụm đám mây C++ có hỗ trợ -pthread.","wb_eyebrow":"MÔI TRƯỜNG C++20 &amp; STL TƯƠNG TÁC","sec_cap_title":"Xây dựng cho Lập trình viên Thi đấu, Sinh viên CS &amp; Kỹ sư C++","sec_cap_lead":"Viết C++20 hiện đại mà không phải vật lộn với bàn phím di động, hàng đợi đám mây chậm chạp hay mã mẫu CMake thủ công.","f1_title":"Thư viện Chuẩn C++20 (STL) Đầy đủ Offline","f1_desc":"Sử dụng std::vector, map, unordered_map, set, priority_queue, string_view, optional, unique_ptr/shared_ptr, std::ranges::sort, lambda và template hoàn toàn offline.","f1_badge":"-std=gnu++2a &middot; Container STL &middot; Ranges &amp; Template","f2_title":"Hoàn thành AST Chuyên sâu cho std::, -&gt; và ::","f2_desc":"Gõ v., ptr-&gt; hoặc std:: để nhận gợi ý thành viên và phương thức offline tức thì trên container STL, iterator, luồng, smart pointer và các lớp của riêng bạn.","f2_badge":"Suy luận Kiểu AST &middot; Bộ 21 Phím Ký tự C++","f3_title":"Trình dựng Đa tệp .cpp / .hpp &amp; Bộ nhớ đệm Hash","f3_desc":"Hỗ trợ các tệp .cpp, .cc, .cxx, .hpp, .hh, .hxx và .inl qua nhiều thư mục con. Các đơn vị dịch không đổi được lưu đệm theo hash để dựng lặp cực nhanh.","f3_badge":"OOP Đa tệp &middot; Tự chạy Header -&gt; main.cpp","f4_title":"Console Chia đôi Chuẩn Thi đấu &amp; std::cin Trực tiếp","f4_desc":"Dán test case nhiều dòng vào std::cin trực tiếp, kiểm tra chính xác thời gian chạy (ms) và bộ nhớ đỉnh (KB), đồng thời lập trình song song trên chế độ chia 55%/45% màn hình ngang máy tính bảng.","f4_badge":"I/O Nhanh &middot; Tự thu gọn Khi mở Bàn phím &middot; Bảng màu 12x12","f5_title":"Đồng bộ Tệp ofstream &amp; Chống Vòng lặp Mất kiểm soát","f5_desc":"Tệp tạo qua std::ofstream được đồng bộ thẳng vào cây dự án, trong khi bộ giám sát CPU 15 giây và giới hạn xuất 250K bảo vệ phiên làm việc khỏi đệ quy hay vòng lặp vô hạn.","f5_badge":"Đồng bộ ofstream &middot; Giám sát 15s &middot; 8 Mẫu C++","f6_title":"Mở rộng C++ Đám mây Đa luồng Liền mạch","f6_desc":"Đang dùng &lt;thread&gt;, std::async hay mạng POSIX? SuperCode tự động định tuyến mã nguồn đa tệp tới cụm đám mây C++ (-pthread) kèm chẩn đoán dòng khớp 1:1.","f6_badge":"Hỗ trợ &lt;thread&gt; &middot; Chẩn đoán Chính xác Từng dòng Trình soạn thảo","workflow_title":"Cách Giải Thuật toán &amp; Xây dựng Dự án C++ trên Android","workflow_lead":"Tối ưu hóa cho vòng lặp thi đấu tốc độ cao và bài tập đại học đa lớp sạch sẽ.","wf_foot_note":"Hỗ trợ .cpp &middot; .cc &middot; .cxx &middot; .hpp &middot; .hh &middot; .hxx &middot; .h &middot; .inl","wf1_title":"Bắt đầu từ Mẫu hoặc Thư mục Đa tệp","wf1_desc":"Mở một trong 8 ví dụ C++ tích hợp sẵn hoặc sắp xếp các tệp header (.hpp) và triển khai (.cpp) trong thư mục cục bộ hay thư mục theo dõi bằng Git.","wf2_title":"Viết Mã STL Thần tốc với Phím :: và -&gt;","wf2_desc":"Các phím ký tự C++ chuyên dụng chèn ::, -&gt;, &lt;&lt;, &gt;&gt;, {} và &lt;&gt; chỉ với một chạm đồng thời kích hoạt gợi ý thành viên STL từ AST offline.","wf3_title":"Biên dịch Offline &amp; Nạp Test Case Thi đấu","wf3_desc":"Chạm Chạy để dựng offline trong vài mili giây, nhập hoặc dán dữ liệu mẫu vào std::cin rồi kiểm chứng thông số thời gian chạy và bộ nhớ.","wf4_title":"Định dạng &amp; Đẩy Bài giải lên GitHub","wf4_desc":"Định dạng mã giải C++20 chỉ với một chạm và commit trực tiếp lên kho lưu trữ thuật toán GitHub bằng Trình khách Git Trực quan tích hợp."},"java_ide":{"metaTitle":"Java IDE & Ứng dụng lập trình Java 17 ngoại tuyến cho Android — Records, OOP & SQLite JDBC | SuperCode","metaDesc":"Biên dịch và chạy Java 17 ngoại tuyến trên Android — giải pháp hiện đại thay thế ứng dụng Java 11. Hỗ trợ records, sealed classes, Streams, OOP đa lớp, bộ nhớ đệm bytecode 0ms, tích hợp SQLite JDBC và tệp .jar tùy chỉnh.","hero_tag":"JAVA 17 NGOẠI TUYẾN · OOP ĐA LỚP &amp; JDBC","hero_h1":"Biên dịch &amp; Chạy <span class=\"text-gradient\">Java 17 &amp; OOP đa lớp</span> ngoại tuyến trên Android.","hero_desc":"Thiết kế cho môn Java đại học, AP Computer Science, dựng prototype backend và luyện phỏng vấn. Viết <strong>Java 17 records, sealed classes &amp; Streams</strong> ngoại tuyến với <strong>chạy lại từ cache 0ms</strong>, <strong>SQLite JDBC tích hợp sẵn</strong> và nhập liệu trực tiếp <strong><code>Scanner(System.in)</code></strong>.","table_h2":"SuperCode Java 17 IDE so với trình biên dịch Java Android cũ","snippet_p":"<strong>SuperCode Java IDE</strong> là trình biên dịch Java 17 ngoại tuyến và môi trường OOP đa lớp cho Android. Hỗ trợ Java 17 records, sealed classes, biểu thức switch, Streams, hàm void main() rút gọn, chạy lại từ cache 0ms, SQLite JDBC ngoại tuyến tích hợp sẵn, thư viện .jar tùy chỉnh và nhập liệu console Scanner(System.in) tương tác.","table_caption":"SO SÁNH JAVA IDE &amp; TRÌNH BIÊN DỊCH ANDROID","faq_lead":"Giải đáp về tính năng Java 17, OOP nhiều tệp, thư viện .jar tùy chỉnh và nhập liệu Scanner ngoại tuyến.","cta_h2":"Viết &amp; Chạy Java 17 hiện đại mọi nơi trên Android.","cta_desc":"Tải SuperCode IDE trên Google Play — đầy đủ Java 17 ngoại tuyến, SQLite JDBC, gợi ý mã AST và Git trực quan.","th_0":"Tính năng Java","th_1":"SuperCode Java 17 IDE","th_2":"App Java di động cũ","th_3":"Trình biên dịch Java online","th_4":"IDE điều khiển PC từ xa","tr1_c0":"Phiên bản Java","tr1_c1":"Java 17 ngoại tuyến + Cloud Java 21+","tr1_c2":"Kẹt ở Java 7 hoặc Java 8","tr1_c3":"Cần kết nối Internet","tr1_c4":"Cần PC kết nối từ xa","tr2_c0":"Đa lớp &amp; .jar","tr2_c1":"Tự chạy đa gói + libs/*.jar + Cache","tr2_c2":"Cấu hình lớp main thủ công","tr2_c3":"Chỉ dán một tệp đơn lẻ","tr2_c4":"Build Gradle nặng nề","tr3_c0":"Kết nối cơ sở dữ liệu","tr3_c1":"Driver jdbc:sqlite ngoại tuyến tích hợp sẵn","tr3_c2":"Không tích hợp","tr3_c3":"Chỉ lưu tạm trên RAM","tr3_c4":"Thiết lập Maven thủ công","tr4_c0":"Tối ưu học tập","tr4_c1":"Hàm void main() gọn + Stack trace sạch","tr4_c2":"Chỉ hỗ trợ mã khung dài dòng","tr4_c3":"Không chạy được ngoại tuyến","tr4_c4":"Chưa tối ưu cảm ứng","tr5_c0":"Quy trình tích hợp","tr5_c1":"Java + SQL Explorer + Git trực quan + SFTP","tr5_c2":"Sandbox chỉ riêng Java","tr5_c3":"Chỉ trong tab trình duyệt","tr5_c4":"Hao pin và tốn dữ liệu mạng","faq1_q":"SuperCode biên dịch phiên bản Java nào ngoại tuyến trên Android?","faq1_a":"SuperCode biên dịch và chạy Java 17 ngoại tuyến — gồm records, sealed classes, biểu thức switch, pattern matching cho instanceof, text blocks và Streams — đồng thời tự động chuyển sang Cloud Java cho tính năng Java 21+.","faq2_q":"Tôi có thể chạy dự án Java gồm nhiều lớp và nhiều package không?","faq2_a":"Có. SuperCode phân giải toàn bộ tệp .java trong thư mục dự án và các tab đang mở, tự động xác định lớp chứa hàm main() và đồng bộ mọi tệp được tạo lại vào workspace.","faq3_q":"Có thể kết nối Java với SQLite cục bộ hoặc thêm tệp .jar ngoài không?","faq3_a":"Có! Driver JDBC jdbc:sqlite:... ngoại tuyến đã được tích hợp sẵn, và mọi thư viện .jar tương thích đặt trong thư mục libs/ của dự án sẽ tự động được thêm vào classpath.","faq4_q":"Scanner(System.in) có hỗ trợ nhập liệu tương tác không?","faq4_a":"Có. Chương trình sẽ tạm dừng gọn gàng mỗi khi Scanner hoặc BufferedReader chờ dữ liệu, cho phép bạn nhập nhiều dòng trực tiếp trong terminal chia màn hình.","wb_eyebrow":"MÔI TRƯỜNG THỰC HÀNH JAVA 17 &amp; JDBC TƯƠNG TÁC","sec_cap_title":"Sức mạnh Java 17 hiện đại không cần máy tính cồng kềnh","sec_cap_lead":"Từ bài tập void main() cơ bản đến dự án cơ sở dữ liệu JDBC đa package đều chạy mượt ngay trên thiết bị Android của bạn.","f1_title":"Cú pháp Java 17 ngoại tuyến &amp; void main() rút gọn","f1_desc":"Dùng record classes, sealed interfaces, biểu thức switch -&gt;, pattern matching cho instanceof, text blocks (\"\"\"\"), Streams, java.time và hàm void main() ngắn gọn 100% ngoại tuyến.","f1_badge":"Records · Sealed · Switch -&gt; · Text Blocks · Streams","f2_title":"OOP đa package &amp; Bộ nhớ đệm Bytecode 0ms","f2_desc":"Biên dịch các package nhiều tệp trên tab đang mở và thư mục dự án, tự tìm lớp khởi chạy chứa main() và lưu cache bytecode theo mã băm để chạy lại ⚡ Cache tức thì.","f2_badge":"Package đa lớp · Tự nhận diện main() · ⚡ Cache","f3_title":"SQLite JDBC ngoại tuyến tích hợp &amp; libs/*.jar tùy chỉnh","f3_desc":"Kết nối trực tiếp CSDL cục bộ qua DriverManager.getConnection(\"jdbc:sqlite:app.db\") không cần tải driver, hoặc chép thư viện .jar riêng vào thư mục libs/ của dự án.","f3_badge":"Sẵn sàng jdbc:sqlite · Classpath .jar tùy chỉnh","f4_title":"Scanner(System.in) trực tiếp &amp; Stack trace gọn sạch","f4_desc":"Hỗ trợ vòng lặp Scanner và BufferedReader tương tác kèm nút [EOF], chặn System.exit() an toàn không làm đóng app và lọc bỏ nhiễu nội bộ khỏi stack trace ngoại lệ.","f4_badge":"System.in trực tiếp · System.exit() an toàn · Chẩn đoán sạch","f5_title":"Gợi ý mã AST Java, Định dạng mã &amp; 8 mẫu dự án","f5_desc":"Code nhanh với thanh 21 phím ký tự Java/Kotlin, gợi ý mã AST ngoại tuyến, định dạng chuẩn Java một chạm và 8 mẫu OOP &amp; cấu trúc dữ liệu tích hợp sẵn.","f5_badge":"Tự hoàn thành AST · Trình định dạng Java · 8 ví dụ Java","f6_title":"Tự động định tuyến Cloud Java 21+ &amp; Java SE","f6_desc":"Cần thử cú pháp Java 21+ hoặc các gói Standard Edition chưa có trên di động? SuperCode tự động đóng gói các lớp của bạn và thực thi trên Cloud Java.","f6_badge":"Dự phòng Java 21+ · Đóng gói đa tệp lên Cloud","workflow_title":"Cách xây dựng dự án Java đa lớp trong SuperCode","workflow_lead":"Lý tưởng cho bài tập OOP, cấu trúc dữ liệu và ứng dụng Java kết nối cơ sở dữ liệu.","wf_foot_note":"Watchdog tự động 15s · Bảo vệ hạn mức Thread · SQLite JDBC tích hợp sẵn","wf1_title":"Tạo các lớp Java &amp; Thư viện .jar tùy chọn","wf1_desc":"Tổ chức các lớp .java theo package (và tệp .jar tùy chọn trong libs/) với gợi ý mã AST ngoại tuyến cùng hỗ trợ đóng ngoặc và import tự động.","wf2_title":"Định dạng khối mã Java &amp; Kiểm tra cú pháp","wf2_desc":"Chạm Định dạng để căn chỉnh lớp, phương thức và chú thích Javadoc gọn đẹp, đồng thời kiểm tra Error Radar để phát hiện ngoặc hoặc chuỗi chưa đóng.","wf3_title":"Biên dịch ngoại tuyến sang Bytecode có bộ nhớ đệm","wf3_desc":"SuperCode biên dịch mã nguồn Java 17 ngay trên máy (tải Java SDK ngoại tuyến một lần ở lần chạy đầu) và lưu cache bytecode để các lần chạy lại tức thì.","wf4_title":"Tương tác qua System.in &amp; Đồng bộ tệp đầu ra","wf4_desc":"Nhập dữ liệu console trực tiếp, truy vấn CSDL SQLite cục bộ qua JDBC và kiểm tra mọi tệp được tạo ra tự động đồng bộ vào workspace."},"js_ide":{"metaTitle":"JavaScript IDE & App Node/ES2024 ngoại tuyến cho Android — fs, Crypto & ESM | SuperCode","metaDesc":"Chạy JavaScript ES2024 độc lập và 29+ module lõi Node.js (fs, path, crypto, stream, zlib) ngoại tuyến trên Android. Hỗ trợ ESM & CommonJS, Web Crypto AES-GCM, ngắt vòng lặp <1ms và Cloud Node.js.","hero_tag":"JAVASCRIPT ES2024 ĐỘC LẬP &amp; STUDIO MODULE","hero_h1":"Chạy <span class=\"text-gradient\">JavaScript ES2024 &amp; Module</span> độc lập ngoại tuyến trong môi trường tách biệt không giật lag.","hero_desc":"Không cần bọc script trong khung HTML chỉ để kiểm thử logic JavaScript. Thực thi <strong>ES2024 <code>async/await</code></strong>, <strong>module ESM &amp; CommonJS đa tệp</strong> và <strong>thuật toán</strong> trực tiếp trong worker console tách biệt với cơ chế <strong>bảo vệ ngắt vòng lặp &lt;1ms</strong>.","table_h2":"SuperCode JavaScript IDE so với mẹo chạy qua Console trình duyệt","snippet_p":"<strong>SuperCode JavaScript IDE</strong> là trình chạy JavaScript ES2024 ngoại tuyến chuyên dụng và trình soạn thảo mã mô-đun cho Android. Công cụ thực thi các script ES Modules và CommonJS đa tệp trong luồng worker tách biệt khỏi UI, tích hợp bảo vệ vòng lặp vô hạn dưới 1 mili-giây, console có cấu trúc, gợi ý mã AST và hỗ trợ Cloud Node.js.","table_caption":"BẢNG SO SÁNH THỰC THI &amp; TRÌNH SOẠN THẢO JAVASCRIPT ANDROID","faq_lead":"Giải đáp về chạy tệp .js không cần HTML, ES modules, vòng lặp vô hạn và các module Node.js.","cta_h2":"Lập trình &amp; Chạy JavaScript ES2024 hiện đại mọi lúc.","cta_desc":"Cài đặt SuperCode IDE trên Google Play để dùng JS module ngoại tuyến độc lập, gợi ý AST và bộ Web DevTools toàn diện.","th_0":"Tính năng JS","th_1":"SuperCode JS IDE","th_2":"Trình sửa Web cần HTML","th_3":"JS Fiddle trực tuyến","th_4":"Cài Node CLI thủ công","tr1_c0":"Chạy JS độc lập","tr1_c1":"Chạy thẳng .js / .mjs / .cjs ngoại tuyến","tr1_c2":"Bắt buộc tạo tệp HTML giả","tr1_c3":"Cần kết nối Internet","tr1_c4":"Cài gói CLI hơn 100MB","tr2_c0":"Hệ thống Module","tr2_c1":"ESM import/export + CommonJS + .json cục bộ","tr2_c2":"Thường lỗi CORS trên file://","tr2_c3":"Đơn tệp hoặc CDN chậm","tr2_c4":"Có hỗ trợ","tr3_c0":"An toàn vòng lặp vô hạn","tr3_c1":"Worker tách biệt (ngắt tức thì &lt;1ms, 0 lag)","tr3_c2":"Treo cứng toàn bộ giao diện WebView","tr3_c3":"Đơ tab trình duyệt di động","tr3_c4":"Phải tắt tiến trình thủ công","tr4_c0":"Định dạng JS/TS","tr4_c1":"Trình định dạng JS/TS/JSX/JSON 100% ngoại tuyến","tr4_c2":"Cơ bản hoặc phụ thuộc plugin","tr4_c3":"Chỉ dùng khi có mạng","tr4_c4":"Cần cài npm prettier","tr5_c0":"API Node.js","tr5_c1":"Tự đóng gói module cục bộ lên Cloud Node.js","tr5_c2":"Chỉ có API trình duyệt","tr5_c3":"Chỉ có API trình duyệt","tr5_c4":"Chỉ chạy trên CLI cục bộ","faq1_q":"Tôi có thể chạy thẳng tệp .js trên Android mà không cần tạo trang HTML không?","faq1_a":"Có! Chỉ cần chạm Chạy trên mọi tệp .js, .mjs hoặc .cjs, console JavaScript độc lập của SuperCode sẽ khởi chạy ngay lập tức — hoàn toàn ngoại tuyến.","faq2_q":"Tôi có thể tách mã JavaScript thành nhiều tệp với import/export hoặc require() không?","faq2_a":"Có. Cả ES Modules (import / export), CommonJS (require / module.exports) lẫn tệp .json đều hoạt động xuyên suốt các tệp dự án cục bộ và các tab chưa lưu.","faq3_q":"Nếu lỡ viết vòng lặp while(true) thì có làm treo trình soạn thảo hay mất code chưa lưu không?","faq3_a":"Không bao giờ. Script chạy trong worker nền tách biệt, được bảo vệ bởi watchdog 15 giây và bộ ngắt tràn đầu ra, chấm dứt vòng lặp treo trong chưa tới 1 mili-giây mà không chạm tới luồng UI.","faq4_q":"Nếu tôi muốn xây dựng website DOM trực quan với HTML, CSS và WebAssembly thì sao?","faq4_a":"SuperCode tích hợp sẵn cả hai! Dùng JavaScript IDE độc lập cho module JS/Node thuần và thuật toán, còn khi cần dựng DOM HTTP trực tiếp, Responsive Viewports và Web DevTools, hãy chuyển sang Full-Stack Web &amp; PHP Studio.","wb_eyebrow":"WORKER CONSOLE JAVASCRIPT ĐỘC LẬP","sec_cap_title":"Runtime JavaScript độc lập thực thụ, tách khỏi tab trình duyệt","sec_cap_lead":"Kiểm thử cấu trúc dữ liệu, luồng bất đồng bộ, biến đổi JSON và gói mô-đun với phản hồi tức thì cùng chẩn đoán chính xác từng dòng.","f1_title":"Hỗ trợ đầy đủ ES6–ES2024 ngoại tuyến","f1_desc":"Chạy async/await, Promise.allSettled/any, generators, trường lớp riêng tư (#), optional chaining (?.), nullish coalescing (??), BigInt, structuredClone, timers và performance.now() ngoại tuyến.","f1_badge":"ES2024 · BigInt · Trường # riêng tư · structuredClone","f2_title":"Liên kết ES Modules &amp; CommonJS đa tệp","f2_desc":"Import tự do các module .js, .mjs, .cjs và .json cục bộ bằng import/export hoặc require()/module.exports — hỗ trợ cả tab đang mở chưa lưu và nhận diện tệp khởi chạy thông minh.","f2_badge":"import / export · require() · Import module .json","f3_title":"Tách biệt Worker ngoài UI &amp; Ngắt vòng lặp &lt;1ms","f3_desc":"Thực thi trên luồng worker nền chuyên biệt thay vì luồng giao diện. Ngay cả vòng lặp vô hạn while(true){} dày đặc cũng bị ngắt sạch dưới 1ms mà trình soạn thảo không hề khựng.","f3_badge":"Không treo UI · Watchdog 15s · Báo lỗi chuẩn 1:1 từng dòng","f4_title":"Console có cấu trúc &amp; Nhập Stdin tương tác","f4_desc":"Kiểm tra rõ ràng đối tượng lồng nhau, mảng, mức console.warn/error và bộ đếm thời gian độ phân giải cao, đồng thời nhận dữ liệu nhập trực tiếp cho các bài tập JavaScript dạng CLI.","f4_badge":"Đối tượng cấu trúc · Nhập Prompt trực tiếp · Console chia đôi","f5_title":"Gợi ý AST JS/TS &amp; Định dạng chuẩn Prettier một chạm","f5_desc":"Tích hợp thanh 21 phím ký tự JS/TS (=&gt;, ?., ===, ``, ${}), tự hoàn thành AST ngoại tuyến cho Array/Promise/JSON/Math/DOM và định dạng nguyên khối JS/TS/JSON.","f5_badge":"Thanh ký tự JS/TS · Gợi ý AST · Kiểm tra JSON","f6_title":"Tự động đóng gói đa tệp lên Cloud Node.js","f6_desc":"Đang import API lõi Node.js (http, fs, crypto, child_process) hoặc dùng // @cloud? SuperCode tự động đóng gói các module cục bộ của bạn thành một gói Node.js thống nhất.","f6_badge":"Nhận diện API Node.js · Đóng gói đa module lên Cloud","workflow_title":"Cách viết &amp; kiểm thử JavaScript mô-đun trong SuperCode","workflow_lead":"Lý tưởng để luyện LeetCode bằng JS, viết tiện ích mô-đun, mô phỏng payload API và kiểm thử logic frontend.","wf_foot_note":"6 ví dụ JavaScript tích hợp sẵn · Hỗ trợ .js · .mjs · .cjs · .ts · .json","wf1_title":"Tạo tệp .js, .mjs, .cjs hoặc .json độc lập","wf1_desc":"Viết thẳng JavaScript thuần hoặc các gói mô-đun — không cần tạo khung index.html.","wf2_title":"Viết hàm Async &amp; Arrow gọn sạch","wf2_desc":"Dùng phím chạm nhanh =&gt;, ?., === và dấu backtick template-literal cùng gợi ý AST ngoại tuyến và định dạng JS một chạm.","wf3_title":"Thực thi tức thì trong Worker Console tách biệt","wf3_desc":"Chạm Chạy để liên kết các module cục bộ, xem kết quả console có cấu trúc và đo thời gian thực thi chính xác tới mili-giây.","wf4_title":"Chuyển sang Xem trước DOM trực tiếp hoặc Đẩy lên Git","wf4_desc":"Cần đầy đủ DOM/Canvas/WASM của trình duyệt? Ghép script của bạn với tệp .html trong Web Studio hoặc commit trực tiếp qua Visual Git."},"lua_ide":{"metaTitle":"Lua IDE & Ứng dụng lập trình Lua 5.4 offline cho Android — Script game, cjson & SQLite | SuperCode","metaDesc":"Viết và chạy script Lua 5.4.7 native offline trên Android trong vài micro giây. Tích hợp hơn 11 module (cjson, lsqlite3, lfs, crypto, socket), metatable, coroutine, toán tử bit và gợi ý AST phân biệt . với :.","hero_tag":"STUDIO LẬP TRÌNH LUA 5.4.7 NATIVE OFFLINE","hero_h1":"<span class=\"text-gradient\">Lua 5.4 IDE offline</span> tốc độ dưới mili giây cho logic game &amp; script.","hero_desc":"Dù đang tạo prototype máy trạng thái game, script nhúng hay quy tắc tự động hóa, hãy chạy <strong>Lua 5.4.7 native</strong> offline chỉ trong <strong>vài micro giây</strong> với <strong><code>require()</code> đa tệp</strong>, <strong>gợi ý AST phân biệt <code>.</code> và <code>:</code></strong> và <strong><code>io.read()</code></strong> trực tiếp.","table_h2":"So sánh SuperCode Lua 5.4 Studio và trình soạn thảo di động thông thường","snippet_p":"<strong>SuperCode Lua IDE</strong> là studio lập trình Lua 5.4.7 native offline cho Android. Ứng dụng mang lại tốc độ thực thi dưới mili giây kèm đo lường micro giây và bộ nhớ, phân giải require() đa tệp, tự động hoàn tất AST hiểu phương thức (. với :), định dạng Lua một chạm và nhập console io.read() tương tác.","table_caption":"SO SÁNH IDE LẬP TRÌNH LUA 5.4 TRÊN ANDROID","faq_lead":"Giải đáp về cú pháp Lua 5.4 offline, require() đa tệp và viết script game.","cta_h2":"Chạy script Lua 5.4 native trong vài micro giây trên Android.","cta_desc":"Tải SuperCode IDE trên Google Play để trải nghiệm Lua 5.4.7 offline, gợi ý AST và workspace đa tệp.","th_0":"Tính năng Lua","th_1":"SuperCode Lua 5.4 IDE","th_2":"Trình soạn văn bản Lua thường","th_3":"Demo Lua trên web","tr1_c0":"Phiên bản Runtime","tr1_c1":"Lua 5.4.7 Native Offline (~400 µs)","tr1_c2":"Không tích hợp chạy code","tr1_c3":"Chỉ chạy online","tr2_c0":"Phân giải Module","tr2_c1":"require() đa tệp + Tab chưa lưu","tr2_c2":"Không có","tr2_c3":"Chỉ chạy một đoạn code đơn","tr3_c0":"Hỗ trợ thông minh Lua","tr3_c1":"Phân biệt hàm . và phương thức : + Bộ định dạng","tr3_c2":"Chỉ tô màu từ khóa cơ bản","tr3_c3":"Ô nhập văn bản thuần","tr4_c0":"I/O tương tác","tr4_c1":"io.read() trực tiếp + Đồng bộ tệp Workspace","tr4_c2":"Không có","tr4_c3":"Chỉ xuất kết quả tĩnh","tr5_c0":"Tương tác &amp; Cloud","tr5_c1":"Tương tác luajava.* + Cloud lpeg/socket/lfs","tr5_c2":"Không có","tr5_c3":"Không có","faq1_q":"SuperCode chạy phiên bản Lua nào ở chế độ offline?","faq1_a":"SuperCode tích hợp sẵn Lua 5.4.7 native để chạy offline 100%, hỗ trợ chia lấy nguyên (//), toán tử bit, thuộc tính &lt;const&gt; và &lt;close&gt;, coroutine, metatable và utf8.","faq2_q":"Tôi có thể chia script Lua thành nhiều tệp và dùng require() không?","faq2_a":"Có. require() tự động tìm trong thư mục dự án và các tab đang mở, đồng thời mọi tệp tạo qua io.open() đều đồng bộ ngược lại cây thư mục Explorer.","faq3_q":"SuperCode có hỗ trợ định dạng mã Lua offline không?","faq3_a":"Có. Tính năng định dạng một chạm tự động thụt lề chuẩn xác cho function, if/then/else, for/do, repeat/until và cấu trúc table ngay khi offline.","wb_eyebrow":"BÀN LÀM VIỆC LUA 5.4.7 TƯƠNG TÁC","sec_cap_title":"Tốc độ siêu nhẹ kết hợp trí tuệ IDE toàn diện cho Lua","sec_cap_lead":"Soạn thảo, định dạng và chạy đa module Lua chuẩn mực ngay trong túi bạn.","f1_title":"Lua 5.4.7 Native kèm đo lường micro giây","f1_desc":"Hỗ trợ chia nguyên //, toán tử bit (&amp; | ~ &lt;&lt; &gt;&gt;), biến &lt;const&gt; và &lt;close&gt;, coroutine, metatable, string.pack/unpack và utf8 — hiển thị chính xác thời gian chạy (µs) và bộ nhớ (KB).","f1_badge":"Lua 5.4.7 · Đo µs · Đo bộ nhớ KB","f2_title":"require() đa tệp &amp; Đồng bộ tệp Workspace","f2_desc":"Sắp xếp thực thể game và tiện ích theo thư mục con; require('modules.vec2') phân giải mượt mà cả tệp đã lưu lẫn tab chưa lưu, và ghi qua io.open() sẽ đồng bộ về cây tệp.","f2_badge":"require() đa tệp · Chọn điểm vào · Đồng bộ tệp","f3_title":"Gợi ý AST hiểu phương thức (. với :) &amp; Định dạng code","f3_desc":"SuperCode phân biệt rõ hàm table (string., table., math.) với phương thức dấu hai chấm (str:, customObj:), đi kèm bộ định dạng Lua offline chuyên biệt và chú thích `--` / `--[[ ]]`.","f3_badge":"Gợi ý . với : · Định dạng Lua Offline","f4_title":"Console io.read() tương tác &amp; Giới hạn an toàn","f4_desc":"Kiểm thử game text adventure và công cụ CLI với hộp nhập io.read() trực tiếp, được bảo vệ bởi giới hạn bộ nhớ VM thích ứng và timeout CPU.","f4_badge":"io.read() trực tiếp · 8 mẫu Lua · Hỗ trợ C-Module Cloud","workflow_title":"Cách tạo prototype script Lua đa module trên Android","workflow_lead":"Thử nghiệm nhanh từ một tệp đơn đến logic game phân module bài bản.","wf_foot_note":"Hỗ trợ Lua 5.4.7 Native · Tương tác Java luajava.* · Module Lua Cloud","wf1_title":"Tạo script Lua hoặc mở ví dụ mẫu","wf1_desc":"Chọn từ 8 ví dụ Lua tích hợp sẵn hoặc tạo các module đa tệp trong Explorer.","wf2_title":"Soạn thảo với gợi ý Table &amp; Định dạng code","wf2_desc":"Gõ : hoặc . trên thư viện chuẩn và table tùy chỉnh để nhận gợi ý offline tức thì, rồi chạm Định dạng.","wf3_title":"Thực thi offline trong vài micro giây","wf3_desc":"Chạy tức thì với dữ liệu nhập io.read() trực tiếp và xem thông số đo lường µs, KB chính xác.","wf4_title":"Đồng bộ script lên Game Engine hoặc Server","wf4_desc":"Đẩy các module Lua lên kho Git hoặc server từ xa qua SFTP chỉ với một chạm."},"shell_ide":{"metaTitle":"Trình chạy Shell Script (.sh không cần Root) & Lập trình Kotlin cho Android — Bash & awk | SuperCode","metaDesc":"Chạy script Linux .sh không cần root và biên dịch Kotlin (.kt/.kts) trên Android. Thực thi pipeline awk, sed, grep, curl và bc offline, chuyển mượt lên Ubuntu Bash 5.2, triển khai qua SFTP & Visual Git.","hero_tag":"STUDIO LINUX SHELL (.SH) NATIVE &amp; KOTLIN","hero_h1":"Tự động hóa với <span class=\"text-gradient\">Pipeline Linux Shell &amp; Kotlin</span> trên Android.","hero_desc":"Viết, định dạng và chạy cục bộ <strong>script shell <code>.sh</code></strong> với các pipeline <strong><code>grep</code>, <code>awk</code>, <code>sed</code>, <code>sort</code> &amp; <code>find</code></strong> native đồng bộ với thư mục dự án — cùng khả năng chạy cloud mượt mà cho <strong>Ubuntu Bash 5.2</strong> và <strong>Kotlin (<code>.kt</code>)</strong>.","table_h2":"So sánh SuperCode Shell &amp; Kotlin Studio","snippet_p":"<strong>SuperCode Shell &amp; Kotlin Studio</strong> giúp lập trình viên Android soạn thảo, định dạng và chạy cục bộ các pipeline Linux shell (.sh) bằng grep, awk, sed và sort với cơ chế tự động đồng bộ thư mục dự án, song hành cùng trình biên dịch cloud GNU Bash 5.2 và Kotlin (.kt).","table_caption":"MA TRẬN SHELL SCRIPTING &amp; WORKSPACE KOTLIN TRÊN ANDROID","faq_lead":"Giải đáp về chạy tệp .sh trên bộ nhớ Android, pipeline awk/sed và thực thi Kotlin.","cta_h2":"Chạy Shell Script &amp; Kotlin mọi lúc mọi nơi trên điện thoại.","cta_desc":"Cài đặt SuperCode IDE trên Google Play để sử dụng pipeline Linux shell native, chạy Kotlin và bộ công cụ server SFTP.","th_0":"Tính năng","th_1":"SuperCode Shell + Kotlin","th_2":"Ứng dụng Terminal thuần","th_3":"Trình xem script cơ bản","tr1_c0":"Chạy .sh trên bộ nhớ chung","tr1_c1":"Chạy mượt dù bộ nhớ Android chặn noexec","tr1_c2":"Báo lỗi Permission denied trên /sdcard","tr1_c3":"Không thể thực thi","tr2_c0":"Soạn thảo &amp; Định dạng Script","tr2_c1":"Gợi ý AST + Bộ định dạng Shell &amp; Kotlin Offline","tr2_c2":"Chỉ có nano/vi nhỏ hẹp trên CLI","tr2_c3":"Chỉ tô màu cú pháp","tr3_c0":"GNU Bash 5 &amp; Kotlin","tr3_c1":"Tích hợp sẵn Cloud Ubuntu Bash 5.2 + Trình chạy Kotlin","tr3_c2":"Cài rootfs/JDK thủ công rất nặng","tr3_c3":"Không hỗ trợ","tr4_c0":"Triển khai Server","tr4_c1":"Lưu nguyên tử SFTP trực tiếp + Visual Git","tr4_c2":"Gõ lệnh scp thủ công","tr4_c3":"Không có","faq1_q":"Vì sao SuperCode chạy được script .sh trong thư mục dự án dù Android chặn chmod +x trên bộ nhớ chung?","faq1_a":"SuperCode tự động chuẩn bị môi trường và ánh xạ $PWD minh bạch với shell native của Android, rồi đồng bộ thẳng mọi tệp kết quả mới tạo hoặc chỉnh sửa về thư mục dự án của bạn.","faq2_q":"Tôi có thể viết và chạy mã Kotlin (.kt) trong SuperCode không?","faq2_a":"Có! SuperCode cung cấp tô màu cú pháp Kotlin &amp; Gradle (.kt, .kts, .gradle.kts) đầy đủ, gợi ý AST offline, định dạng code offline và biên dịch, chạy Kotlin trên cloud chỉ với một chạm.","faq3_q":"Điều gì xảy ra nếu script của tôi dùng mảng kết hợp của GNU Bash 5 vốn không có trong sh mặc định của Android?","faq3_a":"SuperCode tự nhận diện cú pháp đặc thù của Bash hoặc chỉ thị # @cloud và định tuyến script trong workspace sang môi trường Ubuntu GNU Bash 5.2 tự động.","wb_eyebrow":"BÀN LÀM VIỆC SHELL PIPELINE &amp; KOTLIN TƯƠNG TÁC","sec_cap_title":"Viết script gọn gàng, chạy pipeline văn bản cục bộ &amp; hỗ trợ Kotlin","sec_cap_lead":"Kết hợp soạn thảo, định dạng thân thiện cảm ứng với thực thi pipeline thực tế — không cần chuyển qua lại các app terminal ngoài.","f1_title":"Thực thi OS Shell Native &amp; Pipeline Toybox","f1_desc":"Chạy cục bộ script .sh với grep, awk, sed, sort, uniq, wc, cut, tr, find, cat và chuyển hướng tệp — ngay cả trên bộ nhớ chung Android nơi chmod +x thường thất bại.","f1_badge":"grep · awk · sed · sort · uniq · find · Pipes","f2_title":"Source đa script &amp; Đồng bộ tệp đầu ra Workspace","f2_desc":"Gọi source các script .sh phụ trợ trong thư mục, nhập dữ liệu read tương tác trực tiếp và xem báo cáo hay tệp xử lý mới xuất hiện tự động trong Explorer.","f2_badge":"source đa tệp · Stdin read trực tiếp · Đồng bộ tệp","f3_title":"GNU Bash 5.2 &amp; Cloud Studio Kotlin (.kt) một chạm","f3_desc":"Cần mảng kết hợp GNU Bash 5 hay muốn biên dịch Kotlin data class, coroutine và lập trình hàm? SuperCode định tuyến mượt mà sang các runtime cloud chuyên dụng.","f3_badge":"Ubuntu Bash 5.2 · Thực thi Kotlin .kt / .kts","f4_title":"Gợi ý AST Shell &amp; Kotlin + Bộ định dạng Offline","f4_desc":"Gồm gợi ý mở rộng biến shell ${var:-default}, hoàn tất AST Kotlin, định dạng offline cho cả Shell lẫn Kotlin/Gradle cùng 6 mẫu Shell tích hợp sẵn.","f4_badge":"Định dạng Shell + Kotlin · Tô màu Dockerfile/Makefile","workflow_title":"Cách chạy tự động hóa Shell &amp; đoạn mã Kotlin","workflow_lead":"Quy trình tinh gọn cho script DevOps, xử lý log và luyện tập Kotlin.","wf_foot_note":"6 ví dụ Shell có sẵn · Bộ giám sát tiến trình 120 giây · Giữ nguyên quyền POSIX qua SFTP","wf1_title":"Tạo Shell Script hoặc tệp Kotlin","wf1_desc":"Soạn tệp .sh, .bash, Makefile, Dockerfile hoặc .kt với thanh phím ký tự chuyên dụng và tô màu cú pháp.","wf2_title":"Tự động định dạng vòng lặp, case &amp; khối Kotlin","wf2_desc":"Định dạng câu lệnh shell if/fi, case/esac và class Kotlin offline chỉ bằng một chạm.","wf3_title":"Chạy cục bộ hoặc trên Cloud Bash / Kotlin","wf3_desc":"Thực thi pipeline POSIX shell ngay trên thiết bị, hoặc chạy mã GNU Bash 5.2 và Kotlin mượt mà.","wf4_title":"Triển khai script thẳng lên Server Production","wf4_desc":"Tải script đã kiểm tra lên qua SFTP (giữ nguyên quyền POSIX!) hoặc commit bằng Visual Git."},"web_ide":{"metaTitle":"IDE Web & PHP 8.2 cho Android — HTML, CSS, JS, PDO SQLite & Máy chủ WASM Ngoại tuyến | SuperCode","metaDesc":"IDE Web & PHP 8.2 full-stack ngoại tuyến cho Android. Máy chủ HTTP cục bộ thực thụ cho HTML5, CSS3, ES Modules, WebAssembly (.wasm), PHP $_SESSION + CSDL PDO SQLite, DevTools REPL 3 khung nhìn và triển khai SFTP.","hero_tag":"WEB FULL-STACK · PHP · WASM · SQL · STUDIO SFTP","hero_h1":"Studio <span class=\"text-gradient\">Web, PHP Ngoại tuyến &amp; WASM</span> Full-Stack Tích hợp DevTools.","hero_desc":"Không chỉ là trình xem <code>file://</code> tĩnh — mà là máy chủ web full-stack hoàn chỉnh trong túi bạn. Chạy <strong>HTML5, CSS3, ES Modules &amp; WebAssembly (<code>.wasm</code>)</strong> cùng <strong>PHP động ngoại tuyến</strong>, <strong>CSDL PDO SQLite</strong>, <strong>DevTools đa khung nhìn</strong> và <strong>xuất bản FTP/SFTP</strong> trực tiếp.","table_h2":"SuperCode Web &amp; PHP Studio so với Trình xem HTML di động","snippet_p":"<strong>SuperCode Web &amp; PHP Studio</strong> là IDE phát triển web full-stack ngoại tuyến cho Android. Tích hợp máy chủ HTTP cục bộ thực thụ hỗ trợ HTML5, CSS3, ES Modules, WebAssembly (.wasm), PHP động với CSDL PDO SQLite, chuyển đổi khung nhìn 3 chế độ, Web DevTools kèm JS REPL và triển khai SFTP trực tiếp.","table_caption":"BẢNG SO SÁNH PHÁT TRIỂN WEB &amp; PHP FULL-STACK TRÊN ANDROID","faq_lead":"Giải đáp về PHP + SQLite ngoại tuyến, ES Modules / fetch() / WASM, Web DevTools và triển khai FTP/SFTP.","cta_h2":"Mang theo Máy chủ HTML, WASM, PHP &amp; SQL Full-Stack trong túi bạn.","cta_desc":"Tải SuperCode IDE trên Google Play để xây dựng, kiểm tra và triển khai ứng dụng web hoàn chỉnh từ Android.","th_0":"Khả năng Web","th_1":"SuperCode Web + PHP Studio","th_2":"Trình sửa HTML di động cơ bản","th_3":"Môi trường Dev đám mây","tr1_c0":"Origin Máy chủ &amp; WASM","tr1_c1":"HTTP cục bộ thực + ES Modules + .wasm Streaming","tr1_c2":"CORS của file:// chặn fetch &amp; modules","tr1_c3":"Cần kết nối mạng","tr2_c0":"Backend PHP &amp; SQL","tr2_c1":"PHP ngoại tuyến 100% + $_SESSION + PDO SQLite","tr2_c2":"Chỉ HTML/JS frontend tĩnh","tr2_c3":"Container đám mây trả phí","tr3_c0":"Responsive &amp; DevTools","tr3_c1":"Di động/Tablet/Desktop + Net Log + JS REPL trực tiếp","tr3_c2":"Chỉ alert() cơ bản hoặc log văn bản","tr3_c3":"Giao diện desktop chật hẹp trên điện thoại","tr4_c0":"Đa phương tiện &amp; Xuất tệp","tr4_c1":"Tải lên Camera/Tệp + Canvas/Blob + PNG 2560px","tr4_c2":"Lỗi &lt;input type=file&gt; &amp; blob:","tr4_c3":"Phải tải xuống từ xa","tr5_c0":"Lưu trữ từ xa","tr5_c1":"Xem trước SFTP/FTPS trực tiếp + Lưu nguyên tử 3 pha","tr5_c2":"Ứng dụng FTP ngoài thủ công","tr5_c3":"Khóa trên đám mây","faq1_q":"Tôi có thể chạy website PHP động và kết nối CSDL SQL ngoại tuyến trên Android không?","faq1_a":"Có! SuperCode chạy trang .php, endpoint REST JSON, session, tải lên biểu mẫu và include nhiều tệp hoàn toàn ngoại tuyến, tích hợp sẵn hỗ trợ CSDL PDO('sqlite:...') và SQLite3.","faq2_q":"ES6 modules (&lt;script type=\"module\"&gt;), fetch() và WebAssembly (.wasm) có hoạt động không?","faq2_a":"Có. Vì SuperCode phục vụ dự án qua máy chủ HTTP cục bộ thực thụ với hơn 65 kiểu MIME (gồm cả application/wasm), nên fetch(), ES modules, mô hình WebGL 3D và WebAssembly.instantiateStreaming() hoạt động ngay lập tức.","faq3_q":"Làm sao gỡ lỗi JavaScript, yêu cầu mạng và bố cục desktop trên điện thoại?","faq3_a":"Chạm thanh Dynamic Island có thể kéo trong chế độ xem trước để chuyển khung nhìn Mobile, Tablet (768dp) và Desktop, hoặc mở ngăn Web DevTools tùy chỉnh kích thước để lọc log Error/Warn/Net và chạy JavaScript trực tiếp trong REPL.","faq4_q":"Tôi có thể xem trước và cập nhật website đặt trên máy chủ FTP hoặc SFTP từ xa không?","faq4_a":"Có. Gắn máy chủ trong không gian làm việc SFTP/FTPS/FTP, chỉnh sửa trực tiếp các tab HTML/CSS/JS/PHP từ xa với lưu nguyên tử 3 pha, rồi chạm Chạy để xem trước trang từ xa kèm bộ nhớ đệm tài nguyên theo nhu cầu.","wb_eyebrow":"BÀN LÀM VIỆC HTTP FULL-STACK, PHP NGOẠI TUYẾN, WASM &amp; DEVTOOLS","sec_cap_title":"Sáu lớp liên kết của Kỹ thuật Web hiện đại trên Android","sec_cap_lead":"ES modules frontend, WebAssembly nhị phân, PHP session backend, CSDL SQL quan hệ, kiểm tra DevTools và triển khai SFTP từ xa — tất cả hợp nhất.","f1_title":"Origin HTTP cục bộ thực thụ cho HTML5, CSS3, JS &amp; WASM","f1_desc":"Phục vụ dự án qua origin HTTP/1.1 cục bộ thực thụ thay cho URL file:// hay lỗi — mở khóa fetch(), &lt;script type=\"module\"&gt;, WebAssembly.instantiateStreaming() (.wasm), tài nguyên WebGL .glb/.gltf, IndexedDB và tua video/âm thanh HTTP 206.","f1_badge":"65+ Kiểu MIME · ES Modules · application/wasm · HTTP 206","f2_title":"Công cụ Backend PHP động Ngoại tuyến 100%","f2_desc":"Chạy mẫu .php nhiều trang, lớp OOP, closure, match và include/require hoàn toàn ngoại tuyến với $_GET, $_POST, $_SESSION bền vững, tải lên $_FILES, header JSON REST và password_hash().","f2_badge":"$_GET / $_POST / $_SESSION · API JSON · PHP Ngoại tuyến","f3_title":"Tích hợp CSDL SQL qua PDO &amp; SQLite3","f3_desc":"Xây dựng ứng dụng PHP hướng dữ liệu ngoại tuyến với new PDO('sqlite:app.db') hoặc SQLite3, hỗ trợ prepared statements (? và :named bindings), giao dịch ACID và kiểm tra bảng tức thì trong SQL IDE.","f3_badge":"PDO('sqlite:...') · Prepared Statements · Giao dịch ACID","f4_title":"Bảng điều khiển DevTools nổi, Nhật ký mạng &amp; JS REPL","f4_desc":"Kiểm tra yêu cầu HTTP trực tiếp (GET /api.php -&gt; 200 · 3ms · 1.2 KB), lọc log All / Error / Warn / Net, xem cây DOM/Object có cấu trúc và chạy biểu thức trực tiếp trong REPL &gt; Run JavaScript...","f4_badge":"Thời gian mạng · Huy hiệu lỗi · JS REPL Tương tác","f5_title":"Chuyển Khung nhìn 3 Chế độ &amp; Chụp trang 2560px","f5_desc":"Chuyển tức thì giữa bố cục Mobile, Tablet (768dp) và Desktop từ Dynamic Island có thể kéo, thử tải lên camera/thư viện &lt;input type=\"file\"&gt; và xuất ảnh chụp PNG 2560px sắc nét.","f5_badge":"Mobile / Tablet / Desktop · Xuất PNG 2560px","f6_title":"Xem trước &amp; Triển khai Web FTP / FTPS / SFTP Từ xa Trực tiếp","f6_desc":"Đang sửa trang production trực tiếp qua SFTP hoặc FTPS? Chạm Chạy để xem trước trang từ xa ngay tại máy (tải CSS, JS và ảnh tương đối theo nhu cầu) và lưu chỉnh sửa nguyên tử về máy chủ web.","f6_badge":"Xem trước Từ xa · Xuất bản SFTP / FTPS Nguyên tử","workflow_title":"Cách Xây dựng, Gỡ lỗi &amp; Triển khai Web Full-Stack trên Android","workflow_lead":"Từ tạo mẫu HTML/CSS/WASM và PHP+SQL cục bộ đến triển khai máy chủ trực tiếp.","wf_foot_note":"Vuốt cạnh trái để về thẳng Trình duyệt tệp · Đặt lại Cache &amp; Session một chạm","wf1_title":"Soạn thảo tệp HTML5, CSS3, JS, WASM &amp; PHP","wf1_desc":"Chỉnh sửa dự án web đa tệp với gợi ý mã AST HTML/CSS/JS/PHP và định dạng đệ quy một chạm giúp thụt lề đồng bộ cả khối &lt;script&gt; và &lt;style&gt; nhúng.","wf2_title":"Kết nối Biểu mẫu &amp; API PHP Ngoại tuyến với SQL","wf2_desc":"Truy vấn CSDL SQLite .db cục bộ từ PHP qua PDO prepared statements, hoặc tạo dữ liệu mẫu trực tiếp trong SQL Studio của SuperCode.","wf3_title":"Xem trước trên Mobile, Tablet &amp; Desktop + DevTools","wf3_desc":"Đổi khung nhìn tức thì, kiểm tra trạng thái mạng và lỗi JS trong ngăn DevTools tùy chỉnh kích thước, hoặc thử chỉnh DOM trực tiếp trong JS REPL.","wf4_title":"Xuất bản Cập nhật thẳng lên Host hoặc GitHub Pages","wf4_desc":"Đẩy bản dựng tĩnh/WASM lên GitHub Pages qua Visual Git, hoặc triển khai PHP &amp; tài nguyên web trực tiếp lên VPS qua SFTP/FTPS."},"sql_ide":{"metaTitle":"SQL IDE, Trình xem SQLite .db & Ứng dụng Thực hành SQL Ngoại tuyến cho Android — MySQL & JSON | SuperCode","metaDesc":"SQL IDE ngoại tuyến, trình sửa CSDL .db/.sqlite và ứng dụng thực hành SQL cho Android. Chạy Window Functions, CTE, tìm kiếm FTS5, hơn 50 hàm MySQL/PostgreSQL, 9 chế độ xuất, nhập CSV/JSON và Cloud MySQL 8.0.","hero_tag":"SQL IDE NGOẠI TUYẾN CHUYÊN DỤNG &amp; TRÌNH DUYỆT .DB","hero_h1":"Chạy <span class=\"text-gradient\">SQL Hiện đại &amp; Kiểm tra CSDL .db</span> Ngoại tuyến trên Android.","hero_desc":"Thiết kế chuyên biệt cho kỹ sư CSDL, chuyên viên phân tích dữ liệu và người học SQL. Thực thi <strong>window functions, CTE, JSONB &amp; tìm kiếm toàn văn</strong> ngoại tuyến với <strong>9 chế độ xuất định dạng</strong>, kiểm tra tệp nhị phân <strong><code>.db/.sqlite</code></strong> một chạm và nhập <strong>bộ dữ liệu CSV/JSON</strong>.","table_h2":"SuperCode SQL IDE so với Trình xem CSDL di động","snippet_p":"<strong>SuperCode SQL IDE</strong> là trình chạy truy vấn SQL và khám phá CSDL ngoại tuyến chuyên dụng cho Android. Hỗ trợ window functions, CTE đệ quy, đường dẫn JSONB, tìm kiếm toàn văn, hơn 60 hàm thống kê và regex, 9 định dạng xuất (Box, Markdown, CSV, JSON), kiểm tra .db/.sqlite một chạm, nhập CSV/JSON và Cloud MySQL 8.0.","table_caption":"SO SÁNH SQL IDE &amp; TRÌNH XEM CSDL TRÊN ANDROID","faq_lead":"Giải đáp về thực hành SQL ngoại tuyến, mở tệp .db/.sqlite, nhập CSV/JSON và cú pháp MySQL.","cta_h2":"Làm chủ SQL &amp; Quản lý CSDL Ngoại tuyến trên Android.","cta_desc":"Cài đặt SuperCode IDE trên Google Play để sở hữu trình chạy SQL ngoại tuyến, trình duyệt .db và studio dữ liệu CSV/JSON hoàn chỉnh.","th_0":"Khả năng SQL","th_1":"SuperCode SQL Studio","th_2":"Trình xem bảng .db đơn giản","th_3":"SQL Fiddle trực tuyến","tr1_c0":"Engine SQL Ngoại tuyến","tr1_c1":"Window Functions + CTE + JSONB + FTS Ngoại tuyến","tr1_c2":"Chỉ SELECT cơ bản / duyệt giao diện","tr1_c3":"Cần kết nối mạng","tr2_c0":"Chế độ Hiển thị &amp; Xuất","tr2_c1":"9 Chế độ (Box, Markdown, CSV, JSON, INSERT...)","tr2_c2":"Chỉ lưới GUI cố định","tr2_c3":"Chỉ bảng HTML web","tr3_c0":"Nhập dữ liệu &amp; Đồng bộ","tr3_c1":"Nhập mảng CSV, TSV &amp; JSON + Đồng bộ Workspace","tr3_c2":"Tính năng Pro trả phí hoặc thiếu","tr3_c3":"Dán lệnh INSERT thủ công","tr4_c0":"Tương thích MySQL","tr4_c1":"Tương thích DDL cục bộ + Cloud MySQL 8.0 Procedures","tr4_c2":"Chỉ cú pháp SQLite thuần","tr4_c3":"Phiên làm việc tạm thời","tr5_c0":"Tích hợp Full-Stack","tr5_c1":"Dùng chung tệp .db với PHP PDO &amp; Java JDBC cục bộ","tr5_c2":"Ứng dụng xem tách biệt","tr5_c3":"Tab trình duyệt tách biệt","faq1_q":"Tôi có thể thực hành truy vấn SQL ngoại tuyến mà không cần cài máy chủ CSDL không?","faq1_a":"Có! Tạo tệp .sql bất kỳ và chạm Chạy để thực thi đa câu lệnh CREATE, INSERT, JOIN, CTE và Window Function ngoại tuyến 100% với bảng lưới Unicode Box được căn chỉnh đẹp.","faq2_q":"SuperCode có mở được tệp .db và .sqlite có sẵn trên điện thoại không?","faq2_a":"Có. Chạm hoặc chạy tệp .db, .sqlite, .sqlite3 hoặc .db3 để kiểm tra toàn bộ bảng, view, chỉ mục và lược đồ; mọi tập lệnh .sql trong cùng thư mục dự án đều có thể truy vấn trực tiếp CSDL đó.","faq3_q":"Ứng dụng có hỗ trợ cú pháp MySQL như AUTO_INCREMENT, SHOW TABLES, DESCRIBE hay Stored Procedures không?","faq3_a":"Các lệnh và DDL MySQL/PostgreSQL thông dụng (AUTO_INCREMENT, ENUM, SHOW TABLES, DESCRIBE, ILIKE) chạy ngoại tuyến ngay tại máy, còn Stored Procedures và Triggers đặc thù của MySQL 8.0 tự động định tuyến tới Cloud MySQL 8.0.","faq4_q":"Làm thế nào để xuất kết quả truy vấn SQL ra CSV, Markdown hoặc JSON?","faq4_a":"Thêm `.mode csv` (hoặc `.mode markdown` / `.mode json`) và `.once output.csv` trước câu lệnh SELECT — SuperCode sẽ ghi tệp xuất thẳng vào thư mục dự án của bạn.","wb_eyebrow":"BÀN LÀM VIỆC SQL &amp; CSDL NGOẠI TUYẾN TƯƠNG TÁC","sec_cap_title":"Phân tích SQL chuẩn Desktop, Kiểm tra Tệp &amp; Linh hoạt Phương ngữ","sec_cap_lead":"Truy vấn sandbox trong bộ nhớ hoặc tệp CSDL đa bảng bền vững với căn chỉnh bảng sắc nét.","f1_title":"SQL Ngoại tuyến Hiện đại: Window Functions, CTE &amp; JSONB","f1_desc":"Hỗ trợ ROW_NUMBER/RANK/DENSE_RANK/LAG/LEAD OVER(...), WITH RECURSIVE CTE, RETURNING, UPSERT, truy vấn đường dẫn JSON -&gt; và -&gt;&gt;, json_each() và tìm kiếm toàn văn BM25 ngoại tuyến 100%.","f1_badge":"Window Functions · CTE Đệ quy · JSONB &amp; FTS","f2_title":"9 Chế độ Hiển thị Kết quả &amp; Quy trình Xuất","f2_desc":"Xem kết quả mặc định dưới dạng lưới Unicode Box căn chuẩn CJK (┌──┬──┐), hoặc chuyển qua .mode sang table, markdown, csv, tsv, json, line, list hay câu lệnh SQL insert — và xuất trực tiếp qua .once.","f2_badge":"box · markdown · csv · json · table · insert","f3_title":"Kiểm tra .db / .sqlite Một chạm &amp; Tự động Gắn","f3_desc":"Mở bất kỳ tệp .db, .sqlite, .sqlite3 hay .db3 nào để xem ngay siêu dữ liệu trang, bảng, view, chỉ mục và toàn bộ lược đồ CREATE. Truy vấn trong cùng thư mục sẽ tự động gắn CSDL có sẵn của bạn!","f3_badge":"Mở trực tiếp .db / .sqlite3 · ATTACH DATABASE","f4_title":"Nhập CSV / TSV / JSON &amp; 60+ Hàm Phân tích","f4_desc":"Nhập CSV, TSV và mảng đối tượng JSON trực tiếp vào bảng tự động định kiểu (.import --csv / --json), cùng hơn 60 hàm tích hợp SHA256, REGEXP_EXTRACT, MEDIAN, STDDEV, PERCENTILE và UUID.","f4_badge":".import CSV/JSON · SHA256 · REGEXP · MEDIAN/STDDEV","f5_title":"Tương thích Cú pháp MySQL / PostgreSQL &amp; READ_STDIN()","f5_desc":"Viết truy vấn AUTO_INCREMENT, SERIAL, ENUM, SHOW TABLES, DESCRIBE và ILIKE thông dụng ngay tại máy không cần sửa lại rườm rà, và nhập giá trị trực tiếp từ console vào SQL qua READ_STDIN().","f5_badge":"SHOW TABLES / DESCRIBE · READ_STDIN() Tương tác","f6_title":"Chuỗi SQL Đa tệp &amp; Cloud MySQL 8.0","f6_desc":"Nối chuỗi 01_schema.sql -&gt; 02_seed.sql -&gt; 03_report.sql tự động, hoặc chạy stored procedures MySQL 8.0 (DELIMITER, CREATE PROCEDURE, CALL, JSON_TABLE) trên cụm Cloud MySQL.","f6_badge":"Chạy Tô-pô Đa tệp · Cloud MySQL 8.0","workflow_title":"Cách Truy vấn CSDL &amp; Nhập Bộ dữ liệu trong SuperCode","workflow_lead":"Quy trình CSDL gọn nhẹ hướng tập lệnh, lưu trữ bền vững ngay trong không gian làm việc Android.","wf_foot_note":"6 Ví dụ SQL Tích hợp · Liên thông Trực tiếp với PHP PDO &amp; Java 17 JDBC","wf1_title":"Mở CSDL .db hoặc Tạo Tập lệnh .sql","wf1_desc":"Chạm bất kỳ tệp .db/.sqlite cục bộ nào để xem lược đồ, hoặc tạo tệp .sql với tính năng gợi ý từ khóa/hàm và định dạng SQL dựa trên AST ngoại tuyến.","wf2_title":"Tạo dữ liệu Bảng hoặc Nhập tệp CSV &amp; JSON","wf2_desc":"Nạp bộ dữ liệu CSV, TSV hoặc JSON từ thư mục dự án vào bảng quan hệ có định kiểu chỉ với một lệnh.","wf3_title":"Thực thi Truy vấn Đa câu lệnh Ngoại tuyến","wf3_desc":"Kiểm tra lưới Unicode Box, bảng Markdown hoặc kết quả JSON trong bảng điều khiển chia màn hình, kèm hộp nhắc tham số READ_STDIN() trực tiếp khi cần.","wf4_title":"Xuất Báo cáo Sạch &amp; Đồng bộ .db sang PHP/Java","wf4_desc":"Lưu tệp .db đã cập nhật hoặc báo cáo .csv/.json thẳng vào thư mục dự án — sẵn sàng truy vấn từ không gian làm việc PHP PDO hoặc Java JDBC của SuperCode!"},"git_client":{"metaTitle":"Trình khách Git Trực quan cho Android — Clone, Diff Time Machine & Giao diện Merge | SuperCode","metaDesc":"Trình khách Git trực quan tích hợp sẵn trong SuperCode IDE cho Android. Clone repo GitHub/GitLab/Gitee qua PAT, xem diff commit mã hóa màu, chuyển nhánh, tự động stash khi Pull và giải quyết xung đột merge trực quan.","hero_tag":"TRẠM LÀM VIỆC GIT TRỰC QUAN V2.0 TÍCH HỢP SẴN","hero_h1":"Trọn bộ <span class=\"text-gradient\">Git Trực quan, Diff Time Machine &amp; Xử lý Xung đột Merge</span> trên Android.","hero_desc":"Không cần cài gói terminal ngoài. Clone repo <strong>GitHub, GitLab, Gitee &amp; Bitbucket</strong> qua token HTTPS, xem <strong>Unified Diff mã hóa màu</strong>, pull với <strong>tự động stash &amp; tải lại tab</strong> và giải quyết <strong>xung đột merge chỉ với một chạm</strong>.","table_h2":"SuperCode Visual Git so với các Quy trình Git khác trên Android","snippet_p":"<strong>SuperCode Visual Git Client</strong> là trạm làm việc Git tích hợp nguyên bản trong SuperCode IDE cho Android. Hỗ trợ clone HTTPS + PAT, chuyển đổi nhiều repo, quản lý nhánh, Pull tự động stash thông minh, Time Machine 120 commit kèm unified diff mã hóa màu và trình giải quyết xung đột merge trực quan.","table_caption":"BẢNG SO SÁNH QUY TRÌNH KIỂM SOÁT PHIÊN BẢN GIT TRÊN ANDROID","faq_lead":"Giải đáp thực tế về Personal Access Token GitHub, repo riêng tư, xung đột merge và lịch sử commit.","cta_h2":"Quản lý Repo, Diff &amp; Merge dễ dàng trên Android.","cta_desc":"Tải SuperCode IDE trên Google Play để sở hữu Trình khách Git Trực quan tích hợp sẵn cùng hơn 10 không gian lập trình ngoại tuyến.","th_0":"Quy trình Git","th_1":"SuperCode Visual Git V2","th_2":"Plugin Git Di động Cơ bản","th_3":"Git Terminal CLI","tr1_c0":"Cài đặt &amp; Phụ thuộc","tr1_c1":"Engine tích hợp không cần cài đặt + Khôi phục Lock","tr1_c2":"Lỗi plugin hoặc hỏng xác thực","tr1_c3":"Cài pkg thủ công + cấu hình SSH/PAT","tr2_c0":"Pull khi có sửa đổi cục bộ","tr2_c1":"Tự động Stash + Khôi phục + Tải lại Tab tại chỗ","tr2_c2":"Thất bại với lỗi checkout","tr2_c3":"Chạy git stash / pop thủ công","tr3_c0":"Lịch sử &amp; Diff Mã nguồn","tr3_c1":"Time Machine 120 Commit + Unified Diff 2D Màu sắc","tr3_c2":"Chỉ có log commit dạng văn bản thuần","tr3_c3":"Khó cuộn trên màn hình điện thoại","tr4_c0":"Xung đột Merge","tr4_c1":"Thẻ Trực quan: Giữ Hiện tại / Đến / Cả hai","tr4_c2":"Sửa dấu &lt;&lt;&lt;&lt;&lt;&lt;&lt; dạng văn bản thô","tr4_c3":"Sửa marker bằng vim thủ công","tr5_c0":"An toàn Detached HEAD","tr5_c1":"Banner Cứu hộ 1 Chạm (+ Nhánh Mới / Quay lại)","tr5_c2":"Dễ làm mất commit","tr5_c3":"Trạng thái CLI khó hiểu","faq1_q":"Làm sao để xác thực với các repo GitHub, GitLab hoặc Gitee riêng tư?","faq1_a":"Hãy tạo HTTPS Personal Access Token (PAT) với quyền repo trên GitHub/GitLab/Gitee rồi dán vào ô Token khi Clone, Commit &amp; Push hoặc Pull. SuperCode lưu trữ an toàn để bạn không phải nhập lại mỗi lần dùng.","faq2_q":"Điều gì xảy ra nếu tôi nhấn Pull khi đang có tab chưa lưu hoặc thay đổi chưa commit?","faq2_a":"SuperCode sẽ ghi các tab chưa lưu xuống bộ nhớ trước, tự động stash các thay đổi đã theo dõi chưa commit, pull các commit mới nhất từ remote, áp dụng lại phần làm việc cục bộ và tải lại các tab đang mở đúng tại dòng con trỏ của bạn.","faq3_q":"Làm sao để xem những gì đã thay đổi trong một commit trước đó hoặc khôi phục lại?","faq3_a":"Mở Git Time Machine từ Bảng điều khiển Git và chạm vào bất kỳ commit nào trên dòng thời gian. Chọn Xem Thay đổi Mã (Commit Diff) để xem unified diff mã hóa màu, Checkout (Chỉ xem) để kiểm tra bản chụp đó an toàn, hoặc Hard Reset để tua lại nhánh.","faq4_q":"Tôi có thể commit thay đổi ngoại tuyến khi không có kết nối internet không?","faq4_a":"Có! Việc stage, commit cục bộ, tạo nhánh, xem lịch sử, unified diff và giải quyết xung đột đều hoạt động ngoại tuyến; hãy push các commit cục bộ lên origin bất cứ khi nào bạn kết nối lại.","wb_eyebrow":"BẢNG ĐIỀU KHIỂN GIT TƯƠNG TÁC, DIFF &amp; BÀN LÀM VIỆC MERGE","sec_cap_title":"Mọi thao tác Git thiết yếu — Thiết kế chuyên biệt cho Cảm ứng","sec_cap_lead":"Được bảo vệ bởi khóa repo, tự động lưu tab đang sửa và banner cứu hộ Detached HEAD để việc quản lý phiên bản trên di động luôn nhẹ nhàng.","f1_title":"Bảng điều khiển Git Chiến thuật &amp; Chuyển nhanh Đa Repo","f1_desc":"Xem ngay repo đang gắn, nhánh hoạt động, mã hash commit rút gọn, bộ đếm ↑ Trước / ↓ Sau remote trực tiếp và số tệp Đã sửa / Thêm / Xóa / Xung đột — cùng khả năng chuyển repo chỉ bằng một chạm.","f1_badge":"Chuyển Đa Repo · ↑Trước ↓Sau · Gắn Repo Có sẵn","f2_title":"Clone HTTPS + PAT &amp; Lưu trữ Thông tin Xác thực Mã hóa","f2_desc":"Clone repo công khai hoặc riêng tư từ GitHub, GitLab, Gitee, Bitbucket hoặc máy chủ Git tự lưu trữ bằng Personal Access Token (PAT). Tên thư mục đích tự động điền và token được lưu an toàn cho các lần push sau.","f2_badge":"PAT GitHub / GitLab / Gitee · Tiến trình Truyền Trực tiếp","f3_title":"Tự động Ghi Tab đang sửa, Xem trước Thay đổi &amp; Cấu hình Tác giả","f3_desc":"Trước khi commit, SuperCode tự động lưu mọi tab trình soạn thảo đang mở có chỉnh sửa để không bỏ sót thay đổi, xem trước tới 80 tệp thay đổi với huy hiệu [M]/[A]/[U]/[D] và cho phép đặt Tên &amp; Email Tác giả tùy chỉnh.","f3_badge":"Không Sót Sửa đổi · Tác giả Tùy chỉnh · Tự động Gắn Upstream","f4_title":"Pull Thông minh với Tự động Stash &amp; Tải lại Giữ Con trỏ","f4_desc":"Có thay đổi cục bộ chưa commit khi pull? SuperCode tự động stash chúng mà không tạo commit giả, pull bản cập nhật từ remote, áp dụng lại thay đổi và tải lại nóng các tab đang mở đúng tại dòng và cột con trỏ của bạn!","f4_badge":"Tự động Stash Sạch sẽ · Tải lại Nóng Tab Tại chỗ","f5_title":"Git Time Machine, Tạo Nhánh &amp; Trình xem Unified Diff","f5_desc":"Duyệt tới 120 commit, mở Unified Diff +xanh / -đỏ cuộn 2D cho bất kỳ commit nào, tạo/chuyển nhánh cục bộ hoặc remote, kiểm tra an toàn các bản chụp lịch sử hoặc thực hiện Hard Reset có xác nhận.","f5_badge":"Trình xem Unified Diff · + Nhánh Mới · Cứu hộ Detached HEAD","f6_title":"Trình Giải quyết Xung đột Merge Trực quan Đa Tệp","f6_desc":"Không bao giờ phải sửa tay các dấu &lt;&lt;&lt;&lt;&lt;&lt;&lt; thô. Duyệt qua từng tệp xung đột (1 / N) và chạm Giữ Hiện tại, Giữ Đến hoặc Giữ Cả hai trên các thẻ Cục bộ và Remote rõ ràng — tự động stage để Commit &amp; Push ngay.","f6_badge":"Giữ Hiện tại / Đến / Cả hai · Hàng đợi Tự động Stage","workflow_title":"Hướng dẫn Đầy đủ 6 Bước: Cách dùng Git trong SuperCode IDE","workflow_lead":"Làm theo đúng quy trình này trong SuperCode để clone, tạo nhánh, xem diff, merge và push ngay từ điện thoại hoặc máy tính bảng.","wf_foot_note":"Tự động Khôi phục index.lock Cũ · Hỗ trợ Commit Cục bộ Ngoại tuyến","wf1_title":"Clone Repo Remote hoặc Gắn Dự án Cục bộ","wf1_desc":"Dán URL HTTPS (vd: https://github.com/user/repo.git) và token PAT tùy chọn rồi chạm CLONE — hoặc chạm Gắn Repo Có sẵn nếu thư mục đã có sẵn thư mục .git.","wf2_title":"Chuyển đổi hoặc Tạo Nhánh Tính năng Mới","wf2_desc":"Mở Git Time Machine và chạm vào bộ chọn nhánh trên cùng để chuyển nhánh hoặc chạm + Tạo Nhánh Mới… (vd: feature/mobile-ui) với kiểm tra tên nhánh tự động.","wf3_title":"Chỉnh sửa Mã Đa Tệp với Đầy đủ Trí tuệ IDE","wf3_desc":"Sửa đổi, định dạng và kiểm thử mã ngoại tuyến. Ngay cả khi bạn quên lưu một tab đang mở, các thao tác Git vẫn tự động ghi các tab đang sửa xuống bộ nhớ trước khi chạy.","wf4_title":"Pull Cập nhật Nhóm từ Remote An toàn","wf4_desc":"Chạm Pull trước khi push. Các sửa đổi cục bộ chưa commit được stash và khôi phục tự động, còn các tab đang mở được làm mới tại chỗ mà không làm mất vị trí con trỏ.","wf5_title":"Giải quyết Mọi Va chạm Merge Trực quan","wf5_desc":"Nếu có sửa đổi chồng chéo, chạm Mở Trình giải quyết Xung đột, so sánh song song khối Cục bộ và Remote, chọn Giữ Hiện tại / Đến / Cả hai rồi chạm Áp dụng Giải pháp.","wf6_title":"Kiểm tra Tệp Đang chờ, Nhập Thông điệp &amp; Push","wf6_desc":"Kiểm tra huy hiệu [M]/[A]/[D] trong danh sách Thay đổi Đang chờ, xác nhận Danh tính Tác giả cùng thông điệp commit rồi chạm COMMIT để stage, commit và push lên origin."},"sftp_client":{"metaTitle":"Trình soạn thảo Mã SFTP, FTPS & FTP cho Android — Két Khóa SSH & Lưu Nguyên tử | SuperCode","metaDesc":"Kết nối tới máy chủ SFTP, FTPS (TLS 1.3) và FTP trực tiếp trong SuperCode IDE trên Android. Xác thực bằng khóa SSH Ed25519/RSA/PEM trong két AES-256, sửa mã từ xa với lưu nguyên tử 3 pha và tiếp tục truyền tệp bị gián đoạn.","hero_tag":"KHÔNG GIAN MÁY CHỦ TỪ XA SFTP · FTPS TLS 1.3 · FTP","hero_h1":"Chỉnh sửa Máy chủ Production qua <span class=\"text-gradient\">SFTP, FTPS &amp; FTP</span> với An toàn Lưu Nguyên tử.","hero_desc":"Xây dựng cho kỹ sư cloud, quản trị hệ thống và lập trình viên web trực chiến. Kết nối qua <strong>SFTP (SSH 22), FTPS Explicit/Implicit (TLS 1.3) hoặc FTP</strong> bằng <strong>khóa Ed25519/RSA/PEM</strong> trong <strong>két phần cứng AES-256</strong> và sửa tệp từ xa với cơ chế <strong>lưu nguyên tử chống hỏng tệp</strong>.","table_h2":"Không gian SFTP / FTPS SuperCode so với Ứng dụng Truyền tệp Rời rạc","snippet_p":"<strong>SuperCode SFTP &amp; FTPS Client</strong> là trình soạn thảo mã máy chủ từ xa tích hợp cho Android, hỗ trợ SFTP (SSH), FTPS Explicit/Implicit (TLS 1.3) và FTP. Công cụ kết hợp két khóa SSH AES-256 trên Android KeyStore, xác minh dấu vân tay TOFU, lưu nguyên tử từ xa 3 pha và truyền 4 luồng tiếp tục theo từng byte.","table_caption":"SO SÁNH TRÌNH SOẠN THẢO MÃ TỪ XA SFTP / FTPS TRÊN ANDROID","faq_lead":"Giải đáp về khóa riêng SSH (.pem / Ed25519), FTPS TLS 1.3, chống hỏng tệp lưu từ xa và tiếp tục tải xuống tệp lớn.","cta_h2":"Quản lý VPS Production &amp; Máy chủ Web An toàn từ Android.","cta_desc":"Cài đặt SuperCode IDE trên Google Play để sửa SFTP/FTPS chuẩn AES-256, xác thực khóa SSH và triển khai nguyên tử 3 pha.","th_0":"Khả năng Từ xa","th_1":"SuperCode SFTP/FTPS Studio","th_2":"Ứng dụng Tệp FTP Độc lập","th_3":"Plugin Soạn thảo Cơ bản","tr1_c0":"Giao thức Hỗ trợ","tr1_c1":"SFTP (22) + FTPS Explicit TLS 1.3 + FTPS 990 + FTP","tr1_c2":"Chỉ truyền tệp (không có IDE)","tr1_c3":"Chỉ có FTP/SFTP cơ bản","tr2_c0":"Bảo mật Khóa &amp; MITM","tr2_c1":"Ed25519/RSA/PEM + KeyStore AES-256 + TOFU SHA256","tr2_c2":"Tùy ứng dụng; không có trình sửa mã AST","tr2_c3":"Cấu hình văn bản thuần hoặc khóa yếu","tr3_c0":"An toàn Lưu khi Rớt mạng","tr3_c1":"Lưu Nguyên tử 3 Pha + Giữ nguyên Quyền POSIX","tr3_c2":"Tải xuống/tải lên lại thủ công","tr3_c3":"Ghi luồng trực tiếp dễ gây tệp 0-byte","tr4_c0":"Truyền tệp Bị gián đoạn","tr4_c1":"4 Luồng Song song + Tiếp tục Đúng Vị trí Byte","tr4_c2":"Chỉ hỗ trợ ở bản trả phí","tr4_c3":"Phải tải lại từ 0%","tr5_c0":"Xem trước Web Trực tiếp","tr5_c1":"Xem trước HTML/CSS/JS/PHP Từ xa 1 Chạm","tr5_c2":"Không có","tr5_c3":"Không có","faq1_q":"Những định dạng khóa riêng SSH nào hoạt động với máy chủ AWS EC2, DigitalOcean hoặc Linux VPS?","faq1_a":"SuperCode hỗ trợ khóa riêng OpenSSH, PEM (.pem), RSA (id_rsa), Ed25519 (id_ed25519) và ECDSA — có hoặc không có mật khẩu bảo vệ (passphrase) — kèm bộ chọn nhanh tới thư mục Downloads và .ssh.","faq2_q":"SuperCode ngăn tệp 0-byte bị hỏng trên máy chủ khi mất sóng di động lúc đang lưu bằng cách nào?","faq2_a":"Mỗi lần lưu tab từ xa đều dùng Giao dịch Nguyên tử 3 Pha: tải lên tệp tạm trước, truy vấn máy chủ qua STAT/SIZE để xác minh đúng số byte đã tới nguyên vẹn, rồi mới đổi tên nguyên tử ghi đè lên tệp đích đồng thời giữ nguyên quyền Linux.","faq3_q":"Ngoài SSH SFTP, SuperCode có hỗ trợ FTPS (FTP qua SSL/TLS) không?","faq3_a":"Có! Cả FTPS Explicit (AUTH TLS 1.2/1.3 trên cổng 21 với kênh dữ liệu thụ động mã hóa PROT P) lẫn FTPS Implicit (cổng 990), cùng FTP thụ động UTF-8 tiêu chuẩn đều được hỗ trợ nguyên bản.","faq4_q":"Tôi có thể tiếp tục tải xuống hoặc tải lên bản sao lưu lớn nếu kết nối bị ngắt quãng không?","faq4_a":"Có. Khi truyền vào một tệp dang dở có sẵn, SuperCode nhận diện dung lượng phần đã có và đề xuất Tiếp tục Truyền Dang dở 1 chạm ngay từ vị trí byte chính xác mà không gửi lại các byte đã hoàn tất.","wb_eyebrow":"KÉT SFTP TƯƠNG TÁC, LƯU NGUYÊN TỬ &amp; BÀN TRUYỀN TẢI","sec_cap_title":"Bảo mật Từ xa Cấp Doanh nghiệp &amp; Kỹ thuật Tệp Chống Hỏng Tuyệt đối","sec_cap_lead":"Thiết kế chuyên biệt cho mạng di động chập chờn — nơi một trình sửa FTP thông thường sẽ cắt cụt cấu hình production thành 0 byte nếu rớt 5G hoặc Wi-Fi.","f1_title":"Đủ 4 Giao thức: SFTP, FTPS Explicit, FTPS Implicit &amp; FTP","f1_desc":"Hỗ trợ SSH SFTP (cổng 22), FTPS Explicit qua TLS 1.2/1.3 với kênh dữ liệu thụ động mã hóa (PBSZ 0 + PROT P), FTPS Implicit (cổng 990) và FTP thụ động UTF-8 (cổng 21).","f1_badge":"SFTP (22) · FTPS TLS 1.3 (21) · FTPS (990) · FTP","f2_title":"Bộ chọn Khóa Riêng SSH, Két AES-256 &amp; Lá chắn TOFU","f2_desc":"Nhập khóa OpenSSH, PEM, RSA, Ed25519 hoặc ECDSA (.pem, .key, id_rsa, id_ed25519) + passphrase. Mọi bí mật được mã hóa qua Android KeyStore AES-256-GCM và bảo vệ bởi cảnh báo sai lệch khóa máy chủ SHA256.","f2_badge":"Ed25519 / RSA / PEM · AES-256-GCM · Chống MITM Máy chủ","f3_title":"Lưu Từ xa Nguyên tử 3 Pha (Không bao giờ Hỏng 0-Byte)","f3_desc":"Mở tệp từ xa sẽ tạo một tab bản sao cục bộ bền vững (☁️). Khi nhấn Lưu, hệ thống tải lên tệp tạm, xác minh chính xác kích thước byte từ xa qua STAT/SIZE và đổi tên nguyên tử ghi đè tệp đích trong khi giữ nguyên quyền POSIX!","f3_badge":"Tải Tệp Tạm -&gt; Xác minh Dung lượng -&gt; Đổi tên Nguyên tử + chmod","f4_title":"Bảng điều khiển Kiểm tra Bắt tay Trực tiếp &amp; Pool Tự phục hồi","f4_desc":"Xác minh TCP, đàm phán TLS/SSH và xác thực khóa trong bảng điều khiển chẩn đoán tích hợp trước khi lưu máy chủ. Nhóm kết nối 3 kênh tự động khôi phục các socket cũ sau khi chuyển Wi-Fi/5G.","f4_badge":"⚡ Kiểm tra Bắt tay · Pool Tự phục hồi 3 Kênh","f5_title":"Hàng đợi Truyền 4 Luồng &amp; Tiếp tục theo Vị trí Byte","f5_desc":"Tải lên hoặc tải xuống toàn bộ cây thư mục qua 4 luồng song song với bảng tiến trình MB/s mượt 20fps. Các lần truyền tệp lớn bị ngắt sẽ tiếp tục đúng từ vị trí byte qua SFTP RESUME hoặc FTP REST!","f5_badge":"4 Luồng Song song · MB/s Trực tiếp · Tiếp tục Vị trí Byte","f6_title":"Tìm kiếm Mờ Từ xa &amp; Xem trước Web Từ xa Trực tiếp","f6_desc":"Tìm tên tệp xuyên suốt các thư mục máy chủ từ xa, tải lại tab từ xa với bất kỳ bộ mã hóa nào trong 34 bảng mã và nhấn Chạy trên tệp HTML/PHP từ xa để xem trước trang máy chủ trực tiếp trước hoặc sau khi sửa.","f6_badge":"Tìm Mờ Từ xa · 34 Bảng mã · Xem trước Web Trực tiếp","workflow_title":"Cách Kết nối &amp; Sửa Máy chủ Trực tiếp An toàn từ Android","workflow_lead":"Cấu hình một lần trong két mã hóa phần cứng và triển khai bản vá nóng từ mọi nơi chỉ trong vài giây.","wf_foot_note":"Giữ nguyên Quyền Tệp POSIX Linux Từ xa · Bền vững qua Khởi động lại Ứng dụng Ngoại tuyến","wf1_title":"Chọn Giao thức &amp; Nhập Mật khẩu hoặc Khóa SSH","wf1_desc":"Chọn SFTP, FTPS (TLS), FTPS (990) hoặc FTP, nhập host/user và nhập mật khẩu hoặc chọn tệp khóa riêng .pem / id_ed25519 của bạn.","wf2_title":"Kiểm tra Chẩn đoán Bắt tay &amp; Tin cậy Dấu vân tay Máy chủ","wf2_desc":"Chạm Kiểm tra Bắt tay để xác nhận xác thực TCP/TLS/SSH theo thời gian thực, xác minh dấu vân tay SHA256 của máy chủ và lưu vào két AES-256.","wf3_title":"Duyệt Cây Từ xa &amp; Chỉnh sửa với Đầy đủ AST + Định dạng","wf3_desc":"Mở cấu hình Nginx, tệp backend Python/PHP hoặc script shell trực tiếp trong tab soạn thảo với hoàn thành mã AST, Radar Lỗi và định dạng một chạm.","wf4_title":"Lưu Nguyên tử hoặc Đồng bộ Thư mục với Kiểm soát Xung đột","wf4_desc":"Chạm Lưu để triển khai nguyên tử 3 pha, hoặc chọn nhiều thư mục để tải lên/tải xuống với chính sách Ghi đè, Tiếp tục Vị trí Byte, Giữ Cả hai hoặc Bỏ qua."},"py_pip_manager":{"metaTitle":"Cài đặt gói PIP trên Android — Hướng dẫn .whl offline, PyPI & requirements.txt | SuperCode","metaDesc":"Hướng dẫn đầy đủ cách cài gói Python PIP trên Android với SuperCode. Dùng Auto-PIP ánh xạ alias, cài hàng loạt requirements.txt hoặc nhập file .whl/.zip offline từ thư mục Tải xuống không cần mạng.","hero_tag":"VISUAL PIP &#183; PEP 440 &#183; TRÌNH CÀI ĐẶT FILE .WHL OFFLINE","hero_h1":"Cài đặt <span class=\"text-gradient\">gói Python PIP &amp; file .whl offline</span> trên Android.","hero_desc":"Tạm biệt lỗi biên dịch CLI trên di động. Trong <strong>ứng dụng lập trình Python cho Android</strong> của chúng tôi, quản lý thư viện bên thứ ba trực quan: chạy <strong><code>requirements.txt</code></strong> chỉ với một chạm, để <strong>Auto-PIP</strong> xử lý hơn 35 alias module, hoặc nhập <strong>file <code>.whl</code> offline</strong> ngay từ thư mục Tải xuống.","pip_s1":"Ánh xạ alias import","pip_s2":"Khớp phiên bản","pip_s3":"Nhập gói offline","pip_s4":"Trình quản lý trực quan","wb_eyebrow":"BÀN LÀM VIỆC VISUAL PIP, AUTO-ALIAS &amp; WHEEL OFFLINE","sec_cap_title":"Bốn cách nhẹ nhàng để thêm thư viện Python trên điện thoại","sec_cap_lead":"Dù có Wi-Fi tốc độ cao hay không có mạng trong lớp học, SuperCode luôn giữ các dependency Python của bạn gọn gàng và bền vững.","f1_title":"Auto-PIP phát hiện thiếu import &amp; 35+ bảng ánh xạ alias","f1_desc":"Viết import bs4, import yaml, import dotenv, import jwt hay import telebot rồi nhấn Chạy. SuperCode tự động ánh xạ tên import sang gói PyPI chuẩn (beautifulsoup4, pyyaml, python-dotenv, PyJWT, pyTelegramBotAPI), cài đặt và chạy lại script của bạn.","f1_badge":"bs4 -&gt; beautifulsoup4 &#183; yaml -&gt; pyyaml &#183; 35+ Alias","f2_title":"Tự động nhận diện requirements.txt không cần cấu hình","f2_desc":"Clone repository Git hoặc mở thư mục dự án chứa requirements.txt. Trình quản lý Visual PIP quét tối đa 6 thư mục cha, phân tích dấu nối dòng (\\) cùng marker nền tảng và hiển thị banner cài hàng loạt 1 chạm.","f2_badge":"Quét ngược thư mục gốc &#183; Marker nền tảng &#183; Hàng đợi lô","f3_title":"Trình nhập cục bộ .whl, .tar.gz &amp; .zip offline 100%","f3_desc":"Học khi đang di chuyển, trên máy bay hay Wi-Fi trường bị giới hạn? Tải trước gói thuần Python .whl, .tar.gz hoặc .zip vào thư mục Tải xuống Android và cài đặt hoàn toàn offline với kiểm tra phiên bản PEP 440 đầy đủ.","f3_badge":"Cài ở chế độ máy bay &#183; .whl / .tar.gz / .zip","f4_title":"Ràng buộc phiên bản PEP 440 &amp; bộ phân tích lệnh","f4_desc":"Dán trực tiếp lệnh pip install đầy đủ (như pip install requests&gt;=2.31.0 flask~=3.0) vào ô nhập. SuperCode tự loại bỏ tiền tố CLI, đánh giá các toán tử ==, &gt;=, &lt;=, !=, ~= theo Python 3.11 và tìm bản phát hành tương thích.","f4_badge":"Chuẩn PEP 440 &#183; Dán đầy đủ lệnh pip","f5_title":"Kiểm tra dung lượng gói đã cài &amp; dọn dẹp 1 chạm","f5_desc":"Chuyển sang tab Quản lý để lọc các thư viện đã cài theo thời gian thực, xem chính xác số phiên bản cùng dung lượng KB/MB trên đĩa và gỡ bỏ sạch sẽ gói không dùng chỉ với một chạm.","f5_badge":"Bộ lọc tìm trực tiếp &#183; Dung lượng đĩa chính xác &#183; Gỡ sạch sẽ","f6_title":"Bảo vệ thông minh cho gói khoa học &amp; extension native","f6_desc":"Gõ numpy, pandas, matplotlib, scipy hay scikit-learn trong PIP sẽ không gây lỗi trình biên dịch C/Fortran trên điện thoại &#8212; SuperCode tự động điều hướng sang các wheel khoa học dựng sẵn được cache trên thiết bị.","f6_badge":"Không lỗi build gcc &#183; Điều hướng gói khoa học dựng sẵn","workflow_title":"Từng bước: Cách dùng PIP &amp; wheel offline trong SuperCode","workflow_lead":"Cài gói PyPI online hoặc nạp file .whl offline chỉ trong dưới 30 giây.","wf1_title":"Mở Trình quản lý gói Visual PIP","wf1_desc":"Mở bất kỳ file .py nào và chạm vào biểu tượng PIP trên thanh tiêu đề console Python &#8212; hoặc chỉ cần chạy script có import chưa cài để kích hoạt Auto-PIP.","wf2_title":"Chạm chip phổ biến, dán pip install hoặc chọn requirements.txt","wf2_desc":"Chạm nhanh chip cài 1 chạm (requests, rich, beautifulsoup4, pyyaml, flask, telebot, colorama), nhập chuỗi phiên bản hoặc chạm vào banner requirements.txt tự phát hiện.","wf3_title":"Hoặc duyệt thư mục Tải xuống tìm gói .whl / .zip offline","wf3_desc":"Khi không có mạng, chạm Lưu trữ cục bộ trong hộp thoại PIP để quét thư mục Tải xuống hoặc thư mục dự án tìm file .whl, .tar.gz và .zip.","wf4_title":"Import ngay lập tức trên nhiều file script","wf4_desc":"Các thư viện đã cài được lưu bền vững trong thư mục site-packages riêng biệt qua các lần khởi động lại ứng dụng và hoạt động ngay với tự động hoàn thành AST.","wf_foot_note":"site-packages lưu bền vững trên máy &#183; Luồng log cài đặt không chặn 50ms","table_h2":"SuperCode Visual PIP so với trình cài gói di động truyền thống","snippet_p":"<strong>Trình quản lý gói Visual PIP của SuperCode</strong> giúp lập trình viên Android cài thư viện Python bên thứ ba không vướng rào cản terminal. Công cụ kết hợp phân giải gói PyPI, hơn 35 ánh xạ alias import tự động, cài hàng loạt requirements.txt trong workspace và nhập gói lưu trữ .whl/.tar.gz/.zip offline.","table_caption":"SO SÁNH QUẢN LÝ GÓI PYTHON TRÊN ANDROID","th_0":"Tính năng PIP","th_1":"SuperCode Python Studio","th_2":"Ứng dụng Python cơ bản","th_3":"Terminal CLI pip","th_4":"Notebook trực tuyến","tr1_c0":"Ánh xạ alias import","tr1_c1":"35+ ánh xạ tự động (bs4, yaml, pil, dotenv, jwt)","tr1_c2":"Phải tự tra cứu thủ công","tr1_c3":"Phải tự tra cứu thủ công","tr1_c4":"Gõ `!pip install` thủ công","tr2_c0":".whl / .zip offline","tr2_c1":"Trình quét bộ nhớ cục bộ tích hợp (0 Internet)","tr2_c2":"Hiếm khi hỗ trợ","tr2_c3":"Cờ đường dẫn file thủ công","tr2_c4":"Yêu cầu có mạng liên tục","tr3_c0":"requirements.txt","tr3_c1":"Tự phát hiện tới 6 thư mục cha + Chạy 1 chạm","tr3_c2":"Không hỗ trợ","tr3_c3":"Gõ `cd` + `pip -r` thủ công","tr3_c4":"Mất sạch mỗi phiên chạy","tr4_c0":"C-Extension khoa học","tr4_c1":"Tự chuyển sang wheel dựng sẵn đã cache","tr4_c2":"Lỗi nếu thiếu plugin trả phí","tr4_c3":"Lỗi khi biên dịch C/Fortran","tr4_c4":"Chỉ chạy trên cloud","tr5_c0":"Kiểm tra đĩa &amp; phiên bản","tr5_c1":"Tab Quản lý trực quan kèm dung lượng &amp; lọc tức thì","tr5_c2":"Thư mục bị ẩn","tr5_c3":"Chỉ hiện chữ `pip list`","tr5_c4":"Container tạm thời","faq_lead":"Giải đáp thắc mắc thường gặp về cài gói PyPI, wheel .whl offline và requirements.txt trên Android.","faq1_q":"Tôi có thể dán nguyên lệnh `pip install requests beautifulsoup4` vào SuperCode không?","faq1_a":"Có. Bộ phân tích đầu vào PIP tự động cắt bỏ các tiền tố `pip install`, `pip3 install` hoặc `python -m pip install`, bỏ qua an toàn các cờ CLI không hỗ trợ và đưa toàn bộ gói kèm ràng buộc PEP 440 vào hàng đợi cài đặt.","faq2_q":"Làm sao cài gói Python trên Android khi không có internet?","faq2_a":"Hãy tải trước file thuần Python `.whl` (ví dụ `*-py3-none-any.whl`), `.tar.gz` hoặc `.zip` về điện thoại, mở Trình quản lý gói PIP của SuperCode rồi chạm nút Lưu trữ cục bộ để cài thẳng từ thư mục Tải xuống.","faq3_q":"Tại sao tôi không cần tự chạy `pip install numpy` hay `matplotlib`?","faq3_a":"Các thư viện chứa C/Fortran extension nặng như NumPy, Pandas, SciPy, Matplotlib và Scikit-Learn đã được thích ứng sẵn trong runtime khoa học của SuperCode. Chỉ cần viết `import numpy as np` trong script rồi nhấn Chạy.","faq4_q":"Các gói PIP đã cài có còn trên điện thoại sau khi đóng ứng dụng không?","faq4_a":"Có. Mọi gói đã cài đều được lưu bền vững trong bộ nhớ `python_site_packages` cục bộ của SuperCode, giúp script của bạn chạy offline bất cứ lúc nào mà không cần cài lại.","cta_h2":"Quản lý gói Python trực quan ngay trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; tích hợp sẵn Auto-PIP, cài hàng loạt requirements.txt và hỗ trợ .whl offline."},"py_libraries":{"metaTitle":"Thư viện Python hỗ trợ trên Android — 250+ gói Offline, PyPI & Khoa học dữ liệu | SuperCode","metaDesc":"Khám phá danh sách đầy đủ các thư viện Python hỗ trợ trên Android trong SuperCode IDE: 200+ module chuẩn Python 3.11, wheel PyPI thuần Python, 60+ thư viện NumPy/Pandas/OpenCV/Scikit-Learn dựng sẵn và PyTorch.","hero_tag":"200+ STDLIB &#183; PYPI THUẦN PYTHON &#183; 60+ GÓI KHOA HỌC &amp; AI","hero_h1":"250+ <span class=\"text-gradient\">Thư viện Python sẵn sàng chạy</span> trên thiết bị Android của bạn.","hero_desc":"Trước khi chọn một <strong>ứng dụng lập trình Python</strong>, hãy kiểm tra xem thư viện nào thực sự import mượt trên di động. SuperCode kết hợp <strong>200+ module chuẩn Python 3.11</strong>, <strong>wheel PyPI thuần Python</strong>, <strong>60+ gói khoa học &amp; native dựng sẵn</strong> cùng tăng tốc cloud tùy chọn cho <strong>PyTorch/TensorFlow</strong>.","lib_s1":"Module Stdlib","lib_s2":"Khoa học &amp; Native","lib_s3":"Wheel thuần Python","lib_s4":"Định tuyến tầng thông minh","wb_eyebrow":"BÀN LÀM VIỆC TƯƠNG THÍCH THƯ VIỆN PYTHON ĐA TẦNG","sec_cap_title":"Phân loại đầy đủ các nhóm gói Python được hỗ trợ","sec_cap_lead":"SuperCode kiểm tra các câu lệnh import trong script và tự động điều phối thực thi &#8212; không cần quản lý môi trường ảo hay toolchain biên dịch.","f1_title":"200+ module chuẩn Python 3.11 tích hợp sẵn","f1_desc":"Mọi module cốt lõi chạy offline ngay lập tức: sqlite3, json, csv, re, pathlib, os, sys, math, statistics, collections, itertools, heapq, bisect, dataclasses, typing, asyncio, urllib, hashlib, hmac, tomllib, unittest, decimal, fractions, zipfile và tarfile.","f1_badge":"sqlite3 &#183; asyncio &#183; dataclasses &#183; tomllib &#183; unittest","f2_title":"Số học, DataFrame &amp; phân tích SQL dạng cột","f2_desc":"Thực hiện kỹ thuật dữ liệu chuyên sâu trên di động với numpy, scipy, sympy, mpmath, numexpr, pandas, polars, pyarrow, duckdb, fastparquet, h5py, netcdf4, xarray và zarr &#8212; được cache cục bộ để chạy offline.","f2_badge":"numpy &#183; pandas &#183; polars &#183; duckdb &#183; scipy &#183; sympy","f3_title":"Thư viện vẽ biểu đồ, trực quan hóa &amp; địa không gian","f3_desc":"Tạo biểu đồ DPI cao và bản đồ địa không gian bằng matplotlib, seaborn, bokeh, plotly, wordcloud, shapely, geopandas, pyproj và cartopy. Mọi file PNG, SVG hay PDF đã lưu đều đồng bộ thẳng vào thư mục dự án.","f3_badge":"matplotlib &#183; seaborn &#183; plotly &#183; wordcloud &#183; geopandas","f4_title":"Học máy, Thị giác máy tính, NLP &amp; Khoa học đồ thị","f4_desc":"Xây dựng và đánh giá mô hình với scikit-learn (sklearn), xgboost, lightgbm, statsmodels, joblib, opencv-python (cv2), Pillow (PIL), scikit-image, nltk, tiktoken, networkx và biopython.","f4_badge":"scikit-learn &#183; xgboost &#183; opencv-python &#183; Pillow &#183; nltk","f5_title":"Thu thập dữ liệu Web, API, Mã hóa, ORM &amp; Tài liệu Office","f5_desc":"Kết hợp wheel PIP và bộ phân tích native: requests, beautifulsoup4 (bs4), lxml, orjson, ujson, pydantic, regex, sqlalchemy, cryptography, bcrypt, pycryptodome, pynacl, flask, telebot, python-docx và python-pptx.","f5_badge":"requests &#183; bs4 &#183; lxml &#183; pydantic &#183; cryptography &#183; flask","f6_title":"Framework Deep Learning hạng nặng &amp; Cloud phân tán","f6_desc":"Khi script của bạn import torch (PyTorch), torchvision, tensorflow, keras, jax, onnxruntime hoặc pyspark, SuperCode đóng gói dự án đa file lên cụm cloud và trả về traceback dòng lỗi cục bộ có thể chạm để mở.","f6_badge":"PyTorch &#183; TensorFlow &#183; Keras &#183; JAX &#183; ONNX Runtime","workflow_title":"Cách SuperCode tự động định tuyến thư viện Python","workflow_lead":"Viết câu lệnh import Python chuẩn &#8212; SuperCode xử lý chọn runtime ở hậu trường.","wf1_title":"Thư viện chuẩn &amp; gói PIP đã cài chạy offline trong &lt;30ms","wf1_desc":"Script dùng thư viện chuẩn Python 3.11 hoặc wheel PIP thuần Python đã cài thực thi tức thì trong sandbox native cục bộ.","wf2_title":"Gói khoa học &amp; native kích hoạt wheel 3.12 đã cache","wf2_desc":"Việc import bất kỳ gói nào trong hơn 60 thư viện khoa học, thị giác hay mã hóa sẽ kích hoạt runtime khoa học trên thiết bị và cache cục bộ các wheel cần thiết.","wf3_title":"Framework Deep Learning đẩy sang cụm Cloud","wf3_desc":"Các framework nhiều gigabyte như PyTorch hay TensorFlow chạy từ xa mà không làm phình bộ nhớ điện thoại, vẫn giữ nguyên các lệnh import module cục bộ.","wf4_title":"Kết quả &amp; file đầu ra đồng bộ về thư mục của bạn","wf4_desc":"Biểu đồ, CSV, cơ sở dữ liệu SQLite và mô hình .pkl đã tuần tự hóa được tạo trong lúc chạy sẽ xuất hiện ngay trong thư mục dự án Android.","wf_foot_note":"Không cần tạo virtualenv thủ công &#183; Trình quét import bắc cầu tự động","table_h2":"Ma trận tham chiếu các tầng hỗ trợ thư viện Python","snippet_p":"<strong>SuperCode IDE cho Android</strong> hỗ trợ hơn 250 thư viện Python tích hợp sẵn và thích ứng trước cùng hàng nghìn gói PyPI thuần Python: module chuẩn Python 3.11, thư viện PIP/.whl offline, 60+ gói khoa học đã cache (NumPy, Pandas, Polars, DuckDB, Matplotlib, Scikit-Learn, OpenCV, Pydantic) và PyTorch/TensorFlow trên cloud.","table_caption":"CÁC TẦNG TƯƠNG THÍCH GÓI PYTHON TRÊN ANDROID CỦA SUPERCODE","th_0":"Lĩnh vực thư viện","th_1":"Gói tiêu biểu","th_2":"Chế độ thực thi","th_3":"Chạy offline?","th_4":"Đồng bộ file đầu ra","tr1_c0":"Stdlib Python 3.11","tr1_c1":"sqlite3, asyncio, json, csv, pathlib, tomllib, unittest","tr1_c2":"Python 3.11 trên thiết bị","tr1_c3":"100% Offline tích hợp sẵn","tr1_c4":"Đọc/ghi thư mục trực tiếp","tr2_c0":"Web, Bot &amp; Tài liệu","tr2_c1":"requests, bs4, flask, rich, pyyaml, telebot, python-docx","tr2_c2":"Visual PIP / .whl cục bộ","tr2_c3":"100% Offline sau khi cài","tr2_c4":"Đọc/ghi thư mục trực tiếp","tr3_c0":"Dữ liệu &amp; Biểu đồ","tr3_c1":"numpy, pandas, polars, duckdb, scipy, matplotlib, seaborn","tr3_c2":"Khoa học 3.12 trên thiết bị","tr3_c3":"Offline sau lần cache đầu","tr3_c4":"Tự động đồng bộ PNG/SVG/CSV","tr4_c0":"ML, Thị giác &amp; Mã hóa","tr4_c1":"scikit-learn, xgboost, cv2, Pillow, pydantic, cryptography","tr4_c2":"Khoa học 3.12 trên thiết bị","tr4_c3":"Offline sau lần cache đầu","tr4_c4":"Tự động đồng bộ .pkl &amp; ảnh","tr5_c0":"Deep Learning","tr5_c1":"torch (PyTorch), tensorflow, keras, jax, onnxruntime","tr5_c2":"Cụm Cloud Python","tr5_c3":"Yêu cầu kết nối mạng","tr5_c4":"Ánh xạ traceback 1:1","faq_lead":"Giải đáp về các gói Python cụ thể, bộ công cụ GUI và khả năng tương thích C-extension trên Android.","faq1_q":"Polars, DuckDB, Pydantic v2 và Cryptography có chạy được trên Android trong SuperCode không?","faq1_a":"Có. Khác với trình cài pip di động thông thường bị lỗi khi cố biên dịch extension Rust hoặc C trên điện thoại, SuperCode tích hợp sẵn nhị phân dựng trước cho polars, duckdb, pydantic, orjson, lxml và cryptography.","faq2_q":"Tôi có thể dùng cơ sở dữ liệu SQLite với Python trên Android không?","faq2_a":"Có &#8212; `sqlite3` được tích hợp sẵn trong thư viện chuẩn Python 3.11 offline, đồng thời `sqlalchemy` và `apsw` cũng được hỗ trợ. Tuyệt vời hơn, bạn có thể kiểm tra trực quan chính file `.db` đó trong SQL IDE của SuperCode.","faq3_q":"Còn các gói yêu cầu cửa sổ desktop X11 như Tkinter thì sao?","faq3_a":"Tạo biểu đồ headless (`matplotlib`, `seaborn`, `Pillow`, `opencv-python`) hoạt động mượt mà và lưu ảnh thẳng vào thư mục dự án để xem bằng Trình xem ảnh HD của SuperCode, còn giao diện web có thể dựng bằng `flask` hoặc Web IDE của SuperCode.","faq4_q":"Làm sao biết một gói PyPI có phải thuần Python để cài `.whl` offline không?","faq4_a":"Trên PyPI.org -&gt; Download files, bất kỳ file wheel nào kết thúc bằng `-py3-none-any.whl` đều là wheel thuần Python phổ quát, cài đặt 100% offline qua trình nhập Lưu trữ cục bộ của SuperCode.","cta_h2":"Chạy thư viện Python thực thụ trên điện thoại Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play để mở khóa 250+ module stdlib, PyPI, Khoa học dữ liệu và ML."},"py_data_science":{"metaTitle":"Ứng dụng Python Khoa học dữ liệu cho Android — NumPy, Pandas, DuckDB & Matplotlib Offline | SuperCode","metaDesc":"Phân tích dữ liệu và vẽ biểu đồ offline trên Android với SuperCode. Chạy NumPy, Pandas, Polars, DuckDB, SciPy, SymPy, Matplotlib và Seaborn trên điện thoại hoặc máy tính bảng với tự động đồng bộ PNG/SVG/PDF vào thư mục.","hero_tag":"NUMPY &#183; PANDAS &#183; POLARS &#183; DUCKDB &#183; MATPLOTLIB OFFLINE","hero_h1":"Studio <span class=\"text-gradient\">Python Khoa học dữ liệu, Pandas &amp; Matplotlib</span> bỏ túi cho Android.","hero_desc":"Phân tích tập dữ liệu CSV, JSON và SQLite thực thụ ở mọi nơi mà không cần khởi động notebook cloud. SuperCode cache <strong>NumPy, Pandas, Polars, DuckDB, SciPy và Matplotlib</strong> ngay trên thiết bị Android và đồng bộ mọi hình ảnh <strong><code>plt.savefig()</code></strong> thẳng vào workspace của bạn.","ds_s1":"&amp; SciPy / SymPy","ds_s2":"Polars &amp; DuckDB","ds_s3":"PNG &#183; SVG &#183; PDF","ds_s4":"Cache chạy offline","wb_eyebrow":"BÀN LÀM VIỆC DATAFRAME, DUCKDB &amp; MATPLOTLIB TƯƠNG TÁC","sec_cap_title":"Thiết kế cho Chuyên viên phân tích dữ liệu, Nhà nghiên cứu &amp; Sinh viên STEM","sec_cap_lead":"Từ giải tích ký hiệu trong SymPy đến câu lệnh JOIN đa bảng trong DuckDB và biểu đồ Matplotlib chuẩn xuất bản đều chạy native trên Android.","f1_title":"Pandas, Polars &amp; DuckDB trên tập dữ liệu cục bộ thực tế","f1_desc":"Đặt các file .csv, .tsv, .json, .db hoặc .sqlite3 vào thư mục dự án và truy vấn trực tiếp bằng pd.read_csv(), polars, pyarrow hoặc duckdb.sql(). Xuất file CSV đã làm sạch hay bảng SQLite thẳng về bộ nhớ.","f1_badge":"pandas &#183; polars &#183; duckdb &#183; pyarrow &#183; fastparquet","f2_title":"Tính toán khoa học với NumPy, SciPy &amp; SymPy","f2_desc":"Thực hiện đại số tuyến tính, xử lý tín hiệu FFT, tích phân số, tối ưu hóa và vi phân ký hiệu offline bằng numpy, scipy, sympy, mpmath, numexpr và pywavelets.","f2_badge":"Đại số ma trận &#183; FFT &#183; Giải tích ký hiệu &#183; .npy/.npz","f3_title":"Đồng bộ biểu đồ Matplotlib &amp; Seaborn không cần cấu hình","f3_desc":"Gọi plt.savefig('figure.png', dpi=200) hoặc xuất đồ thị vector .svg, .pdf &#8212; ngay cả khi quên gọi savefig(), các figure đang mở vẫn có thể được chụp và đồng bộ thẳng vào thư mục dự án để xem tức thì.","f3_badge":"matplotlib &#183; seaborn &#183; wordcloud &#183; Trình xem HD tích hợp","f4_title":"Kết nối liền mạch với Studio File GB &amp; SQL của SuperCode","f4_desc":"Có file log CSV thô 500 MB hay cơ sở dữ liệu SQLite đa bảng? Tiền xử lý các bản dump lớn bằng Thay thế Regex luồng toàn cục, kiểm tra schema trong SQL IDE và chạy pipeline Python Pandas ngay trong cùng workspace.","f4_badge":"Làm sạch Log GB + Trình khám phá SQL + Python Pandas","f5_title":"Tích hợp định dạng file Địa không gian &amp; Khoa học","f5_desc":"Làm việc với các định dạng nghiên cứu chuyên sâu trên máy tính bảng và điện thoại Android bằng geopandas, shapely, pyproj, h5py, netcdf4, xarray và zarr.","f5_badge":"geopandas &#183; shapely &#183; h5py &#183; xarray &#183; zarr","f6_title":"Chia màn hình ngang 55:45 trên tablet &amp; tự hoàn thành AST","f6_desc":"Trên máy tính bảng Android và điện thoại gập, viết phép biến đổi DataFrame ở khung 55% bên trái với gợi ý phương thức AST trong khi theo dõi bảng dữ liệu rộng ở console 45% bên phải.","f6_badge":"Thu phóng Console 7sp&#8211;26sp &#183; Hiển thị bảng rộng dễ đọc","workflow_title":"Cách phân tích dữ liệu &amp; xuất biểu đồ offline trên Android","workflow_lead":"Chu trình khoa học dữ liệu cục bộ hoàn chỉnh, không bị hết giờ Jupyter server hay rớt kết nối trình duyệt.","wf1_title":"Đưa file CSV, JSON hoặc SQLite vào dự án của bạn","wf1_desc":"Mở bất kỳ thư mục nào trên bộ nhớ Android chứa file `.csv`, `.json`, `.sqlite3` hoặc `.npy` &#8212; SuperCode tự động gắn các file dữ liệu đi kèm.","wf2_title":"Viết script NumPy, Pandas, DuckDB hoặc SymPy","wf2_desc":"Lần import thư viện khoa học đầu tiên sẽ cache các wheel nhị phân cục bộ trên điện thoại; mọi lần chạy sau đều hoạt động offline 100%.","wf3_title":"Chạy &amp; tự động đồng bộ hình DPI cao ra ổ đĩa","wf3_desc":"Chạm Chạy &#9654; để xem bảng tóm tắt trong console và tự động ghi file PNG, SVG, PDF hoặc CSV đã làm sạch vào thư mục của bạn.","wf4_title":"Kiểm tra biểu đồ bằng Trình xem Ảnh HD &amp; PDF tích hợp","wf4_desc":"Chạm vào file PNG hoặc PDF vừa tạo trong cây thư mục để phóng to sắc nét bằng hai ngón tay hoặc chia sẻ thẳng với đồng đội và báo cáo thí nghiệm.","wf_foot_note":"Cache wheel chạy offline &#183; Tự động làm mới cây dự án sau mỗi lần chạy","table_h2":"SuperCode Data Science Studio so với Cloud Notebook trên di động","snippet_p":"<strong>SuperCode IDE</strong> mang khoa học dữ liệu Python offline lên Android với khả năng chạy NumPy, SciPy, SymPy, Pandas, Polars, DuckDB, Matplotlib và Seaborn đã cache, truy cập trực tiếp file CSV/SQLite cục bộ và tự động đồng bộ biểu đồ DPI cao.","table_caption":"SO SÁNH KHOA HỌC DỮ LIỆU PYTHON TRÊN DI ĐỘNG","th_0":"Quy trình dữ liệu","th_1":"SuperCode Android Studio","th_2":"Cloud Notebook di động","th_3":"Ứng dụng Python cơ bản","th_4":"Chỉ dùng Laptop Desktop","tr1_c0":"Thực thi offline","tr1_c1":"NumPy, Pandas, DuckDB &amp; Matplotlib đã cache","tr1_c2":"Mất kết nối khi thiếu sóng","tr1_c3":"Chỉ có toán học Stdlib","tr1_c4":"Offline","tr2_c0":"Engine dữ liệu hiện đại","tr2_c1":"Pandas + Polars + DuckDB + PyArrow","tr2_c2":"Tùy thuộc từng container","tr2_c3":"Không hỗ trợ","tr2_c4":"Có hỗ trợ","tr3_c0":"Đồng bộ file &amp; biểu đồ cục bộ","tr3_c1":"Đọc/ghi thẳng thư mục Android + Trình xem HD","tr3_c2":"Tải lên/tải xuống thủ công","tr3_c3":"Sandbox tạm bị ẩn","tr3_c4":"Trực tiếp","tr4_c0":"Xử lý CSV thô khổng lồ","tr4_c1":"Phân trang file GB &amp; Thay thế Regex luồng tích hợp","tr4_c2":"Tràn bộ nhớ sập tab trình duyệt","tr4_c3":"Sập khi file &gt;20 MB","tr4_c4":"Cần thêm công cụ ngoài","tr5_c0":"Giao diện SQL Database","tr5_c1":"Tích hợp sẵn SQL Studio 9 chế độ","tr5_c2":"Không có","tr5_c3":"Không có","tr5_c4":"Ứng dụng DB riêng biệt","faq_lead":"Giải đáp về việc chạy NumPy, Pandas, Polars và Matplotlib offline trên điện thoại và máy tính bảng Android.","faq1_q":"NumPy và Pandas có thực sự chạy offline trên điện thoại Android của tôi không?","faq1_a":"Có. Sau khi runtime khoa học khởi tạo và cache wheel của gói (như `numpy`, `pandas` hoặc `matplotlib`) trên thiết bị, mọi lần chạy về sau đều thực thi 100% offline không cần internet.","faq2_q":"Làm sao để xem biểu đồ `matplotlib.pyplot` trên Android?","faq2_a":"Lưu biểu đồ bằng `plt.savefig('plot.png', dpi=180)` (hoặc `.svg` / `.pdf`). SuperCode đồng bộ file trực tiếp vào thư mục dự án đang mở và cho phép xem ngay bằng trình xem Ảnh hoặc PDF độ phân giải cao tích hợp sẵn.","faq3_q":"Script Pandas có đọc được file `.csv` hay `.sqlite` nằm cùng thư mục không?","faq3_a":"Có. Các đường dẫn tương đối như `pd.read_csv('sales.csv')` hay `sqlite3.connect('app.db')` phân giải trực tiếp theo workspace dự án của bạn, và mọi file bị sửa đổi hoặc mới tạo sẽ tự đồng bộ lại khi chạy xong.","faq4_q":"Ngoài Pandas thì Polars và DuckDB có được hỗ trợ không?","faq4_a":"Có &#8212; cả `polars` lẫn `duckdb` (cùng `pyarrow` và `fastparquet`) đều được hỗ trợ để thực hiện các truy vấn phân tích tốc độ cao trên di động.","cta_h2":"Phân tích dữ liệu &amp; vẽ biểu đồ mọi nơi trên Android.","cta_desc":"Cài miễn phí SuperCode IDE trên Google Play và chạy NumPy, Pandas, DuckDB cùng Matplotlib ngay trong túi bạn."},"py_machine_learning":{"metaTitle":"Ứng dụng Python Machine Learning cho Android — Scikit-Learn, OpenCV, XGBoost & PyTorch | SuperCode","metaDesc":"Xây dựng và kiểm thử dự án Python Machine Learning và thị giác máy tính trên Android. Chạy ngoại tuyến Scikit-Learn, XGBoost, LightGBM, OpenCV (cv2), Pillow và NLTK, kèm tăng tốc đám mây PyTorch & TensorFlow.","hero_tag":"SCIKIT-LEARN &#183; XGBOOST &#183; OPENCV (CV2) &#183; TĂNG TỐC ĐÁM MÂY PYTORCH","hero_h1":"Xây dựng Pipeline <span class=\"text-gradient\">Machine Learning &amp; Thị giác OpenCV</span> trên Android.","hero_desc":"Tạo nguyên mẫu bộ phân loại ML, cây tăng cường gradient và bộ lọc thị giác máy tính mọi lúc mọi nơi. Huấn luyện ngoại tuyến <strong>Scikit-Learn, XGBoost, LightGBM và OpenCV (<code>cv2</code>)</strong> trên thiết bị, đồng thời đẩy các kiến trúc <strong>PyTorch hoặc TensorFlow</strong> nặng lên đám mây mà không tốn dung lượng lưu trữ.","ml_s1":"XGBoost &amp; LightGBM","ml_s2":"OpenCV &amp; Pillow","ml_s3":"Đồng bộ mô hình Joblib","ml_s4":"Tăng tốc Tensor đám mây","wb_eyebrow":"MÔI TRƯỜNG LÀM VIỆC SCIKIT-LEARN, OPENCV &amp; PYTORCH NGOẠI TUYẾN","sec_cap_title":"Kiến trúc Lai Thiết bị + Đám mây cho Kỹ sư AI &amp; Sinh viên","sec_cap_lead":"Huấn luyện ML cổ điển và pipeline xử lý ảnh 100% ngoại tuyến, chỉ mở rộng lên các framework học sâu nhiều GB khi mã nguồn của bạn import chúng.","f1_title":"Scikit-Learn, XGBoost &amp; LightGBM Ngoại tuyến","f1_desc":"Chạy phân loại, hồi quy, phân cụm, PCA, kiểm chứng chéo và gradient boosting hoàn toàn ngoại tuyến với scikit-learn, xgboost, lightgbm, statsmodels và patsy.","f1_badge":"RandomForest &#183; XGBoost &#183; LightGBM &#183; Kiểm chứng chéo","f2_title":"Studio Thị giác OpenCV (cv2), Pillow &amp; Scikit-Image","f2_desc":"Tải ảnh PNG/JPEG từ thư mục workspace, áp dụng phân ngưỡng, phát hiện biên Canny, đường viền, bộ lọc hình thái học hoặc ghép ảnh Pillow và xem ngay ảnh đầu ra.","f2_badge":"opencv-python (cv2) &#183; Pillow (PIL) &#183; scikit-image","f3_title":"Bộ tách từ NLP, ML Đồ thị &amp; Tin sinh học","f3_desc":"Thử nghiệm đếm token LLM qua tiktoken, xử lý văn bản với nltk và regex, độ trung tâm đồ thị trong networkx và phân tích trình tự với biopython.","f3_badge":"tiktoken &#183; nltk &#183; networkx &#183; biopython","f4_title":"Tuần tự hóa mô hình Joblib &amp; Pickle ra thư mục","f4_desc":"Lưu các mô hình đã huấn luyện và mảng tiền xử lý qua joblib.dump('model.pkl') hoặc np.save('features.npy') trực tiếp vào thư mục Android cục bộ để tái sử dụng giữa các script.","f4_badge":"joblib.dump &#183; Lưu trữ .pkl / .npy / .npz","f5_title":"Tăng tốc Đám mây PyTorch, TensorFlow &amp; JAX Không Phình Dung lượng","f5_desc":"Khi import torch, tensorflow, keras, jax hoặc onnxruntime (hoặc thêm `# @cloud` ở đầu tệp), workspace đa tệp của bạn được đóng gói lên cụm đám mây &#8212; tiết kiệm hơn 4 GB bộ nhớ điện thoại.","f5_badge":"PyTorch &#183; TensorFlow &#183; Keras &#183; ONNX &#183; # @cloud","f6_title":"Quản lý phiên bản thử nghiệm với Visual Git &amp; SFTP","f6_desc":"Commit các mô-đun Python trích xuất đặc trưng qua Visual Git tích hợp, hoặc sửa trực tiếp script huấn luyện trên máy trạm GPU Linux qua SFTP với khóa SSH AES-256.","f6_badge":"Commit Visual Git + Đồng bộ trực tiếp máy chủ GPU qua SFTP","workflow_title":"Cách tạo nguyên mẫu mô hình ML &amp; Thị giác máy tính trên Android","workflow_lead":"Chuyển đổi mượt mà từ khám phá dữ liệu cục bộ sang lưu mô hình và chạy trên máy chủ GPU từ xa.","wf1_title":"Chuẩn bị Đặc trưng &amp; Hình ảnh trong Workspace","wf1_desc":"Tải tệp CSV dạng bảng bằng Pandas hoặc đọc ảnh cục bộ với `cv2.imread()` và `PIL.Image.open()` ngay từ thư mục dự án.","wf2_title":"Huấn luyện &amp; Kiểm chứng chéo mô hình ML cổ điển ngoại tuyến","wf2_desc":"Khớp pipeline Scikit-Learn hoặc mô hình XGBoost ngoại tuyến, in báo cáo phân loại và xuất biểu đồ ROC/ma trận nhầm lẫn qua Matplotlib.","wf3_title":"Kiểm thử kiến trúc Mạng nơ-ron qua Tăng tốc Đám mây","wf3_desc":"Xác minh kích thước tensor, lượt truyền xuôi `nn.Module` tùy chỉnh và hàm mất mát với traceback ánh xạ 1:1 tới tệp và số dòng cục bộ.","wf4_title":"Đẩy mã nguồn sạch lên GitHub hoặc máy chủ GPU","wf4_desc":"Đẩy các thử nghiệm đã xác thực lên GitHub qua Visual Git hoặc đồng bộ trực tiếp tới máy huấn luyện Linux từ xa qua SFTP.","wf_foot_note":"ML Cổ điển &amp; Thị giác Ngoại tuyến &#183; Kho khóa SSH SFTP cho Máy chủ GPU Từ xa","table_h2":"Quy trình AI/ML trên SuperCode so với Các ứng dụng Lập trình Di động Khác","snippet_p":"<strong>SuperCode IDE</strong> hỗ trợ phát triển Python Machine Learning và thị giác máy tính trên Android, chạy ngoại tuyến Scikit-Learn, XGBoost, LightGBM, OpenCV (`cv2`), Pillow, NLTK và Tiktoken cùng thực thi PyTorch, TensorFlow trên đám mây và chỉnh sửa GPU từ xa qua SFTP.","table_caption":"SO SÁNH IDE MACHINE LEARNING &amp; THỊ GIÁC MÁY TÍNH TRÊN ANDROID","th_0":"Tính năng AI / ML","th_1":"SuperCode Python Studio","th_2":"Ứng dụng Code Phổ thông","th_3":"Colab trên Trình duyệt Điện thoại","th_4":"Chỉ Terminal SSH","tr1_c0":"ML Cổ điển Ngoại tuyến","tr1_c1":"Scikit-Learn, XGBoost, LightGBM &amp; Joblib","tr1_c2":"Không hỗ trợ","tr1_c3":"Cần kết nối mạng liên tục","tr1_c4":"Bắt buộc có máy chủ từ xa","tr2_c0":"Thị giác Máy tính","tr2_c1":"OpenCV (cv2), Pillow &amp; Scikit-Image ngoại tuyến","tr2_c2":"Không hỗ trợ","tr2_c3":"Tải ảnh lên chậm","tr2_c4":"Không xem trước được ảnh trực tiếp","tr3_c0":"Học sâu (Deep Learning)","tr3_c1":"Tăng tốc Đám mây PyTorch &amp; TensorFlow (0 GB cồng kềnh)","tr3_c2":"Không có hoặc nặng nhiều GB","tr3_c3":"Tab trình duyệt hay tải lại","tr3_c4":"Phải tự có máy chủ GPU","tr4_c0":"Công cụ LLM &amp; NLP","tr4_c1":"tiktoken, nltk, regex, pydantic, orjson","tr4_c2":"Thiếu wheel Rust/C","tr4_c3":"Phải `!pip install` thủ công","tr4_c4":"Cài đặt thủ công","tr5_c0":"Chỉnh sửa GPU Từ xa","tr5_c1":"Đồng bộ Tab SFTP gốc + Visual Git","tr5_c2":"Không có","tr5_c3":"Không có","tr5_c4":"Vim/Nano CLI khi mạng giật lag","faq_lead":"Giải đáp về việc chạy Scikit-Learn, OpenCV, PyTorch và quy trình GPU từ xa trên Android.","faq1_q":"Tôi có thể chạy Scikit-Learn, XGBoost và OpenCV (`cv2`) khi không có internet không?","faq1_a":"Có. Sau khi được runtime khoa học của SuperCode lưu đệm trên thiết bị, `scikit-learn`, `xgboost`, `lightgbm`, `opencv-python` (`cv2`), `Pillow` và `scikit-image` chạy hoàn toàn ngoại tuyến.","faq2_q":"Làm sao để chạy mã PyTorch hoặc TensorFlow mà không làm đầy bộ nhớ điện thoại?","faq2_a":"Chỉ cần `import torch` hoặc `import tensorflow as tf` (hoặc đặt `# @cloud` ở dòng 1). SuperCode sẽ đóng gói các mô-đun `.py` cục bộ, thực thi trên cụm Python đám mây và ánh xạ mọi traceback trực tiếp về đúng dòng trong trình soạn thảo của bạn.","faq3_q":"Tôi có thể sửa và kích hoạt script trên máy trạm GPU Linux riêng của mình không?","faq3_a":"Có. Kết nối máy trạm qua workspace SFTP của SuperCode (hỗ trợ khóa SSH Ed25519/RSA mã hóa AES-256) để chỉnh sửa tệp `.py` và cấu hình `.yaml` từ xa với gợi ý AST đầy đủ và lưu nguyên tử 3 pha.","faq4_q":"`cv2.imwrite()` có lưu ảnh đã xử lý vào thư mục của tôi không?","faq4_a":"Có &#8212; mọi ảnh được ghi qua `cv2.imwrite()` hoặc `Image.save()` đều đồng bộ thẳng vào thư mục dự án và mở xem mượt mà trong Trình xem ảnh tích hợp của SuperCode.","cta_h2":"Tạo nguyên mẫu Mô hình Machine Learning &amp; Thị giác Mọi Nơi.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play để dùng Scikit-Learn, OpenCV, tăng tốc PyTorch và quy trình GPU qua SFTP."},"py_automation":{"metaTitle":"Ứng dụng Lập trình Python Web Scraping, API & Bot Telegram cho Android | SuperCode","metaDesc":"Xây dựng trình thu thập dữ liệu web, REST API client, bot Telegram và script tự động hóa văn phòng bằng Python trên Android. Hỗ trợ Requests, BeautifulSoup4, lxml, Pydantic, Flask, Telebot, SQLite3 và python-docx.","hero_tag":"REQUESTS &#183; BEAUTIFULSOUP4 &#183; LXML &#183; PYDANTIC &#183; TELEBOT &#183; FLASK","hero_h1":"Tự động hóa <span class=\"text-gradient\">Web Scraping, REST API &amp; Bot</span> bằng Python trên Android.","hero_desc":"Biến điện thoại thành trung tâm điều khiển tự động hóa linh hoạt. Cào dữ liệu HTML/XML với <strong>Requests, BeautifulSoup4 và lxml</strong>, xác thực API bằng <strong>Pydantic và orjson</strong>, tạo nguyên mẫu <strong>bot Telegram &amp; route Flask</strong>, rồi triển khai thẳng lên production qua <strong>SFTP hoặc Visual Git</strong>.","au_s1":"Requests &amp; lxml","au_s2":"orjson &amp; .env","au_s3":"Telebot &amp; WebSocket","au_s4":"Triển khai lên Linux VPS","wb_eyebrow":"MÔI TRƯỜNG TỰ ĐỘNG HÓA WEB SCRAPING, PYDANTIC API &amp; SQLITE","sec_cap_title":"Viết Script Python Thực tế &amp; Tạo nguyên mẫu Backend trên Di động","sec_cap_lead":"Cài thư viện tự động hóa chỉ với một chạm, kiểm thử với API thực tế hoặc tệp cục bộ, rồi đẩy lên VPS đám mây mà không cần mở laptop.","f1_title":"Phân tích cú pháp gốc với Requests, BeautifulSoup4 &amp; lxml","f1_desc":"Tải trang web và nguồn XML/RSS với requests và urllib, phân tích bộ chọn DOM phức tạp bằng beautifulsoup4 (bs4) và lxml biên dịch sẵn, rồi xuất dữ liệu JSON hoặc CSV có cấu trúc thẳng vào thư mục.","f1_badge":"requests &#183; beautifulsoup4 &#183; lxml &#183; Bộ chọn CSS","f2_title":"Pydantic v2, orjson, PyJWT &amp; Quản lý bí mật .env an toàn","f2_desc":"Xác thực chặt chẽ schema webhook và REST API bằng pydantic, tuần tự hóa hàng triệu bản ghi JSON với orjson/ujson, ký token qua PyJWT và cryptography, đồng thời nạp thông tin xác thực gọn gàng từ tệp .env qua python-dotenv.","f2_badge":"pydantic &#183; orjson &#183; PyJWT &#183; cryptography &#183; dotenv","f3_title":"Bot Telegram, WebSocket &amp; Công cụ CLI Rich","f3_desc":"Chip PIP một chạm cài ngay telebot (pyTelegramBotAPI), rich và colorama &#8212; xây dựng handler bot tương tác, chẩn đoán DNS (dnspython) và bảng điều khiển terminal TrueColor ngay trên điện thoại.","f3_badge":"telebot &#183; websocket-client &#183; dnspython &#183; rich","f4_title":"SQLite3, SQLAlchemy &amp; Script Word / PowerPoint / PDF","f4_desc":"Tự động hóa tác vụ tài liệu nhàm chán ngay trên Android: tạo báo cáo .docx bằng python-docx, slide thuyết trình với python-pptx, phân tích PDF và truy vấn cơ sở dữ liệu SQLite cục bộ.","f4_badge":"sqlite3 &#183; sqlalchemy &#183; python-docx &#183; python-pptx","f5_title":"Trình định dạng API đa định dạng &amp; Radar Lỗi","f5_desc":"Cần kiểm tra payload API thô? SuperCode định dạng ngoại tuyến Python, JSON, XML, YAML, TOML, SQL và HTML chỉ bằng một chạm trong khi Radar Lỗi bắt lỗi cú pháp theo thời gian thực.","f5_badge":"Định dạng JSON / YAML / XML / Python ngoại tuyến","f6_title":"Triển khai VPS qua SFTP mượt mà &amp; Visual Git","f6_desc":"Khi bot hoặc dịch vụ Flask chạy ổn định cục bộ, hãy commit `.env.example` và `requirements.txt` bằng Visual Git hoặc tải thẳng lên VPS Ubuntu/Debian qua SFTP.","f6_badge":"Thử trên điện thoại -&gt; Triển khai VPS Production qua SFTP","workflow_title":"Từ nguyên mẫu Scraper hoặc Bot trên Di động tới Triển khai VPS","workflow_lead":"Xây dựng, kiểm thử, kiểm tra đầu ra và phát hành script Python production trong một IDE Android thống nhất.","wf1_title":"Chạm Chip Nhanh trong Trình quản lý PIP Trực quan","wf1_desc":"Cài đặt `requests`, `beautifulsoup4`, `rich`, `pyyaml`, `flask` hoặc `telebot` trong vài giây bằng các chip cài nhanh tích hợp sẵn.","wf2_title":"Lưu khóa API an toàn trong .env &amp; Chạy Script","wf2_desc":"Lưu API token trong tệp `.env` cục bộ (tự động gắn vào workspace) và theo dõi log Rich/ANSI được định dạng đẹp mắt trong console.","wf3_title":"Kiểm tra dữ liệu JSON, CSV hoặc SQLite đã xuất","wf3_desc":"Mở tệp `.json` hoặc `.csv` vừa tạo với định dạng đẹp 1 chạm, hoặc duyệt các bảng `.db` trong Trình khám phá SQL của SuperCode.","wf4_title":"Commit lên GitHub hoặc Đồng bộ tới Máy chủ Từ xa","wf4_desc":"Đẩy bản cập nhật lên kho lưu trữ hoặc sửa trực tiếp script systemd/bot trên máy chủ từ xa qua SFTP được mã hóa.","wf_foot_note":"Cửa sổ thực thi nhận biết mạng 120 giây &#183; Hiển thị Console ANSI TrueColor","table_h2":"SuperCode Automation Studio so với Trình chạy Script Cơ bản","snippet_p":"<strong>SuperCode IDE</strong> là ứng dụng lập trình tự động hóa Python, web scraping và phát triển bot toàn diện cho Android, kết hợp cài PIP 1 chạm (`requests`, `bs4`, `flask`, `telebot`, `rich`), hỗ trợ gốc `lxml`/`pydantic`/`orjson`, tích hợp `.env` và SQLite, cùng triển khai SFTP/Git tích hợp.","table_caption":"SO SÁNH CÔNG CỤ WEB SCRAPING &amp; TỰ ĐỘNG HÓA PYTHON TRÊN ANDROID","th_0":"Khả năng Tự động hóa","th_1":"SuperCode Python Studio","th_2":"Ứng dụng Chạy Snippet","th_3":"Web IDE Đám mây","th_4":"SSH Client Thuần túy","tr1_c0":"Trình phân tích HTML/XML","tr1_c1":"BeautifulSoup4 + lxml gốc biên dịch sẵn","tr1_c2":"Chỉ có Regex/html.parser","tr1_c3":"Bị IP mục tiêu chặn","tr1_c4":"Chỉ chạy phía máy chủ","tr2_c0":"JSON nhanh &amp; Schema","tr2_c1":"Pydantic v2 + orjson + ujson + PyJWT","tr2_c2":"Lỗi với wheel Rust","tr2_c3":"Có hỗ trợ","tr2_c4":"Tự thiết lập venv thủ công","tr3_c0":"Thư viện Bot &amp; CLI","tr3_c1":"Chip 1 chạm: telebot, requests, flask, rich","tr3_c2":"Thủ công hoặc không hỗ trợ","tr3_c3":"Container bị ngủ đông","tr3_c4":"Có hỗ trợ","tr4_c0":"Kiểm tra Payload","tr4_c1":"Trình định dạng JSON/YAML/XML + GUI SQL tích hợp","tr4_c2":"Văn bản thô không định dạng","tr4_c3":"Phải mở tab riêng","tr4_c4":"Dùng CLI jq/sqlite3","tr5_c0":"Triển khai VPS","tr5_c1":"SFTP/FTPS tích hợp + Visual Git Client","tr5_c2":"Phải sao chép dán mã ra ngoài","tr5_c3":"Dùng git CLI thủ công","tr5_c4":"Không kiểm thử ngoại tuyến được","faq_lead":"Giải đáp về web scraping, tệp `.env`, bot Telegram và triển khai script Python từ Android.","faq1_q":"`lxml` và `pydantic` có hoạt động cùng với `requests` và `beautifulsoup4` không?","faq1_a":"Có. Cả thư viện thuần Python (`requests`, `beautifulsoup4`, `telebot`, `rich`) lẫn các trình phân tích biên dịch (`lxml`, `pydantic`, `orjson`, `cryptography`) đều được hỗ trợ.","faq2_q":"Script Python của tôi có thể nạp biến từ tệp `.env` hoặc `config.yaml` không?","faq2_a":"Có. Trình phân giải workspace của SuperCode tự động gắn các tệp `.env`, `.yaml`, `.yml`, `.toml`, `.ini` và `.json` cùng với các mô-đun `.py` của bạn.","faq3_q":"Một trình cào dữ liệu hoặc bot poll có thể chạy trong console tương tác bao lâu?","faq3_a":"Script tương tác chạy tối đa trong cửa sổ thực thi 120 giây cho mỗi lần chạy cục bộ (có nút Dừng/Ngắt tức thì bất cứ lúc nào) để bạn kiểm thử an toàn lệnh gọi API, scraper và webhook bot mà không lo hao pin ngầm.","faq4_q":"Làm sao để chạy bot Telegram 24/7 sau khi kiểm thử xong trong SuperCode?","faq4_a":"Hãy xây dựng và gỡ lỗi các handler bot cục bộ trong SuperCode, sau đó dùng SFTP client hoặc Visual Git client tích hợp sẵn để đẩy dự án thẳng lên Linux VPS hoặc máy chủ đám mây để chạy 24/7.","cta_h2":"Xây dựng Scraper, API &amp; Bot Ngay Trên Điện Thoại.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play với chip PIP 1 chạm, hỗ trợ Pydantic/lxml và triển khai SFTP."},"py_workspace":{"metaTitle":"IDE Python Đa tệp cho Android — Thư mục Dự án, input() Tương tác, PEP 8 & Git | SuperCode","metaDesc":"Phát triển dự án Python đa tệp thực thụ trên Android. Định tuyến điểm vào main.py thông minh, gói PEP 420, lớp phủ bộ nhớ tab chưa lưu, console chia đôi input() tương tác, gợi ý AST, định dạng PEP 8 và Visual Git.","hero_tag":"GÓI ĐA TỆP &#183; ĐỊNH TUYẾN ĐIỂM VÀO THÔNG MINH &#183; PEP 8 &#183; VISUAL GIT","hero_h1":"Kiến trúc <span class=\"text-gradient\">Python Đa tệp</span> Thực thụ &amp; Git trên Android.","hero_desc":"Vượt xa trình nháp đơn tệp. SuperCode tự động phân giải <strong>gói <code>src/</code>, import tương đối và gốc <code>pyproject.toml</code></strong> &#8212; giúp bạn chỉnh sửa mô-đun phụ với <strong>gợi ý AST</strong>, bấm Chạy từ bất kỳ tab nào để khởi chạy <strong><code>main.py</code></strong> và đẩy commit qua <strong>Visual Git</strong>.","ws_s1":"Tệp / Workspace","ws_s2":"Điều phối main.py","ws_s3":"AST &amp; Radar Lỗi","ws_s4":"&amp; SFTP Tích hợp","wb_eyebrow":"WORKSPACE PYTHON ĐA MÔ-ĐUN &amp; MÔI TRƯỜNG KIỂM THỬ UNITTEST","sec_cap_title":"Trải nghiệm Dự án Python Chuẩn Desktop Tái thiết kế cho Cảm ứng","sec_cap_lead":"Mọi chi tiết của trình phân giải workspace Python trong SuperCode đều được thiết kế để loại bỏ sự rườm rà khi quản lý tệp trên di động.","f1_title":"Điều phối Điểm vào Thông minh từ Bất kỳ Tab nào đang mở","f1_desc":"Đang sửa `services/ledger.py` hoặc `models/user.py` không có khối chạy cấp cao nhất? Khi nhấn Chạy, hệ thống tự động dò lên gốc dự án (`pyproject.toml`, `requirements.txt`, `.git`) và thực thi `main.py`, `app.py`, `run.py` hoặc `src/main.py`.","f1_badge":"Sửa mô-đun phụ -&gt; Nhấn Chạy -&gt; Thực thi main.py","f2_title":"Lớp phủ Bộ nhớ Tab chưa lưu Trực tiếp &amp; Namespace PEP 420","f2_desc":"Chỉnh sửa ba tab `.py` đang mở và bấm Chạy ngay lập tức &#8212; SuperCode phủ trực tiếp bộ đệm trình soạn thảo chưa lưu trong bộ nhớ mà không làm bừa bộn thư mục `src/` bằng các tệp `__init__.py` rỗng.","f2_badge":"Chạy không độ trễ &#183; Gói Namespace ngầm định PEP 420","f3_title":"Console Hai khung Hỗ trợ input() Tương tác thực &amp; [EOF]","f3_desc":"Kiểm thử ứng dụng CLI với các lệnh gọi `input()` và `sys.stdin.readline()` tuần tự. Console tự động neo bên dưới mã nguồn trên điện thoại hoặc chia đôi 55%/45% trên máy tính bảng, kèm nút Dừng/Ngắt tức thì.","f3_badge":"Hàng đợi Stdin Không chặn &#183; Tín hiệu [EOF] &#183; Chia tỷ lệ 55:45","f4_title":"Gợi ý AST Ngoại tuyến, Định dạng PEP 8 &amp; Radar Lỗi","f4_desc":"Gõ `.` trên lớp và mô-đun để nhận gợi ý AST ngoại tuyến dưới một mili-giây, định dạng thụt lề chuẩn PEP 8 chỉ với một chạm và bắt lỗi trộn tab/khoảng trắng (`TabError`) hoặc thiếu dấu hai chấm qua Radar Lỗi trước khi chạy.","f4_badge":"Bộ máy Phạm vi AST &#183; PEP 8 1 chạm &#183; Radar TabError","f5_title":"Visual Git Độc lập &amp; Cỗ máy Thời gian 120 Commit","f5_desc":"Clone kho Python riêng tư trên GitHub/GitLab qua HTTPS PAT, tạo nhánh tính năng, xem diff tô màu cú pháp, giải quyết xung đột merge trực quan và đẩy commit mà không cần rời trình soạn thảo.","f5_badge":"Clone &#183; Nhánh &#183; Merge Trực quan &#183; Commit &amp; Push","f6_title":"Tìm tệp Mờ 50.000 nút &amp; Tìm kiếm Regex Toàn dự án","f6_desc":"Nhảy tới bất kỳ mô-đun `.py` nào trong monorepo khổng lồ chỉ trong tích tắc với trình tìm tệp mờ, hoặc tái cấu trúc tên hàm trên toàn dự án bằng tìm kiếm &amp; thay thế regex luồng.","f6_badge":"Nhảy tệp mờ &#183; Tái cấu trúc Regex toàn dự án","workflow_title":"Cách Clone, Tái cấu trúc, Kiểm thử &amp; Push Kho Python trên Android","workflow_lead":"Chu trình kỹ thuật phần mềm hoàn chỉnh ngay trên điện thoại hoặc máy tính bảng Android.","wf1_title":"Clone Kho GitHub hoặc Mở Cây Dự án Cục bộ","wf1_desc":"Clone qua HTTPS Personal Access Token hoặc mở bất kỳ thư mục nào trên bộ nhớ thiết bị &#8212; rác từ `.git`, `venv` và `__pycache__` được tự động bỏ qua khi quét.","wf2_title":"Chỉnh sửa Mô-đun với Gợi ý AST &amp; Thanh Ký tự 21 phím","wf2_desc":"Vuốt lên thanh ký tự 21 phím để nhập `:`, `-&gt;`, `_`, `()`, `[]` và `INDENT`, rồi chạm Định dạng để căn lề 4 khoảng trắng chuẩn PEP 8.","wf3_title":"Chạy Script Điểm vào hoặc Bộ Kiểm thử Đơn vị Ngoại tuyến","wf3_desc":"Thực thi `main.py` hoặc bộ kiểm thử `unittest` ngoại tuyến với thời gian phản hồi tính bằng mili-giây và điều hướng stack-trace chỉ bằng một chạm.","wf4_title":"Xem Diff Thống nhất, Commit &amp; Push lên Upstream","wf4_desc":"Kiểm tra từng dòng thay đổi trong Cỗ máy Thời gian Git, stage tệp và push gọn gàng về lại GitHub, GitLab hoặc Bitbucket.","wf_foot_note":"Hỗ trợ tới 250 tệp Workspace mỗi lần chạy &#183; Tự động làm mới bộ đệm bytecode 2,5 giây","table_h2":"Workspace Python Đa tệp SuperCode so với Trình nháp Di động","snippet_p":"<strong>SuperCode IDE</strong> mang lại khả năng hỗ trợ dự án Python đa tệp chuẩn desktop trên Android, với phân giải gốc `pyproject.toml`/`src/` tự động, điều phối điểm vào `main.py` thông minh, lớp phủ bộ nhớ tab chưa lưu, định dạng PEP 8, gợi ý AST và Visual Git tích hợp.","table_caption":"SO SÁNH IDE DỰ ÁN PYTHON ĐA TỆP TRÊN ANDROID","th_0":"Tính năng Kỹ thuật","th_1":"SuperCode Python Studio","th_2":"Ứng dụng Python Đơn tệp","th_3":"Cloud IDE trên Trình duyệt","th_4":"Trình soạn thảo CLI Terminal","tr1_c0":"Gốc Dự án &amp; src/","tr1_c1":"Tự phân giải pyproject.toml, src/ &amp; PEP 420","tr1_c2":"Chỉ hỗ trợ 1 script phẳng","tr1_c3":"Có hỗ trợ (chỉ khi có mạng)","tr1_c4":"Phải đặt PYTHONPATH thủ công","tr2_c0":"Chạy từ Mô-đun con","tr2_c1":"Điều phối Điểm vào Thông minh -&gt; Chạy main.py/app.py","tr2_c2":"Chạy nhầm tệp phụ trợ","tr2_c3":"Cần launch.json thủ công","tr2_c4":"Gõ lệnh CLI thủ công","tr3_c0":"Đa tab chưa lưu","tr3_c1":"Lớp phủ Bộ nhớ Trực tiếp trên Mọi Tab đang mở","tr3_c2":"Phải lưu từng tệp trước","tr3_c3":"Độ trễ tự động lưu","tr3_c4":"Chỉ trong bộ đệm","tr4_c0":"Công cụ Chất lượng Mã","tr4_c1":"Gợi ý AST + Định dạng PEP 8 + Radar TabError","tr4_c2":"Danh sách từ khóa cơ bản","tr4_c3":"Có hỗ trợ","tr4_c4":"Cần cài plugin LSP","tr5_c0":"Quản lý Phiên bản","tr5_c1":"Cỗ máy Thời gian Visual Git &amp; Giải quyết Xung đột","tr5_c2":"Không có","tr5_c3":"Giao diện Git web","tr5_c4":"Văn bản git merge CLI","faq_lead":"Giải đáp về cấu trúc `src/`, import tương đối, `unittest` và tích hợp Git cho Python trên Android.","faq1_q":"Điều gì xảy ra nếu tôi nhấn Chạy khi đang sửa mô-đun phụ trợ như `utils/helpers.py`?","faq1_a":"Nếu `helpers.py` chỉ định nghĩa hàm hoặc lớp mà không có mã thực thi cấp cao nhất, SuperCode tự động tìm script điểm vào của dự án (`main.py`, `app.py`, `run.py`, `__main__.py` hoặc `src/main.py`) và chạy toàn bộ ứng dụng.","faq2_q":"SuperCode có hỗ trợ cú pháp Python 3.12 như `match/case` và bí danh `type` không?","faq2_a":"Cấu trúc `match/case` và `tomllib` hoạt động ngoại tuyến trên Python 3.11+, và các tệp sử dụng cú pháp bí danh `type` generic PEP 695 sẽ tự động kích hoạt hỗ trợ Python 3.12.","faq3_q":"Tôi có cần `__init__.py` trong mọi thư mục để import đa thư mục hoạt động không?","faq3_a":"Không. SuperCode tuân thủ gói namespace ngầm định PEP 420 và gắn gốc dự án sạch sẽ mà không tự ý chèn các tệp `__init__.py` ngoài ý muốn vào kho mã của bạn.","faq4_q":"Tôi có thể clone kho GitHub riêng tư và chạy các bài kiểm thử Python ngoại tuyến không?","faq4_a":"Có. Clone qua HTTPS + Personal Access Token trong Visual Git, cài hàng loạt `requirements.txt` một lần, sau đó chỉnh sửa và chạy các bộ `unittest` hoàn toàn ngoại tuyến ở bất kỳ đâu.","cta_h2":"Xây dựng Dự án Python Đa tệp Thực thụ trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play để trải nghiệm Python đa mô-đun, công cụ PEP 8 và Visual Git."},"py_learn":{"metaTitle":"Ứng dụng code Python cho người mới & sinh viên — Học Python ngoại tuyến trên Android | SuperCode","metaDesc":"Thực hành và học Python ngoại tuyến trên Android không cần đăng nhập. SuperCode tích hợp 8 mẫu Python chạy ngay, console input() trực tiếp, thanh ký tự Python 21 phím, Error Radar và PIP/NumPy.","hero_tag":"KHÔNG CẦN ĐĂNG NHẬP &#183; CHẠY 100% CHẾ ĐỘ MÁY BAY &#183; 8 MẪU KHỞI ĐẦU","hero_h1":"<span class=\"text-gradient\">Ứng dụng code Python</span> được xây dựng để học &amp; thực hành mọi lúc mọi nơi.","hero_desc":"Đừng chỉ bấm thẻ trắc nghiệm &#8212; hãy viết và chạy <strong>mã Python 3 thực thụ</strong> ngay trên điện thoại. SuperCode khởi động chỉ trong vài mili-giây, <strong>không yêu cầu đăng ký</strong>, <strong>chạy ngoại tuyến 100%</strong>, đi kèm <strong>8 mẫu khởi đầu chạy ngay</strong>, <strong>thanh ký tự Python 21 phím</strong> và cảnh báo tức thì từ <strong>Error Radar</strong>.","ln_s1":"Khởi chạy ngoại tuyến tức thì","ln_s2":"Mẫu code chạy ngay","ln_s3":"Thanh ký tự vuốt lên","ln_s4":"Ngôn ngữ CNTT trong 1 ứng dụng","wb_eyebrow":"MÔI TRƯỜNG THỰC HÀNH PYTHON TƯƠNG TÁC TỪ CƠ BẢN ĐẾN CS101","sec_cap_title":"Vì sao sinh viên &amp; người tự học chọn viết code thật thay vì làm trắc nghiệm mô phỏng","sec_cap_lead":"Mọi bất tiện khi gõ Python trên màn hình điện thoại đều đã được giải quyết ngay từ tầng UI gốc.","f1_title":"Thực hành 100% ngoại tuyến ở chế độ máy bay &amp; không ép đăng nhập","f1_desc":"Mở ứng dụng trên tàu điện, xe buýt, giảng đường vùng xa hay trên máy bay và chạy Python ngay lập tức. Không bắt đăng ký email, không vòng xoay chờ hàng đợi cloud và hoàn toàn không tốn dữ liệu di động.","f1_badge":"Chạy ngoại tuyến mọi nơi &#183; Khởi động nguội tức thì","f2_title":"Thanh ký tự Python 21 phím hỗ trợ vuốt lên","f2_desc":"Bàn phím điện thoại thông thường giấu `:`, `_`, `[]`, `{}`, `=` và `Tab` sau ba lớp phím. Thanh ký tự công thái học của SuperCode đưa thụt lề thông minh 4 dấu cách, dấu hai chấm, ngoặc, dấu nháy và phím mũi tên lên ngay phía trên bàn phím.","f2_badge":"Chạm + Vuốt lên nhập ký tự phụ &#183; Thụt lề thông minh 4 dấu cách","f3_title":"Error Radar trực tiếp bắt sớm lỗi gõ sai cho người mới","f3_desc":"Quên dấu hai chấm `:` sau `if` hoặc `def`? Trộn dấu cách với tab (`TabError`)? Chưa đóng ngoặc `(`? Error Radar tô sáng chính xác dòng lỗi ngay trước khi bạn bấm Run, còn PEP 8 Format 1 chạm sẽ chỉnh gọn thụt lề lộn xộn.","f3_badge":"Cảnh báo thiếu dấu hai chấm &#183; Chống TabError &#183; Chuẩn hóa PEP 8 1 chạm","f4_title":"8 mẫu Python tích hợp sẵn &amp; hàm input() tương tác","f4_desc":"Nạp các ví dụ chạy được ngay từ thanh công cụ để xem cách hoạt động của biến, lời nhắc `input()`, hàm, OOP `@dataclass`, đọc/ghi tệp và thuật toán &#8212; sau đó tùy chỉnh mã và chạy lại tức thì.","f4_badge":"8 ví dụ chọn lọc &#183; input() nhiều lượt trực tiếp","f5_title":"Xuất code ra PDF A4 gốc để nộp bài tập","f5_desc":"Cần nộp mã nguồn định dạng gọn gàng cho bài thực hành đại học hoặc cổng chấm bài? Xuất trực tiếp mọi script Python từ menu trình soạn thảo thành tệp PDF A4 sắc nét có tô màu cú pháp và đánh số dòng.","f5_badge":"Xuất PDF A4 tô màu cú pháp &#183; Sẵn sàng nộp lớp học","f6_title":"Một ứng dụng 40,2 MB bao trọn toàn bộ chương trình học CNTT","f6_desc":"Bắt đầu với Python nhập môn hôm nay, rồi tiếp tục chinh phục con trỏ C17, cấu trúc dữ liệu C++20 STL, OOP Java 17, cơ sở dữ liệu SQL, bài lab web HTML/CSS/JS/PHP, Linux Shell và Git mà không cần cài bảy ứng dụng rời rạc.","f6_badge":"Python + C17 + C++20 + Java 17 + SQL + Web + Git","workflow_title":"Cách bắt đầu viết Python trên điện thoại trong 60 giây","workflow_lead":"Không cần cấu hình &#8212; cài đặt, chọn mẫu hoặc tệp trống rồi chạy ngay.","wf1_title":"Tạo script `.py` hoặc nạp ví dụ có sẵn","wf1_desc":"Cài SuperCode từ Google Play, tạo `hello.py` hoặc mở menu Ví dụ để nạp một trong 8 mẫu Python chạy ngay.","wf2_title":"Gõ mượt mà với thụt lề thông minh &amp; gợi ý tự động","wf2_desc":"Dùng thanh ký tự 21 phím cho `:`, `()` và `Tab`, trong khi gợi ý AST ngoại tuyến giúp bạn khám phá các phương thức Python ngay khi đang gõ.","wf3_title":"Chạy ngoại tuyến &amp; trả lời lời nhắc input() trực tiếp","wf3_desc":"Chạm Run &#9654; để xem kết quả sau vài mili-giây, nhập dữ liệu kiểm thử trực tiếp trên console gắn liền và xem thông báo lỗi rõ ràng theo từng dòng.","wf4_title":"Nâng cấp lên thư viện PIP, Khoa học dữ liệu &amp; GitHub","wf4_desc":"Khi kỹ năng tiến bộ, hãy cài gói PyPI, vẽ biểu đồ Matplotlib, xuất bài tập PDF A4 hoặc đẩy dự án cá nhân lên GitHub.","wf_foot_note":"8 giao diện Studio dịu mắt (Tối &amp; Sáng) &#183; 32 ngôn ngữ giao diện bản địa hóa","table_h2":"So sánh SuperCode với ứng dụng học kiểu trò chơi &amp; trình biên dịch trực tuyến","snippet_p":"<strong>SuperCode</strong> là ứng dụng viết code Python ngoại tuyến miễn phí trên Android dành cho người mới bắt đầu, sinh viên và người tự học lập trình. Khác với ứng dụng trắc nghiệm hoặc trình biên dịch chỉ chạy khi có mạng, ứng dụng cung cấp môi trường chạy Python 3.11/3.12 ngoại tuyến thực thụ, console `input()` trực tiếp, thanh công cụ lập trình 21 phím, Error Radar và xuất bài tập PDF A4 gốc.","table_caption":"HỌC PYTHON TRÊN ANDROID: SO SÁNH ỨNG DỤNG","th_0":"Nhu cầu học tập","th_1":"Ứng dụng code SuperCode","th_2":"Ứng dụng trắc nghiệm gamification","th_3":"Trình biên dịch web trực tuyến","th_4":"Chỉ dùng PC để bàn","tr1_c0":"Chạy code thực thụ","tr1_c1":"Python 3.11/3.12 ngoại tuyến đầy đủ + Đa tệp","tr1_c2":"Bài tập điền chỗ trống","tr1_c3":"Hộp chạy trực tuyến đơn tệp","tr1_c4":"Đầy đủ","tr2_c0":"Chạy không cần Wi-Fi","tr2_c1":"100% ngoại tuyến (Tàu điện, Xe buýt, Lớp học)","tr2_c2":"Yêu cầu gói cước/mạng","tr2_c3":"Lỗi khi mất mạng","tr2_c4":"Ngoại tuyến","tr3_c0":"Tốc độ gõ trên di động","tr3_c1":"Thanh vuốt lên 21 phím + AST + PEP 8 1 chạm","tr3_c2":"Gõ rất ít","tr3_c3":"Bàn phím mặc định điện thoại","tr3_c4":"Bàn phím vật lý","tr4_c0":"Giới hạn phát triển","tr4_c1":"PIP, NumPy, Pandas, OpenCV, SQL &amp; Git","tr4_c2":"Chạm trần sau phần cơ bản","tr4_c3":"Không có tệp cục bộ hay Git","tr4_c4":"Đầy đủ","tr5_c0":"Ngôn ngữ ngành CNTT","tr5_c1":"Gồm C, C++, Java 17, JS, PHP &amp; SQL","tr5_c2":"Khóa học trả phí tách rời","tr5_c3":"Nhiều tab trình duyệt","tr5_c4":"Nhiều IDE nặng nề","faq_lead":"Các câu hỏi thường gặp từ người mới học, sinh viên CNTT và giảng viên đứng lớp.","faq1_q":"SuperCode có phù hợp cho người mới hoàn toàn học Python trên điện thoại không?","faq1_a":"Có. Bạn không cần cấu hình trình biên dịch, đường dẫn hay tài khoản &#8212; chỉ cần tạo tệp `.py` (hoặc chọn một trong 8 ví dụ Python có sẵn) rồi chạm Run. Error Radar và tính năng định dạng PEP 8 1 chạm giúp người mới sửa lỗi gõ sai ngay lập tức.","faq2_q":"Tôi có thể luyện thuật toán LeetCode và cấu trúc dữ liệu ngoại tuyến không?","faq2_a":"Có. Toàn bộ mô-đun thuật toán chuẩn (`collections`, `heapq`, `bisect`, `itertools`, `functools`, `math`, `typing`) đều chạy ngoại tuyến 100% kèm số đo thời gian chạy theo mili-giây và bộ nhớ tiêu thụ.","faq3_q":"Giáo viên có thể dùng SuperCode trong lớp học khi sinh viên không có Wi-Fi không?","faq3_a":"Hoàn toàn được. Lõi Python 3.11 chạy ngoại tuyến ngay khi cài đặt, các gói `.whl` ngoại tuyến có thể chia sẻ nội bộ không cần internet, và sinh viên có thể xuất trực tiếp bài làm hoàn chỉnh sang tệp PDF A4 có tô màu cú pháp.","faq4_q":"SuperCode có hỗ trợ cả chế độ sáng lẫn chế độ tối để đọc ban ngày không?","faq4_a":"Có &#8212; SuperCode tích hợp 8 giao diện studio bảo vệ mắt (gồm cả giao diện sáng sắc nét và giao diện tối dịu mắt) cùng khả năng phóng to/thu nhỏ cỡ chữ trình soạn thảo và console.","cta_h2":"Bắt đầu hành trình học Python ngoại tuyến ngay hôm nay.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; không cần đăng nhập, kèm sẵn 8 mẫu Python."},"c_pointers_lab":{"metaTitle":"Học lập trình C ngoại tuyến trên Android — Phòng lab con trỏ, struct & malloc | SuperCode","metaDesc":"Học ANSI/GNU C17 ngoại tuyến trên Android không còn lỗi Turbo C  cổ lỗ. Thực hành con trỏ, struct, malloc/free, thao tác bit và  với 6 mẫu C cùng tính năng xuất PDF A4.","hero_tag":"CHUẨN GNU C17 THUẦN &#183; LAB CON TRỎ &amp; HEAP &#183; 6 MẪU TÍCH HỢP SẴN","hero_h1":"Học <span class=\"text-gradient\">Con trỏ C, Struct &amp; Bộ nhớ động</span> ngoại tuyến trên Android.","hero_desc":"Đừng vật lộn với các ứng dụng Turbo C thập niên 1990 dùng <code>&lt;conio.h&gt;</code> dạy sai cú pháp chuẩn. SuperCode mang đến cho sinh viên CNTT phòng lab <strong>GNU C17 ngoại tuyến (<code>-std=gnu17</code>)</strong> thực thụ với liên kết tự động <strong><code>&lt;math.h&gt;</code> (<code>-lm</code>)</strong>, <strong>6 mẫu C chạy ngay</strong>, <strong>gợi ý thành viên struct qua <code>-&gt;</code> bằng AST</strong> và <strong>xuất bài tập PDF A4</strong> 1 chạm.","cp1_s1":"Chuẩn -std=gnu17 thuần","cp1_s2":"Mẫu lab C có sẵn","cp1_s3":"Tự động liên kết math.h","cp1_s4":"Xuất bài lab PDF","wb_eyebrow":"BÀN THỰC HÀNH C17 TƯƠNG TÁC: CON TRỎ, STRUCT &amp; MATH.H","sec_cap_title":"Thiết kế chuyên biệt cho môn Nhập môn Lập trình, Nguyên lý Hệ thống &amp; Lab Nhúng","sec_cap_lead":"Mọi chi tiết đều được tinh chỉnh để sinh viên viết mã ISO/GNU C17 chuẩn đại học ngay trên điện thoại hoặc máy tính bảng&#8212;ngay cả trong giảng đường không có Wi-Fi.","f1_title":"GNU C17 hiện đại &#8212; Không còn bẫy Turbo C lỗi thời","f1_desc":"Nhiều ứng dụng C trên Play Store giả lập Turbo C thời DOS (void main(), clrscr(), getch(), kiểu int 16-bit) khiến bài nộp bị máy chấm đại học đánh trượt. SuperCode biên dịch đúng chuẩn GNU C17 64-bit (-std=gnu17) khớp hoàn toàn với máy chủ lab Linux.","f1_badge":"-std=gnu17 &#183; Con trỏ 64-bit &#183; Chuẩn máy chấm tự động","f2_title":"6 mẫu C chạy ngay ngay trên thanh công cụ","f2_desc":"Mở bài lab chạy được chỉ với một chạm: pointers.c (cơ chế địa chỉ &amp; giải tham chiếu), structs.c (kiểu bản ghi tổ hợp), bitwise.c (mặt nạ bit &amp; dịch bit), sinewave.c (DSP lượng giác), echo.c (stdin) và hello.c.","f2_badge":"pointers.c &#183; structs.c &#183; bitwise.c &#183; sinewave.c &#183; echo.c","f3_title":"Hoàn tất thành viên Struct -&gt; và . bằng AST","f3_desc":"Đang cài đặt danh sách liên kết đơn/đôi, cây nhị phân hay header gói tin? Gõ node-&gt; hoặc record. để xem chính xác các trường struct và union ngoại tuyến mà không cần học vẹt tên từng thành viên.","f3_badge":"node-&gt;next &#183; record.field &#183; Bộ máy AST ngoại tuyến","f4_title":"Tự động liên kết -lm (&lt;math.h&gt;) &amp; thư viện chuẩn","f4_desc":"Gọi sin(), cos(), sqrt(), pow(), hypot() và fma() từ &lt;math.h&gt; cùng &lt;stdlib.h&gt;, &lt;stdint.h&gt;, &lt;stdbool.h&gt; và &lt;inttypes.h&gt; mà không bao giờ phải gõ thủ công cờ liên kết gcc -lm.","f4_badge":"&lt;math.h&gt; tự liên kết &#183; &lt;stdint.h&gt; &#183; &lt;stdlib.h&gt;","f5_title":"Thanh ký tự C 21 phím &amp; Error Radar thời gian thực","f5_desc":"Chèn -&gt;, *, &amp;, {}, [], ;, #include và != chỉ bằng một thao tác vuốt lên. Khi bạn đang gõ, Error Radar phát hiện ngay ngoặc nhọn lệch cặp, token thừa và #include sai cú pháp trước cả khi biên dịch.","f5_badge":"Thanh vuốt lên 21 phím &#183; Error Radar trực tiếp &#183; Định dạng 1 chạm","f6_title":"Xuất bài tập PDF A4 tô màu cú pháp","f6_desc":"Hoàn thành bài tập danh sách liên kết hay cấp phát bộ nhớ động? Xuất trực tiếp mã nguồn .c sang tệp PDF A4 sắc nét, có tô màu cú pháp và đánh số dòng sẵn sàng nộp lên Canvas, Moodle hay Google Classroom.","f6_badge":"PDF A4 gốc &#183; Đánh số dòng &#183; Không hình mờ","workflow_title":"Cách thực hành con trỏ C &amp; bài lab ngoại tuyến","workflow_lead":"Đi từ màn hình trống đến tệp thực thi C17 chuẩn xác và báo cáo PDF định dạng đẹp chỉ trong bốn bước.","wf1_title":"Chọn mẫu C17 có sẵn hoặc tạo tệp .c mới","wf1_desc":"Mở pointers.c, structs.c, bitwise.c hoặc sinewave.c từ thanh công cụ C&#8212;không cần đăng ký tài khoản hay kết nối mạng.","wf2_title":"Viết logic con trỏ &amp; struct nhanh như máy tính","wf2_desc":"Dùng các phím chuyên dụng *, &amp;, -&gt; kết hợp gợi ý thành viên struct AST ngoại tuyến để cấp phát và duyệt các nút trên heap.","wf3_title":"Biên dịch ngoại tuyến &amp; kiểm tra thông số bộ nhớ","wf3_desc":"Chạm Run để biên dịch chặt chẽ theo chuẩn C17 (không ép qua C++) và kiểm tra đầu ra, mã thoát, thời gian chạy (&#181;s/ms) cùng đỉnh bộ nhớ KB.","wf4_title":"Tự định dạng chuẩn K&amp;R/Allman &amp; xuất PDF A4","wf4_desc":"Làm gọn thụt lề chỉ bằng một chạm và xuất phiếu bài lab PDF A4 sẵn sàng in ấn ngay từ thiết bị Android của bạn.","wf_foot_note":"C17 100% chế độ máy bay &#183; Tách biệt khỏi name-mangling của C++ &#183; 8 giao diện dịu mắt","table_h2":"So sánh SuperCode C17 Lab với các ứng dụng C di động kiểu cũ","snippet_p":"<strong>Phòng lab lập trình C17 ngoại tuyến của SuperCode</strong> giúp sinh viên học con trỏ C, struct, cấp phát bộ nhớ động (<code>malloc</code> và <code>free</code>) cùng các phép toán bit trên Android mà không cần mẹo vá lỗi kiểu Turbo C lỗi thời. Nền tảng kết hợp chuẩn GNU C17 thuần và tự động liên kết <code>math.h</code> với sáu mẫu khởi đầu, gợi ý struct bằng AST và xuất bài tập PDF A4.","table_caption":"SO SÁNH TRÌNH BIÊN DỊCH HỌC TẬP &amp; LÀM BÀI TẬP C TRÊN ANDROID","th_0":"Yêu cầu môn học","th_1":"SuperCode C17 Studio","th_2":"Ứng dụng Turbo C cũ kỹ","th_3":"Trình biên dịch web trực tuyến","th_4":"Thiết lập terminal thô","tr1_c0":"Chuẩn ngôn ngữ C","tr1_c1":"GNU C17 64-bit thuần (-std=gnu17)","tr1_c2":"&lt;conio.h&gt; 16-bit phi chuẩn","tr1_c3":"Tùy thuộc máy chủ web","tr1_c4":"Phải tự gõ cờ cấu hình","tr2_c0":"Liên kết &lt;math.h&gt;","tr2_c1":"Tự động thêm -lm mặc định","tr2_c2":"Lỗi hoặc thiếu hàm toán học C99/C17","tr2_c3":"Thường phải tự tích chọn","tr2_c4":"Báo lỗi nếu thiếu `-lm` thủ công","tr3_c0":"Hỗ trợ Con trỏ &amp; Struct","tr3_c1":"Gợi ý AST -&gt; / . + Thanh 21 phím","tr3_c2":"Gõ bàn phím thường","tr3_c3":"Ô nhập liệu trình duyệt","tr3_c4":"Không có thanh ký tự cảm ứng","tr4_c0":"Mẫu khởi đầu","tr4_c1":"Tích hợp sẵn 6 bài lab C chạy ngay","tr4_c2":"Đoạn code `clrscr()` lỗi thời","tr4_c3":"Một khung hello-world duy nhất","tr4_c4":"Không có","tr5_c0":"Nộp bài tập","tr5_c1":"PDF A4 gốc tô màu cú pháp","tr5_c2":"Chỉ chụp ảnh màn hình","tr5_c3":"Sao chép dán sang máy tính","tr5_c4":"Chỉ có văn bản `.c` thuần","faq_lead":"Giải đáp cho sinh viên chuyển từ Turbo C, luyện malloc/free hoặc nộp bài lab C ở đại học.","faq1_q":"Vì sao tôi không nên dùng `&lt;conio.h&gt;`, `clrscr()` hay `getch()` khi học C?","faq1_a":"`&lt;conio.h&gt;` là tệp tiêu đề MS-DOS phi chuẩn từ thập niên 1980 và bị mọi máy chủ chấm bài Linux, macOS cũng như trường đại học hiện đại từ chối. SuperCode biên dịch chuẩn ISO/GNU C17 (`&lt;stdio.h&gt;`, `&lt;stdlib.h&gt;`, `getchar()`, `fgets()`) để mọi kiến thức bạn học đều dùng trực tiếp được trong kỳ thi và công việc lập trình hệ thống.","faq2_q":"SuperCode có biên dịch tệp `.c` bằng trình biên dịch C thực thụ thay vì C++ không?","faq2_a":"Có. Trong C, `malloc()` trả về `void *` có thể ép kiểu ngầm sang con trỏ định kiểu mà không cần cast, trong khi C++ sẽ báo lỗi. SuperCode biên dịch tệp `.c` bằng chuẩn GNU C17 chuyên biệt (`-std=gnu17`) để mọi cú pháp C17 hợp lệ hoạt động trơn tru.","faq3_q":"Tôi có cần tự truyền cờ `-lm` khi dùng `sqrt()`, `pow()` hoặc `sin()` không?","faq3_a":"Không. SuperCode tự động liên kết thư viện toán học chuẩn (`-lm`) trong mọi lần build C17, nên các hàm `&lt;math.h&gt;` chạy được ngay lập tức.","faq4_q":"Điều gì xảy ra nếu tôi vô tình giải tham chiếu con trỏ lỗi hoặc viết vòng lặp vô hạn `while(1)`?","faq4_a":"Phiên làm việc của trình soạn thảo vẫn hoàn toàn an toàn: tiến trình con chạy tách biệt sẽ báo rõ mã lỗi thoát khi gặp sự cố, và bộ giám sát CPU 20 giây sẽ dừng vòng lặp vô hạn mà không làm treo điện thoại của bạn.","cta_h2":"Thực hành ISO/GNU C17 thực thụ ngoại tuyến trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; kèm sẵn 6 bài lab C khởi đầu, gợi ý AST -&gt; và xuất PDF A4."},"c_multifile":{"metaTitle":"Trình biên dịch C đa tệp cho Android — Tự liên kết .c/.h, Makefile & CMake | SuperCode","metaDesc":"Biên dịch dự án .c và .h đa tệp tới 350 tệp ngoại tuyến trên Android. SuperCode tự động phân tích CMakeLists.txt và Makefile—hoặc tự liên kết header #include không cần cấu hình kèm bộ nhớ đệm tăng dần.","hero_tag":"TỐI ĐA 350 TỆP &#183; CMAKELISTS.TXT &amp; MAKEFILE &#183; BỘ NHỚ ĐỆM TĂNG DẦN","hero_h1":"Biên dịch <span class=\"text-gradient\">Dự án .c &amp; .h đa tệp</span> ngoại tuyến trên Android.","hero_desc":"Vượt xa giới hạn hộp cát đơn tệp <code>main.c</code>. SuperCode quét tối đa <strong>350 tệp trong không gian làm việc</strong>, phân tích gốc đồ thị mục tiêu từ <strong><code>CMakeLists.txt</code></strong> và <strong><code>Makefile</code></strong>&#8212;hoặc tự động liên kết các dự án dùng <strong><code>#include &quot;...&quot;</code></strong> mà không cần cấu hình, kết hợp <strong>bộ nhớ đệm tệp đối tượng theo từng tệp</strong>.","cp2_s1":"Số tệp workspace tối đa","cp2_s2":"&amp; Trình phân tích Makefile","cp2_s3":"Chạy từ .h -&gt; main()","cp2_s4":"Bộ nhớ đệm tăng dần","wb_eyebrow":"BÀN DỰNG C ĐA TỆP .C / .H, CMAKE &amp; TRÌNH LIÊN KẾT TĂNG DẦN","sec_cap_title":"Kỹ thuật lập trình C đa mô-đun thực thụ không vướng rào cản script build","sec_cap_lead":"Dù bạn đặt hai tệp `.c`/`.h` vào chung một thư mục hay clone kho lưu trữ CMake có cấu trúc chặt chẽ từ GitHub, SuperCode đều tự động giải quyết đồ thị biên dịch.","f1_title":"Trình liên kết đồ thị #include \"...\" không cần cấu hình","f1_desc":"Không muốn viết Makefile cho dự án cấu trúc dữ liệu 5 tệp? Chỉ cần tạo main.c, list.h và list.c. SuperCode tự động quét các chỉ thị #include tương đối qua tối đa 350 tệp (16 MB) và liên kết đúng các tệp cài đặt .c tương ứng.","f1_badge":"Không cần script build &#183; Hỗ trợ thư mục lồng src/ &amp; include/","f2_title":"Trình phân tích đồ thị mục tiêu CMakeLists.txt gốc","f2_desc":"Mở một kho lưu trữ CMake sẵn có và bấm Run. SuperCode xử lý các biến set(), add_executable(), add_library() và target_include_directories() để ghép chính xác đường dẫn include và các đơn vị biên dịch.","f2_badge":"add_executable &#183; add_library &#183; target_include_directories","f3_title":"Trích xuất mã nguồn từ Makefile &amp; GNUmakefile","f3_desc":"Đang làm bài tập đại học phát kèm Makefile hoặc GNUmakefile? Bộ phân tích build trích xuất SRCS, OBJS, CFLAGS và phụ thuộc mục tiêu để dự án của bạn biên dịch ngoại tuyến chỉ với một chạm.","f3_badge":"Makefile &#183; GNUmakefile &#183; Phân giải đồ thị SRCS / OBJS","f4_title":"Loại bỏ nhánh chết #if 0 &amp; #ifdef theo nền tảng thông minh","f4_desc":"Các kho mã nguồn C đa nền tảng thường bọc &lt;windows.h&gt; hoặc header macOS trong khối #ifdef _WIN32 hay #if 0. SuperCode lọc bỏ chú thích và cắt tỉa các nhánh tiền xử lý không hoạt động trước khi phân giải header.","f4_badge":"Bỏ qua #if 0 &amp; #ifdef _WIN32 &#183; Build đa nền tảng sạch sẽ","f5_title":"Điều phối điểm vào thông minh từ tệp header đến main()","f5_desc":"Đặt con trỏ ngay trong include/parser.h hoặc src/lexer.c và chạm Run trực tiếp. SuperCode kiểm tra đồ thị mục tiêu, phân biệt định nghĩa main() đang hoạt động với các mô-đun phụ trợ và khởi chạy đúng tệp thực thi.","f5_badge":"Chạy từ bất kỳ tab .h hay .c nào &#183; Nhận diện đa mục tiêu","f6_title":"Bộ nhớ đệm đối tượng tăng dần theo từng đơn vị biên dịch","f6_desc":"Mỗi tệp .c cùng chuỗi phụ thuộc .h bắc cầu được tạo dấu vân tay theo mã băm nội dung. Khi sửa main.c, hệ thống tái sử dụng các tệp đối tượng .o đã lưu đệm của toàn bộ mô-đun không đổi, giảm mạnh độ trễ build lại trên di động.","f6_badge":"Bộ nhớ đệm .o theo hash nội dung &#183; Build lại tức thì","workflow_title":"Cách build dự án C đa tệp &amp; CMake trên Android","workflow_lead":"Tổ chức giao diện `.h` và phần cài đặt `.c` gọn gàng hệt như trên máy trạm Linux để bàn.","wf1_title":"Tạo thư mục src/ + include/ hoặc clone một kho lưu trữ","wf1_desc":"Sắp xếp các header .h và đơn vị .c cục bộ hoặc clone kho bài tập C trên GitHub bằng trình khách Visual Git tích hợp của SuperCode.","wf2_title":"Để tự động phát hiện hoặc CMakeLists.txt phân giải đơn vị build","wf2_desc":"Bạn có thể tận dụng cơ chế tự dò #include \"...\" hoặc giữ nguyên CMakeLists.txt / Makefile sẵn có của dự án.","wf3_title":"Biên dịch tăng dần từ bất kỳ tệp đang mở nào","wf3_desc":"Chạm Run ngay cả khi đang sửa tệp header .h; SuperCode tự định vị main(), biên dịch lại các TU đã đổi, liên kết -lm và thực thi.","wf4_title":"Xem diff hợp nhất &amp; commit các mô-đun sạch sẽ","wf4_desc":"Đối chiếu thay đổi trên các tệp .c và .h trong giao diện unified diff tô màu rồi đẩy commit thẳng lên GitHub hoặc GitLab.","wf_foot_note":"Quét tối đa 350 tệp / 16 MB workspace &#183; Phủ lớp đệm tab đang mở chưa lưu","table_h2":"So sánh SuperCode Multi-File C Builder với trình biên dịch đơn tệp trên di động","snippet_p":"<strong>Trình dựng dự án C đa tệp của SuperCode</strong> biên dịch các không gian làm việc mô-đun <code>.c</code> và <code>.h</code> lên tới 350 tệp ngoại tuyến trên Android. Công cụ tự động phân tích đồ thị mục tiêu của <code>CMakeLists.txt</code> và <code>Makefile</code>, liên kết cây header không cần cấu hình, cắt bỏ nhánh tiền xử lý không hoạt động, điều phối <code>main()</code> từ header đang mở và lưu đệm các tệp đối tượng không thay đổi.","table_caption":"NĂNG LỰC XÂY DỰNG DỰ ÁN C ĐA TỆP TRÊN ANDROID","th_0":"Năng lực build","th_1":"SuperCode C17 Builder","th_2":"Ứng dụng C di động cơ bản","th_3":"Hộp cát trình duyệt","th_4":"Chạy Make CLI thủ công","tr1_c0":"Quy mô dự án","tr1_c1":"Tối đa 350 tệp / 16 MB thư mục lồng nhau","tr1_c2":"Chỉ một tệp main.c duy nhất","tr1_c3":"2-3 tab dán mã thủ công","tr1_c4":"Không giới hạn (cấu hình tay)","tr2_c0":"CMake &amp; Makefile","tr2_c1":"Phân tích gốc CMakeLists.txt &amp; Makefile","tr2_c2":"Không hỗ trợ","tr2_c3":"Hiếm khi hỗ trợ","tr2_c4":"Cần cài gói CLI","tr3_c0":"Liên kết không cần cấu hình","tr3_c1":"Tự quét #include \"...\" + tệp .c đi kèm","tr3_c2":"Lỗi `undefined reference`","tr3_c3":"Viết script biên dịch tay","tr3_c4":"Gõ tay `gcc *.c`","tr4_c0":"Chạy từ tệp header .h","tr4_c1":"Điều phối thông minh tự tìm main()","tr4_c2":"Báo lỗi (`no main in .h`)","tr4_c3":"Chỉ chạy tab đang chọn","tr4_c4":"Gõ lệnh thủ công","tr5_c0":"Bộ nhớ đệm tăng dần","tr5_c1":"Đệm tệp đối tượng (.o) theo hash từng TU","tr5_c2":"Biên dịch lại toàn bộ mỗi lần chạy","tr5_c3":"Biên dịch lại từ xa toàn bộ","tr5_c4":"Dựa theo dấu thời gian","faq_lead":"Câu hỏi thường gặp về lỗi `undefined reference`, đường dẫn `#include`, Makefile và CMake trên Android.","faq1_q":"Vì sao các ứng dụng C khác trên Android báo `undefined reference` khi tôi `#include \"helper.h\"`?","faq1_a":"Các ứng dụng di động đơn tệp chỉ truyền tệp đang mở vào trình biên dịch và không bao giờ liên kết `helper.c`. SuperCode quét toàn bộ thư mục của bạn (cùng mọi thư mục con `src/` hoặc `include/`), biên dịch `helper.c` song song với `main.c` và tự động liên kết mọi tệp đối tượng lại với nhau.","faq2_q":"Tôi có bắt buộc phải viết `CMakeLists.txt` hoặc `Makefile` cho dự án C nhỏ không?","faq2_a":"Hoàn toàn không. Nếu không có `CMakeLists.txt` hay `Makefile`, bộ quét phụ thuộc `#include \"...\"` không cần cấu hình của SuperCode sẽ tự tìm và liên kết các tệp `.c` và `.h` của bạn. Khi dự án đã có `CMakeLists.txt` hoặc `Makefile`, SuperCode sẽ tuân thủ đúng đồ thị mục tiêu của tệp đó.","faq3_q":"Điều gì xảy ra nếu dự án có sửa đổi chưa lưu trong một tab `.h` đang mở khi tôi bấm Run?","faq3_a":"SuperCode tự động phủ nội dung bộ đệm chưa lưu từ trình soạn thảo lên bản chụp build của không gian làm việc, nên mọi chỉnh sửa trên các tab `.h` và `.c` đang mở luôn được áp dụng tức thì.","faq4_q":"SuperCode xử lý thế nào khi một không gian làm việc chứa hai chương trình kiểm thử `main()` riêng biệt?","faq4_a":"Nếu bạn chạy từ một tệp tự định nghĩa `main()`, hàm `main()` đó sẽ được ưu tiên chọn. Nếu bạn chạy từ một header `.h` dùng chung, SuperCode sẽ kiểm tra các mục tiêu trong `CMakeLists.txt`/`Makefile` và các cạnh `#include` cục bộ để chọn đúng tệp thực thi tương ứng mà không gây xung đột trùng ký hiệu.","cta_h2":"Xây dựng dự án C đa tệp thực thụ ngay trên điện thoại.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; tự liên kết .c/.h không cần cấu hình, phân tích CMake/Makefile và Visual Git trong cùng một studio."},"c_scanf_io":{"metaTitle":"Trình biên dịch C nhập liệu trực tiếp trên Android — scanf, @args & fopen I/O | SuperCode","metaDesc":"Chạy chương trình C tương tác trên Android với stdout không đệm trước scanf/fgets, ngắt vòng lặp [EOF], cờ CLI // @args argc/argv và đồng bộ tệp fopen/fwrite hai chiều.","hero_tag":"STDOUT KHÔNG ĐỆM &#183; SCANF TRỰC TIẾP &amp; [EOF] &#183; // @ARGS &#183; ĐỒNG BỘ FOPEN","hero_h1":"Console <span class=\"text-gradient\">C scanf, argc/argv &amp; File I/O</span> tương tác cho Android.","hero_desc":"Không còn phải đoán nhập trước mọi dữ liệu khi chạy. SuperCode tự động bỏ đệm <code>stdout</code> để lời nhắc trước <strong><code>scanf()</code> / <code>fgets()</code></strong> hiện tức thì, gửi <strong><code>[EOF]</code></strong> chỉ một chạm, truyền <strong>cờ CLI <code>// @args</code></strong> và đồng bộ tệp <strong><code>fopen()</code></strong> thẳng vào thư mục dự án.","cp3_s1":"Nhắc lệnh tức thì","cp3_s2":"Ngắt vòng lặp 1 chạm","cp3_s3":"Cờ CLI // @args","cp3_s4":"fopen / fwrite I/O","wb_eyebrow":"BÀN LÀM VIỆC C STDIN TƯƠNG TÁC, // @ARGS &amp; FILE I/O TRONG WORKSPACE","sec_cap_title":"Mọi luồng nhập xuất C hoạt động hệt như Terminal gốc","sec_cap_lead":"Ứng dụng console dạng menu, trình phân tích dòng lệnh và bài tập ghi bản ghi nhị phân hoạt động y hệt terminal trên máy tính.","f1_title":"Tự động bỏ đệm stdout trước scanf &amp; fgets","f1_desc":"Trên nhiều trình chạy di động và web, lệnh printf(\"Enter age: \"); không có ký tự xuống dòng sẽ bị ẩn đến khi scanf() xong! SuperCode tự động bỏ đệm stdout để lời nhắc luôn hiện trước khi bạn nhập.","f1_badge":"Không cần fflush(stdout) &#183; Vòng lặp menu tự nhiên","f2_title":"Stdin trực tiếp nhiều bước &amp; gửi [EOF] một chạm","f2_desc":"Nhập dữ liệu từng bước khi chương trình đang chạy. Cần kiểm thử while (scanf(\"%d\", &amp;x) != EOF) hay while (fgets(buf, sizeof buf, stdin))? Chỉ cần gửi một dòng trống để phát tín hiệu EOF chuẩn.","f2_badge":"scanf &#183; fgets &#183; getchar &#183; Ngắt [EOF] chuẩn xác","f3_title":"Chỉ thị // @args cho chương trình CLI argc / argv","f3_desc":"Thêm // @args -i \"input data.csv\" --verbose ở đầu tệp .c để truyền tối đa 32 tham số dòng lệnh đã phân tách vào thẳng main(int argc, char *argv[]), giữ nguyên dấu cách trong ngoặc kép.","f3_badge":"// @args &#183; Chuỗi ngoặc kép &#183; Tối đa 32 tham số argv","f4_title":"Tự động gắn bộ dữ liệu .txt / .csv / .dat / .in","f4_desc":"Thả input.in, students.csv hoặc records.dat vào thư mục dự án và mở bằng đường dẫn tương đối chuẩn như fopen(\"students.csv\", \"r\")&#8212;không cần ghi cứng đường dẫn Android /storage/emulated/0.","f4_badge":"fopen() đường dẫn tương đối &#183; .txt / .csv / .dat / .in","f5_title":"Đồng bộ Workspace hai chiều cho fopen, fprintf &amp; fwrite","f5_desc":"Báo cáo văn bản và struct nhị phân ghi qua fopen(..., \"w\" / \"wb\"), fprintf() và fwrite() tự động đồng bộ vào cây thư mục Android và làm mới Trình quản lý tệp ngay lập tức.","f5_badge":"Đồng bộ tệp văn bản &amp; nhị phân &#183; Làm mới tức thì","f6_title":"Bộ giám sát vòng lặp CPU 20 giây tự tạm dừng khi chờ nhập","f6_desc":"Thoải mái suy nghĩ và nhập liệu trên console&#8212;bộ giám sát 20 giây sẽ tạm dừng khi đang chờ stdin, nhưng ngắt ngay nếu vòng lặp lỗi quay CPU vô tận sau khi nhập.","f6_badge":"Watchdog nhận biết trạng thái chờ &#183; Chống tràn output","workflow_title":"Cách kiểm thử Stdin, tham số CLI &amp; File I/O trong SuperCode","workflow_lead":"Chạy bài tập menu tương tác, công cụ Unix CLI và thực hành xử lý tệp mượt mà trên di động.","wf1_title":"Khai báo cờ CLI tùy chọn ở đầu tệp","wf1_desc":"Thêm chú thích như // @args input.txt output.csv ở dòng 1 mỗi khi bài tập cần đọc argc và argv[].","wf2_title":"Đặt tệp dữ liệu đầu vào trong thư mục dự án","wf2_desc":"Tạo hoặc nhập tệp .txt, .csv, .in hay .dat vào cùng thư mục để lệnh fopen() tương đối tự động tìm thấy.","wf3_title":"Trả lời lời nhắc trực tiếp &amp; gửi [EOF] khi hoàn tất","wf3_desc":"Xem lời nhắc printf không đệm theo thời gian thực, nhập giá trị vào thanh console hoặc chạm gửi trên ô trống để phát [EOF].","wf4_title":"Mở tệp kết quả vừa tạo ngay trong trình soạn thảo","wf4_desc":"Chạm vào bất kỳ tệp .txt, .csv hoặc log mới tạo nào trong cây dự án để kiểm tra chính xác dữ liệu ghi ra đĩa.","wf_foot_note":"Console chia đôi ngang 55:45 &#183; Thu phóng cỡ chữ Terminal &#183; Xóa &amp; sao chép Output","table_h2":"Stdin trực tiếp &amp; File I/O của SuperCode vs. Trình chạy di động theo lô","snippet_p":"<strong>Console C tương tác của SuperCode</strong> mang lại trải nghiệm nhập chuẩn, tham số dòng lệnh và xử lý tệp ngang tầm máy tính trên Android. Tự động hiển thị lời nhắc không đệm trước <code>scanf</code> và <code>fgets</code>, hỗ trợ ngắt EOF một chạm, truyền tới 32 cờ <code>argc/argv</code> qua <code>// @args</code> và đồng bộ đầu ra <code>fopen</code> về thư mục dự án.","table_caption":"SO SÁNH CONSOLE C &amp; XỬ LÝ TỆP TRÊN ANDROID","th_0":"Khả năng I/O","th_1":"Console SuperCode C17","th_2":"Ứng dụng nhập hộp trước","th_3":"Trình biên dịch web","th_4":"Terminal máy tính","tr1_c0":"Lời nhắc trước scanf","tr1_c1":"stdout tự động không đệm (Tức thì)","tr1_c2":"Lời nhắc chỉ in sau khi chạy xong","tr1_c3":"Bị đệm tới khi xuống dòng/thoát","tr1_c4":"Tức thì","tr2_c0":"Vòng lặp menu tương tác","tr2_c1":"Stdin trực tiếp nhiều lượt + [EOF]","tr2_c2":"Phải đoán toàn bộ input từ đầu","tr2_c3":"Ô nhập stdin theo lô","tr2_c4":"Hỗ trợ","tr3_c0":"Tham số argc / argv","tr3_c1":"Chỉ thị `// @args` tích hợp (32 tham số)","tr3_c2":"Không hỗ trợ","tr3_c3":"Ẩn trong ngăn cài đặt","tr3_c4":"Cờ CLI thủ công","tr4_c0":"Tệp fopen / fwrite","tr4_c1":"Tự gắn đầu vào &amp; đồng bộ đầu ra về thư mục","tr4_c2":"Thư mục tạm mất khi thoát","tr4_c3":"Xóa sạch sau phiên chạy","tr4_c4":"Thư mục cục bộ","tr5_c0":"An toàn vòng lặp vô hạn","tr5_c1":"Watchdog CPU 20s tạm dừng khi chờ nhập","tr5_c2":"Đơ UI hoặc hết giờ khi đang gõ","tr5_c3":"Ngắt cứng theo thời gian thực","tr5_c4":"Nhấn Ctrl+C thủ công","faq_lead":"Giải đáp lỗi lời nhắc `scanf`, xuống dòng `fgets`, tín hiệu `EOF` và đường dẫn `fopen` trên Android.","faq1_q":"Tại sao `printf(\"Enter number: \");` hiện ngay lập tức trong SuperCode mà không cần `fflush(stdout)`?","faq1_a":"Luồng C chuẩn thường bị đệm theo khối khi chuyển hướng pipe, làm ẩn lời nhắc không kết thúc bằng `\\\\n`. SuperCode tự động cấu hình luồng chuẩn không đệm để lời nhắc tương tác hiện trước khi `scanf`, `fgets` hoặc `getchar` chờ nhập.","faq2_q":"Làm sao gửi `Ctrl+D` (`EOF`) trên bàn phím cảm ứng Android?","faq2_a":"Khi thanh nhập console đang bật và để trống, chạm nút Gửi sẽ truyền tín hiệu `EOF` (`[EOF]`) chuẩn xác vào tiến trình C đang chạy&#8212;kết thúc gọn các vòng lặp `while (scanf(...) != EOF)` và `getchar() != EOF`.","faq3_q":"Làm sao truyền tham số dòng lệnh có dấu cách vào `char *argv[]`?","faq3_a":"Viết `// @args \"My Report.txt\" -n 10` gần đầu tệp `.c`. Bộ phân tích tham số của SuperCode giữ nguyên chuỗi trong ngoặc kép thành một phần tử `argv[i]` duy nhất và hỗ trợ tối đa 32 tham số.","faq4_q":"Các tệp tạo bằng `fopen(\"output.txt\", \"w\")` được lưu ở đâu?","faq4_a":"Chúng được đồng bộ trực tiếp vào đúng thư mục dự án Android chứa tệp nguồn `.c` của bạn, nên được lưu bền vững và mở được ngay trong trình soạn thảo SuperCode.","cta_h2":"Chạy bài tập C tương tác &amp; xử lý tệp ngay trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; scanf trực tiếp không đệm, cờ CLI // @args và đồng bộ fopen thật."},"c_posix_sys":{"metaTitle":"Trình biên dịch POSIX C cho Android — unistd.h, pthread, Sockets & Lab Hệ điều hành | SuperCode","metaDesc":"Viết mã Hệ điều hành và POSIX C trên Android. Dùng unistd.h, fcntl.h, dirent.h, getopt.h, regex.h và stdatomic.h ngoại tuyến, cùng biên dịch pthread, semaphore, fork/pipe và socket mượt mà.","hero_tag":"HEADER POSIX NGOẠI TUYẾN &#183; PTHREAD &amp; SEMAPHORE &#183; UNIX SOCKETS &amp; IPC","hero_h1":"Lập trình <span class=\"text-gradient\">POSIX Systems C, pthreads &amp; Sockets</span> ngay trên thiết bị Android.","hero_desc":"Thiết kế cho môn Hệ điều hành và Mạng máy tính. Biên dịch ngoại tuyến <strong><code>unistd.h</code>, <code>fcntl.h</code>, <code>dirent.h</code>, <code>getopt.h</code>, <code>regex.h</code> và <code>stdatomic.h</code></strong>&#8212;và chuyển liền mạch sang <strong>POSIX Cloud C (<code>-pthread -lm</code>)</strong> cho bài lab <strong><code>pthread</code>, <code>fork/pipe</code> và <code>sys/socket.h</code></strong>.","cp4_s1":"unistd &#183; fcntl &#183; dirent","cp4_s2":"stdatomic &amp; complex","cp4_s3":"Threads &amp; Semaphores","cp4_s4":"Chẩn đoán lỗi từng tệp 1:1","wb_eyebrow":"BÀN LÀM VIỆC POSIX HEADERS, ĐỒNG BỘ PTHREAD &amp; SOCKET IPC","sec_cap_title":"Kết nối Header hệ thống ngoại tuyến với đồng bộ hóa &amp; IPC Linux đầy đủ","sec_cap_lead":"SuperCode tự động kiểm tra chỉ thị `#include` và lời gọi hệ thống để bài lab OS chạy mượt mà không cần cấu hình biên dịch chéo thủ công.","f1_title":"Hỗ trợ toàn diện Header POSIX ngoại tuyến","f1_desc":"Biên dịch các tiện ích hệ thống Unix thường ngày hoàn toàn ngoại tuyến với &lt;unistd.h&gt;, &lt;fcntl.h&gt;, &lt;dirent.h&gt;, &lt;poll.h&gt;, &lt;sys/stat.h&gt;, &lt;sys/time.h&gt;, &lt;signal.h&gt;, &lt;regex.h&gt;, &lt;fnmatch.h&gt; và &lt;getopt.h&gt;.","f1_badge":"unistd.h &#183; fcntl.h &#183; dirent.h &#183; poll.h &#183; regex.h &#183; getopt.h","f2_title":"Sẵn sàng C11/C17 &lt;stdatomic.h&gt; &amp; &lt;complex.h&gt; ngoại tuyến","f2_desc":"Thử nghiệm bộ đếm atomic không khóa (atomic_int, atomic_fetch_add, memory_order_acq_rel) và số học phức C17 gốc (&lt;complex.h&gt;) trực tiếp trên thiết bị của bạn.","f2_badge":"&lt;stdatomic.h&gt; &#183; &lt;complex.h&gt; &#183; Thuần GNU C17","f3_title":"Tự động biên dịch -pthread &amp; IPC trên Cloud C","f3_desc":"Sandbox của Android giới hạn fork tiến trình thô và một số lời gọi IPC nhân cục bộ. Khi mã C dùng &lt;pthread.h&gt;, &lt;semaphore.h&gt;, &lt;sys/socket.h&gt;, fork() hoặc pipe(), SuperCode tự động biên dịch trên Linux Cloud C (-pthread -lm).","f3_badge":"&lt;pthread.h&gt; &#183; &lt;semaphore.h&gt; &#183; &lt;sys/socket.h&gt; &#183; fork / pipe","f4_title":"Đóng gói đa tệp POSIX giữ nguyên #line","f4_desc":"Ngay cả khi đẩy dự án đa tệp .c và .h lên Cloud C, SuperCode vẫn chèn chỉ thị #line chuẩn để mọi cảnh báo hay lỗi cú pháp trỏ đúng tệp và số dòng cục bộ.","f4_badge":"Gói Cloud đa tệp &#183; Ánh xạ chính xác số dòng cục bộ","f5_title":"&lt;getopt.h&gt; + // @args tạo mẫu Unix CLI nhanh chóng","f5_desc":"Xây dựng công cụ dòng lệnh POSIX chuẩn mực với getopt() và getopt_long(), truyền cờ kiểm thử như // @args -r -n 16 -o out.log ngay từ đầu tệp nguồn.","f5_badge":"getopt / getopt_long &#183; Kiểm thử cờ // @args","f6_title":"Tích hợp Shell, Git &amp; triển khai máy chủ SFTP","f6_desc":"Thử nghiệm daemon POSIX hoặc công cụ CLI trên Android, theo dõi phiên bản bằng Visual Git và triển khai thẳng lên Linux VPS hoặc máy lab trường học qua trình khách SFTP tích hợp.","f6_badge":"Trình chạy Shell &#183; Visual Git &#183; Lưu từ xa SFTP nguyên tử","workflow_title":"Cách định tuyến POSIX hoạt động tự động trong SuperCode","workflow_lead":"Viết mã POSIX C chuẩn&#8212;SuperCode tự chọn biên dịch ngoại tuyến hoặc thực thi Linux `-pthread`.","wf1_title":"Include các Header C17 &amp; hệ thống POSIX chuẩn","wf1_desc":"Viết bộ mô tả tệp, trình quét thư mục, khớp regex hoặc trình phân tích getopt() bằng các header POSIX tiêu chuẩn.","wf2_title":"Bài lab tệp, Regex &amp; Atomic biên dịch ngoại tuyến","wf2_desc":"Chương trình dùng unistd.h, fcntl.h, dirent.h, regex.h, getopt.h hoặc stdatomic.h biên dịch và chạy cục bộ không cần mạng.","wf3_title":"Bài lab Thread, Semaphore &amp; Socket chạy trên Linux C","wf3_desc":"Khi include &lt;pthread.h&gt;, &lt;semaphore.h&gt;, &lt;sys/socket.h&gt;, fork() hoặc pipe(), hệ thống tự kích hoạt Linux Cloud C với -pthread -lm.","wf4_title":"Sửa cảnh báo chính xác 1:1 theo tệp &amp; dòng cục bộ","wf4_desc":"Chẩn đoán trình biên dịch ánh xạ thẳng về tab .c và .h cục bộ bất kể chạy ngoại tuyến hay đám mây.","wf_foot_note":"Không cần cờ -pthread thủ công &#183; Mở rộng Header đa tệp &#183; Sẵn sàng triển khai Linux qua SFTP","table_h2":"Ma trận hỗ trợ POSIX &amp; Systems C trong SuperCode","snippet_p":"<strong>POSIX C Systems Studio của SuperCode</strong> mang lập trình C17 chuẩn Unix lên điện thoại và máy tính bảng Android. Lập trình viên có thể biên dịch ngoại tuyến <code>unistd.h</code>, <code>fcntl.h</code>, <code>dirent.h</code>, <code>poll.h</code>, <code>getopt.h</code>, <code>regex.h</code> và <code>stdatomic.h</code>, đồng thời chạy các dự án đa tệp <code>pthread.h</code>, semaphore, pipe và socket mượt mà trên POSIX Cloud C với định vị dòng lỗi cục bộ chính xác.","table_caption":"CÁC CẤP ĐỘ HEADER &amp; SYSCALL POSIX C TRÊN ANDROID CỦA SUPERCODE","th_0":"Nhóm hệ thống","th_1":"Header &amp; hàm gốc chính","th_2":"Cấp thực thi","th_3":"Đa tệp .c/.h?","th_4":"Cờ liên kết (Linker)","tr1_c0":"I/O Tệp &amp; Thư mục POSIX","tr1_c1":"unistd.h, fcntl.h, dirent.h, sys/stat.h, poll.h","tr1_c2":"100% C17 ngoại tuyến","tr1_c3":"Có (Tối đa 350 tệp)","tr1_c4":"Tự động `-std=gnu17 -lm`","tr2_c0":"CLI, Glob &amp; Regex","tr2_c1":"getopt.h, regex.h, fnmatch.h, sys/time.h, signal.h","tr2_c2":"100% C17 ngoại tuyến","tr2_c3":"Có + `// @args`","tr2_c4":"Tự động `-std=gnu17 -lm`","tr3_c0":"Atomic &amp; Toán DSP","tr3_c1":"stdatomic.h, complex.h, stdint.h, inttypes.h","tr3_c2":"100% C17 ngoại tuyến","tr3_c3":"Có (Cache `.o`)","tr3_c4":"Tự động `-std=gnu17 -lm`","tr4_c0":"POSIX Threads &amp; Đồng bộ","tr4_c1":"pthread.h, semaphore.h, mutexes, condition vars","tr4_c2":"Tự động POSIX Cloud C","tr4_c3":"Có (Ánh xạ `#line`)","tr4_c4":"Tự động `-pthread -lm`","tr5_c0":"Tiến trình &amp; Sockets","tr5_c1":"sys/socket.h, netinet/in.h, arpa/inet.h, fork, pipe","tr5_c2":"Tự động POSIX Cloud C","tr5_c3":"Có (Ánh xạ `#line`)","tr5_c4":"Tự động `-pthread -lm`","faq_lead":"Giải đáp về bài tập Hệ điều hành, liên kết `pthread`, `fork()` và lập trình socket trên Android.","faq1_q":"Tôi có thể biên dịch `&lt;unistd.h&gt;`, `&lt;dirent.h&gt;` và `&lt;getopt.h&gt;` hoàn toàn ngoại tuyến không?","faq1_a":"Có. Các header POSIX cốt lõi gồm `unistd.h`, `fcntl.h`, `dirent.h`, `poll.h`, `regex.h`, `fnmatch.h`, `getopt.h`, `sys/stat.h`, `sys/time.h`, `signal.h` và `stdatomic.h` được tích hợp sẵn trong sysroot C17 ngoại tuyến.","faq2_q":"Tôi có cần thêm `-pthread` thủ công khi dùng `&lt;pthread.h&gt;` hoặc `&lt;semaphore.h&gt;` không?","faq2_a":"Không. SuperCode tự động phát hiện `&lt;pthread.h&gt;` và `&lt;semaphore.h&gt;`, rồi truyền `-pthread -lm` cho trình biên dịch POSIX Cloud C mà không cần cấu hình cờ build.","faq3_q":"Tại sao `fork()`, `pipe()` và `&lt;sys/socket.h&gt;` chạy trên tầng POSIX Cloud C?","faq3_a":"Chính sách bảo mật SELinux trên Android hiện đại chặn phân cấp `fork()` tiến trình con và ràng buộc socket thô bên trong sandbox ứng dụng. Định tuyến các bài lab này sang container Linux cô lập giúp mã giáo trình OS chuẩn chạy nguyên bản không cần sửa.","faq4_q":"Nếu dự án `pthread` đa tệp bị lỗi gõ sai trong `worker.h`, thông báo lỗi có hiện đúng tệp và số dòng không?","faq4_a":"Có. Trình đóng gói đa tệp của SuperCode chèn chỉ thị `#line` C chuẩn cho mọi header được include và đơn vị dịch `.c`, giúp chẩn đoán lỗi ánh xạ 1:1 tới đúng tệp `worker.h` và số dòng chính xác.","cta_h2":"Giải quyết bài lab Hệ điều hành &amp; Systems C mọi nơi trên Android.","cta_desc":"Cài đặt miễn phí SuperCode IDE trên Google Play &#8212; header POSIX ngoại tuyến, build -pthread liền mạch và SFTP trong một ứng dụng 40.2 MB."},"cpp_comp_stl":{"metaTitle":"Ứng dụng Lập trình thi đấu trên Android — C++20 STL ngoại tuyến & std::cin nhanh | SuperCode","metaDesc":"Luyện Codeforces, LeetCode, AtCoder, CSES và USACO ngoại tuyến trên Android. Đầy đủ GNU C++20 STL, console chia đôi 55:45 std::cin, đo thời gian chạy µs/KB bộ nhớ và ngắt vòng lặp 20s.","hero_tag":"GNU C++20 STL NGOẠI TUYẾN &#183; CONSOLE THI ĐẤU 55:45 &#183; ĐO &#181;S &amp; KB","hero_h1":"Đấu trường <span class=\"text-gradient\">C++20 &amp; STL ngoại tuyến</span> cho dân Lập trình thi đấu.","hero_desc":"Giải bài Codeforces, AtCoder, LeetCode, CSES và USACO mọi lúc&#8212;ngay cả trên máy bay hay xe buýt. SuperCode kết hợp <strong>GNU C++20 ngoại tuyến (<code>-std=gnu++2a</code>)</strong> cùng trọn bộ <strong>STL</strong> với <strong>console chia đôi 55:45 cho <code>std::cin</code></strong> và <strong>đo thời gian chạy + bộ nhớ đỉnh</strong>.","cpp1_s1":"Đầy đủ STL ngoại tuyến","cpp1_s2":"Chia đôi màn hình thi đấu","cpp1_s3":"Thống kê Thời gian &amp; RAM","cpp1_s4":"Ngắt vòng lặp vô hạn","wb_eyebrow":"BÀN LÀM VIỆC C++20 STL THI ĐẤU, &lt;BIT&gt; &amp; STD::CIN ĐA TEST CASE","sec_cap_title":"Tối ưu cho tốc độ, thao tác thi đấu &amp; độ ổn định ngoại tuyến","sec_cap_lead":"Không phải chờ hàng đợi chấm bài trên web chậm chạp chỉ để kiểm tra test mẫu hay tìm lỗi lệch chỉ số off-by-one.","f1_title":"100% GNU C++20 STL &amp; hàm nội tại &lt;bit&gt; ngoại tuyến","f1_desc":"Mọi công cụ thi đấu quen thuộc đều chạy ngoại tuyến: vector, priority_queue, deque, set, multiset, map, unordered_map, bitset, &lt;algorithm&gt;, &lt;numeric&gt; (std::gcd, std::lcm) và C++20 &lt;bit&gt; (std::popcount, std::bit_width, std::countl_zero).","f1_badge":"STL Containers &#183; &lt;algorithm&gt; &#183; &lt;numeric&gt; &#183; C++20 &lt;bit&gt;","f2_title":"Dán nhanh std::cin, nhắc lệnh không đệm &amp; [EOF]","f2_desc":"Dán thẳng test mẫu nhiều dòng vào console, kiểm thử luồng ios::sync_with_stdio(false) mượt mà và chạm Gửi trên dòng trống để truyền [EOF] cho lời giải while (cin &gt;&gt; n).","f2_badge":"Dán test nhiều dòng &#183; Tín hiệu [EOF] &#183; stdout không đệm","f3_title":"Chế độ chia ngang 55:45 cho máy tính bảng &amp; điện thoại","f3_desc":"Xoay ngang điện thoại, máy gập hoặc tablet để viết mã ở khung 55% và soi đầu vào/đầu ra song song ở khung terminal 45%&#8212;tự thu gọn mượt mà khi bật bàn phím ảo.","f3_badge":"Chia đôi 55:45 &#183; Tối ưu máy gập &amp; Tablet","f4_title":"Đo thời gian chạy (&#181;s/ms) &amp; bộ nhớ đỉnh (KB/MB)","f4_desc":"Phát hiện sớm nút thắt O(N^2) hay mảng DP quá nặng trước khi nộp bài lên hệ thống chấm. Mỗi lần chạy đều hiện mã thoát, thời gian thực thi và bộ nhớ đỉnh ở chân console.","f4_badge":"Mã thoát &#183; Thời gian &#181;s / ms &#183; Đỉnh RAM KB / MB","f5_title":"Cầu dao ngắt vòng lặp vô hạn &amp; tràn Output sau 20 giây","f5_desc":"Viết while (lo &lt; hi) mà quên cập nhật mid hoặc thiếu mảng visited[] trong DFS? Bộ giám sát CPU 20s và giới hạn tràn output sẽ ngắt ngay tiến trình lỗi mà không mất một ký tự mã nào.","f5_badge":"Watchdog CPU 20s &#183; Chống tràn Output &#183; Không đơ UI","f6_title":"Chuyển hướng tệp .in &amp; .out chuẩn USACO / Olympiad","f6_desc":"Đặt problem.in vào workspace và dùng freopen(\"problem.in\", \"r\", stdin) hoặc std::ifstream/ofstream&#8212;tệp .out sinh ra tự động đồng bộ về thư mục để bạn đối chiếu.","f6_badge":"Sẵn sàng freopen() &#183; Tự đồng bộ .in / .out trong Workspace","workflow_title":"Quy trình thi đấu: Từ đề bài đến lời giải chuẩn xác","workflow_lead":"Thử nghiệm test mẫu trong vài giây mà không tốn dữ liệu di động hay chờ hàng đợi biên dịch từ xa.","wf1_title":"Mở mẫu thi đấu với phím tắt ký hiệu C++20","wf1_desc":"Bắt đầu từ tệp C++20 fast-I/O cùng thanh vuốt 21 phím ký hiệu (::, &lt;&lt;, &gt;&gt;, {}, [], &amp;) và gợi ý std:: từ AST.","wf2_title":"Biên dịch cục bộ ở chế độ Máy bay","wf2_desc":"Biên dịch lời giải đơn tệp ngoại tuyến không độ trễ máy chủ&#8212;ngay cả trên tàu điện, xe buýt hay khi di chuyển đi thi.","wf3_title":"Nạp trực tiếp bộ test nhiều trường hợp","wf3_desc":"Dán test mẫu Codeforces hoặc AtCoder vào std::cin (hoặc đọc từ problem.in) và kiểm tra kết quả tức thì.","wf4_title":"Kiểm tra Thời gian &amp; Bộ nhớ trước khi nộp bài","wf4_desc":"Xác nhận Exit code 0, thời gian chạy mili-giây và mức RAM KB/MB, sau đó sao chép mã sạch đẹp để nộp bài.","wf_foot_note":"Hỗ trợ Structured Bindings, Generic Lambdas &amp; 64-Bit long long &#183; Sao chép mã 1 chạm","table_h2":"Đấu trường C++20 thi đấu của SuperCode vs. Các lựa chọn di động khác","snippet_p":"<strong>Competitive C++20 Studio của SuperCode</strong> trang bị cho lập trình viên Olympiad, Codeforces, LeetCode và USACO trình biên dịch GNU C++20 STL ngoại tuyến tốc độ cao trên Android. Tích hợp console thi đấu chia đôi 55:45, <code>std::cin</code> trực tiếp không đệm có điều khiển EOF, đo thời gian chạy và bộ nhớ đỉnh, cùng cầu dao ngắt vòng lặp vô hạn 20 giây.","table_caption":"SO SÁNH LẬP TRÌNH THI ĐẤU C++ TRÊN ANDROID","th_0":"Yêu cầu thi đấu","th_1":"Đấu trường SuperCode C++20","th_2":"Ứng dụng C++11 cũ","th_3":"Tab Web IDE","th_4":"Trình ghi chú thuần","tr1_c0":"Chuẩn C++ &amp; &lt;bit&gt;","tr1_c1":"GNU C++20 ngoại tuyến (`popcount`, `ranges`, `[a,b]`)","tr1_c2":"Mắc kẹt ở C++98 / C++11","tr1_c3":"Nghẽn hàng đợi vào đêm thi đấu","tr1_c4":"Không có trình biên dịch","tr2_c0":"Nhập Test Case","tr2_c1":"Dán trực tiếp `std::cin` + `[EOF]` + `freopen`","tr2_c2":"Hộp thoại pop-up bất tiện","tr2_c3":"Một ô nhập lô duy nhất","tr2_c4":"Không có","tr3_c0":"Thống kê Thời gian &amp; RAM","tr3_c1":"Chân trang đo `&#181;s/ms` &amp; `KB/MB` tích hợp","tr3_c2":"Chỉ hiện văn bản kết quả","tr3_c3":"Thường bị ẩn","tr3_c4":"Không có","tr4_c0":"Lỗi TLE tìm kiếm nhị phân","tr4_c1":"Watchdog CPU 20s ngắt gọn vòng lặp","tr4_c2":"Treo toàn bộ ứng dụng Android","tr4_c3":"Lỗi máy chủ sau 10-15s","tr4_c4":"Không áp dụng","tr5_c0":"Thao tác chia đôi màn hình","tr5_c1":"Chia ngang 55:45 + Thanh C++ 21 phím","tr5_c2":"Giao diện cũ chỉ hỗ trợ màn dọc","tr5_c3":"Trình duyệt di động chật chội","tr5_c4":"Bàn phím mặc định","faq_lead":"Giải đáp cho thí sinh Codeforces, LeetCode, AtCoder, ICPC và USACO lập trình trên Android.","faq1_q":"Các tính năng C++20 như structured bindings `auto [u, w]`, `std::popcount` và `std::ranges::sort` có chạy ngoại tuyến không?","faq1_a":"Có. Trình biên dịch C++ cục bộ của SuperCode chạy theo chuẩn GNU C++20 (`-std=gnu++2a`), nên structured bindings, `constexpr if`, generic lambdas, `&lt;bit&gt;`, `&lt;ranges&gt;` và `std::gcd` / `std::lcm` đều biên dịch 100% ngoại tuyến.","faq2_q":"Tôi có thể dùng `ios::sync_with_stdio(false); cin.tie(nullptr);` trong SuperCode không?","faq2_a":"Có! Mẫu fast-I/O quen thuộc trong lập trình thi đấu hoạt động trơn tru với cả test nhiều dòng dán vào console lẫn chuyển hướng tệp `freopen()`.","faq3_q":"Làm sao kiểm thử các bài đọc input đến hết tệp (`while (cin &gt;&gt; x)`)?","faq3_a":"Dán các dòng test vào thanh nhập console trực tiếp và gửi, sau đó chạm Gửi thêm một lần khi ô nhập trống để truyền `[EOF]` và in ra đáp án cuối cùng.","faq4_q":"SuperCode có hiển thị tốc độ chạy và lượng bộ nhớ lời giải C++ đã dùng không?","faq4_a":"Có. Sau mỗi lần chạy đều hiện nhãn tóm tắt gồm mã thoát tiến trình, thời gian thực thi (`&#181;s` hoặc `ms`) và bộ nhớ đỉnh (`KB` hoặc `MB`).","cta_h2":"Nâng hạng C++20 mọi lúc mọi nơi không cần mạng.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; trọn bộ C++20 STL, console thi đấu chia đôi 55:45 và đo hiệu năng từng micro-giây."},"cpp_modern_20":{"metaTitle":"Trình biên dịch C++20 hiện đại cho Android — Ranges, Concepts & Con trỏ thông minh | SuperCode","metaDesc":"Tạm biệt các app C++11 lỗi thời. Viết C++20 hiện đại offline trên Android với , , , , optional/variant, con trỏ thông minh và đa luồng /.","hero_tag":"C++20 RANGES &amp; CONCEPTS &#183; CON TRỎ THÔNG MINH RAII &#183; &lt;THREAD&gt; &amp; &lt;LATCH&gt;","hero_h1":"Viết <span class=\"text-gradient\">C++20 hiện đại, Ranges &amp; Con trỏ thông minh</span> chuẩn mực trên Android.","hero_desc":"Những app lỗi thời như CppDroid đã kẹt lại ở kỷ nguyên C++11 hơn một thập kỷ trước. SuperCode mang <strong>C++20 offline thực thụ</strong> lên Android&#8212;đầy đủ <strong><code>&lt;ranges&gt;</code>, <code>&lt;concepts&gt;</code>, <code>&lt;span&gt;</code>, <code>std::optional</code>, <code>std::variant</code>, con trỏ thông minh RAII</strong> cùng xử lý đa luồng <strong><code>-pthread</code></strong> mượt mà.","cpp2_s1":"&amp; C++20 Concepts","cpp2_s2":"unique &amp; shared_ptr","cpp2_s3":"span &#183; optional &#183; variant","cpp2_s4":"thread &#183; latch &#183; barrier","wb_eyebrow":"KHÔNG GIAN LÀM VIỆC C++20 RANGES, CON TRỎ THÔNG MINH RAII &amp; ĐA LUỒNG","sec_cap_title":"Chuẩn C++ hiện đại cấp Production&#8212;Không phải tập con cũ kỹ từ 2013","sec_cap_lead":"Thực hành quản lý sở hữu RAII sạch sẽ, view zero-copy, template có ràng buộc và các cơ chế đồng bộ C++20 ngay trên phần cứng Android hiện đại.","f1_title":"Pipeline &lt;ranges&gt; lười (Lazy) &amp; Ràng buộc &lt;concepts&gt;","f1_desc":"Xây dựng luồng xử lý dữ liệu mạch lạc với std::views::filter, transform, take, drop, reverse và thay thế lỗi SFINAE khó hiểu bằng mệnh đề requires và &lt;concepts&gt; C++20 dễ đọc.","f1_badge":"std::ranges &#183; std::views &#183; &lt;concepts&gt; &#183; Mệnh đề requires","f2_title":"View Zero-Copy &amp; Các kiểu dữ liệu đại số","f2_desc":"Viết API không cấp phát bộ nhớ bằng std::span và std::string_view, mô hình hóa kiểu nullable hoặc tổng an toàn với std::optional, std::variant, std::any và định dạng chuỗi gọn gàng qua &lt;format&gt;, &lt;charconv&gt;.","f2_badge":"&lt;span&gt; &#183; &lt;string_view&gt; &#183; &lt;optional&gt; &#183; &lt;variant&gt; &#183; &lt;format&gt;","f3_title":"Con trỏ thông minh RAII &amp; Hệ thống OOP hiện đại","f3_desc":"Loại bỏ rò rỉ new/delete thủ công với std::make_unique, std::make_shared, std::weak_ptr, kiểm tra virtual override/final, move constructor, toán tử so sánh &lt;=&gt; mặc định và raw string literal R\"(...)\".","f3_badge":"unique_ptr &#183; shared_ptr &#183; Toán tử &lt;=&gt; &#183; R\"(...)\"","f4_title":"Đa luồng C++20 mượt mà (&lt;thread&gt;, &lt;latch&gt;, &lt;barrier&gt;)","f4_desc":"Đang thử nghiệm hàng đợi producer-consumer đa luồng? Chỉ cần include &lt;thread&gt;, &lt;future&gt;, &lt;semaphore&gt;, &lt;latch&gt; hoặc &lt;barrier&gt;, dự án sẽ tự động định tuyến sang Cloud C++20 (-pthread) với chẩn đoán dòng 1:1 chuẩn xác.","f4_badge":"&lt;thread&gt; &#183; &lt;future&gt; &#183; &lt;semaphore&gt; &#183; &lt;latch&gt; &#183; &lt;barrier&gt;","f5_title":"Tự động hoàn thiện AST cho ::, -&gt; và .","f5_desc":"Điều hướng hệ thống phân cấp lớp sâu, namespace std:: và giải tham chiếu con trỏ thông minh (ptr-&gt;) hoàn toàn offline&#8212;engine AST phân giải phương thức, thuộc tính và API container STL ngay khi bạn gõ.","f5_badge":"std:: &#183; ptr-&gt; &#183; obj. &#183; AST thông minh Offline","f6_title":"Định dạng C++20 1 chạm &amp; Radar báo lỗi cú pháp","f6_desc":"Giữ phần đầu template phức tạp, lambda capture và namespace lồng nhau luôn gọn đẹp trên màn hình di động nhờ định dạng offline tức thì và Hoàn tác nguyên khối một bước.","f6_badge":"Định dạng C++ Offline &#183; Hoàn tác 1 bước &#183; 8 Giao diện","workflow_title":"Cách phác thảo kiến trúc C++20 hiện đại trên Android","workflow_lead":"Viết C++20 chuẩn mực offline và bứt tốc tác vụ đa luồng dễ dàng khi cần.","wf1_title":"Viết Template có ràng buộc &amp; Lớp RAII","wf1_desc":"Sử dụng ngay các header C++20 (&lt;ranges&gt;, &lt;concepts&gt;, &lt;memory&gt;, &lt;span&gt;, &lt;optional&gt;, &lt;variant&gt;) mà không cần cấu hình cờ biên dịch.","wf2_title":"Hoàn thiện thành viên con trỏ thông minh &amp; Căn chỉnh code","wf2_desc":"Tra cứu thành viên lớp và STL qua gợi ý -&gt; và ::, sau đó chạm Định dạng để căn đều các view và lambda nhiều dòng.","wf3_title":"Biên dịch &amp; Kiểm chứng OOP đơn/đa tệp Offline","wf3_desc":"Chạy các module C++20 thuần cục bộ chỉ trong tích tắc nhờ cơ chế cache file object tăng dần theo từng đơn vị biên dịch.","wf4_title":"Kiểm thử đa luồng không cần sửa cấu hình Build","wf4_desc":"Include &lt;thread&gt;, &lt;future&gt; hoặc &lt;latch&gt; bất cứ khi nào cần chạy song song&#8212;SuperCode tự động liên kết -pthread cho bạn.","wf_foot_note":"Tối ưu cho Android 8.0&#8211;15+ &#183; Thay thế các app C++11 32-bit bị bỏ rơi &#183; Tích hợp Git trực quan","table_h2":"SuperCode C++20 Hiện Đại vs. Trình Biên Dịch C++ Cũ Trên Android","snippet_p":"<strong>IDE C++20 Hiện Đại của SuperCode</strong> đưa lập trình C++ trên Android vượt xa các trình biên dịch C++11 lỗi thời. Kỹ sư có thể viết code C++20 offline với <code>std::ranges</code>, concepts, <code>std::format</code>, <code>std::span</code>, <code>std::optional</code>, <code>std::variant</code> và con trỏ thông minh RAII, cùng khả năng biên dịch cloud <code>-pthread</code> liền mạch cho <code>std::thread</code>, future, latch và barrier.","table_caption":"HỖ TRỢ NGÔN NGỮ C++20 HIỆN ĐẠI TRÊN ANDROID","th_0":"Tính năng C++ hiện đại","th_1":"SuperCode C++20 Studio","th_2":"App cũ (VD: CppDroid)","th_3":"Web Runner trực tuyến","th_4":"CLI di động thuần","tr1_c0":"&lt;ranges&gt; &amp; &lt;concepts&gt;","tr1_c1":"Hỗ trợ Offline (-std=gnu++2a)","tr1_c2":"Không hỗ trợ (Kẹt ở C++11)","tr1_c3":"Bắt buộc có mạng","tr1_c4":"Cài gói thủ công","tr2_c0":"optional / variant / span","tr2_c1":"Đầy đủ kiểu từ vựng C++17 &amp; C++20","tr2_c2":"Thiếu hoặc thử nghiệm","tr2_c3":"Hỗ trợ trực tuyến","tr2_c4":"Có hỗ trợ","tr3_c0":"Tương thích Android OS","tr3_c1":"64-bit chuẩn Android 8.0&#8211;15+","tr3_c2":"Lỗi hoặc bị gỡ trên Android mới","tr3_c3":"Tab trình duyệt di động","tr3_c4":"Thiết lập thủ công","tr4_c0":"&lt;thread&gt;, &lt;latch&gt;, &lt;barrier&gt;","tr4_c1":"Tự liên kết `-pthread` + Ánh xạ dòng 1:1","tr4_c2":"Lỗi liên kết hoặc văng app","tr4_c3":"Thường bị bóp CPU","tr4_c4":"Gõ cờ `-pthread` thủ công","tr5_c0":"Gợi ý AST `-&gt;` &amp; `::`","tr5_c1":"AST Offline tích hợp + Thanh 21 phím","tr5_c2":"Danh sách từ khóa sơ sài cũ kỹ","tr5_c3":"Giao diện thiết kế cho PC","tr5_c4":"Không có UI cảm ứng","faq_lead":"Giải đáp về thư viện C++17/C++20, chuyển đổi từ CppDroid, raw string literal và `&lt;thread&gt;`.","faq1_q":"Tại sao nên chuyển từ các app cũ như CppDroid sang SuperCode?","faq1_a":"Các app cũ viết từ một thập kỷ trước thiếu các header C++17 và C++20 (`&lt;optional&gt;`, `&lt;variant&gt;`, `&lt;string_view&gt;`, `&lt;span&gt;`, `&lt;ranges&gt;`, `&lt;concepts&gt;`) và thường không cài được trên máy Android 14/15 64-bit hiện đại. SuperCode cung cấp môi trường C++20 64-bit được bảo trì liên tục.","faq2_q":"Raw string literal `R\"(...)\"` của C++ có hoạt động với bộ quét header đa tệp không?","faq2_a":"Có. Bộ quét phụ thuộc C++ của SuperCode hiểu chuẩn xác raw string literal C++11/20 (`R\"delim(...)delim\"`) cũng như dấu phân cách chữ số nháy đơn (`1'000'000`), nên chữ `#include` nằm trong chuỗi thô không bao giờ kích hoạt tìm header nhầm.","faq3_q":"`std::unique_ptr`, `std::shared_ptr`, `std::optional` và `std::variant` có chạy 100% offline không?","faq3_a":"Có&#8212;toàn bộ các header `&lt;memory&gt;`, `&lt;optional&gt;`, `&lt;variant&gt;`, `&lt;any&gt;`, `&lt;span&gt;`, `&lt;string_view&gt;`, `&lt;ranges&gt;`, `&lt;concepts&gt;` và `&lt;charconv&gt;` đều biên dịch hoàn toàn offline ngay trên thiết bị của bạn.","faq4_q":"`&lt;thread&gt;`, `std::async`, `&lt;latch&gt;` và `&lt;barrier&gt;` chạy trên Android như thế nào?","faq4_a":"Khi dự án C++ của bạn include các header đa luồng như `&lt;thread&gt;`, `&lt;future&gt;`, `&lt;semaphore&gt;`, `&lt;latch&gt;` hay `&lt;barrier&gt;`, SuperCode tự động đóng gói dự án kèm thẻ `#line` để chuyển sang tầng Cloud C++20 (`-pthread`).","cta_h2":"Nâng cấp lên C++20 Hiện Đại Đích Thực trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; C++20 ranges offline, con trỏ thông minh và 21 mẫu dự án đa tệp."},"cpp_multifile":{"metaTitle":"IDE C++ Đa Tệp cho Android — Bộ liên kết .cpp/.hpp & 21 Mẫu CMake | SuperCode","metaDesc":"Xây dựng dự án C++20 đa tệp .cpp, .hpp và .inl offline trên Android. Tích hợp sẵn 21 dự án mẫu CMake đa tệp hoàn chỉnh, tự động phân tích CMakeLists.txt/Makefile và cache object tăng dần.","hero_tag":"21 DỰ ÁN CMAKE ĐA TỆP &#183; .CPP / .HPP / .INL &#183; CACHE TĂNG DẦN","hero_h1":"Xây dựng <span class=\"text-gradient\">Dự án .cpp / .hpp Đa Tệp &amp; CMake</span> trên Android.","hero_desc":"Kiến trúc phần mềm C++ đa lớp thực thụ ngay trên di động. SuperCode tích hợp sẵn <strong>21 dự án khởi tạo C++ CMake đa tệp hoàn chỉnh</strong>, hỗ trợ <strong><code>.cpp</code>, <code>.cc</code>, <code>.hpp</code> và <code>.inl</code></strong> qua nhiều thư mục con, phân tích trực tiếp <strong><code>CMakeLists.txt</code></strong> và lưu cache các đơn vị object không đổi.","cpp3_s1":"Dự án mẫu CMake","cpp3_s2":"Đuôi tệp C++","cpp3_s3":"Số tệp tối đa/dự án","cpp3_s4":"&amp; Cache .o tăng dần","wb_eyebrow":"KHÔNG GIAN XÂY DỰNG DỰ ÁN .CPP / .HPP ĐA TỆP &amp; CMAKE VỚI 21 MẪU CÓ SẴN","sec_cap_title":"Đầy đủ công cụ cho Đồ án OOP Đại học &amp; Repo C++ Mô-đun hóa","sec_cap_lead":"Tách giao diện vào header `.hpp`, phần cài đặt vào đơn vị `.cpp` và template inline vào tệp `.inl` với trình biên dịch thông minh chuẩn desktop.","f1_title":"21 Dự án C++ CMake Đa Tệp Chạy Ngay Lập Tức","f1_desc":"Khởi tạo dự án đa tệp chuẩn chỉnh (.cpp + .h/.hpp + CMakeLists.txt) chỉ với một chạm&#8212;bao gồm hệ thống ngân hàng/kho hàng OOP, design pattern, thư viện đồ thị &amp; cây, trình phân tích cú pháp và tiện ích CLI, kèm 8 snippet đơn tệp nhanh.","f1_badge":"21 Dự án Đa Tệp + 8 Snippet Đơn Tệp","f2_title":"Hỗ trợ đầy đủ .cpp, .cc, .cxx, .hpp, .hh, .inl &amp; .ipp","f2_desc":"Mã nguồn C++ thực tế thường phối hợp nhiều quy ước đặt tên. Bộ phân giải header/source của SuperCode ghép cặp header .hpp/.hh với các đơn vị .cpp/.cc/.cxx và theo dõi tệp template .inl/.ipp lên tới 350 tệp.","f2_badge":".cpp &#183; .cc &#183; .cxx &#183; .hpp &#183; .hh &#183; .inl &#183; .ipp","f3_title":"Engine Đồ Thị Phụ Thuộc CMakeLists.txt &amp; Makefile Tự Động","f3_desc":"Đọc trực tiếp CMakeLists.txt (project, set, include_directories, add_library, add_executable) và Makefile&#8212;hoặc tự động chuyển sang liên kết thư mục #include \"...\" không cần cấu hình khi bạn muốn code nhanh.","f3_badge":"Phân tích CMakeLists.txt gốc &#183; Dự phòng không cần cấu hình","f4_title":"Chạy Trực Tiếp Từ Tab Header .hpp Hoặc Lớp .cpp","f4_desc":"Đang sửa include/Entity.hpp hay src/Renderer.cpp? Chạm Chạy ngay mà không cần chuyển tab&#8212;bộ điều phối điểm vào của SuperCode tự truy vết đồ thị dự án về main.cpp và khởi chạy tệp thực thi đích.","f4_badge":"Điều hướng thông minh Header -&gt; main.cpp","f5_title":"Cache Object Tăng Dần Theo Từng Đơn Vị Biên Dịch","f5_desc":"Biên dịch lại toàn bộ 15 lớp C++ mỗi lần sửa lỗi chính tả rất tốn pin và thời gian. SuperCode lưu cache tệp .o đã biên dịch theo từng đơn vị và chỉ biên dịch lại các tệp bị ảnh hưởng bởi chỉnh sửa mới nhất.","f5_badge":"Băm Header bắc cầu &#183; Liên kết tăng dần siêu tốc","f6_title":"Quản lý Git Trực Quan &amp; Tìm Tệp Thông Minh (Fuzzy)","f6_desc":"Nhảy qua lại giữa hàng chục tệp .hpp và .cpp trong tích tắc với bộ tìm tệp mờ, xem unified diff có màu, xử lý xung đột trộn nhánh trực quan và đẩy commit đồ án lên GitHub.","f6_badge":"Git Trực Quan &#183; Unified Diff &#183; Tìm kiếm mờ 50k nút","workflow_title":"Cách Khởi Tạo &amp; Xây Dựng Dự Án C++ Đa Tệp Trên Android","workflow_lead":"Mở không gian làm việc CMake đa lớp trong vài giây hoặc clone kho Git có sẵn.","wf1_title":"Tạo Mẫu Khởi Đầu CMake Đa Tệp Hoặc Clone Git","wf1_desc":"Chọn một trong 21 mẫu C++ đa tệp (đầy đủ CMakeLists.txt và các header) hoặc clone repo của riêng bạn.","wf2_title":"Viết Lớp Với Gợi Ý AST std::, :: và -&gt;","wf2_desc":"Chuyển đổi mượt mà giữa phần khai báo include/*.hpp và phần cài đặt src/*.cpp với bộ đệm đồng bộ tức thì.","wf3_title":"Biên Dịch Tăng Dần Các Đơn Vị Thay Đổi Offline","wf3_desc":"SuperCode phân tích CMakeLists.txt (hoặc liên kết #include), tái sử dụng các tệp .o trong cache, liên kết tệp nhị phân và xuất kết quả trực tiếp.","wf4_title":"Đẩy Commit Sạch Lên GitHub Hoặc Xuất Tài Liệu Lab","wf4_desc":"Stage các tệp .hpp/.cpp đã sửa trực quan trong Git hoặc xuất các module chính thành tệp PDF A4 tô màu cú pháp.","wf_foot_note":"Hỗ trợ #pragma once &amp; Include Guard cổ điển &#183; Phản ánh trực tiếp tab chưa lưu","table_h2":"SuperCode Studio C++ Đa Tệp vs. Trình Soạn Thảo Di Động Thường","snippet_p":"<strong>Trình dựng dự án C++ Đa Tệp của SuperCode</strong> biên dịch kiến trúc <code>.cpp</code>, <code>.cc</code>, <code>.hpp</code> và <code>.inl</code> thực tế hoàn toàn offline trên Android. Tích hợp 21 dự án mẫu CMake đa tệp, tự động phân tích target trong <code>CMakeLists.txt</code> và <code>Makefile</code>, định tuyến <code>main()</code> từ tab header và lưu cache object theo từng đơn vị để build tăng dần cực nhanh.","table_caption":"SO SÁNH NĂNG LỰC C++ ĐA TỆP &amp; CMAKE TRÊN ANDROID","th_0":"Tính năng dự án","th_1":"SuperCode C++20 Studio","th_2":"App C++ đơn tệp","th_3":"Sandbox Web đám mây","th_4":"Cài đặt CLI thủ công","tr1_c0":"Mẫu dự án khởi đầu","tr1_c1":"21 Dự án CMake Đa Tệp + 8 Snippet","tr1_c2":"1-3 ví dụ đơn tệp","tr1_c3":"Tệp main.cpp trống","tr1_c4":"Không có","tr2_c0":"Định dạng tệp hỗ trợ","tr2_c1":"`.cpp .cc .cxx .hpp .hh .h .inl .ipp`","tr2_c2":"`.cpp` &amp; `.h` trong 1 thư mục","tr2_c3":"`.cpp` / `.h` cơ bản","tr2_c4":"Tự viết quy tắc","tr3_c0":"Hỗ trợ CMakeLists.txt","tr3_c1":"Tích hợp bộ phân tích Target &amp; Đồ thị Include","tr3_c2":"Bị bỏ qua","tr3_c3":"Gói trả phí hoặc container","tr3_c4":"Cần CLI cmake","tr4_c0":"Tốc độ Build tăng dần","tr4_c1":"Cache `.o` theo mã băm nội dung từng TU","tr4_c2":"Biên dịch lại toàn bộ","tr4_c3":"Biên dịch từ xa không cache","tr4_c4":"Có hỗ trợ","tr5_c0":"Git &amp; Giao diện xung đột","tr5_c1":"Git Trực Quan tích hợp + Unified Diff","tr5_c2":"Phải dùng app ngoài","tr5_c3":"Yêu cầu đăng nhập GitHub OAuth","tr5_c4":"Chỉ dùng CLI git","faq_lead":"Câu hỏi thường gặp về 21 mẫu dự án C++, tệp `.hpp`/`.inl`, `#pragma once` và CMake trên Android.","faq1_q":"21 dự án khởi đầu C++ đa tệp của SuperCode gồm những gì?","faq1_a":"Mỗi mẫu trong 21 mẫu dự án sẽ tạo sẵn cấu trúc thư mục gọn gàng gồm các header `.h`/`.hpp` mô-đun hóa, các tệp cài đặt `.cpp`, tệp điều khiển `main.cpp` và một `CMakeLists.txt` chuẩn&#8212;giúp bạn chạy, nghiên cứu hoặc tùy biến kiến trúc đa lớp ngay lập tức.","faq2_q":"Tôi có thể mở dự án CMake tạo trên SuperCode bằng CLion hoặc VS Code trên laptop không?","faq2_a":"Có! Vì các dự án được tạo ra dùng `CMakeLists.txt` chuẩn và bố cục thư mục ISO/GNU C++20 tương thích đa nền tảng, bạn có thể mở mượt mà trên IDE máy tính qua Git mà không bị khóa định dạng độc quyền.","faq3_q":"SuperCode có hỗ trợ thư viện chỉ chứa header (header-only) và tệp cài đặt template `.inl` / `.ipp` không?","faq3_a":"Có. Cả header dùng `#pragma once` lẫn các tệp template `.inl` / `.ipp` nằm trong `include/` hoặc thư mục con lồng nhau đều được bộ quét phụ thuộc và cache mã băm nội dung theo dõi đầy đủ.","faq4_q":"Nếu tôi đổi tên hoặc tách một tệp `.cpp` khi đang làm việc offline thì sao?","faq4_a":"Cả bộ phân tích `CMakeLists.txt` lẫn trình thu thập `#include` không cấu hình đều tự động lập lại chỉ mục không gian làm việc ở lần Chạy tiếp theo, nhận diện ngay các tệp `.cpp` và `.hpp` vừa thêm hoặc đổi tên.","cta_h2":"Kiến trúc Dự án C++20 Đa Lớp ngay trên Android.","cta_desc":"Cài đặt miễn phí SuperCode IDE trên Google Play &#8212; 21 mẫu CMake đa tệp, cache .o tăng dần và Git trực quan."},"cpp_learn":{"metaTitle":"Học C++ Offline trên Android — App Lập Trình C++20 Miễn Phí Cho Người Mới & Sinh Viên IT | SuperCode","metaDesc":"Học và thực hành C++20 offline trên Android không cần đăng ký tài khoản. Tích hợp 8 snippet đơn tệp + 21 dự án C++ đa tệp, thanh 21 phím ký tự C++ (::, ->, >), Error Radar, định dạng 1 chạm và xuất PDF A4.","hero_tag":"KHÔNG CẦN ĐĂNG NHẬP &#183; C++20 CHẠY CHẾ ĐỘ MÁY BAY 100% &#183; 29 MẪU KHỞI ĐẦU","hero_h1":"Học &amp; Thực Hành <span class=\"text-gradient\">C++ Offline trên Android</span> &#8212; Không Cần Thiết Lập.","hero_desc":"Bỏ qua các app đố vui trắc nghiệm và tường thu phí tài khoản. Viết, biên dịch và gỡ lỗi <strong>chương trình C++20 thực thụ 100% offline</strong> với <strong>29 mẫu khởi đầu chạy được ngay</strong>, <strong>thanh 21 phím ký tự C++ (<code>::</code>, <code>-&gt;</code>, <code>&lt;&lt;</code>, <code>&gt;&gt;</code>)</strong>, <strong>Error Radar</strong> và <strong>xuất bài tập PDF A4</strong>.","cpp4_s1":"Không cần đăng nhập hay Wi-Fi","cpp4_s2":"8 Snippet + 21 Dự án","cpp4_s3":"Thanh :: -&gt; &lt;&lt; &gt;&gt; {}","cpp4_s4":"Xuất PDF bài thực hành","wb_eyebrow":"MÔI TRƯỜNG HỌC C++20 OFFLINE TỪ NGƯỜI MỚI ĐẾN SINH VIÊN CNTT","sec_cap_title":"Thiết Kế Để Bàn Phím Điện Thoại Không Bao Giờ Cản Trở Việc Học C++","sec_cap_lead":"Từ dòng `std::cout &lt;&lt; \"Hello!\"` đầu tiên cho tới lập trình hướng đối tượng, cây tìm kiếm nhị phân và portfolio GitHub.","f1_title":"Không Cần Đăng Ký &amp; Biên Dịch Chế Độ Máy Bay Thực Thụ","f1_desc":"Tải bộ công cụ C++20 offline một lần và luyện tập mọi nơi&#8212;trên xe buýt, tàu điện, máy bay hay giảng đường không có Wi-Fi. Không bắt buộc tạo tài khoản và không giới hạn thời gian token mỗi lần chạy.","f1_badge":"100% C++20 Offline &#183; Không rào cản tài khoản","f2_title":"8 Snippet Đơn Tệp + 21 Dự Án Khởi Đầu Đa Tệp","f2_desc":"Bắt đầu nhẹ nhàng với 8 ví dụ C++ đơn tệp (nhập/xuất, vector, sắp xếp, lớp OOP, đệ quy), rồi chuyển dần lên 21 dự án CMake .cpp/.h đa tệp khi các môn học đại học nâng cao hơn.","f2_badge":"Tích hợp sẵn 29 Mẫu C++ chạy được ngay","f3_title":"Thanh Ký Tự C++ Vuốt Lên 21 Phím","f3_desc":"Bàn phím điện thoại thông thường giấu kín ::, &lt;&lt;, &gt;&gt;, -&gt;, {} và ; sâu tới ba lớp. SuperCode gắn cố định thanh ký tự C++ ngay phía trên bàn phím để bạn gõ toán tử luồng và ngoặc nhọn chỉ với một chạm.","f3_badge":":: &#183; -&gt; &#183; &lt;&lt; &#183; &gt;&gt; &#183; {} &#183; [] &#183; ; &#183; #include","f4_title":"Error Radar Thời Gian Thực &amp; Chạm Nhảy Đến Dòng Lỗi","f4_desc":"Quên dấu chấm phẩy sau ngoặc đóng class hoặc thiếu dấu ngoặc tròn? Error Radar gạch chân trực tiếp lỗi cấu trúc cú pháp ngay khi bạn gõ, còn thông báo trình biên dịch nhảy thẳng đến đúng dòng lỗi.","f4_badge":"Bảo vệ cú pháp trực tiếp &#183; Nhảy dòng thân thiện người mới","f5_title":"Định Dạng Offline 1 Chạm &amp; 8 Giao Diện Bảo Vệ Mắt","f5_desc":"Chạm Định dạng để căn chỉnh vòng lặp lồng nhau, khối switch và thụt lề lớp ngay tức thì kèm Hoàn tác nguyên khối. Học tập thoải mái ngày hay đêm với 8 giao diện studio (nền sáng sắc nét và nền tối dịu mắt).","f5_badge":"Định dạng C++ 1 chạm &#183; 8 Giao diện Sáng &amp; Tối","f6_title":"Xuất Bài Tập PDF A4 Chuẩn Gốc + Phát Triển Đa Ngôn Ngữ","f6_desc":"Xuất bài tập C++ hoàn chỉnh thành tệp PDF A4 sắc nét, tô màu cú pháp để nộp cho trường&#8212;và dùng chính ứng dụng này khi chương trình học mở rộng sang C17, Python, Java 17, SQL và Git.","f6_badge":"Xuất PDF A4 &#183; Tích hợp cả C17, Python, Java &amp; SQL","workflow_title":"5 Phút Đầu Tiên Học C++ Trong SuperCode","workflow_lead":"Không cần cấu hình PATH, trình biên dịch hay biến môi trường&#8212;chỉ cần mở app và code.","wf1_title":"Chọn 1 Trong 8 Snippet Hoặc 21 Dự Án Mẫu","wf1_desc":"Mở một ví dụ C++ chạy sẵn hoặc tạo main.cpp trong bất kỳ thư mục cục bộ nào&#8212;không cần đăng nhập.","wf2_title":"Viết Code Thoải Mái Với Thanh C++ 21 Phím","wf2_desc":"Chèn nhanh std::cout &lt;&lt;, std::cin &gt;&gt;, ngoặc nhọn và dấu chấm phẩy trong khi Error Radar theo dõi lỗi gõ nhầm.","wf3_title":"Kiểm Thử Nhập std::cin Trực Tiếp Offline","wf3_desc":"Nhập số và chuỗi tương tác trực tiếp trong console và xem kết quả cùng lời nhắc không bị đệm ngay tức thì.","wf4_title":"Căn Chỉnh Thụt Lề &amp; Chia Sẻ Bài Thực Hành PDF A4","wf4_desc":"Làm đẹp code C++ chỉ với một chạm và xuất tệp PDF A4 tô màu cú pháp để nộp cho giảng viên hoặc LMS.","wf_foot_note":"App gọn nhẹ 40.2 MB &#183; 32 Ngôn ngữ giao diện &#183; Chạy mượt trên Điện thoại &amp; Máy tính bảng","table_h2":"SuperCode vs. App Đố Vui Học Code &amp; Trình Biên Dịch C++ Trực Tuyến","snippet_p":"<strong>SuperCode</strong> là ứng dụng lập trình C++20 offline miễn phí dành cho người mới bắt đầu trên Android, học sinh THPT và sinh viên ngành CNTT. Không tường đăng nhập, app mang đến khả năng biên dịch chế độ máy bay, 29 mẫu C++ đơn/đa tệp chạy được ngay, thanh 21 phím ký tự C++, Error Radar, định dạng một chạm và xuất bài tập PDF A4.","table_caption":"HỌC C++ TRÊN ANDROID: SO SÁNH ỨNG DỤNG CHO SINH VIÊN","th_0":"Nhu cầu sinh viên","th_1":"Ứng dụng SuperCode C++20","th_2":"App học kiểu trắc nghiệm","th_3":"IDE trực tuyến trên trình duyệt","th_4":"Chỉ dùng Laptop","tr1_c0":"Chạy C++20 thực thụ","tr1_c1":"Đầy đủ GNU C++20 Offline + STL + Đa tệp","tr1_c2":"Bài tập điền khuyết trắc nghiệm","tr1_c3":"Ô nhập web đơn tệp","tr1_c4":"Đầy đủ","tr2_c0":"Học ở chế độ máy bay","tr2_c1":"100% Offline sau 1 lần cài Toolchain","tr2_c2":"Thường đòi gói cước/mạng","tr2_c3":"Tê liệt khi mất Wi-Fi","tr2_c4":"Offline","tr3_c0":"Gõ code trên màn hình cảm ứng","tr3_c1":"Thanh C++ 21 phím (`:: -&gt; &lt;&lt; &gt;&gt;`) + AST","tr3_c2":"Ít được tự gõ code thật","tr3_c3":"Bàn phím mặc định chật chội","tr3_c4":"Bàn phím vật lý","tr4_c0":"Lộ trình theo môn học","tr4_c1":"8 Snippet -&gt; 21 Dự án CMake -&gt; Git","tr4_c2":"Chạm trần ngay sau phần cơ bản","tr4_c3":"Không có thư mục cục bộ hay Git","tr4_c4":"Đầy đủ","tr5_c0":"Xuất báo cáo thực hành","tr5_c1":"PDF A4 tô màu cú pháp tích hợp sẵn","tr5_c2":"Không hỗ trợ","tr5_c3":"Sao chép dán thủ công","tr5_c4":"Hộp thoại In ấn","faq_lead":"Các câu hỏi phổ biến từ người mới, sinh viên năm nhất ngành CNTT và giảng viên lập trình.","faq1_q":"Tôi có cần laptop hay kinh nghiệm lập trình để bắt đầu học C++ trên SuperCode không?","faq1_a":"Không cần laptop hay kinh nghiệm cài đặt. SuperCode tự động cấu hình toàn bộ trình biên dịch C++20&#8212;bạn chỉ cần chạm vào một trong 8 snippet C++ cho người mới, nhấn Chạy và thử sửa từng dòng code một cách trực quan.","faq2_q":"Tôi có thể luyện tập cấu trúc dữ liệu đại học (danh sách liên kết, cây, đồ thị, bảng băm) trên điện thoại không?","faq2_a":"Có! Cả cấu trúc dữ liệu dùng con trỏ thuần/lớp (danh sách liên kết, cây tìm kiếm nhị phân, heap, trie) lẫn đầy đủ các container STL của C++20 (`vector`, `stack`, `queue`, `unordered_map`, `priority_queue`) đều chạy 100% offline.","faq3_q":"Làm sao để nộp bài tập `.cpp` lên Canvas, Blackboard hoặc Google Classroom?","faq3_a":"Bạn có thể chia sẻ trực tiếp tệp `.cpp`/`.hpp` từ thư mục dự án Android, đẩy thư mục lên GitHub qua Git trực quan, hoặc chạm Xuất PDF để tạo tài liệu PDF A4 sạch sẽ có tô màu cú pháp.","faq4_q":"Tôi có thể chạy thêm C, Python, Java và SQL ngay trong cùng ứng dụng cho các môn CNTT khác không?","faq4_a":"Có. SuperCode tích hợp sẵn các môi trường offline chuyên biệt cho C17, C++20, Python 3.11/3.12, Java 17, JavaScript, Lua 5.4, PHP/Web và SQLite chỉ trong một Android studio gọn nhẹ 40.2 MB.","cta_h2":"Bắt Đầu Viết C++20 Thực Thụ Offline Ngay Hôm Nay.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; không cần đăng ký, 29 mẫu khởi đầu C++ và xuất PDF A4."},"jv_records_17":{"metaTitle":"Trình biên dịch Java 17 cho Android — Records, Sealed Classes, Streams & Java 21+ Offline | SuperCode","metaDesc":"Biên dịch và chạy Java 17 hiện đại offline trên Android. Hỗ trợ records, sealed classes, biểu thức switch ->, pattern matching, text blocks và Streams — kèm Cloud Java 21+ virtual threads tự động.","hero_tag":"JAVA 17 LTS OFFLINE &#183; RECORDS &#183; SEALED &#183; CLOUD JAVA 21+","hero_h1":"Chạy <span class=\"text-gradient\">Java 17 Records, Sealed Classes &amp; Streams</span> Offline trên Android.","hero_desc":"Ngừng viết lại bài tập hiện đại chỉ để chiều lòng các trình biên dịch Java 8 hay Java 11 lỗi thời trên điện thoại. SuperCode biên dịch <strong>LTS Java 17 100% offline</strong> &#8212; hỗ trợ đầy đủ kiểu <strong><code>record</code></strong>, phân cấp <strong><code>sealed</code></strong>, biểu thức <strong><code>switch -&gt;</code></strong>, text blocks và virtual threads <strong>Cloud Java 21+</strong>.","jvr_s1":"100% LTS Offline","jvr_s2":"&amp; Sealed Classes","jvr_s3":"Switch -&gt; &amp; Time","jvr_s4":"Cloud Virtual Threads","wb_eyebrow":"MÔI TRƯỜNG JAVA 17 &amp; CLOUD JAVA 21+ HIỆN ĐẠI","sec_cap_title":"Vì sao lập trình viên nâng cấp từ trình biên dịch Java 8/11 cũ trên di động","sec_cap_lead":"Viết mã Java hiện đại súc tích, không boilerplate ngay trên điện thoại hoặc máy tính bảng với đúng cú pháp LTS dùng trong giảng đường và phỏng vấn backend.","f1_title":"Java 17 Records bất biến &amp; Compact Constructor","f1_desc":"Thay thế 70 dòng boilerplate getter, equals(), hashCode() và toString() bằng một khai báo record duy nhất. Hỗ trợ compact canonical constructor để validate dữ liệu, generic record, local record trong hàm và triển khai interface.","f1_badge":"record Order(...) &#183; Compact Validation &#183; Local Records","f2_title":"Sealed Classes &amp; Phân cấp miền đại số","f2_desc":"Mô hình hóa state machine đóng, node AST và trạng thái thanh toán gọn gàng bằng sealed class và sealed interface kết hợp permits, final và non-sealed &#8212; kiểm tra hoàn toàn offline lúc biên dịch.","f2_badge":"sealed interface &#183; permits &#183; Kiểm tra vét cạn lúc biên dịch","f3_title":"Biểu thức Switch mũi tên, Pattern Matching &amp; Text Blocks","f3_desc":"Loại bỏ lỗi fall-through bằng biểu thức switch (-&gt;) và yield, ép kiểu nội tuyến với pattern matching if (obj instanceof Card c), suy luận kiểu generic dài dòng bằng var, và nhúng chuỗi JSON/SQL đa dòng sạch sẽ với \\\"\\\"\\\" text blocks.","f3_badge":"switch -&gt; &#183; instanceof Pattern &#183; \\\"\\\"\\\" Text Blocks &#183; var","f4_title":"Streams hiện đại (.toList()), java.time &amp; CompletableFuture","f4_desc":"Xâu chuỗi xử lý hàm với Stream.toList(), Stream.mapMulti(), Optional.ifPresentOrElse() của Java 17, factory bất biến Map.of(), tính toán thời gian java.time LocalDate/Instant và pipeline bất đồng bộ CompletableFuture.","f4_badge":"Stream.toList() &#183; java.time &#183; CompletableFuture","f5_title":"Sinh ra để thay thế app Java 8 &amp; Java 11 cũ kỹ trên điện thoại","f5_desc":"Nhiều ứng dụng Java cũ trên Android báo lỗi cú pháp với từ khóa record, text blocks hay .toList(). SuperCode biên dịch đầy đủ target Java 17 ngay trên thiết bị và cache bytecode không đổi để chạy lại tức thì.","f5_badge":"--release 17 &#183; Chạy lại cache 0ms &#183; Tự hoàn thành AST","f6_title":"Tự động chạy Virtual Threads Java 21+ &amp; Record Patterns trên Cloud","f6_desc":"Đang thử nghiệm virtual threads của Project Loom (Thread.ofVirtual(), Executors.newVirtualThreadPerTaskExecutor()), sequenced collections hay record deconstruction lồng nhau? SuperCode tự động nhận diện cú pháp Java 21+ và chạy dự án trên Cloud Java.","f6_badge":"Thread.ofVirtual() &#183; SequencedCollection &#183; Cloud Java 21+","workflow_title":"Cách biên dịch mã Java 17 &amp; Java 21+ trên Android","workflow_lead":"Không cần biến môi trường JDK hay tải Gradle wrapper &#8212; mở tệp và biên dịch ngay.","wf1_title":"Viết Java 17 Records, Sealed Types hoặc main() gọn nhẹ","wf1_desc":"Tạo tệp .java với thanh ký tự Java 21 phím và gợi ý AST offline cho java.util, java.time và java.util.stream.","wf2_title":"Tự động căn ngoặc &amp; kiểm tra cú pháp trực tiếp","wf2_desc":"Nhấn Định dạng để căn chỉnh switch mũi tên, records và text blocks chuẩn đẹp trong khi Error Radar bắt dấu ngoặc chưa đóng theo thời gian thực.","wf3_title":"Biên dịch Java 17 100% Offline trong vài mili-giây","wf3_desc":"Ở lần chạy đầu tiên, SuperCode khởi tạo SDK Java 17 offline một lần duy nhất; mọi bản build sau đều biên dịch cục bộ với cache SHA-256.","wf4_title":"Mở rộng lên Cloud Java 21+ bất cứ khi nào cần","wf4_desc":"Dùng virtual threads Java 21+ hoặc chú thích // @cloud bất kỳ lúc nào để thử JDK mới hơn kèm stack trace khớp 1:1 trong trình soạn thảo.","wf_foot_note":"SDK Java 17 Offline đầy đủ &#183; Cache Bytecode SHA-256 &#183; Hỗ trợ lai Cloud Java 21+","table_h2":"So sánh SuperCode Java 17 Studio với trình biên dịch Java cũ trên Android","snippet_p":"<strong>Trình biên dịch SuperCode Java 17 cho Android</strong> biên dịch và chạy LTS Java 17 hiện đại hoàn toàn offline trên điện thoại và máy tính bảng. Khác với các trình biên dịch di động cũ bị kẹt ở Java 8 hoặc Java 11, app hỗ trợ records, sealed classes, biểu thức switch mũi tên, pattern matching, text blocks và Streams offline, cộng thêm virtual threads Cloud Java 21+.","table_caption":"HỖ TRỢ NGÔN NGỮ JAVA HIỆN ĐẠI TRÊN ANDROID","th_0":"Tính năng Java","th_1":"SuperCode Java Studio","th_2":"App Java 8 / 11 di động","th_3":"Sandbox trình duyệt Web","th_4":"OpenJDK CLI thủ công","tr1_c0":"Records &amp; Kiểu Sealed","tr1_c1":"Hỗ trợ gốc Java 17 Offline 100%","tr1_c2":"Lỗi cú pháp (Không hỗ trợ)","tr1_c3":"Bắt buộc có mạng internet","tr1_c4":"Tự gõ cờ javac trên CLI","tr2_c0":"Switch -&gt; &amp; Text Blocks","tr2_c1":"Đầy đủ Arrow Switch, yield &amp; khối \\\"\\\"\\\"","tr2_c2":"Thiếu hoặc chỉ preview một phần","tr2_c3":"Ô dán một tệp duy nhất","tr2_c4":"Không có thanh ký tự cảm ứng","tr3_c0":"Stream.toList() &amp; var","tr3_c1":"API chuẩn Java 17 tích hợp sẵn","tr3_c2":"Chỉ có Collectors.toList() dài dòng","tr3_c3":"Độ trễ mạng mỗi lần chạy","tr3_c4":"CLI đầy đủ","tr4_c0":"Java 21+ Virtual Threads","tr4_c1":"Tự định tuyến lên Cloud Java 21+","tr4_c2":"Không hỗ trợ","tr4_c3":"Hiếm khi cập nhật lên 21+","tr4_c4":"Tốn 2+ GB root/proot thủ công","tr5_c0":"Độ trễ build lại","tr5_c1":"Trúng Cache &#9889; SHA-256 gần 0ms","tr5_c2":"Biên dịch lại từ đầu","tr5_c3":"Hàng đợi mạng 2s&#8211;5s","tr5_c4":"Tự viết script build thủ công","faq_lead":"Giải đáp về hỗ trợ ngôn ngữ Java 17 offline, chuyển đổi từ Jvdroid và tính năng Java 21+ trên Android.","faq1_q":"SuperCode có thực sự biên dịch được Java 17 records và sealed classes khi không có mạng không?","faq1_a":"Có. Sau khi SDK Java 17 offline gọn nhẹ khởi tạo ở lần mở đầu tiên, `record`, `sealed` / `permits`, biểu thức `switch -&gt;`, pattern matching `instanceof`, text blocks (`\\\"\\\"\\\"`) và `Stream.toList()` đều biên dịch và chạy 100% offline ngay cả ở chế độ máy bay.","faq2_q":"SuperCode thay thế các ứng dụng Java 8 hoặc Java 11 cũ trên di động như thế nào?","faq2_a":"Các app Java Android đời cũ thường báo lỗi khi gặp bài tập đại học hoặc lời giải LeetCode dùng tuple `record`, `Stream.toList()` hay biểu thức switch. SuperCode hỗ trợ đầy đủ LTS Java 17 offline kèm dự phòng Cloud Java 21+ tự động, Visual Git và SQLite JDBC tích hợp sẵn.","faq3_q":"Tôi có thể dùng `CompletableFuture`, `Optional` và `java.time` offline không?","faq3_a":"Có. Toàn bộ thư viện chuẩn cốt lõi &#8212; bao gồm `java.util.stream`, `java.util.concurrent.CompletableFuture`, `java.time.*`, `java.math.BigDecimal` và `java.nio.file` &#8212; đều chạy cục bộ hoàn toàn offline.","faq4_q":"Làm sao để chạy virtual threads Java 21 trên điện thoại Android?","faq4_a":"Chỉ cần viết `Thread.ofVirtual()` hoặc `Executors.newVirtualThreadPerTaskExecutor()` (hoặc thêm `// @cloud` ở đầu tệp) rồi nhấn Chạy. SuperCode tự động đóng gói các class dự án lên Cloud Java 21+ và trả kết quả về console.","cta_h2":"Nâng cấp lên Java 17 Offline trên Android ngay hôm nay.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; biên dịch Java 17 records, sealed classes và Streams mọi nơi."},"jv_multiclass":{"metaTitle":"Biên dịch nhiều lớp Java & Thư viện .jar trên Android — IDE đa Package Offline | SuperCode","metaDesc":"Build dự án Java 17 nhiều class, nhiều package offline trên Android. Quét tối đa 500 tệp .java, tự động nạp thư viện libs/*.jar (tối đa 30 MB), đóng gói resources/ và chạy lại gần 0ms qua cache SHA-256.","hero_tag":"500 TỆP .JAVA &#183; LIBS/*.JAR &#183; MAIN() THÔNG MINH &#183; CACHE &#9889; 0MS","hero_h1":"Build <span class=\"text-gradient\">Dự án Java nhiều Class, Package &amp; .jar tùy chỉnh</span> Offline trên Android.","hero_desc":"Phần mềm hướng đối tượng thực thụ không gói gọn trong một tệp <code>Main.java</code>. SuperCode biên dịch tối đa <strong>500 class <code>.java</code> qua các package lồng nhau</strong>, tự gắn thư viện <strong><code>libs/*.jar</code></strong> ngoài, phân giải tài nguyên <strong><code>getResourceAsStream()</code></strong> và chạy lại bản build không đổi chỉ trong <strong>gần <code>0ms</code></strong>.","jvm_s1":"Tối đa tệp .java","jvm_s2":"Trình nạp libs/*.jar","jvm_s3":"Cache SHA-256 &#9889;","jvm_s4":"Định tuyến main()","wb_eyebrow":"MÔI TRƯỜNG OOP ĐA PACKAGE &amp; CLASSPATH .JAR TÙY CHỈNH","sec_cap_title":"Kiến trúc Java Package chuẩn Desktop không cần chờ Gradle nặng nề","sec_cap_lead":"Tổ chức gọn gàng các package domain, service và repository trên Android mà không phải vật lộn với 4 phút đồng bộ Gradle hay cờ `javac -cp` thủ công.","f1_title":"Quét tới 500 tệp .java xuyên suốt các Package lồng nhau","f1_desc":"Tổ chức dự án theo chuẩn thư mục Maven/Gradle (src/main/java/com/company/...) hoặc thư mục con gọn nhẹ. SuperCode quét tối đa 500 tệp .java (hạn mức mã nguồn 12 MB) và biên dịch import liên package trong một lượt.","f1_badge":"src/main/java &#183; Package lồng nhau &#183; 500 Tệp / 12 MB","f2_title":"Trình nạp Classpath libs/*.jar &amp; lib/*.jar không cần cấu hình","f2_desc":"Cần dùng Gson, Apache Commons, org.json hay thư viện chấm bài của giảng viên? Thả tệp .jar thuần Java (tổng tối đa 30 MB) vào thư mục libs/ hoặc lib/ của dự án và import dùng ngay offline.","f2_badge":"libs/*.jar &#183; lib/*.jar &#183; Classpath tối đa 30 MB","f3_title":"Cache bao đóng SHA-256 giúp chạy lại gần 0ms tức thì","f3_desc":"SuperCode tính mã băm SHA-256 trên toàn bộ mã nguồn .java, buffer các tab đang mở và tệp .jar. Khi chạy thử lại với input console khác, hệ thống trúng Cache &#9889; trong ~0ms mà không cần biên dịch lại.","f3_badge":"Băm SHA-256 &#183; Huy hiệu Cache &#9889; &#183; Khởi chạy tức thì","f4_title":"Tự tìm điểm vào main() thông minh từ bất kỳ tab nào đang mở","f4_desc":"Đang sửa interface InvoiceRepository hay class hỗ trợ TaxCalculator? Nhấn Chạy &#9654; ngay tại đó &#8212; SuperCode quét đồ thị package, tìm lớp chứa hàm main() của dự án và tự gộp cả nội dung tab chưa lưu.","f4_badge":"Chạy từ mọi Tab &#183; Gộp Buffer chưa lưu","f5_title":"Tự động đóng gói tài nguyên Classpath trong resources/","f5_desc":"Đặt các mẫu .properties, .json, .csv, .xml hay .txt vào thư mục resources/ hoặc src/main/resources/. Các class của bạn đọc trực tiếp bằng Class.getResourceAsStream() hoặc ClassLoader.getResource() hệt như trên máy tính.","f5_badge":"resources/ &#183; src/main/resources/ &#183; getResourceAsStream","f6_title":"Tìm kiếm mờ 50k nút, Gợi ý AST &amp; Visual Git","f6_desc":"Nhảy nhanh giữa hàng chục class Java trong tích tắc bằng tìm kiếm mờ CamelCase (ví dụ gõ 'ICR' ra ngay InvoiceController.java), tái cấu trúc với gợi ý AST và commit cột mốc qua Visual Git tích hợp.","f6_badge":"Nhảy tệp CamelCase &#183; Gợi ý thành viên AST &#183; Visual Git","workflow_title":"Cách tổ chức dự án đa Package &amp; .jar trên Android","workflow_lead":"Thiết lập không gian làm việc OOP nhiều package với thư viện .jar bên thứ ba chỉ trong 4 bước.","wf1_title":"Tạo thư mục Package hoặc Clone kho Git","wf1_desc":"Tạo các thư mục package lồng nhau trong Trình duyệt tệp (hoặc clone sẵn repo Java từ GitHub/trường học qua Visual Git của SuperCode).","wf2_title":"Thả tệp .jar bên thứ ba vào thư mục libs/","wf2_desc":"Chép các tệp .jar thuần Java tương thích vào libs/ hoặc lib/ và đặt tệp cấu hình tĩnh vào resources/.","wf3_title":"Nhấn Chạy ngay khi đang ở class phụ trợ","wf3_desc":"Nhấn Chạy &#9654; kể cả khi đang xem tab model hay interface &#8212; SuperCode tự chọn main() và biên dịch toàn bộ cây package offline.","wf4_title":"Kiểm thử edge case tức thì với bản build cache 0ms","wf4_desc":"Chạy lại ngay với dữ liệu Scanner mới hoặc tham số CLI khác nhờ cơ chế cache bytecode SHA-256.","wf_foot_note":"Tối đa 500 nguồn .java (12 MB) &#183; Hạn mức .jar 30 MB &#183; Đồng bộ tab chưa lưu","table_h2":"So sánh hỗ trợ dự án Java nhiều tệp &amp; .jar","snippet_p":"<strong>SuperCode Multi-Class Java IDE</strong> build các dự án Java 17 đa package thực thụ offline trên Android mà không cần gánh Gradle. Ứng dụng quét tối đa 500 tệp nguồn qua các package lồng nhau, tự nạp thư viện .jar từ libs/, định tuyến class chứa main() thông minh và cache bao đóng biên dịch theo mã băm SHA-256 để chạy lại gần 0ms.","table_caption":"KHẢ NĂNG BUILD JAVA ĐA CLASS &amp; .JAR TRÊN ANDROID","th_0":"Năng lực dự án","th_1":"SuperCode Java 17 IDE","th_2":"App Java di động cơ bản","th_3":"Trình biên dịch web online","th_4":"Bản port Gradle nặng nề","tr1_c0":"Quy mô đa Package","tr1_c1":"Tới 500 tệp .java qua src/main/java","tr1_c2":"1 thư mục hoặc danh sách thủ công","tr1_c3":"1 tệp (chỉ Main.java)","tr1_c4":"Ngốn RAM &amp; bộ nhớ lưu trữ cao","tr2_c0":"Thư viện .jar tùy chỉnh","tr2_c1":"Tự nạp libs/*.jar &amp; lib/*.jar (30 MB)","tr2_c2":"Không hỗ trợ hoặc khóa trả phí","tr2_c3":"Không tải được .jar riêng","tr2_c4":"Bắt buộc đồng bộ Maven online","tr3_c0":"Trải nghiệm điểm vào main()","tr3_c1":"Tự tìm main() từ mọi tab đang mở","tr3_c2":"Lỗi nếu đang mở tab phụ trợ","tr3_c3":"Cố định tên class Main","tr3_c4":"Cấu hình XML chạy thủ công","tr4_c0":"Tài nguyên Classpath","tr4_c1":"Tự gắn resources/ qua getResourceAsStream","tr4_c2":"Thiếu gốc classpath","tr4_c3":"Không hỗ trợ","tr4_c4":"Có hỗ trợ","tr5_c0":"Chạy lại không đổi mã","tr5_c1":"Trúng Cache &#9889; SHA-256 gần 0ms","tr5_c2":"Biên dịch lại toàn bộ mỗi lần bấm","tr5_c3":"Đợi hàng đợi mạng mỗi lần bấm","tr5_c4":"Daemon tăng dần chậm chạp","faq_lead":"Câu hỏi thường gặp về cấu trúc đa package, thêm thư viện .jar ngoài và phân giải main().","faq1_q":"Làm sao để thêm thư viện `.jar` ngoài như Gson hoặc Commons Lang trong SuperCode?","faq1_a":"Tạo thư mục tên `libs` (hoặc `lib`) trong thư mục gốc dự án Java của bạn rồi chép tệp `.jar` vào đó. SuperCode tự động đưa toàn bộ tệp `.jar` trong `libs/` (tối đa 30 MB) vào cả classpath biên dịch lẫn chạy thực thi &#8212; không cần viết script build.","faq2_q":"Điều gì xảy ra nếu tôi nhấn Chạy khi đang sửa một class Java không có hàm `main()`?","faq2_a":"Bộ phân giải điểm vào của SuperCode sẽ quét các class đã biên dịch trong dự án, tự động chọn class chính có chứa `main()` để chạy &#8212; giúp bạn không phải chuyển tab qua lại liên tục.","faq3_q":"Tôi có bắt buộc dùng `src/main/java` không, hay thư mục nhiều tệp đơn giản vẫn chạy được?","faq3_a":"Cả hai đều chạy mượt! Bạn có thể đặt hai tệp `.java` cạnh nhau trong một thư mục đơn giản không cần khai báo `package`, tổ chức trực tiếp các thư mục con `com.example.*`, hoặc dùng cấu trúc đầy đủ `src/main/java` + `resources/` + `libs/`.","faq4_q":"Những tệp `.jar` nào chạy được offline trên Android?","faq4_a":"Mọi thư viện `.jar` thuần Java chuẩn nhắm mục tiêu Java 8, 11 hoặc 17 (như `gson`, `org.json`, `commons-lang3`, `commons-csv`, hoặc thư viện chấm bài của trường) đều chạy 100% offline. Các jar giao diện desktop đòi hỏi cửa sổ AWT/Swing không dành cho console di động.","cta_h2":"Build dự án Java nhiều Package thực thụ ngay trên điện thoại.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; build Java 17 tới 500 tệp, hỗ trợ libs/*.jar và cache chạy lại 0ms."},"jv_jdbc_sqlite":{"metaTitle":"Java SQLite JDBC & NIO.2 File I/O trên Android — App lập trình CSDL Offline | SuperCode","metaDesc":"Viết chương trình Java kết nối CSDL và đọc ghi tệp offline trên Android. Kết nối qua jdbc:sqlite tích hợp sẵn không cần Maven, xem tệp .db trong SQL Studio, đồng bộ NIO.2 Files vào thư mục và dùng HttpClient.","hero_tag":"JDBC:SQLITE TÍCH HỢP &#183; JAVA NIO.2 FILES &#183; HTTPCLIENT","hero_h1":"Chạy <span class=\"text-gradient\">Java SQLite JDBC, NIO.2 File I/O &amp; HttpClient</span> Offline trên Android.","hero_desc":"Làm đồ án backend xử lý dữ liệu thực tế mà không phải vật lộn với Maven trên di động. SuperCode tích hợp sẵn <strong><code>org.sqlite.JDBC</code></strong> &#8212; chạy <strong><code>jdbc:sqlite:app.db</code></strong> offline, kiểm tra trực quan chính cơ sở dữ liệu đó trong <strong>SQL Studio</strong> và đồng bộ <strong><code>java.nio.file.Files</code></strong> thẳng vào thư mục làm việc Android.","jvj_s1":"SQLite tích hợp sẵn","jvj_s2":"Không cần Maven/Gradle","jvj_s3":"Đồng bộ thư mục thật","jvj_s4":"Java HttpClient","wb_eyebrow":"MÔI TRƯỜNG JAVA SQLITE JDBC, ĐỒNG BỘ TỆP NIO.2 &amp; HTTPCLIENT","sec_cap_title":"Ngăn xếp lưu trữ bền vững, File I/O &amp; Mạng hoàn chỉnh cho Java 17","sec_cap_lead":"Thực hành bài lab CSDL đại học, mẫu DAO repository, trình phân tích CSV/JSON và REST client trong cùng một không gian làm việc thống nhất trên Android.","f1_title":"Driver SQLite JDBC Offline tích hợp sẵn không cần cài đặt","f1_desc":"Viết DriverManager.getConnection(\\\"jdbc:sqlite:campus.db\\\") hoặc \\\"jdbc:sqlite::memory:\\\" rồi nhấn Chạy. SuperCode đăng ký sẵn org.sqlite.JDBC offline &#8212; không cần săn tìm tệp .jar driver, mẹo Class.forName() hay cấu hình pom.xml rườm rà.","f1_badge":"jdbc:sqlite:app.db &#183; :memory: &#183; Không cần cài Driver","f2_title":"PreparedStatement, Giao dịch ACID &amp; Bài lab DAO theo lô","f2_desc":"Làm chủ phòng chống SQL injection bằng tham số hóa PreparedStatement, chạy giao dịch nhiều bảng nguyên tử với setAutoCommit(false) và rollback(), bật PRAGMA foreign_keys và kiểm tra cột qua ResultSetMetaData.","f2_badge":"PreparedStatement &#183; ACID Rollback &#183; executeBatch()","f3_title":"Chuyển 1 chạm sang SQL Studio trực quan của SuperCode","f3_desc":"Mọi tệp .db hoặc .sqlite3 được tạo từ mã Java JDBC của bạn sẽ hiện ngay trong cây dự án. Chạm vào tệp để xem schema, index và bảng dữ liệu trong SQL Studio theo chế độ Box, Markdown, CSV và JSON.","f3_badge":"Workspace .db dùng chung &#183; Xem Schema &amp; Bảng trực quan","f4_title":"Đầy đủ Java NIO.2 &amp; Stream File I/O truyền thống","f4_desc":"Đọc tập dữ liệu CSV, cập nhật cấu hình .properties và xuất báo cáo có cấu trúc bằng java.nio.file.Files (readString, writeString, readAllLines, createDirectories), FileChannel, BufferedReader và ObjectOutputStream &#8212; đồng bộ trực tiếp ra thư mục.","f4_badge":"java.nio.file.Files &#183; Path.of() &#183; Đồng bộ đĩa bền vững","f5_title":"java.net.http.HttpClient chuẩn &amp; HttpServer cục bộ","f5_desc":"Gọi REST JSON API bằng HttpClient hiện đại của Java (đồng bộ send() hoặc bất đồng bộ sendAsync() với CompletableFuture, timeout và header tùy chỉnh) hoặc dựng nhanh các route com.sun.net.httpserver.HttpServer.","f5_badge":"java.net.http.HttpClient &#183; sendAsync &#183; HttpServer","f6_title":"Chẩn đoán SQLException &amp; IOException chính xác từng dòng","f6_desc":"Khi sai tên cột SQL hoặc thiếu đường dẫn CSV, SuperCode lọc bỏ các frame reflection nội bộ để stack trace làm nổi bật chính xác số dòng trong lớp DAO hay parser của bạn.","f6_badge":"Stack Trace đã lọc &#183; Chẩn đoán chính xác số dòng","workflow_title":"Cách xây dựng dự án Java + SQLite JDBC trên Android","workflow_lead":"Đi từ thư mục trống đến vòng lặp CSDL JDBC bền vững + kiểm tra SQL trực quan chỉ trong vài giây.","wf1_title":"Kết nối qua DriverManager.getConnection(\\\"jdbc:sqlite:...\\\")","wf1_desc":"Mở bất kỳ tệp .java nào và kết nối tới tên tệp CSDL tương đối (ví dụ: jdbc:sqlite:store.db) &#8212; driver tự động nạp offline.","wf2_title":"Chạy DDL, Insert tham số hóa &amp; truy vấn Join","wf2_desc":"Thực thi CREATE TABLE, INSERT theo lô và SELECT join offline, hoặc đọc tệp dữ liệu mẫu .csv đi kèm bằng Files.readAllLines().","wf3_title":"Kiểm tra tệp .db vừa tạo trong SQL Studio","wf3_desc":"Chạm vào tệp store.db đã đồng bộ trong Trình duyệt tệp để xem bảng, chạy truy vấn SQL tùy ý hoặc xuất kết quả dạng Markdown/CSV.","wf4_title":"Xuất báo cáo hoặc Commit dự án DAO của bạn","wf4_desc":"Kiểm tra tệp CSV/JSON xuất ra ngay trong trình soạn thảo, in mã nguồn sang PDF A4 hoặc commit repo DAO đa class bằng Visual Git.","wf_foot_note":"Đóng gói sẵn org.sqlite.JDBC Offline &#183; Đồng bộ tệp thật &#183; Kèm SQL IDE trực quan","table_h2":"So sánh hỗ trợ Java Database &amp; File I/O trên các nền tảng di động","snippet_p":"<strong>SuperCode Java SQLite &amp; File I/O Studio</strong> tích hợp sẵn driver org.sqlite.JDBC offline trên Android mà không cần cấu hình Maven hay Gradle. Lập trình viên có thể chạy truy vấn SQLite tham số hóa, chia sẻ tệp .db trực tiếp với SQL Studio trực quan của SuperCode, đọc ghi tệp dự án qua Java NIO.2 Files và kiểm thử REST API bằng HttpClient.","table_caption":"NĂNG LỰC JAVA JDBC, FILE I/O &amp; HTTP TRÊN ANDROID","th_0":"Tính năng Backend","th_1":"SuperCode Java 17 IDE","th_2":"App Java di động thông thường","th_3":"Trình biên dịch Java Web","th_4":"Cài đặt Maven trên Desktop","tr1_c0":"Driver SQLite JDBC","tr1_c1":"jdbc:sqlite Offline tích hợp sẵn (0 cấu hình)","tr1_c2":"Thiếu (Lỗi ClassNotFoundException)","tr1_c3":"Không lưu CSDL cục bộ bền vững","tr1_c4":"Cần pom.xml + tải thư viện","tr2_c0":"Xem CSDL trực quan","tr2_c1":"Mở 1 chạm trong SQL Studio tích hợp","tr2_c2":"Phải cài app xem DB bên ngoài","tr2_c3":"Không có","tr2_c4":"Dùng plugin GUI DB riêng biệt","tr3_c0":"Java NIO.2 File I/O","tr3_c1":"Đồng bộ thư mục đầy đủ Files.readString/writeString","tr3_c2":"Giới hạn trong sandbox tạm thời","tr3_c3":"Container tạm bị xóa sau khi chạy","tr3_c4":"Đầy đủ","tr4_c0":"HTTP REST Client","tr4_c1":"java.net.http.HttpClient &amp; Server tích hợp sẵn","tr4_c2":"Chỉ có HttpURLConnection đời cũ","tr4_c3":"Chặn kết nối mạng ra ngoài","tr4_c4":"Đầy đủ","tr5_c0":"Độ tin cậy Offline","tr5_c1":"Chạy JDBC + NIO.2 100% Offline","tr5_c2":"Tùy thuộc từng plugin","tr5_c3":"Bắt buộc có mạng internet","tr5_c4":"Offline sau khi đã cache Maven","faq_lead":"Giải đáp về chuỗi kết nối JDBC, tệp `.db` bền vững, đường dẫn NIO.2 và `HttpClient` trên Android.","faq1_q":"Tôi có cần gọi `Class.forName(\\\"org.sqlite.JDBC\\\")` hay thêm Maven dependency để dùng SQLite trong Java không?","faq1_a":"Không! SuperCode tích hợp và tự động đăng ký sẵn `org.sqlite.JDBC`. Chỉ cần import `java.sql.*` và gọi `DriverManager.getConnection(\\\"jdbc:sqlite:mydb.db\\\")` &#8212; chạy ngay 100% offline.","faq2_q":"Các tệp `.db`, `.csv` và `.txt` được lưu ở đâu khi chương trình Java của tôi ghi dữ liệu?","faq2_a":"Đường dẫn tương đối như `jdbc:sqlite:inventory.db` hay `Path.of(\\\"report.csv\\\")` được phân giải thẳng vào thư mục dự án đang mở và tự động đồng bộ lại vào không gian làm việc Android ngay khi chạy xong.","faq3_q":"Tôi có thể tạo sẵn dữ liệu SQLite trong SQL Studio của SuperCode rồi dùng Java truy vấn lại không?","faq3_a":"Hoàn toàn được! Đây là một trong những quy trình phổ biến nhất trên SuperCode: thiết kế bảng và nạp dữ liệu mẫu trong SQL Studio (`schema.sql` -&gt; `app.db`), sau đó mở lớp `.java` DAO trong cùng thư mục và truy vấn `jdbc:sqlite:app.db` mượt mà.","faq4_q":"`java.net.http.HttpClient` có dùng để test REST API được không?","faq4_a":"Có. `HttpClient`, `HttpRequest` và `HttpResponse` chuẩn Java 11/17 hoạt động ngay cho các yêu cầu HTTPS REST khi thiết bị có mạng, trong khi mọi thao tác JDBC và tệp NIO.2 hoạt động hoàn toàn offline.","cta_h2":"Lập trình Java Database &amp; File Pipeline Offline trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; tích hợp SQLite JDBC, đồng bộ Java NIO.2 và SQL Studio trực quan."},"jv_learn_apcs":{"metaTitle":"Học Java & Luyện AP CS / DSA Offline trên Android — App Code Java Miễn Phí | SuperCode","metaDesc":"App code Java offline miễn phí trên Android cho người mới học, học sinh AP Computer Science A và luyện phỏng vấn LeetCode DSA. Chạy void main() gọn nhẹ, Scanner(System.in) tương tác, 8 mẫu Java và xuất bài tập PDF A4.","hero_tag":"KHÔNG CẦN ĐĂNG NHẬP &#183; AP CS A &amp; DSA &#183; VOID MAIN() GỌN NHẸ &#183; PDF A4","hero_h1":"Học <span class=\"text-gradient\">Java, AP Computer Science A &amp; DSA</span> Offline trên Android.","hero_desc":"Bỏ qua các app trắc nghiệm flashcard và viết code Java chạy thật ngay từ phút đầu. Thực hành với <strong>script <code>void main()</code> gọn nhẹ</strong>, hộp nhắc <strong><code>Scanner(System.in)</code></strong> tương tác, <strong>8 mẫu Java có sẵn</strong>, con trỏ báo lỗi chính xác <strong><code>^~~~</code></strong> và <strong>xuất bài tập PDF A4</strong> chỉ với 1 chạm &#8212; 100% offline.","jvl_s1":"App 100% Offline","jvl_s2":"Mẫu Java có sẵn","jvl_s3":"Thanh ký tự Java","jvl_s4":"Xuất bài tập PDF","wb_eyebrow":"MÔI TRƯỜNG HỌC JAVA CƠ BẢN, AP CS A &amp; LUYỆN LEETCODE DSA","sec_cap_title":"Thiết kế cho Người mới, Lớp học AP CS &amp; Luyện Phỏng vấn","sec_cap_lead":"Đủ thân thiện cho dòng `System.out.println` đầu tiên, nhưng đủ mạnh để bạn tiến xa với OOP đa lớp, cấu trúc dữ liệu, CSDL SQL và Git.","f1_title":"void main() Gọn nhẹ, Không Cần Code Khung Rườm rà Ngày đầu","f1_desc":"Người mới không nên vấp phải `public static void main(String[] args)` trước khi học biến và vòng lặp. SuperCode hỗ trợ hàm `void main()` cấp cao gọn nhẹ song song với định nghĩa OOP đa lớp chuẩn mực.","f1_badge":"void main() gọn nhẹ &#183; Lộ trình mượt tới OOP chuẩn","f2_title":"Sẵn sàng 100% cho AP Computer Science A &amp; CS1/CS2 Đại học","f2_desc":"Luyện mọi chủ đề câu hỏi tự luận (FRQ) AP CS A offline: xử lý String, hàm Math, mảng 1D và 2D, ArrayList&lt;E&gt;, thiết kế lớp, kế thừa, đa hình, đệ quy, tìm kiếm nhị phân và sắp xếp trộn.","f2_badge":"Chuẩn Java AP CS A &#183; Mảng 2D &#183; Kế thừa &amp; FRQ","f3_title":"Đầy đủ Java Collections cho LeetCode &amp; Phỏng vấn DSA","f3_desc":"Luyện sliding window, đường đi ngắn nhất Dijkstra, trie và quy hoạch động mọi lúc offline với HashMap, HashSet, TreeMap, TreeSet, PriorityQueue, ArrayDeque, Collections và Arrays &#8212; kèm đo mili-giây &amp; bộ nhớ.","f3_badge":"PriorityQueue &#183; HashMap &#183; ArrayDeque &#183; Đo ms/KB","f4_title":"Scanner(System.in) Tương tác Trực tiếp &amp; System.exit() An toàn","f4_desc":"Bài tập CLI tương tác tự dừng đúng lúc ở mỗi lệnh Scanner.nextLine() hoặc nextInt() trên terminal chia đôi màn hình (kèm nút [EOF] riêng), và gọi System.exit(0) kết thúc chương trình an toàn mà không sập app.","f4_badge":"System.in trực tiếp &#183; Nút [EOF] &#183; System.exit() an toàn","f5_title":"Con trỏ Báo lỗi ^~~~ Chính xác, 8 Mẫu &amp; Thanh 21 Phím","f5_desc":"Trình biên dịch gạch chân đúng cột lỗi bằng con trỏ ^~~~ và số dòng rõ ràng. Gõ nhanh `{`, `}`, `[`, `]`, `;`, `-&gt;` và các đoạn code mẫu trên màn hình điện thoại với thanh ký tự Java vuốt lên 21 phím và 8 ví dụ khởi đầu.","f5_badge":"Con trỏ cột ^~~~ &#183; Thanh 21 phím &#183; 8 ví dụ chạy ngay","f6_title":"Format Java 1 Chạm &amp; Xuất Bài tập PDF A4 Nộp lớp","f6_desc":"Căn lề các khối if/for lồng nhau chỉ với 1 chạm, đọc thoải mái qua 8 giao diện tối/sáng bảo vệ mắt, và xuất file bài tập `.java` thành PDF A4 sắc nét sẵn sàng nộp lên Canvas hoặc Google Classroom.","f6_badge":"Tự căn lề 1 chạm &#183; 8 giao diện dịu mắt &#183; Lưu dạng .pdf","workflow_title":"Cách Bắt đầu Học Java Offline trên Điện thoại","workflow_lead":"Không cần đăng ký, không quảng cáo cắt ngang khi gõ code và không cần máy tính để bàn.","wf1_title":"Chọn Mẫu Java Có sẵn hoặc Tạo Hello.java","wf1_desc":"Mở 1 trong 8 ví dụ Java chạy sẵn (vòng lặp, lớp OOP, collections, đệ quy) hoặc viết nhanh script `void main()` gọn nhẹ.","wf2_title":"Gõ Mượt mà Với Đóng mở ngoặc Thông minh &amp; Gợi ý Code","wf2_desc":"Dùng thanh ký tự vuốt lên cho `;`, `{}` và `[]` trong khi gợi ý AST offline đề xuất sẵn các phương thức `String`, `ArrayList` và `Math`.","wf3_title":"Biên dịch Offline &amp; Nhập Dữ liệu Scanner Trực tiếp","wf3_desc":"Chạm Chạy &#9654; để xem kết quả tức thì, thử nhập `Scanner(System.in)` tương tác và sửa lỗi chính tả nhờ gợi ý con trỏ `^~~~`.","wf4_title":"Định dạng Code &amp; Xuất Bài tập PDF A4","wf4_desc":"Chạm Định dạng để căn lề sạch đẹp, sau đó xuất bản in PDF A4 hoặc đẩy portfolio sinh viên lên GitHub bằng Visual Git.","wf_foot_note":"Không Cần Đăng ký &#183; Chạy 100% ở Chế độ Máy bay &#183; Điện thoại, Màn hình gập &amp; Chromebook","table_h2":"SuperCode so với App Trắc nghiệm &amp; Trình chạy Java Web cho Sinh viên","snippet_p":"<strong>SuperCode</strong> là app lập trình Java offline miễn phí trên Android dành cho người mới học, học sinh AP Computer Science A và luyện phỏng vấn DSA. Ứng dụng hỗ trợ chạy `void main()` gọn nhẹ thân thiện, nhập liệu `Scanner(System.in)` trực tiếp, chẩn đoán lỗi bằng con trỏ chính xác, 8 mẫu Java chạy ngay, thanh 21 ký tự và xuất bài tập PDF A4.","table_caption":"HỌC JAVA &amp; LUYỆN DSA TRÊN ANDROID","th_0":"Nhu cầu Học tập","th_1":"App Java SuperCode","th_2":"App Trắc nghiệm Game hóa","th_3":"Trình chạy Java Web","th_4":"IDE Java Di động Cũ","tr1_c0":"Đơn giản Ngày đầu","tr1_c1":"void main() gọn nhẹ + 8 Mẫu Khởi đầu","tr1_c2":"Chỉ chạm chọn trắc nghiệm","tr1_c3":"Khung class Main dài dòng","tr1_c4":"Trình tạo dự án rườm rà","tr2_c0":"Học Offline trên Xe/Máy bay","tr2_c1":"Java 17 + Collections 100% Offline","tr2_c2":"Thu phí / cần Wi-Fi","tr2_c3":"Lỗi khi mất mạng","tr2_c4":"Cú pháp Java 8/11 lỗi thời","tr3_c0":"Console Tương tác","tr3_c1":"Scanner Trực tiếp + [EOF] + exit() An toàn","tr3_c2":"Ô tĩnh điền sẵn","tr3_c3":"Ô stdin nhập trước khi chạy","tr3_c4":"Sập app khi gọi System.exit()","tr4_c0":"Nộp Bài tập","tr4_c1":"Format 1 chạm + PDF A4 Gốc + Git","tr4_c2":"Không hỗ trợ xuất file","tr4_c3":"Chỉ sao chép-dán văn bản","tr4_c4":"Chỉ có file .java thô","tr5_c0":"Giá trị Đa môn học","tr5_c1":"Chạy cả Python, C/C++, JS, SQL &amp; HTML","tr5_c2":"Chỉ một lộ trình đơn lẻ","tr5_c3":"Phải mở nhiều tab web rời","tr5_c4":"App chỉ chạy Java","faq_lead":"Giải đáp cho người mới học Java, học sinh AP Computer Science A, giáo viên và ứng viên phỏng vấn.","faq1_q":"Tôi có thể dùng SuperCode để ôn thi AP Computer Science A khi không có Wi-Fi không?","faq1_a":"Có! Mọi lớp Java, mảng, `ArrayList`, phương thức chuỗi, hệ thống kế thừa và mẫu đệ quy có trong kỳ thi AP Computer Science A đều biên dịch và chạy 100% offline trên điện thoại hoặc máy tính bảng.","faq2_q":"Tại sao `Scanner(System.in)` hay lỗi trên trình biên dịch web khi đọc nhiều dòng, và SuperCode xử lý ra sao?","faq2_a":"Nhiều trình biên dịch web bắt bạn nhập toàn bộ dữ liệu đầu vào trước khi bấm Chạy. SuperCode truyền `System.in` tương tác theo thời gian thực &#8212; in câu nhắc trước, đợi bạn gõ từng dòng và có sẵn nút `[EOF]` cho vòng lặp `while (sc.hasNext())`.","faq3_q":"Tôi có cần tạo tài khoản hoặc đăng nhập trước khi viết code Java không?","faq3_a":"Không bao giờ. SuperCode mở thẳng vào không gian làm việc mà không có rào cản đăng ký, giúp học sinh và lớp học bắt đầu code ngay lập tức.","faq4_q":"Sau này tôi có thể chuyển từ `void main()` gọn nhẹ sang gói Java đa lớp chuẩn không?","faq4_a":"Có. `void main()` gọn nhẹ chỉ là tiện ích tùy chọn cho bài tập nhanh &#8212; bất cứ khi nào bạn viết file `public class Main` chuẩn, nhiều class `.java`, interface hoặc dự án CSDL `jdbc:sqlite`, SuperCode tự biên dịch mà không cần chuyển chế độ.","cta_h2":"Bắt đầu Luyện Java &amp; DSA Offline Miễn phí Ngay.","cta_desc":"Tải SuperCode IDE trên Google Play &#8212; không cần đăng nhập, 8 mẫu Java, nhập Scanner trực tiếp và xuất PDF A4."},"js_node_core":{"metaTitle":"Chạy Module Lõi Node.js Offline trên Android — fs, path, stream, zlib & ESM | SuperCode","metaDesc":"Chạy hơn 29 module lõi Node.js (node:fs, fs/promises, path, buffer, events, stream, zlib, crypto, readline, util) 100% offline trên Android. Hỗ trợ ESM, CommonJS, package.json exports và đồng bộ thư mục thật.","hero_tag":"29+ MODULE LÕI NODE OFFLINE &#183; ESM + COMMONJS &#183; ĐỒNG BỘ FS THẬT","hero_h1":"Chạy <span class=\"text-gradient\">29+ Module Lõi Node.js (<code>fs</code>, <code>path</code>, <code>stream</code>, <code>zlib</code>)</span> Offline trên Android.","hero_desc":"Viết script tự động hóa backend và xử lý file thật ngay trên điện thoại mà không cần Linux chroot nặng nề. SuperCode tích hợp <strong>29+ API lõi Node.js 100% offline</strong> &#8212; hỗ trợ cả <strong><code>import</code> (ESM)</strong> lẫn <strong><code>require()</code> (CommonJS)</strong>, <strong><code>package.json</code> subpath exports</strong> và <strong>đồng bộ thư mục <code>node:fs</code></strong> trực tiếp.","jsn_s1":"API Node Offline","jsn_s2":"Đồng bộ Thư mục Thật","jsn_s3":"&amp; package.json","jsn_s4":"Tự động Đẩy http/net","wb_eyebrow":"MÔI TRƯỜNG MODULE LÕI NODE.JS OFFLINE &amp; PACKAGE.JSON","sec_cap_title":"Script JavaScript Backend &amp; Công cụ File Không Rào cản Terminal","sec_cap_lead":"Tự động chuyển đổi JSON/CSV, nén build artifact, kiểm thử thư viện module hóa và chạy tiện ích CLI offline trong vài mili-giây.","f1_title":"29+ Module Lõi Node.js Tích hợp Sẵn Chạy Offline","f1_desc":"Import module lõi có tiền tố `node:` hoặc tên rút gọn mà không cần cài đặt: fs, fs/promises, path, path/posix, buffer, events, stream, stream/promises, stream/web, zlib, crypto, util, assert, url, querystring, readline, string_decoder, timers, timers/promises, perf_hooks, os, process và diagnostics_channel.","f1_badge":"node:fs &#183; path &#183; buffer &#183; events &#183; stream &#183; zlib &#183; util","f2_title":"Đồng bộ Workspace Thật với node:fs &amp; fs/promises","f2_desc":"Chạy readFileSync, writeFile, appendFile, mkdir({ recursive: true }), readdir, stat và copyFile trực tiếp trên file dự án thật. Bundle JSON, tài liệu Markdown, CSV và file nén `.gz` tạo ra sẽ xuất hiện ngay trong thư mục Android của bạn.","f2_badge":"fs.readFileSync &#183; fs/promises &#183; I/O Thư mục Lưu trữ Thật","f3_title":"Tương thích Liền mạch ES Modules (.mjs) &amp; CommonJS (.cjs)","f3_desc":"Viết ES Modules hiện đại với `import` / `export` và `await` cấp cao nhất, duy trì tiện ích CommonJS với `require()` và `module.exports`, đồng thời import file cấu hình `.json` nguyên bản qua các thư mục lồng nhau.","f3_badge":"import / export &#183; require() &#183; .mjs / .cjs / .json","f4_title":"Hỗ trợ package.json Exports, Subpaths &amp; #imports","f4_desc":"Tổ chức package đa file gọn gàng bằng `package.json`: SuperCode phân giải `\\\"type\\\": \\\"module\\\"`, `\\\"main\\\"`, bảng `\\\"exports\\\"` có điều kiện và subpath `#internal/*` nội bộ &#8212; ngay cả trên các tab trình soạn thảo chưa lưu.","f4_badge":"package.json &#183; Conditional exports &#183; #subpath Imports","f5_title":"Buffer Nhị phân, EventEmitter, Stream &amp; Zlib","f5_desc":"Xử lý giao thức nhị phân và luồng văn bản lớn hiệu quả trên di động bằng `Buffer.alloc`/`concat` (UTF-8, hex, base64, base64url), `EventEmitter`, `Readable`/`Writable`/`Transform` `pipeline()` và `zlib.gzipSync`/`gunzipSync`.","f5_badge":"Buffer &#183; EventEmitter &#183; stream.pipeline &#183; gzipSync","f6_title":"Tự động Chuyển Cloud Node.js cho Socket &amp; Worker","f6_desc":"Khi script cần socket TCP/HTTP cấp OS hoặc tạo đa tiến trình (`node:http`, `https`, `net`, `tls`, `dns`, `dgram`, `child_process`, `worker_threads`), SuperCode tự đóng gói cây module nội bộ lên Cloud Node.js.","f6_badge":"http &#183; net &#183; worker_threads &#183; Dấu vết Lỗi 1:1","workflow_title":"Cách Xây dựng Script Node.js Đa Module trên Android","workflow_lead":"Chạy script xử lý hệ thống file, stream và công cụ CLI thật mà không phải cài hàng gigabyte gói terminal.","wf1_title":"Tạo File .js, .mjs hoặc .cjs trong Workspace","wf1_desc":"Bắt đầu một script độc lập hoặc thêm `package.json` với `\\\"type\\\": \\\"module\\\"` để bật cú pháp ES Module trên các file `.js`.","wf2_title":"Import Bất kỳ API nào trong 29+ Module Lõi Node Offline","wf2_desc":"Đọc file `.json`/`.csv` nội bộ, xử lý đường dẫn bằng `node:path`, biến đổi stream hoặc nén đầu ra qua `node:zlib`.","wf3_title":"Thực thi Offline &amp; Tương tác qua node:readline","wf3_desc":"Chạy trong vài mili-giây bên trong console worker cô lập với stdin tương tác trực tiếp, `process.env` và phản hồi kiểm thử `assert`.","wf4_title":"Kiểm tra File Đã ghi &amp; Commit qua Visual Git","wf4_desc":"Mở trực tiếp các file vừa tạo ngay trong trình soạn thảo SuperCode hoặc commit gói JavaScript module hóa lên GitHub với Visual Git.","wf_foot_note":"29+ Module Lõi Node Offline &#183; Lớp phủ Module Tab Chưa lưu &#183; Tự động Đẩy Cloud Node.js","table_h2":"Node Lõi Offline SuperCode so với Hộp JS Trình duyệt &amp; Terminal Thủ công","snippet_p":"<strong>SuperCode Offline Node.js Core Studio</strong> chạy hơn 29 module chuẩn của Node.js trực tiếp trên Android mà không cần internet hay thiết lập terminal. Lập trình viên có thể import node:fs, fs/promises, path, buffer, events, stream, zlib, crypto và util trên cả ES Modules và CommonJS kèm phân giải package.json exports và đồng bộ thư mục Android thật.","table_caption":"SO SÁNH NODE.JS &amp; JAVASCRIPT MODULE HÓA TRÊN ANDROID","th_0":"Tính năng Node / Module","th_1":"Studio JS &amp; Node SuperCode","th_2":"App JS WebView Trình duyệt","th_3":"Sandbox Node Trực tuyến","th_4":"Terminal CLI Thủ công","tr1_c0":"Module Lõi Offline","tr1_c1":"29+ Tích hợp sẵn (fs, path, buffer, stream, zlib, crypto)","tr1_c2":"Chỉ có API trình duyệt (Không có fs/path)","tr1_c3":"0% offline (Chỉ chạy có mạng)","tr1_c4":"Phải cài thủ công pkg install nodejs","tr2_c0":"Hệ thống Module","tr2_c1":"Cả ESM (import) &amp; CommonJS (require) + JSON","tr2_c2":"Một thẻ `&lt;script&gt;` đơn lẻ","tr2_c3":"Hỗ trợ trực tuyến","tr2_c4":"Có hỗ trợ","tr3_c0":"Điều hướng package.json","tr3_c1":"Tuân thủ type:module, exports &amp; #imports","tr3_c2":"Bị bỏ qua","tr3_c3":"Container tạm thời","tr3_c4":"Có hỗ trợ","tr4_c0":"I/O File Workspace Thật","tr4_c1":"Đồng bộ Đọc/Ghi Thư mục Android Trực tiếp","tr4_c2":"Bị WebView chặn","tr4_c3":"Mất sạch khi đóng tab","tr4_c4":"Điều hướng đường dẫn CLI","tr5_c0":"Trải nghiệm Code Cảm ứng","tr5_c1":"Gợi ý AST + Format Prettier + Visual Git","tr5_c2":"Ô nhập văn bản cơ bản","tr5_c3":"Trình duyệt di động chật hẹp","tr5_c4":"Không có GUI sửa code hay xử lý xung đột","faq_lead":"Câu hỏi về các module `node:*` được hỗ trợ, đường dẫn file `fs`, `package.json` và gói npm trên Android.","faq1_q":"Những module lõi Node.js nào chạy 100% offline trong SuperCode?","faq1_a":"Hơn 29 module chuẩn chạy hoàn toàn offline, bao gồm `fs`, `fs/promises`, `path`, `path/posix`, `buffer`, `events`, `stream`, `stream/promises`, `stream/web`, `zlib`, `crypto`, `readline`, `util`, `assert`, `url`, `querystring`, `string_decoder`, `timers`, `timers/promises`, `perf_hooks`, `os`, `process` và `console`.","faq2_q":"Lệnh `fs.writeFileSync('out.json', data)` có lưu thành file thật vào thư mục Android không?","faq2_a":"Có! Các thao tác hệ thống file đọc trực tiếp từ thư mục dự án đang mở (kể cả tab chưa lưu) và đồng bộ mọi file vừa tạo hoặc chỉnh sửa thẳng về thư mục Android của bạn.","faq3_q":"Tôi có thể dùng cả tiền tố `node:fs` lẫn `require('fs')` thông thường không?","faq3_a":"Có. Cả cú pháp ES Module hiện đại `import fs from 'node:fs/promises'` lẫn lệnh CommonJS truyền thống `const fs = require('fs')` đều trỏ về cùng một bản triển khai offline tích hợp sẵn.","faq4_q":"Điều gì xảy ra nếu script của tôi import `node:http`, `net` hoặc `worker_threads`?","faq4_a":"Các module yêu cầu socket máy chủ cấp OS hoặc tiến trình con (`http`, `https`, `net`, `tls`, `dns`, `child_process`, `worker_threads`) được tự động nhận diện và thực thi qua trình đóng gói Cloud Node.js đa file của SuperCode &#8212; đồng thời xem trước HTTP cục bộ full-stack cũng có sẵn trong Web IDE của SuperCode.","cta_h2":"Viết Script Với Module Lõi Node.js Thật Mọi Lúc Offline.","cta_desc":"Tải SuperCode IDE miễn phí trên Google Play &#8212; 29+ API Node offline, song song ESM/CommonJS và đồng bộ thư mục fs thật."},"js_es2024_async":{"metaTitle":"Trình chạy ES2024 JavaScript cho Android — Top-Level Await, Fetch & Console Offline | SuperCode","metaDesc":"Chạy ES2024 JavaScript hiện đại offline trên Android không cần khung HTML. Hỗ trợ top-level await, async generator, BigInt, structuredClone, Fetch, console.table() và ngắt vòng lặp vô hạn <1ms.","hero_tag":"ES2024 OFFLINE &#183; TOP-LEVEL AWAIT &#183; CONSOLE.TABLE &#183; BẢO VỆ &lt;1MS","hero_h1":"<span class=\"text-gradient\">ES2024 JavaScript, <code>await</code> Cấp cao nhất &amp; Async Console</span> Offline trên Android.","hero_desc":"Tạm biệt các app di động ES5 cũ kỹ và file HTML bọc rườm rà. SuperCode chạy <strong>ES2024 JavaScript</strong> độc lập trên worker nền cô lập &#8212; hỗ trợ <strong><code>await</code> cấp cao nhất</strong>, <strong><code>for await...of</code></strong>, <strong><code>BigInt</code></strong>, <strong><code>structuredClone</code></strong>, <strong><code>console.table()</code></strong> và <strong>ngắt vòng lặp vô hạn dưới &lt;1ms</strong>.","jse_s1":"await Cấp cao nhất","jse_s2":"Ngắt Vòng lặp Tức thì","jse_s3":"Console JS Thuần túy","jse_s4":"Xả Sạch Event-Loop","wb_eyebrow":"MÔI TRƯỜNG ES2024 BẤT ĐỒNG BỘ ĐỘC LẬP &amp; CÔ LẬP WORKER","sec_cap_title":"Vượt xa Các App Rhino ES5 Cũ kỹ &amp; WebView Luồng Chính","sec_cap_lead":"Kiểm thử điều phối bất đồng bộ hiện đại, sao chép state bất biến và luồng fetch mạng với phản hồi tức thì cùng giao diện mượt mà ổn định.","f1_title":"Chạy Script .js &amp; .mjs Thuần Không Cần Khung HTML","f1_desc":"Muốn thử nhanh hàm retry async, bộ phân tích regex hay state reducer? Chỉ cần tạo một file `.js` hoặc `.mjs` rồi chạm Chạy &#9654; &#8212; không cần thẻ `&lt;script&gt;`, trang HTML giả hay ngăn kéo DevTools di động chật chội.","f1_badge":"Chạy Trực tiếp .js / .mjs &#183; Console Chia đôi Màn hình","f2_title":"Cú pháp ES2024 Hiện đại Vượt trội Các App ES5 Cũ","f2_desc":"Nhiều trình chạy JS trên Play Store dùng engine hàng chục năm tuổi bị lỗi ngay với `const`, arrow function hay `async`. SuperCode chạy offline `await` cấp cao nhất, async generator (`async function*`), `#fields` riêng tư, `BigInt`, `WeakRef`, `structuredClone`, `Object.groupBy` và `Array.at()`.","f2_badge":"await Cấp cao nhất &#183; #Fields Riêng tư &#183; BigInt &#183; WeakRef","f3_title":"Tự động Đợi Event-Loop &amp; Microtask Hoàn tất Thông minh","f3_desc":"Code bất đồng bộ không bao giờ thoát sớm trước khi Promise hoàn thành: worker theo dõi các handle `setTimeout`, `setInterval`, `queueMicrotask` và `timers/promises` đang chạy, xả sạch event loop gọn gàng đến khi mọi tác vụ xong xuôi.","f3_badge":"Promise.allSettled &#183; timers/promises &#183; Xả Sạch Gọn gàng","f4_title":"Luồng Worker Cô lập &amp; Ngắt Vòng lặp Vô hạn &lt;1ms","f4_desc":"Chạy JavaScript trên luồng UI chính khiến trình soạn thảo thông thường đơ cứng khi gặp lỗi `while (true) {}`. SuperCode cô lập thực thi trên worker nền riêng để chạm Dừng &#9632; (hoặc chạm ngưỡng watchdog 15s) là ngắt ngay vòng lặp treo dưới 1ms.","f4_badge":"Worker Ngoài Luồng UI &#183; Hủy &lt;1ms &#183; Không Giật Trình soạn thảo","f5_title":"Fetch API Chuẩn, AbortController &amp; Web Streams","f5_desc":"Thử nghiệm client API thực tế bằng `fetch()`, `Headers`, `Request`, `Response`, `AbortController` / `AbortSignal.timeout()`, `URL`, `URLSearchParams`, `TextEncoder`/`TextDecoder` và `ReadableStream` chuẩn.","f5_badge":"fetch() &#183; AbortController &#183; URL &#183; ReadableStream","f6_title":"console.table() Dạng Bảng ASCII, Bộ đếm Độ phân giải cao &amp; Lỗi 1:1","f6_desc":"Hiển thị mảng đối tượng gọn đẹp qua bảng kẻ khung `console.table()`, đo hiệu năng hàm nóng với `console.time()` và `performance.now()` dưới mili-giây, đồng thời truy vết lỗi về chính xác từng dòng code gốc.","f6_badge":"console.table() &#183; performance.now() &#183; Stack Lỗi 1:1","workflow_title":"Cách Thử nghiệm Nhanh Script ES2024 Bất đồng bộ trong SuperCode","workflow_lead":"Từ những dòng test nhanh tới chuỗi async generator trong giao diện chia đôi tập trung.","wf1_title":"Mở Bất kỳ File JavaScript Độc lập nào","wf1_desc":"Viết code ES2024 trực tiếp cùng thanh 21 ký tự JS/TS (`=&gt;`, `?.`, `??`, `` ` ``, `${}`) và gợi ý AST offline.","wf2_title":"Dùng await Cấp cao nhất, Timers hoặc Fetch","wf2_desc":"Nối chuỗi Promise, iterator `for await...of`, `structuredClone` hoặc request `fetch()` kèm timeout `AbortController`.","wf3_title":"Thực thi trong Worker Cô lập Không Đơ máy","wf3_desc":"Theo dõi log console xuất ra theo thời gian thực ở khung dưới hoặc chia ngang 55:45 &#8212; và ngắt mọi vòng lặp treo trong `&lt;1ms`.","wf4_title":"Đo Thời gian Chạy &amp; Tự động Format Với 1 Chạm","wf4_desc":"So sánh thông số mili-giây giữa các lần chạy và làm gọn các callback async lồng nhau tức thì bằng trình format JS tích hợp.","wf_foot_note":"Worker Nền Chuyên biệt &#183; Watchdog CPU 15s &#183; Tuân thủ Đầy đủ ES6&#8211;ES2024","table_h2":"Worker ES2024 SuperCode so với App JS Di động Cũ kỹ","snippet_p":"<strong>SuperCode ES2024 JavaScript Runner</strong> thực thi JavaScript hiện đại độc lập trên Android bên trong worker nền cô lập mà không cần khung HTML. Khác với các app ES5 cũ, ứng dụng hỗ trợ top-level await, async generator, Promise.allSettled, BigInt, structuredClone, Fetch kèm AbortController, console.table(), tự động đợi hoàn tất event-loop và ngắt vòng lặp vô hạn dưới mili-giây.","table_caption":"SO SÁNH RUNTIME JAVASCRIPT ĐỘC LẬP TRÊN ANDROID","th_0":"Tiêu chí Runtime","th_1":"Worker ES2024 SuperCode","th_2":"App JS Di động ES5 Cũ","th_3":"Trang Nháp WebView HTML","th_4":"Sandbox Repl Trực tuyến","tr1_c0":"Chuẩn ECMAScript","tr1_c1":"ES2024 Hiện đại + Top-Level await Offline","tr1_c2":"ES5 lỗi thời / ES6 chắp vá","tr1_c3":"Gắn chặt vòng đời trang HTML","tr1_c4":"Hiện đại (Chỉ chạy có mạng)","tr2_c0":"An toàn Vòng lặp Vô hạn","tr2_c1":"Worker Cô lập (Ngắt &lt;1ms Không Đơ)","tr2_c2":"Đơ hoặc sập toàn bộ app","tr2_c3":"Treo cứng luồng UI WebView","tr2_c4":"Treo tab trình duyệt","tr3_c0":"Async &amp; Event Loop","tr3_c1":"Tự động Xả Promises, Microtask &amp; Timers","tr3_c2":"Không hỗ trợ async/await gốc","tr3_c3":"Kiểm tra DevTools thủ công","tr3_c4":"Có hỗ trợ","tr4_c0":"Chẩn đoán Console","tr4_c1":"console.table() ASCII, Bộ đếm &amp; Dòng 1:1","tr4_c2":"Chỉ in chuỗi thô đơn giản","tr4_c3":"Ẩn thành `[object Object]`","tr4_c4":"Trễ do mạng","tr5_c0":"Code Khung Bắt buộc","tr5_c1":"0 Dòng (Chạy Trực tiếp .js / .mjs)","tr5_c2":"0 Dòng","tr5_c3":"Bắt buộc có file bọc index.html","tr5_c4":"Bắt đăng nhập tài khoản","faq_lead":"Câu hỏi thường gặp về cú pháp ES2024, `await` cấp cao nhất, `fetch()` và bảo vệ vòng lặp vô hạn.","faq1_q":"Tôi có thể chạy trực tiếp file JavaScript trong SuperCode mà không cần tạo file HTML không?","faq1_a":"Có! SuperCode có engine console JavaScript độc lập tách biệt hoàn toàn khỏi Web IDE HTML5. Chỉ cần mở bất kỳ file `.js`, `.mjs` hoặc `.cjs` nào rồi chạm Chạy &#9654;.","faq2_q":"Làm sao dùng `await` cấp cao nhất mà không cần bọc code vào `async function main()`?","faq2_a":"Hãy lưu file dưới dạng `.mjs` (hoặc đặt `\\\"type\\\": \\\"module\\\"` trong `package.json`, hoặc viết thẳng `await` cấp cao nhất trong script ES Module) &#8212; SuperCode thực thi top-level `await` nguyên bản và đợi toàn bộ Promise hoàn tất.","faq3_q":"Điều gì xảy ra nếu tôi lỡ viết nhầm vòng lặp vô hạn `while (true)` trên điện thoại?","faq3_a":"Trình soạn thảo và các file chưa lưu của bạn vẫn mượt mà 100% vì script chạy trên luồng worker nền cô lập. Chạm nút Dừng &#9632; (hoặc để watchdog CPU 15 giây kích hoạt) để ngắt worker dưới 1 mili-giây.","faq4_q":"`fetch()` có hoạt động bên trong các script JavaScript độc lập không?","faq4_a":"Có. `fetch()`, `Headers`, `Request`, `Response` và `AbortController` chuẩn được tích hợp sẵn trong runtime worker để bạn kiểm thử các API HTTPS thực tế bất cứ khi nào thiết bị có kết nối.","cta_h2":"Chạy ES2024 JavaScript Hiện đại Không Rào cản HTML.","cta_desc":"Tải SuperCode IDE miễn phí trên Google Play &#8212; worker ES2024 cô lập, top-level await, console.table() và ngắt vòng lặp &lt;1ms."},"js_crypto_sec":{"metaTitle":"JavaScript Web Crypto & node:crypto trên Android — AES-GCM, SHA-512 & HMAC Offline | SuperCode","metaDesc":"Thử nghiệm và kiểm tra mã hóa offline bằng JavaScript trên Android. Dùng W3C crypto.subtle và node:crypto cho mã hóa AES-256-GCM, băm SHA-256/512, JWT HMAC constant-time, PBKDF2 và UUID.","hero_tag":"CRYPTO.SUBTLE + NODE:CRYPTO OFFLINE &#183; AES-256-GCM &#183; SHA-512","hero_h1":"Sandbox <span class=\"text-gradient\">JavaScript Web Crypto &amp; <code>node:crypto</code></span> Cách Ly Mạng trên Android.","hero_desc":"Đừng bao giờ dán JWT token thật, secret ký webhook hay test vector mã hóa vào công cụ web lạ. SuperCode chạy cả <strong>W3C <code>crypto.subtle</code></strong> lẫn <strong><code>node:crypto</code> 100% offline</strong> &#8212; hỗ trợ <strong>AES-256-GCM</strong>, <strong>SHA-256/512</strong>, <strong>PBKDF2</strong> và <strong><code>timingSafeEqual</code></strong>.","jsc_s1":"GCM &#183; CBC &#183; CTR","jsc_s2":"Hash &amp; HMAC","jsc_s3":"Key Derivation","jsc_s4":"Subtle + node:crypto","wb_eyebrow":"WORKBENCH NODE:CRYPTO &amp; W3C SUBTLECRYPTO OFFLINE","sec_cap_title":"Các Primitive Mã Hóa Chuẩn Production Ngay Trên Điện Thoại","sec_cap_lead":"Xây dựng tiện ích bảo mật đa nền tảng giữa chuẩn trình duyệt/edge (`crypto.subtle`) và Node.js backend (`node:crypto`) mà không cần kết nối mạng.","f1_title":"Tích Hợp Sẵn Cả W3C crypto.subtle &amp; Node.js node:crypto","f1_desc":"Viết module bảo mật đa runtime với `globalThis.crypto.subtle` (`crypto.webcrypto`) song song các hàm Node backend kinh điển (`import crypto from 'node:crypto'`) &#8212; không cần bundle polyfill hay cài npm ngoài.","f1_badge":"crypto.subtle &#183; crypto.webcrypto &#183; node:crypto","f2_title":"Mã Hóa Xác Thực AES-128/192/256 (GCM, CBC, CTR)","f2_desc":"Mã hóa và giải mã payload offline bằng `createCipheriv` / `createDecipheriv` hoặc `crypto.subtle.encrypt` / `decrypt`. Hỗ trợ đầy đủ `getAuthTag()` và `setAuthTag()` giúp xác minh toàn vẹn ciphertext AEAD chính xác.","f2_badge":"aes-256-gcm &#183; aes-256-cbc &#183; aes-256-ctr &#183; AuthTag","f3_title":"Băm SHA-256/512, HMAC Webhook &amp; timingSafeEqual","f3_desc":"Xác thực header HMAC-SHA256 kiểu GitHub/Stripe, viết trình kiểm tra JWT HS256/HS512 không phụ thuộc với `base64url` Buffer và chống tấn công timing bằng `crypto.timingSafeEqual(a, b)`.","f3_badge":"createHash &#183; createHmac &#183; base64url &#183; timingSafeEqual","f4_title":"Kéo Giãn Khóa PBKDF2 &amp; Sinh Ngẫu Nhiên CSPRNG","f4_desc":"Dẫn xuất khóa 256-bit mạnh từ passphrase qua `pbkdf2`, `pbkdf2Sync` hoặc `subtle.deriveBits`, đồng thời tạo salt, IV nonce và UUID v4 an toàn bằng `randomBytes()`, `getRandomValues()` và `randomUUID()`.","f4_badge":"pbkdf2Sync &#183; randomBytes &#183; getRandomValues &#183; randomUUID","f5_title":"Kiểm Toán Token &amp; Payload Nhạy Cảm 100% Cách Ly Mạng","f5_desc":"Cần kiểm tra bearer token, code challenge OAuth PKCE `S256` hoặc blob cấu hình mã hóa khi xử lý sự cố? Bật chế độ máy bay và kiểm tra cục bộ trên Android với zero rò rỉ telemetry.","f5_badge":"Không Rò Rỉ Mạng &#183; PKCE S256 &#183; Kiểm Toán JWT","f6_title":"Script Checksum File &amp; Sao Lưu Mã Hóa Với node:fs","f6_desc":"Kết hợp `node:crypto` trực tiếp với `node:fs` và `node:zlib` để tạo manifest SHA-256 cho thư mục workspace hoặc mã hóa snapshot JSON/SQLite cục bộ trước khi tải lên qua SFTP.","f6_badge":"Checksum File SHA-256 &#183; Script Kho Mã Hóa","workflow_title":"Cách Thử Nghiệm &amp; Xác Minh Mã Hóa Offline Trong SuperCode","workflow_lead":"Kiểm tra hàm băm, chữ ký HMAC và payload AES-GCM cục bộ chỉ với 4 bước gọn gàng.","wf1_title":"Chọn node:crypto Hoặc Chuẩn globalThis.crypto.subtle","wf1_desc":"Mở file `.mjs` hoặc `.js` &#8212; cả API mã hóa đồng bộ/stream của Node lẫn Web Crypto dạng Promise đều sẵn sàng ngay.","wf2_title":"Tạo Nonce CSPRNG &amp; Dẫn Xuất Khóa","wf2_desc":"Sinh IV, salt hoặc UUID an toàn và dẫn xuất passphrase thành khóa AES-256 32-byte ngay offline.","wf3_title":"Chạy Mã Hóa, Ký Số Hoặc Xác Minh Constant-Time","wf3_desc":"Nhấn Chạy &#9654; để xem kết quả hex/base64url, auth tag và kết quả kiểm tra `timingSafeEqual` trong vài mili-giây.","wf4_title":"Lưu Checksum Hoặc File Mã Hóa Vào Thư Mục","wf4_desc":"Lưu trực tiếp file manifest `.sha256` hoặc payload đã mã hóa vào workspace để quản lý Git hoặc truyền qua SFTP.","wf_foot_note":"Thực Thi Mã Hóa 100% Trên Thiết Bị &#183; Không Cần Thư Viện npm Ngoài","table_h2":"SuperCode JS Crypto Offline vs. Công Cụ Token/Hash Trực Tuyến","snippet_p":"<strong>SuperCode JavaScript Crypto Sandbox</strong> cung cấp cả W3C Web Crypto (crypto.subtle) và Node.js node:crypto hoàn toàn offline trên Android. Kỹ sư bảo mật và lập trình viên backend có thể kiểm thử mã hóa xác thực AES-256-GCM, băm file SHA-256 và SHA-512, xác minh JWT HMAC constant-time, dẫn xuất khóa PBKDF2 và tạo UUID an toàn ngay trên thiết bị mà không cần mạng.","table_caption":"SO SÁNH SANDBOX MÃ HÓA &amp; BẢO MẬT JAVASCRIPT DI ĐỘNG","th_0":"Tính năng bảo mật","th_1":"SuperCode JS Crypto Studio","th_2":"Web JWT / Hash Online","th_3":"App JS WebView Cơ Bản","th_4":"Node CLI Trên Desktop","tr1_c0":"Bảo mật Secret","tr1_c1":"100% Offline cách ly trên điện thoại","tr1_c2":"Nguy cơ lộ qua trình duyệt/mạng","tr1_c3":"Origin HTTP WebView kém an toàn","tr1_c4":"100% Cục bộ","tr2_c0":"Node Crypto API","tr2_c1":"Tích hợp node:crypto (Cipheriv, HMAC, PBKDF2)","tr2_c2":"Không lập trình được","tr2_c3":"Thiếu (`require` bị lỗi)","tr2_c4":"Tích hợp sẵn","tr3_c0":"W3C Web Crypto","tr3_c1":"Đầy đủ crypto.subtle + randomUUID Offline","tr3_c2":"Phụ thuộc trình duyệt","tr3_c3":"Thường bị tắt trên file://","tr3_c4":"Tích hợp sẵn (Node 19+)","tr4_c0":"Mã hóa Nhị phân","tr4_c1":"Đầy đủ Buffer (hex, base64, base64url, utf8)","tr4_c2":"Chuyển đổi copy-paste thủ công","tr4_c3":"Chỉ có `atob`/`btoa` thô sơ","tr4_c4":"Đầy đủ Buffer","tr5_c0":"Băm File Workspace","tr5_c1":"Băm &amp; mã hóa file thư mục cục bộ thật","tr5_c2":"Phải tải file lên bên thứ ba","tr5_c3":"Không truy cập được file cục bộ","tr5_c4":"Đầy đủ","faq_lead":"Giải đáp về Web Crypto offline, thuật toán mã hóa `node:crypto`, xác minh JWT và an toàn secret.","faq1_q":"Tại sao `crypto.subtle` chạy được offline trong SuperCode trong khi hay lỗi ở app WebView Android cơ bản?","faq1_a":"Trình duyệt chặn `window.crypto.subtle` trên trang `file://` không an toàn. Worker JavaScript độc lập của SuperCode cung cấp sẵn cả `globalThis.crypto.subtle` (`crypto.webcrypto`) và `node:crypto` offline tự nhiên mà không gặp rào cản secure-context.","faq2_q":"Những chế độ mã hóa AES và thuật toán băm nào được hỗ trợ offline?","faq2_a":"Bạn có thể chạy `aes-128`, `aes-192` và `aes-256` ở các chế độ `GCM` (kèm tag xác thực 16-byte), `CBC` và `CTR`, cùng hàm băm và HMAC `SHA-1`, `SHA-256`, `SHA-384`, `SHA-512` và `MD5`.","faq3_q":"`Buffer.toString('base64url')` có dùng được để tạo và xác minh JWT không?","faq3_a":"Có! `Buffer` của SuperCode hỗ trợ sẵn mã hóa và giải mã `utf8`, `hex`, `base64` và chuẩn RFC 4648 `base64url` &#8212; giúp viết script JWT và OAuth PKCE `S256` không cần thư viện ngoài cực kỳ gọn nhẹ.","faq4_q":"Có khóa hay payload nào bị gửi qua mạng khi chạy `node:crypto` không?","faq4_a":"Không bao giờ. Mọi tác vụ `node:crypto` và `crypto.subtle` đều chạy 100% cục bộ trên thiết bị Android của bạn và hoạt động ngay cả khi tắt hoàn toàn Wi-Fi lẫn dữ liệu di động.","cta_h2":"Kiểm Thử &amp; Kiểm Toán Mã Hóa JavaScript 100% Offline.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; song song Web Crypto &amp; node:crypto, AES-256-GCM và an toàn cách ly mạng."},"js_learn_dsa":{"metaTitle":"Học JavaScript & Luyện DSA Offline trên Android — App Code JS Miễn Phí | SuperCode","metaDesc":"App code JavaScript offline miễn phí trên Android cho người mới và ôn phỏng vấn LeetCode. Gồm 6 template JS sẵn chạy, thanh ký tự => 21 phím, tự hoàn thành AST, định dạng JSON và nhập prompt() trực tiếp.","hero_tag":"KHÔNG CẦN ĐĂNG NHẬP &#183; 6 TEMPLATE JS &#183; THANH =&gt; &#183; ĐỊNH DẠNG JSON","hero_h1":"Học <span class=\"text-gradient\">JavaScript &amp; Luyện Thuật Toán LeetCode</span> Offline trên Android.","hero_desc":"Làm chủ ES6&#8211;ES2024 JavaScript thực thụ mọi lúc mọi nơi, không tường phí quiz hay phụ thuộc Wi-Fi. Mở ngay <strong>6 template JS chạy được</strong>, gõ arrow function mượt mà với <strong>thanh ký tự 21 phím <code>=&gt;</code> / <code>${}</code></strong>, format <strong>JS &amp; JSON</strong> một chạm và luyện thuật toán ở chế độ máy bay.","jsl_s1":"JS Offline Miễn Phí","jsl_s2":"Template Khởi Đầu","jsl_s3":"Thanh =&gt; &amp; ${}","jsl_s4":"Format JS/JSON","wb_eyebrow":"WORKBENCH ES6+ CƠ BẢN, LEETCODE DSA &amp; ĐỊNH DẠNG JSON","sec_cap_title":"Tối Ưu Cho Gõ Nhanh Bằng Ngón Tay &amp; Giải Bài Tập Thực Tế Trên Di Động","sec_cap_lead":"Dù bạn mới viết vòng lặp `for` đầu tiên hay đang cày đồ thị và quy hoạch động trước buổi phỏng vấn frontend, SuperCode luôn gọn nhẹ và không làm gián đoạn.","f1_title":"Không Bắt Đăng Nhập &amp; Chạy 100% Ở Chế Độ Máy Bay","f1_desc":"Mở SuperCode và chạy JavaScript chỉ trong vài giây &#8212; không ép đăng ký email, không giới hạn 'hết tim' kiểu game hóa và hoàn toàn không cần mạng trên tàu xe hay máy bay.","f1_badge":"Mở Chạy Ngay &#183; Không Tài Khoản &#183; 100% Offline","f2_title":"6 Template JavaScript Khởi Đầu Chạy Được Ngay","f2_desc":"Thực hành các khái niệm cốt lõi qua bộ template tích hợp gồm `arrays.js` (`map`/`filter`/`reduce`), `destructuring.js`, `async.js` (`Promise`/`await`), thuật toán `primes.js`, closure và ES6 class.","f2_badge":"arrays.js &#183; async.js &#183; destructuring.js &#183; primes.js","f3_title":"Thanh Ký Tự JS/TS 21 Phím Vuốt Lên (`=&gt;`, `?.`, `${}`)","f3_desc":"Bàn phím điện thoại giấu dấu backtick và ngoặc nhọn sâu tới ba tầng. Thanh ký tự JS/TS chuyên biệt của SuperCode đặt `=&gt;`, `?.`, `===`, `` ` ``, `${}`, `{}`, `[]`, `()` và `;` ngay tầm ngón cái kèm ký tự phụ vuốt lên.","f3_badge":"=&gt; &#183; ?. &#183; === &#183; ` &#183; ${} &#183; Tự Đóng Ngoặc","f4_title":"Tự Hoàn Thành AST Offline &amp; Radar Báo Lỗi Cú Pháp Trực Tiếp","f4_desc":"Khám phá các phương thức chuẩn của `Array`, `Map`, `Set`, `String`, `Object`, `Promise` và `JSON` ngay khi gõ. Error Radar tô sáng ngoặc lệch hoặc template string chưa đóng trước cả khi bạn nhấn Chạy.","f4_badge":"Gợi Ý AST Offline &#183; Radar Ngoặc &amp; Cú Pháp Trực Tiếp","f5_title":"Định Dạng JS, TypeScript &amp; JSON Kiểu Prettier Trong 1 Chạm","f5_desc":"Đang xử lý payload JSON API một dòng hay lời giải phỏng vấn lồng nhiều cấp? Nhấn Format để căn chỉnh đẹp các file `.js`, `.mjs`, `.ts` và `.json` gọn gàng trong một bước hoàn tác.","f5_badge":"Định Dạng JS / TS / JSON &#183; Kiểm Tra JSON Nghiêm Ngặt","f6_title":"Nhập prompt() / readline Trực Tiếp &amp; Mở Rộng Lên Web IDE Đầy Đủ","f6_desc":"Nhận dữ liệu tương tác từ người dùng cho game CLI và bài tập qua `prompt()` hoặc `node:readline` &#8212; và khi sẵn sàng thao tác DOM, mở dự án `.html`/`.css`/`.js` trong Web IDE tải lại trực tiếp của SuperCode.","f6_badge":"Stdin Tương Tác &#183; Phát Triển Lên HTML5/CSS3/DOM &amp; Git","workflow_title":"Cách Học JavaScript &amp; Luyện Bài Tập DSA Trên Android","workflow_lead":"Quy trình sửa - chạy - đo hiệu năng siêu nhanh thiết kế riêng cho điện thoại, máy gập và tablet.","wf1_title":"Nạp Template JS Có Sẵn Hoặc Tạo solution.js","wf1_desc":"Chọn `arrays.js`, `destructuring.js` hoặc `async.js` từ Ví dụ Code, hay mở ngay file luyện LeetCode mới.","wf2_title":"Viết Code ES2024 Sạch Với Tốc Độ Desktop","wf2_desc":"Chèn `=&gt;`, `` `${}` `` và `===` chỉ bằng một chạm trong khi AST gợi ý sẵn các phương thức `Map`, `Set` và `Array`.","wf3_title":"Chạy Test Case &amp; Đo Hiệu Năng Với console.table / time","wf3_desc":"Chạy offline trong vài mili-giây, kiểm tra edge case qua `console.table()` và ngắt vòng lặp vô hạn ngoài ý muốn trong `&lt;1ms`.","wf4_title":"Tự Format JSON/JS, Xuất PDF Hoặc Đẩy Lên GitHub","wf4_desc":"Căn đẹp code trong một chạm, xuất ghi chú học tập PDF khổ A4 hoặc xây dựng portfolio HTML/CSS/JS hoàn chỉnh với Git trực quan.","wf_foot_note":"8 Giao Diện Studio Tối &amp; Sáng Chuẩn Thị Giác &#183; Console Chia Đôi 55:45 Trên Tablet Ngang","table_h2":"App Code JS SuperCode vs. App Học Thẻ &amp; Trình Sửa Trình Duyệt","snippet_p":"<strong>SuperCode</strong> là ứng dụng lập trình JavaScript offline miễn phí trên Android dành cho người mới bắt đầu, học viên bootcamp và người ôn phỏng vấn thuật toán LeetCode. Không tường đăng nhập, ứng dụng kết hợp 6 template JS chạy được, thanh ký tự arrow-function 21 phím, tự hoàn thành AST offline, định dạng JS và JSON một chạm cùng console nhập liệu tương tác.","table_caption":"HỌC JAVASCRIPT &amp; LUYỆN THUẬT TOÁN TRÊN ANDROID","th_0":"Tính năng học tập","th_1":"App Code JS SuperCode","th_2":"App Quiz Trả Phí","th_3":"Trình Sửa Web Di Động","th_4":"Tiện Ích Xem JSON","tr1_c0":"Thực hành code thật","tr1_c1":"Đầy đủ ES2024 Offline + 29 API lõi Node","tr1_c2":"Trắc nghiệm chạm chọn từ có sẵn","tr1_c3":"Tab trình duyệt di động giật lag","tr1_c4":"Chỉ xem cây JSON (chỉ đọc)","tr2_c0":"Học Offline Khi Di Chuyển","tr2_c1":"100% Offline, không cần đăng ký","tr2_c2":"Khóa sau màn hình đăng nhập/trả phí","tr2_c3":"Cần Wi-Fi liên tục","tr2_c4":"Offline","tr3_c0":"Gõ Ký Tự Di Động","tr3_c1":"Thanh 21 phím =&gt; / ?. / `${}` chuyên dụng","tr3_c2":"Gõ rất ít","tr3_c3":"Bấm 3 lớp phím để đổi ký tự","tr3_c4":"Không có thanh công cụ code","tr4_c0":"Định Dạng Code &amp; JSON","tr4_c1":"Format JS / TS / JSON 1 chạm + Radar","tr4_c2":"Không có","tr4_c3":"Gói web nặng nề","tr4_c4":"Chỉ JSON (không chạy được JS)","tr5_c0":"Hệ Sinh Thái Nâng Cao","tr5_c1":"Có sẵn Web IDE HTML/CSS/PHP, SQL &amp; Git","tr5_c2":"Tắc đường sau khóa nhập môn","tr5_c3":"Không có Git cục bộ hay SFTP","tr5_c4":"Công cụ đơn mục đích","faq_lead":"Các câu hỏi thường gặp từ người mới học JavaScript, học viên bootcamp và người ôn phỏng vấn.","faq1_q":"SuperCode có miễn phí hoàn toàn để bắt đầu học JavaScript offline không?","faq1_a":"Có! Bạn có thể tạo không giới hạn file `.js`, `.mjs`, `.json` và `.html`, chạy toàn bộ 6 template JavaScript tích hợp, dùng thanh ký tự 21 phím, format code và chạy script ES2024 + lõi Node offline miễn phí mà không cần đăng nhập.","faq2_q":"Tôi có thể dùng SuperCode như trình định dạng và kiểm tra JSON offline trên Android không?","faq2_a":"Có. Mở hoặc dán bất kỳ file `.json` nào (kể cả payload nặng nhiều megabyte), kiểm tra chính xác dòng/cột lỗi cú pháp bằng Error Radar và nhấn Format để thụt lề làm sạch chỉ trong một bước.","faq3_q":"SuperCode có chạy được HTML, CSS và DOM JavaScript khi tôi muốn làm website không?","faq3_a":"Chắc chắn rồi. Bất cứ khi nào bạn muốn chuyển từ console JS sang trang web trực quan, Web IDE tích hợp của SuperCode sẽ xem trước đa file HTML5, CSS3, DOM JavaScript và cả PHP + SQLite offline qua máy chủ HTTP cục bộ thật.","faq4_q":"Tôi có thể luyện cú pháp TypeScript luôn không?","faq4_a":"SuperCode hỗ trợ tô sáng cú pháp TypeScript (`.ts` / `.tsx`) đầy đủ, nhận diện ký hiệu AST, thanh ký tự JS/TS 21 phím và định dạng một chạm, cùng khả năng chạy offline độc lập cho `.js`/`.mjs` ES2024.","cta_h2":"Bắt Đầu Lập Trình JavaScript Offline Trên Android Ngay Hôm Nay.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; không đăng nhập, 6 template JS, thanh ký tự =&gt; và format JSON/JS một chạm."},"web_php_pdo":{"metaTitle":"Chạy PHP 8.2 & PDO SQLite Offline trên Android — Server PHP & IDE Không Cấu Hình | SuperCode","metaDesc":"Chạy website PHP 8.2 đa file và PDO SQLite 100% offline trên Android. Hỗ trợ $_GET, $_POST, $_SESSION bền vững, upload $_FILES 24 MB, password_hash() và JSON API không cần KSWEB hay cài CLI.","hero_tag":"PHP 8.2 OFFLINE &#183; PDO SQLITE &#183; $_SESSION &#183; KHÔNG CẤU HÌNH DAEMON","hero_h1":"Chạy <span class=\"text-gradient\">PHP 8.2 &amp; PDO SQLite Offline</span> trên Android Không Cần Thiết Lập Server.","hero_desc":"Đừng tốn công vật lộn với daemon LAMP chạy nền, extension <code>php.ini</code> lỗi hay trình sửa chỉ chạy frontend in ra nguyên thẻ <code>&lt;?php</code> thô. Trong <strong>Web &amp; PHP IDE full-stack cho Android</strong> của chúng tôi, chỉ cần nhấn Chạy trên mọi dự án <code>.php</code> để thực thi <strong>PHP 8.2</strong>, xác thực <strong><code>$_SESSION</code></strong> bền vững, upload file 24 MB và cơ sở dữ liệu <strong><code>PDO('sqlite:app.db')</code></strong> qua origin HTTP <code>localhost</code> thật.","php_s1":"Engine Offline","php_s2":"SQLite Chuẩn ACID","php_s3":"Multipart $_FILES","php_s4":"DocumentRoot Tức Thì","wb_eyebrow":"WORKBENCH PHP 8.2 OFFLINE, XÁC THỰC $_SESSION &amp; PDO SQLITE","sec_cap_title":"Đầy Đủ Công Cụ Xây Dựng Backend PHP Động Thực Thụ Ngay Trên Điện Thoại","sec_cap_lead":"Từ đồ án web đại học, thử nghiệm REST API đến trang quản trị CRUD hoàn chỉnh &#8212; thiết kế để chạy mượt ngay cả ở chế độ máy bay.","f1_title":"Cú Pháp PHP 8.2 Hiện Đại &amp; Include Đa File Tới 32 Cấp","f1_desc":"Xây dựng kiến trúc backend gọn gàng với biểu thức match của PHP 8.2, arrow function (fn() =&gt;), constructor property promotion, namespace cùng chuỗi include, require và require_once lồng nhau sâu tới 32 cấp.","f1_badge":"PHP 8.2 &#183; match &#183; fn() =&gt; &#183; require_once Sâu 32 Cấp","f2_title":"Tích Hợp Sẵn PDO('sqlite:app.db') &amp; Giao Dịch ACID","f2_desc":"Kết nối trực tiếp script PHP với database SQLite cục bộ qua new PDO('sqlite:app.db') &#8212; đầy đủ prepared statement dạng ? và :named chống SQL injection, PDO::FETCH_ASSOC cùng beginTransaction() / commit() / rollBack().","f2_badge":"Không Sửa php.ini &#183; Prepared Statement &#183; ACID","f3_title":"$_SESSION, $_COOKIE Bền Vững &amp; Xác Thực Bcrypt","f3_desc":"Xây dựng luồng đăng nhập, giỏ hàng và bảo vệ CSRF thật sự ngay offline. SuperCode lưu giữ trạng thái $_SESSION và $_COOKIE xuyên suốt các lần chuyển hướng trang (header('Location: ...')) và tích hợp sẵn password_hash(), password_verify().","f3_badge":"session_start() &#183; password_hash() &#183; Chuyển Hướng HTTP","f4_title":"$_GET, $_POST, JSON REST API &amp; Header Tùy Chỉnh","f4_desc":"Xử lý tham số query URL, form HTML urlencoded và payload JSON thô từ php://input trong khi trả về mã trạng thái HTTP tùy chỉnh cùng header('Content-Type: application/json') cho client fetch() phía frontend.","f4_badge":"$_GET / $_POST &#183; php://input &#183; Endpoint JSON REST","f5_title":"Upload Multipart $_FILES Tới 24 MB","f5_desc":"Kiểm thử form &lt;input type=\"file\"&gt; trực tiếp bằng camera hoặc trình chọn tệp Android. Xác thực metadata MIME trong $_FILES và lưu ảnh hoặc tài liệu tải lên thẳng vào workspace qua move_uploaded_file() tới 24 MB.","f5_badge":"multipart/form-data &#183; Camera/Bộ nhớ &#183; Giới Hạn 24 MB","f6_title":"Extension Lõi Phong Phú: mbstring, PCRE &amp; JSON","f6_desc":"Xử lý chuỗi UTF-8 quốc tế bằng mb_strlen() và mb_substr(), kiểm tra dữ liệu đầu vào với preg_match() và preg_replace(), định dạng mốc thời gian và chạy ứng dụng đa file mà không tốn pin cho daemon chạy nền.","f6_badge":"mbstring &#183; preg_* &#183; json_encode &#183; Khởi Chạy Tức Thì","workflow_title":"Cách Chạy Dự Án PHP 8.2 + SQLite Offline Trên Android","workflow_lead":"Không cần quyền root, không menu mở port và không phải bật daemon database riêng.","wf1_title":"Tạo Hoặc Clone Workspace PHP Đa File","wf1_desc":"Tạo thư mục dự án với index.php, includes/db.php và assets/ &#8212; SuperCode tự động nhận gốc dự án làm root máy chủ web cục bộ.","wf2_title":"Kết Nối Cơ Sở Dữ Liệu SQLite Cục Bộ","wf2_desc":"Khởi tạo bảng ngay từ PHP PDO hoặc tạo trước và xem trực quan file app.db bên trong SQL Studio tích hợp của SuperCode.","wf3_title":"Thử Form, Session &amp; Fetch API Qua Localhost","wf3_desc":"Nhấn Chạy &#9654; để mở trình xem trước trực tiếp qua origin HTTP cục bộ thật, gửi form POST/file và theo dõi thời gian request PHP ở tab Net.","wf4_title":"Xóa Cookie Trong 1 Chạm Hoặc Đẩy Lên Qua SFTP","wf4_desc":"Xóa cookie $_SESSION đang hoạt động bất cứ lúc nào từ thanh xem trước để test lại luồng đăng nhập, rồi triển khai file PHP đã kiểm thử thẳng lên host Linux qua SFTP/FTPS.","wf_foot_note":"PHP 8.2 + PDO SQLite 100% Offline &#183; Dùng Chung Workspace Với SQL Studio &amp; SFTP Client","table_h2":"SuperCode PHP 8.2 Studio Offline vs. Các Giải Pháp PHP Khác Trên Android","snippet_p":"<strong>Máy chủ PHP 8.2 &amp; PDO Offline của SuperCode</strong> biến mọi điện thoại hoặc tablet Android thành studio phát triển PHP cục bộ không cần cấu hình. Thực thi script PHP 8.2 đa file, luồng $_SESSION bền vững, upload file multipart, xác thực bcrypt, JSON API và truy vấn PDO('sqlite:app.db') chuẩn ACID qua origin HTTP localhost thật mà không cần thiết lập daemon thủ công.","table_caption":"SO SÁNH SERVER PHP OFFLINE &amp; IDE TRÊN ANDROID","th_0":"Tính năng PHP","th_1":"SuperCode PHP 8.2 Studio","th_2":"KSWEB / Daemon LAMP","th_3":"Terminal CLI php -S","th_4":"Trình Sửa Spck / TrebEdit","tr1_c0":"Thiết lập &amp; DocumentRoot","tr1_c1":"Chạy 1 chạm theo thư mục, không cấu hình","tr1_c2":"Chỉnh vhost, port &amp; dịch vụ nền thủ công","tr1_c3":"Cài pkg thủ công + gõ cờ CLI","tr1_c4":"Không chạy được PHP (chỉ frontend)","tr2_c0":"PHP 8.2 + Include","tr2_c1":"match, fn(), OOP &amp; require_once sâu 32 cấp","tr2_c2":"Có hỗ trợ (tùy gói trả phí)","tr2_c3":"Hỗ trợ qua CLI thủ công","tr2_c4":"In ra chữ &lt;?php thô","tr3_c0":"Database SQL Offline","tr3_c1":"Tích hợp PDO('sqlite:...') + SQL Studio","tr3_c2":"Thiết lập daemon nền nặng nề","tr3_c3":"Nối extension &amp; CLI thủ công","tr3_c4":"Không có database backend","tr4_c0":"Form, $_SESSION &amp; File","tr4_c1":"$_SESSION bền vững + $_FILES 24 MB","tr4_c2":"Hỗ trợ qua trình duyệt ngoài","tr4_c3":"Không có giao diện DevTools tích hợp","tr4_c4":"Chỉ hỗ trợ form HTML tĩnh","tr5_c0":"Editor, Git &amp; SFTP","tr5_c1":"Hợp nhất AST Editor + DevTools + Git + SFTP","tr5_c2":"Cần ứng dụng viết code riêng","tr5_c3":"Chỉ có nano/vim trong terminal","tr5_c4":"Chỉ có Git frontend, không có PHP","faq_lead":"Giải đáp các thắc mắc phổ biến về việc chạy PHP 8.2, PDO SQLite, session và upload file offline trên Android.","faq1_q":"SuperCode có chạy PHP 8.2 hoàn toàn offline không cần internet không?","faq1_a":"Có. Engine PHP 8.2 và driver database PDO SQLite của SuperCode chạy 100% cục bộ trên thiết bị Android &#8212; bạn có thể code và test website PHP nhiều trang, form đăng nhập và JSON API ngay trong chế độ máy bay.","faq2_q":"Tại sao nên chọn SuperCode thay vì KSWEB hay chạy `php -S` trong app terminal?","faq2_a":"Các daemon server rời yêu cầu chỉnh đường dẫn virtual-host thủ công, giữ dịch vụ chạy ngầm và buộc bạn chuyển qua lại giữa ba ứng dụng (editor, server, trình duyệt). SuperCode hợp nhất chỉnh sửa AST PHP, định tuyến HTTP tự động theo gốc dự án, Web DevTools, SQL Studio và xuất bản SFTP trong một IDE gọn nhẹ.","faq3_q":"JavaScript frontend có thể gọi các file `.php` cục bộ bằng `fetch()` không?","faq3_a":"Có! Vì workspace của bạn được phục vụ qua một origin HTTP/1.1 `localhost` thật, `await fetch('/api/tasks.php', { method: 'POST', ... })` hoạt động trơn tru với JSON header, cookie và bảng đo thời gian Network trong DevTools.","faq4_q":"Tôi có thể xem file `.db` SQLite do PHP `new PDO('sqlite:app.db')` tạo ra không?","faq4_a":"Ngay lập tức. Chạm vào `app.db` trong trình quản lý tệp của SuperCode để xem bảng, schema và dữ liệu từng dòng ở định dạng bảng Unicode hoặc Markdown ngay trong SQL Studio.","cta_h2":"Xây Dựng &amp; Kiểm Thử Ứng Dụng PHP 8.2 + SQL Động Offline Mọi Nơi.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; không cấu hình daemon, tích hợp PDO SQLite và Web DevTools trực tiếp."},"web_html_preview":{"metaTitle":"Trình soạn thảo HTML5, CSS3 & JS cho Android — Máy chủ HTTP nội bộ & Xem trước 3 khung hình | SuperCode","metaDesc":"Thiết kế và kiểm thử web responsive ngoại tuyến trên Android. SuperCode kết hợp trình soạn thảo AST HTML5/CSS3/JS, định dạng đệ quy 1 chạm với máy chủ HTTP nội bộ thực thụ, chuyển đổi Mobile/Tablet 768dp/Desktop và xuất ảnh PNG.","hero_tag":"HTTP/1.1 NỘI BỘ THỰC &#183; MOBILE / TABLET 768DP / DESKTOP &#183; ĐỊNH DẠNG ĐỆ QUY","hero_h1":"Soạn thảo <span class=\"text-gradient\">HTML5, CSS3 &amp; ES Modules</span> kèm xem trước responsive 3 khung hình trực tiếp.","hero_desc":"Các trình xem HTML cơ bản trên Android mở tệp qua <code>file://</code> &#8212; làm lỗi <code>&lt;script type=&quot;module&quot;&gt;</code>, <code>fetch()</code> và web storage, đồng thời bó hẹp bạn trong chiều rộng điện thoại. SuperCode phục vụ thư mục của bạn qua <strong>máy chủ HTTP/1.1 <code>localhost</code> thực thụ</strong> với chuyển đổi khung hình <strong>Mobile, Tablet (768dp) và Desktop</strong> tức thì.","html_s1":"Loại MIME HTTP","html_s2":"Mobile/768dp/Desktop","html_s3":"Tua phát Media","html_s4":"Chụp toàn trang","wb_eyebrow":"MÁY CHỦ HTTP/1.1 NỘI BỘ, BREAKPOINT RESPONSIVE &amp; BÀN LÀM VIỆC ES MODULES","sec_cap_title":"Vì sao lập trình viên Frontend nâng cấp từ trình xem HTML di động cơ bản","sec_cap_lead":"Ngữ nghĩa origin trình duyệt thực thụ, kiểm thử đa breakpoint chuẩn xác và định dạng code dễ dàng trên điện thoại, máy gập và tablet.","f1_title":"Máy chủ HTTP/1.1 nội bộ thực thụ (65+ loại MIME)","f1_desc":"Tạm biệt lỗi CORS 'origin null'. Phục vụ qua origin localhost HTTP/1.1 thực giúp mở khóa import &lt;script type=\"module\"&gt; gốc, fetch('./data.json'), localStorage, IndexedDB, SVG sprite và phông chữ web .woff2.","f1_badge":"Origin Localhost thực &#183; 65+ loại MIME &#183; Không bị chặn CORS","f2_title":"Chuyển đổi 3 khung hình Responsive kiểu Dynamic Island","f2_desc":"Kiểm tra cách CSS Grid, Flexbox và @media query thích ứng trên nhiều màn hình mà không cần sở hữu ba thiết bị. Chạm vào thanh Dynamic Island kéo thả được để chuyển trực tiếp giữa bố cục Mobile, Tablet (768dp) và Desktop rộng.","f2_badge":"Breakpoint Mobile &#183; Tablet (768dp) &#183; Desktop","f3_title":"Định dạng đệ quy HTML + &lt;style&gt; + &lt;script&gt; chỉ 1 chạm","f3_desc":"Nguyên mẫu đơn tệp luôn gọn gàng: một chạm vào Định dạng sẽ thụt lề chuẩn xác các phần tử HTML5 lồng nhau, đồng thời định dạng đệ quy quy tắc CSS trong &lt;style&gt; và mã JavaScript trong khối &lt;script&gt;.","f3_badge":"Định dạng hợp nhất Markup + CSS + JS","f4_title":"Truyền phát Media HTTP 206 &amp; Shader 3D WebGL","f4_desc":"Kiểm thử trình phát &lt;video&gt; và &lt;audio&gt; tương tác với tính năng tua thanh thời gian theo dải byte HTTP 206 Partial Content thực, hoặc kết xuất Three.js, mô hình 3D .glb/.gltf, HTML5 Canvas và shader WebGL GLSL tùy chỉnh mượt mà.","f4_badge":"Tua dải byte HTTP 206 &#183; WebGL GLSL &#183; .glb / .gltf","f5_title":"3 mẫu Web tích hợp sẵn &amp; Tự động hoàn thành AST","f5_desc":"Khởi tạo ngay từ 3 mẫu Web đa phần tuyển chọn, gõ nhanh thẻ và thuộc tính CSS với hoàn thành mã AST ngoại tuyến cùng thanh ký tự 21 phím, đồng thời xem trước liền mạch các stylesheet liên kết nhiều thư mục.","f5_badge":"3 mẫu Web &#183; AST HTML/CSS/JS &#183; Thanh 21 phím","f6_title":"Xuất Mockup PNG toàn trang độ phân giải cao","f6_desc":"Cần gửi tiến độ thiết kế cho khách hàng, giảng viên hay GitHub PR? Chụp ảnh màn hình PNG toàn trang sắc nét (tối đa 2560px) trực tiếp từ bất kỳ khung hình Mobile, Tablet hoặc Desktop nào đang mở.","f6_badge":"PNG tới 2560px &#183; Sẵn sàng cho khách hàng &amp; bài tập","workflow_title":"Cách xây dựng &amp; kiểm thử web Responsive ngay trên điện thoại","workflow_lead":"Đi từ stylesheet trống đến bố cục responsive 3 breakpoint đã kiểm chứng chỉ trong vài phút.","wf1_title":"Chọn mẫu Web có sẵn hoặc mở thư mục của bạn","wf1_desc":"Khởi chạy một trong 3 mẫu khởi đầu HTML5/CSS3/JS tích hợp sẵn hoặc mở bất kỳ kho mã frontend nhiều thư mục nào từ bộ nhớ máy hay Git.","wf2_title":"Viết HTML5, CSS Grid &amp; ES Modules sạch đẹp","wf2_desc":"Chỉnh sửa các tab .html, .css và .js liên kết với gợi ý AST ngoại tuyến, sau đó chạm Định dạng để làm gọn đồng thời các khối HTML, &lt;style&gt; và &lt;script&gt;.","wf3_title":"Chuyển đổi trực tiếp Mobile, Tablet (768dp) &amp; Desktop","wf3_desc":"Chạm Chạy &#9654; và đổi khung hình trên thanh Dynamic Island kéo thả được để kiểm tra menu điều hướng, kiểu chữ và các breakpoint lưới.","wf4_title":"Xuất ảnh chụp độ phân giải cao hoặc Push lên GitHub","wf4_desc":"Lưu ảnh mockup PNG sắc nét cho từng breakpoint vào hồ sơ năng lực hoặc push trang web hoàn thiện thẳng lên GitHub Pages.","wf_foot_note":"Hoạt động 100% ngoại tuyến &#183; Hỗ trợ ES Modules, Web Fonts, Canvas, WebGL &amp; yêu cầu dải Media","table_h2":"SuperCode Web Studio so với Spck, TrebEdit &amp; trình xem HTML cơ bản","snippet_p":"<strong>HTML5, CSS3 &amp; JavaScript Studio của SuperCode</strong> phục vụ dự án web di động qua origin localhost HTTP/1.1 thực với hơn 65 loại MIME thay vì đường dẫn file:// bị hạn chế. Xem trước ES Modules, IndexedDB, WebGL và luồng video HTTP 206 trên các khung hình Mobile, Tablet 768dp và Desktop kèm định dạng đệ quy 1 chạm và chụp PNG toàn trang.","table_caption":"SO SÁNH TRÌNH XEM TRƯỚC HTML5, CSS3 &amp; RESPONSIVE TRÊN ANDROID","th_0":"Tính năng Frontend","th_1":"SuperCode Web Studio","th_2":"Spck / TrebEdit","th_3":"Trình xem file:// cơ bản","th_4":"Trình chạy code trực tuyến","tr1_c0":"Giao thức máy chủ nội bộ","tr1_c1":"Localhost HTTP/1.1 thực (65+ loại MIME)","tr1_c2":"Xem trước nội bộ hạn chế (không PHP/206)","tr1_c3":"Lỗi CORS file:// chặn ESM","tr1_c4":"Chỉ đám mây (lỗi khi ngoại tuyến)","tr2_c0":"Kiểm thử Responsive","tr2_c1":"1 chạm Mobile / Tablet 768dp / Desktop","tr2_c2":"Chuyển đổi mobile/desktop cơ bản","tr2_c3":"Cố định chiều rộng điện thoại","tr2_c4":"Khung iframe chia đôi chật hẹp","tr3_c0":"Định dạng mã nguồn","tr3_c1":"Đệ quy HTML + &lt;style&gt; + &lt;script&gt; 1 chạm","tr3_c2":"Đơn ngôn ngữ hoặc thủ công","tr3_c3":"Không có trình định dạng","tr3_c4":"Yêu cầu kết nối mạng","tr4_c0":"Media, WebGL &amp; WASM","tr4_c1":"Tua HTTP 206 + WebGL + Luồng .wasm","tr4_c2":"Tài nguyên tĩnh một phần","tr4_c3":"Lỗi khi tải dải byte &amp; module","tr4_c4":"Giới hạn dung lượng tải lên","tr5_c0":"Hướng phát triển Backend","tr5_c1":"Tích hợp PHP 8.2 ngoại tuyến, PDO SQL &amp; SFTP","tr5_c2":"Giới hạn chỉ ở Frontend","tr5_c3":"Chỉ HTML tĩnh","tr5_c4":"Gói container trả phí","faq_lead":"Câu hỏi thường gặp về chỉnh sửa HTML5/CSS3/JS, ES Modules và xem trước khung hình responsive trên Android.","faq1_q":"Tại sao `&lt;script type=\"module\"&gt;` hoặc `fetch('./data.json')` của tôi bị lỗi trong các ứng dụng sửa HTML khác?","faq1_a":"Trình duyệt chặn ES Modules và `fetch()` trên URL `file://` do quy tắc bảo mật CORS nghiêm ngặt. SuperCode tự động phục vụ dự án của bạn qua origin `localhost` HTTP/1.1 thực với header MIME chuẩn để module JS hiện đại và truy vấn JSON hoạt động tự nhiên khi ngoại tuyến.","faq2_q":"Làm sao tôi có thể xem trước CSS media query cho Tablet và Desktop trên màn hình điện thoại?","faq2_a":"Trong Xem trước Web trực tiếp của SuperCode, chạm vào biểu tượng khung hình trên thanh Dynamic Island nổi để chuyển đổi tức thì giữa các khung hình Mobile, Tablet (`768dp`) và Desktop rộng &#8212; kích hoạt chuẩn xác các quy tắc `@media` của bạn.","faq3_q":"Trình định dạng 1 chạm có định dạng cả CSS trong `&lt;style&gt;` và JS trong `&lt;script&gt;` không?","faq3_a":"Có. Trình định dạng HTML đệ quy của SuperCode phân tích cú pháp các khối `&lt;style&gt;` và `&lt;script&gt;` nhúng trong tệp `.html` và thụt lề gọn gàng cả ba ngôn ngữ chỉ với một chạm.","faq4_q":"Tôi có thể dùng video `.mp4`, phông `.woff2` và mô hình 3D `.glb` cục bộ khi ngoại tuyến không?","faq4_a":"Có. Hơn 65 loại MIME được cấu hình sẵn cục bộ, bao gồm `font/woff2`, `model/gltf-binary`, `image/svg+xml`, cùng truyền phát dải byte HTTP `206 Partial Content` giúp tua thanh thời gian `&lt;video&gt;` và `&lt;audio&gt;` mượt mà.","cta_h2":"Thiết kế trang web HTML5, CSS3 &amp; JS Responsive mọi lúc mọi nơi.","cta_desc":"Tải SuperCode IDE miễn phí trên Google Play &#8212; xem trước HTTP/1.1 nội bộ thực, chuyển 3 khung hình và định dạng đệ quy 1 chạm."},"web_devtools_wasm":{"metaTitle":"Console Web DevTools di động, Nhật ký mạng, DOM REPL & WASM trên Android | SuperCode","metaDesc":"Gỡ lỗi ứng dụng web di động không cần cáp nối máy tính. SuperCode tích hợp ngăn Console DevTools đổi cỡ được (All/Error/Warn/Net), bộ đo thời gian HTTP, DOM JS REPL bất đồng bộ trực tiếp và truyền phát WebAssembly (.wasm) gốc trên Android.","hero_tag":"ALL / ERROR / WARN / NET &#183; DOM REPL TRỰC TIẾP &#183; TRUYỀN PHÁT WEBASSEMBLY","hero_h1":"Studio <span class=\"text-gradient\">Web DevTools, Giám sát Mạng &amp; WASM</span> di động trên Android.","hero_desc":"Trình duyệt Android ẩn mất ngăn F12 DevTools đúng lúc bạn cần chẩn đoán lỗi <code>fetch()</code> âm thầm, lỗi bố cục hay module nhị phân <code>.wasm</code>. SuperCode tích hợp <strong>Console Web DevTools đổi kích thước được, bộ đo mạng HTTP, DOM JS REPL trực tiếp và máy chủ <code>application/wasm</code></strong> ngay trong trình xem trước di động.","dev_s1":"All/Error/Warn/Net","dev_s2":"DOM JS bất đồng bộ trực tiếp","dev_s3":"Trình biên dịch Streaming","dev_s4":"Đo đạc mạng HTTP","wb_eyebrow":"CONSOLE DEVTOOLS DI ĐỘNG, ĐO THỜI GIAN MẠNG, DOM REPL &amp; BÀN LÀM VIỆC WASM","sec_cap_title":"Chẩn đoán trình duyệt chuẩn Desktop mà không cần cắm cáp gỡ lỗi USB","sec_cap_lead":"Xem mọi cảnh báo console, kiểm tra trạng thái JS tham chiếu vòng, đo độ trễ API và truyền phát WebAssembly nhị phân trên điện thoại.","f1_title":"Ngăn DevTools đổi cỡ được &amp; Huy hiệu lỗi trực tiếp","f1_desc":"Kéo thanh chia DevTools lên ngay bên dưới trang web đang hiển thị. Lọc nhật ký tức thì theo các tab All, Error, Warn và Net, đồng thời huy hiệu trực tiếp trên thanh nổi sẽ báo ngay khi có ngoại lệ chưa bắt được.","f1_badge":"All / Error / Warn / Net &#183; Kéo thả chiều cao ngăn chia","f2_title":"Giám sát thời gian mạng HTTP, fetch() &amp; PHP","f2_desc":"Chuyển sang tab Net để kiểm tra mọi tài nguyên trang, ES module, tệp nhị phân WASM và yêu cầu API PHP theo thời gian thực &#8212; định dạng rõ ràng theo METHOD /path -&gt; status &#183; ms &#183; bytes để nhận diện lỗi 404 và payload chậm trong nháy mắt.","f2_badge":"Đo đạc METHOD /path -&gt; status &#183; ms &#183; bytes","f3_title":"DOM trực tiếp tương tác &amp; JS REPL Promise bất đồng bộ","f3_desc":"Nhập bất kỳ biểu thức nào vào dấu nhắc &gt; Run JavaScript... để truy vấn hoặc thay đổi phần tử DOM đang chạy, thử bật/tắt lớp CSS, kiểm tra localStorage hoặc đánh giá Promise fetch() bất đồng bộ trực tiếp trên trang.","f3_badge":"&gt; Run JavaScript... &#183; Tự động phân giải Promise","f4_title":"Phần tử DOM (&lt;div#app.card&gt;) &amp; In an toàn tham chiếu vòng","f4_desc":"Không còn phải nhìn dòng [object HTMLDivElement] vô nghĩa hay lỗi sập JSON do tham chiếu vòng. SuperCode tuần tự hóa các nút DOM sống thành mô tả &lt;tag#id.class&gt; dễ đọc và định dạng an toàn Object, Map, Set lồng nhau cùng liên kết [Circular].","f4_badge":"Định dạng &lt;div#id.class&gt; &#183; An toàn đồ thị vòng","f5_title":"Thực thi truyền phát WebAssembly (.wasm) gốc","f5_desc":"Chạy các module .wasm biên dịch từ Rust, C, C++, Zig hoặc AssemblyScript với tốc độ gần như mã gốc. Máy chủ HTTP nội bộ của chúng tôi cung cấp tệp .wasm với header application/wasm chuẩn xác để WebAssembly.instantiateStreaming(fetch(...)) chạy zero-copy.","f5_badge":"application/wasm &#183; WebAssembly.instantiateStreaming()","f6_title":"Truy vết lỗi chưa bắt &amp; Rejection không cần cấu hình","f6_desc":"Ngay cả trước khi bạn thêm câu lệnh console.log, SuperCode vẫn gắn hook vào vòng đời trang sớm để bắt lỗi cú pháp, TypeError lúc chạy và lỗi Promise unhandledrejection kèm tên script, dòng và cột chính xác.","f6_badge":"Hook vòng đời sớm &#183; Stack trace chuẩn Dòng:Cột","workflow_title":"Cách gỡ lỗi JS, lệnh gọi mạng &amp; WebAssembly trên Android","workflow_lead":"Không cần mẹo bookmarklet, không cần nối cáp desktop từ xa và không cần chèn thẻ script thủ công.","wf1_title":"Khởi chạy dự án Web hoặc WASM qua HTTP nội bộ","wf1_desc":"Mở tệp đầu vào .html, .js hoặc .php và chạm Chạy &#9654; &#8212; các hook DevTools và bộ đo mạng tự động gắn kết ngay.","wf2_title":"Mở ngăn DevTools đổi cỡ được &amp; Lọc nhật ký","wf2_desc":"Chạm vào huy hiệu DevTools (hiển thị số lỗi trực tiếp) và chuyển giữa các tab All, Error, Warn và Net trong khi kéo chỉnh chiều cao khung.","wf3_title":"Truy vấn trạng thái DOM trực tiếp &amp; Chờ biểu thức bất đồng bộ","wf3_desc":"Nhập lệnh JS trực tiếp vào ô REPL bên dưới để kiểm tra nút DOM (&lt;section#hero.active&gt;), khóa lưu trữ hoặc các hàm xuất của WASM.","wf4_title":"Quay lại dòng trình soạn thảo &amp; Kiểm chứng lại","wf4_desc":"Vuốt từ cạnh trái để quay về ngay tab mã nguồn, áp dụng bản sửa lỗi và chạy lại chỉ bằng một chạm.","wf_foot_note":"Không chèn script CDN bên thứ ba &#183; Hoạt động 100% ngoại tuyến ở chế độ máy bay","table_h2":"SuperCode DevTools di động so với trình duyệt di động &amp; Bookmarklet","snippet_p":"<strong>Studio Web DevTools &amp; WASM di động của SuperCode</strong> mang khả năng kiểm tra trình duyệt chuẩn desktop thẳng lên Android. Lọc nhật ký All, Error, Warn và thời gian mạng HTTP trong ngăn kéo đổi cỡ được, kiểm tra phần tử DOM và đối tượng tham chiếu vòng trong JavaScript REPL bất đồng bộ, và biên dịch module .wasm nhị phân qua WebAssembly.instantiateStreaming() gốc.","table_caption":"BẢNG ĐỐI CHIẾU GỠ LỖI WEB DI ĐỘNG &amp; WEBASSEMBLY TRÊN ANDROID","th_0":"Tính năng chẩn đoán","th_1":"SuperCode Web DevTools","th_2":"Android Chrome di động","th_3":"Eruda / CDN Bookmarklet","th_4":"Ứng dụng xem HTML cơ bản","tr1_c0":"Console &amp; Huy hiệu lỗi","tr1_c1":"Tích hợp All / Error / Warn / Net + Huy hiệu","tr1_c2":"Ẩn nếu thiếu PC USB adb","tr1_c3":"Phải chèn thẻ script thủ công","tr1_c4":"Chỉ cảnh báo/log văn bản thuần","tr2_c0":"Đo thời gian mạng HTTP","tr2_c1":"Thời gian thực METHOD /path -&gt; status &#183; ms &#183; B","tr2_c2":"Cần nối cáp DevTools từ PC","tr2_c3":"Chỉ hook XHR một phần","tr2_c4":"Không hỗ trợ","tr3_c0":"JS DOM REPL trực tiếp","tr3_c1":"REPL tương tác + Phân giải Promise","tr3_c2":"Yêu cầu kết nối PC","tr3_c3":"Hỗ trợ khi trực tuyến","tr3_c4":"Không hỗ trợ","tr4_c0":"DOM &amp; Đối tượng vòng","tr4_c1":"&lt;div#app.card&gt; + Bộ tuần tự an toàn [Circular]","tr4_c2":"Yêu cầu kết nối PC","tr4_c3":"Gói chèn vào nặng nề","tr4_c4":"Chuỗi [object Object]","tr5_c0":"WebAssembly (.wasm)","tr5_c1":"Máy chủ stream application/wasm ngoại tuyến","tr5_c2":"Cần máy chủ web bên ngoài","tr5_c3":"Không sửa được MIME file://","tr5_c4":"Lỗi kiểm tra MIME / CORS","faq_lead":"Giải đáp về kiểm tra lỗi console, giám sát yêu cầu HTTP, chạy lệnh DOM JS và thực thi `.wasm` ngoại tuyến.","faq1_q":"Tôi có cần dán `&lt;script src=\"eruda.js\"&gt;` hay có mạng để DevTools hoạt động không?","faq1_a":"Không! Console Web DevTools, bộ giám sát mạng và JavaScript REPL tương tác của SuperCode được tích hợp sẵn vào công cụ xem trước ngoại tuyến &#8212; không cần thẻ script CDN ngoài và hoạt động 100% ở chế độ máy bay.","faq2_q":"Tôi có thể chạy các tệp nhị phân WebAssembly `.wasm` biên dịch từ Rust hoặc C/C++ không?","faq2_a":"Có. Đặt tệp nhị phân `.wasm` trong thư mục dự án và nạp bằng `WebAssembly.instantiateStreaming(fetch('./module.wasm'))` &#8212; SuperCode phục vụ `.wasm` với loại MIME `application/wasm` chuẩn xác.","faq3_q":"Điều gì xảy ra nếu tôi ghi log một phần tử DOM hoặc đối tượng có tham chiếu vòng?","faq3_a":"Các phần tử DOM hiển thị gọn gàng dạng tóm tắt `&lt;tag#id.class&gt;`, còn các tham chiếu vòng được phát hiện an toàn là `[Circular]` thay vì ném ra ngoại lệ `JSON.stringify`.","faq4_q":"Tab Net có bắt được các lệnh gọi backend PHP cũng như tệp tĩnh và `fetch()` không?","faq4_a":"Có. Mọi tài nguyên tĩnh, ES module, tệp nhị phân `.wasm`, lệnh gọi `fetch()` / `XMLHttpRequest` và thực thi endpoint `.php` nội bộ đều hiện trong tab Net kèm mã trạng thái HTTP, độ trễ mili-giây và kích thước byte payload.","cta_h2":"Kiểm tra Console, Mạng &amp; WebAssembly ngay trên điện thoại của bạn.","cta_desc":"Tải SuperCode IDE miễn phí trên Google Play &#8212; tích hợp sẵn Web DevTools, DOM REPL trực tiếp và truyền phát WASM ngoại tuyến."},"web_sftp_deploy":{"metaTitle":"Chỉnh sửa & Triển khai Web trực tiếp từ Android — Staging nội bộ tới SFTP, FTPS & Git | SuperCode","metaDesc":"Bảo trì và triển khai website HTML, CSS, JS, WASM và PHP thực tế từ điện thoại Android. Xem trước tab SFTP/FTPS từ xa ngay tại máy theo nhu cầu, lưu bằng giao dịch nguyên tử 3 pha hoặc push lên GitHub Pages.","hero_tag":"SFTP (KHÓA SSH) &#183; FTPS (TLS 1.3) &#183; XEM TRƯỚC TỪ XA THEO NHU CẦU &#183; GIT TRỰC QUAN","hero_h1":"Staging nội bộ, rồi <span class=\"text-gradient\">Sửa &amp; Triển khai Web thực tế</span> qua SFTP, FTPS &amp; Git.","hero_desc":"Dù đang vá nóng lỗi PHP sản xuất khẩn cấp trên tàu hay xuất bản portfolio tĩnh lên GitHub Pages, SuperCode kết nối trực tiếp <strong>staging HTTP/PHP nội bộ</strong> với <strong>SFTP khóa SSH, FTPS TLS 1.3 và Git trực quan</strong> &#8212; tích hợp sẵn <strong>xem trước trang từ xa theo nhu cầu</strong> và <strong>lưu từ xa nguyên tử 3 pha</strong>.","dep_s1":"Khóa Ed25519 / RSA","dep_s2":"FTPS Tường minh/Ngầm định","dep_s3":"Lưu từ xa nguyên tử","dep_s4":"Push GitHub Pages","wb_eyebrow":"XEM TRƯỚC TRỰC TIẾP SFTP TỪ XA, LƯU NGUYÊN TỬ &amp; BÀN LÀM VIỆC GIT PAGES","sec_cap_title":"Vận hành Web an toàn cho môi trường sản xuất, thiết kế riêng cho mạng di động","sec_cap_lead":"Xem trước trước khi ghi đè, vượt qua sự cố rớt mạng di động an toàn và quản lý VPS hoặc host tĩnh từ một không gian làm việc.","f1_title":"Gắn kết VPS Linux &amp; Shared Host qua SFTP, FTPS &amp; FTP","f1_desc":"Kết nối trực tiếp máy chủ VPS Nginx/Apache bằng SFTP với khóa SSH lưu cứng phần cứng (Ed25519, RSA, ECDSA) hoặc web host cPanel/Plesk qua FTPS tường minh/ngầm định (TLS 1.3) và FTP chuẩn.","f1_badge":"SFTP &#183; FTPS (TLS 1.3) &#183; Két khóa Android KeyStore","f2_title":"Xem trước nội bộ 1 chạm cho tab HTML &amp; PHP từ xa","f2_desc":"Mở tệp .html hoặc .php từ xa trên cây máy chủ và chạm Chạy &#9654;. SuperCode kết xuất trang ngay tại máy, đồng thời tự động tải các stylesheet, script và hình ảnh liên quan từ máy chủ theo nhu cầu.","f2_badge":"Kiểm thử bản sửa từ xa tại máy &#183; Tải tài nguyên theo nhu cầu","f3_title":"Lưu nguyên tử 3 pha ngăn lỗi hỏng trang đang chạy","f3_desc":"Lưu đè trực tiếp lên index.php đang chạy qua Wi-Fi di động chập chờn có thể để lại tệp dở dang và gây sập HTTP 500. SuperCode tải lên tệp tạm cùng cấp, đối chiếu chính xác số byte rồi mới đổi tên nguyên tử.","f3_badge":"Không tệp sản xuất ghi dở &#183; An toàn trên 4G/5G","f4_title":"Staging ngoại tuyến đầy đủ với PHP 8.2 &amp; 3 khung hình","f4_desc":"Clone hoặc tải thư mục trang web về điện thoại, dựng thử route PHP 8.2 + PDO SQLite và bố cục CSS Grid trên khung hình Mobile/Tablet/Desktop ở chế độ máy bay, rồi tải lên các thay đổi đã kiểm chứng.","f4_badge":"Quy trình Staging ngoại tuyến -&gt; Đồng bộ Production","f5_title":"Trình khách Git trực quan cho GitHub, Cloudflare &amp; Netlify Pages","f5_desc":"Đang triển khai ứng dụng JAMstack, HTML5 tĩnh hay WASM? Xem unified diff tô màu từng dòng, stage tệp có chọn lọc, commit và push thẳng lên GitHub, GitLab hoặc Bitbucket để kích hoạt bản dựng CI/CD Pages.","f5_badge":"Unified Diff màu &#183; HTTPS PAT &#183; Git Push 1 chạm","f6_title":"Truyền thư mục đồng thời &amp; Khôi phục khi gián đoạn","f6_desc":"Xuất bản nhanh toàn bộ thư mục dist/, assets/ hoặc media với hàng đợi truyền đa kết nối, tiến độ băng thông trực tiếp, sửa quyền chmod từ xa và tự động nối lại khi rớt kết nối.","f6_badge":"Hàng đợi tải lên song song &#183; Tiếp tục &#183; chmod từ xa","workflow_title":"Cách xem trước, sửa an toàn &amp; xuất bản trang web thực tế từ Android","workflow_lead":"Hai quy trình triển khai gọn gàng &#8212; SFTP/FTPS trực tiếp cho máy chủ PHP/VPS, hoặc Git trực quan cho Pages.","wf1_title":"Gắn kết Web Host hoặc Clone kho Git của bạn","wf1_desc":"Thêm máy chủ VPS/cPanel vào trình quản lý SFTP/FTPS (với khóa SSH mã hóa hoặc mật khẩu) hoặc clone kho lưu trữ GitHub Pages của bạn.","wf2_title":"Xem trước trang từ xa hoặc Staging trên 3 khung hình","wf2_desc":"Sửa HTML, CSS, JS hoặc PHP với hoàn thành mã AST và chạm Chạy &#9654; để kiểm tra hiển thị Mobile/Tablet/Desktop cùng nhật ký DevTools trước khi xuất bản.","wf3_title":"Xác minh thay đổi bằng Unified Diff hoặc Tải lên nguyên tử","wf3_desc":"Lưu các tab SFTP/FTPS từ xa qua đổi tên nguyên tử 3 pha để người truy cập không bao giờ gặp tệp ghi dở, hoặc kiểm tra diff Git tô màu.","wf4_title":"Push lên Production &amp; Xác nhận trạng thái mạng","wf4_desc":"Push các commit để kích hoạt GitHub/Cloudflare Pages hoặc đồng bộ đồng thời các thư mục tài nguyên lên máy chủ sản xuất.","wf_foot_note":"Mã hóa thông tin đăng nhập phần cứng &#183; Hỗ trợ SFTP, FTPS tường minh/ngầm định (TLS 1.3), FTP &amp; Git HTTPS","table_h2":"Triển khai Full-Stack SuperCode so với ứng dụng FTP rời &amp; bảng điều khiển trình duyệt","snippet_p":"<strong>Studio Web SFTP &amp; Git Full-Stack của SuperCode</strong> giúp lập trình viên staging, xem trước và triển khai website thực tế ngay từ Android. Gắn kết máy chủ từ xa qua SFTP khóa SSH hoặc FTPS TLS 1.3, xem trước trang HTML và PHP từ xa tại máy theo nhu cầu, lưu cập nhật qua giao dịch nguyên tử 3 pha hoặc push bản dựng tĩnh lên GitHub Pages.","table_caption":"SO SÁNH BẢO TRÌ &amp; TRIỂN KHAI WEBSITE TRÊN DI ĐỘNG","th_0":"Nhu cầu triển khai","th_1":"SuperCode Web + SFTP + Git","th_2":"Ứng dụng FTP Android rời","th_3":"Giao diện cPanel trình duyệt di động","th_4":"Chỉ dùng Laptop Desktop","tr1_c0":"Xem trước Web từ xa","tr1_c1":"Chạy nội bộ 1 chạm + Tải tài nguyên theo nhu cầu","tr1_c2":"Phải tải thủ công toàn bộ trang web","tr1_c3":"Không có xem trước staging nội bộ","tr1_c4":"SSH tunnel / đồng bộ thủ công","tr2_c0":"Lưu từ xa chống rớt mạng","tr2_c1":"Tải lên nguyên tử 3 pha + Đối chiếu + Đổi tên","tr2_c2":"Ghi đè trực tiếp dễ gây cắt cụt tệp","tr2_c3":"Hết phiên làm mất nội dung sửa","tr2_c4":"Tùy thuộc trình soạn thảo","tr3_c0":"Staging PHP Backend","tr3_c1":"PHP 8.2 + PDO SQLite ngoại tuyến 100%","tr3_c2":"Chỉ trình xem văn bản thuần","tr3_c3":"Sửa trực tiếp lên bản sản xuất đang chạy","tr3_c4":"Cần cài đặt môi trường cục bộ","tr4_c0":"Git + Lưu trữ tĩnh","tr4_c1":"Git trực quan tích hợp + Unified Diff màu","tr4_c2":"Không tích hợp trình khách Git","tr4_c3":"Không có quy trình Git diff","tr4_c4":"Git đầy đủ","tr5_c0":"Giao thức &amp; Bảo mật","tr5_c1":"SFTP (Khóa SSH) + FTPS TLS 1.3 + KeyStore","tr5_c2":"Thường thiếu TLS 1.3 hoặc DevTools","tr5_c3":"Chỉ xác thực cookie trình duyệt","tr5_c4":"SSH đầy đủ","faq_lead":"Câu hỏi thường gặp về sửa website từ xa qua SFTP/FTPS, chống lỗi tải lên và push lên GitHub Pages.","faq1_q":"Tính năng xem trước trang web SFTP hoặc FTP từ xa hoạt động thế nào mà không cần tải cả máy chủ về?","faq1_a":"Khi bạn chạm Chạy trên tab `.html` hoặc `.php` từ xa đang mở, SuperCode kết xuất trang trong máy chủ xem trước nội bộ và tự động tải các tệp CSS, JS, phông chữ và hình ảnh tương đối được tham chiếu từ máy chủ từ xa theo nhu cầu.","faq2_q":"Điều gì xảy ra nếu điện thoại mất sóng di động đúng lúc đang lưu tệp `index.php` từ xa?","faq2_a":"Tệp sản xuất đang chạy của bạn vẫn nguyên vẹn! Cơ chế lưu nguyên tử 3 pha của SuperCode ghi vào tệp tạm trước, xác nhận dung lượng byte đã tải lên khớp 100%, rồi mới thực hiện đổi tên nguyên tử trên máy chủ.","faq3_q":"SuperCode có hỗ trợ shared hosting cPanel/Plesk cũng như máy chủ VPS Linux SSH không?","faq3_a":"Có. Dùng SFTP (với mật khẩu hoặc khóa riêng tư Ed25519/RSA) cho các máy chủ VPS đám mây như DigitalOcean, AWS Lightsail, Hetzner hay Linode, và dùng FTPS (TLS 1.3) hoặc FTP cho cPanel và shared hosting.","faq4_q":"Tôi có thể xây dựng và xuất bản trang HTML/CSS/JS tĩnh hoặc WASM lên GitHub Pages miễn phí không?","faq4_a":"Có. Soạn thảo và kiểm thử trang web ngoại tuyến trên máy chủ HTTP nội bộ của SuperCode, sau đó commit và push thẳng lên kho GitHub Pages của bạn bằng trình khách Git trực quan tích hợp sẵn.","cta_h2":"Bảo trì &amp; Xuất bản Website thực tế đầy tự tin ngay từ túi áo của bạn.","cta_desc":"Tải SuperCode IDE miễn phí trên Google Play &#8212; staging Web &amp; PHP hợp nhất, SFTP/FTPS nguyên tử và Git trực quan."},"sql_db_viewer":{"metaTitle":"Mở & Truy vấn tệp .db, .sqlite & .sqlite3 ngoại tuyến trên Android | SuperCode SQLite 3.54.1","metaDesc":"Mở, kiểm tra và chỉnh sửa tệp .db, .sqlite, .sqlite3, .db3 và .s3db ngoại tuyến 100% trên Android với SQLite 3.54.1. Tự động nhập CSV/TSV/JSON tối đa 8 MB và xuất theo 9 chế độ (Box, Markdown, JSON, CSV).","hero_tag":"SQLITE 3.54.1 NGOẠI TUYẾN &#183; .DB / .SQLITE / .DB3 &#183; 9 CHẾ ĐỘ XUẤT &#183; NHẬP CSV/JSON","hero_h1":"Mở, kiểm tra &amp; truy vấn tệp <span class=\"text-gradient\">.db, .sqlite &amp; .sqlite3</span> ngoại tuyến trên Android.","hero_desc":"Cần kiểm tra tệp nhị phân <code>.db</code> của ứng dụng, chuyển bản xuất <code>.csv</code> hoặc <code>.json</code> thô thành bảng quan hệ, hay chạy lệnh <code>UPDATE</code> thực thụ mà không tải dữ liệu riêng tư lên đám mây? SuperCode tích hợp sẵn <strong>SQLite 3.54.1 ngoại tuyến</strong> với trình kiểm tra schema 1 chạm và <strong>9 chế độ xuất định dạng</strong>.","dbv_s1":"SQLite ngoại tuyến","dbv_s2":"Box/MD/JSON/CSV","dbv_s3":"Nhập CSV/TSV/JSON","dbv_s4":".db/.sqlite/.db3+","wb_eyebrow":"TRÌNH KIỂM TRA .DB NHỊ PHÂN, TỰ ĐỘNG NHẬP CSV/JSON &amp; WORKBENCH 9 CHẾ ĐỘ XUẤT","sec_cap_title":"Hơn cả bảng dữ liệu chỉ đọc &#8212; Trạm làm việc SQLite ngoại tuyến thực thụ","sec_cap_lead":"Kiểm tra metadata nội bộ, chỉnh sửa bằng truy vấn tham số hóa, chuyển tệp phẳng thành bảng SQL và xuất báo cáo gọn gàng trong vài giây.","f1_title":"Trình kiểm tra 1 chạm cho .db, .sqlite, .sqlite3, .db3 &amp; .s3db","f1_desc":"Chạm vào bất kỳ cơ sở dữ liệu SQLite nhị phân nào trong Trình duyệt tệp của SuperCode hoặc mở từ bộ nhớ Android. SuperCode xác minh header nhị phân và tự động in thông số trang .dbinfo, số lượng .tables cùng toàn bộ .schema DDL.","f1_badge":".db &#183; .sqlite &#183; .sqlite3 &#183; .db3 &#183; .s3db","f2_title":"9 định dạng .mode chuyển đổi linh hoạt (Box, Markdown, JSON, CSV+)","f2_desc":"Định dạng kết quả cho mọi nhu cầu: lưới box Unicode sắc nét và bảng ASCII dễ đọc trên di động, bảng markdown cho tài liệu GitHub, mảng json cho API, csv/tabs cho trang tính, bản dump insert SQL hoặc thẻ line dọc.","f2_badge":"box &#183; table &#183; markdown &#183; json &#183; csv &#183; tabs &#183; insert &#183; line &#183; list","f3_title":"Lệnh .import --csv, --tsv &amp; --json không cần code mẫu","f3_desc":"Bỏ qua việc gõ CREATE TABLE rườm rà. Chạy .import --csv sales.csv sales hoặc .import --json users.json users (tối đa 8 MB) và SuperCode tự động suy luận tên cột để bạn JOIN và tổng hợp dữ liệu ngay lập tức.","f3_badge":"Tự tạo bảng &#183; CSV / TSV / JSON tối đa 8 MB","f4_title":"Tự động gắn cơ sở dữ liệu Workspace cho script .sql","f4_desc":"Đặt queries.sql cạnh tệp app.db trong dự án của bạn. SuperCode tự động nhận diện và gắn kết cơ sở dữ liệu workspace (hoặc theo lệnh .open tường minh) để các thay đổi schema và chỉnh sửa được lưu trực tiếp trên ổ đĩa.","f4_badge":"Lưu chỉnh sửa trên ổ đĩa &#183; Hỗ trợ đa DB với .open","f5_title":"Xuất tệp trực tiếp bằng .once vào thư mục dự án","f5_desc":"Kết hợp mọi chế độ xuất với .once &lt;filename&gt; &#8212; như .mode markdown + .once report.md hoặc .mode csv + .once clean_leads.csv &#8212; để ghi kết quả truy vấn thẳng vào tệp workspace sẵn sàng chia sẻ.","f5_badge":"Xuất với .once &#183; Tạo báo cáo &amp; bản dump tức thì","f6_title":"Bảo mật 100% trên thiết bị với SQLite 3.54.1","f6_desc":"Hồ sơ khách hàng, cơ sở dữ liệu ứng dụng di động ngoại tuyến và tệp CSV tài chính không bao giờ chạm tới máy chủ web bên ngoài. Mọi thao tác kiểm tra, tạo index, VACUUM và truy vấn đều chạy cục bộ trong SQLite 3.54.1 nhúng.","f6_badge":"Không tải lên Cloud &#183; Engine SQLite 3.54.1 ngoại tuyến","workflow_title":"Cách kiểm tra tệp `.db` hoặc truy vấn tập dữ liệu CSV/JSON trên Android","workflow_lead":"Mở cơ sở dữ liệu nhị phân có sẵn hoặc tạo mới từ tệp thô chỉ trong 4 bước nhanh chóng.","wf1_title":"Mở mọi tệp .db, .sqlite hoặc .sqlite3 chỉ với 1 chạm","wf1_desc":"Chọn tệp cơ sở dữ liệu trong workspace để xem ngay tóm tắt .dbinfo, danh sách .tables và schema CREATE TABLE / INDEX.","wf2_title":"Hoặc nhập tệp CSV, TSV &amp; JSON thô thành bảng","wf2_desc":"Chạy .import --csv data.csv my_table trong script .sql để tự động tạo và nạp cột quan hệ từ tệp phẳng tối đa 8 MB.","wf3_title":"Chạy truy vấn SQL &amp; chuyển đổi giữa 9 định dạng xuất","wf3_desc":"Viết lệnh SELECT, JOIN, UPDATE hoặc ALTER với gợi ý mã SQL từ AST và xem trước lưới Unicode box hoặc Markdown sắc nét.","wf4_title":"Xuất kết quả sạch trở lại Workspace của bạn","wf4_desc":"Dùng .once với chế độ csv, json, markdown hoặc insert để lưu kết quả phân tích gọn gàng trực tiếp vào thư mục dự án.","wf_foot_note":"Tích hợp SQLite 3.54.1 &#183; Không cần tài khoản &#183; Đầy đủ giao dịch ACID đọc/ghi","table_h2":"SuperCode SQLite 3.54.1 Studio vs. Trình xem `.db` Android cơ bản","snippet_p":"<strong>Trình xem &amp; chỉnh sửa cơ sở dữ liệu SQLite ngoại tuyến của SuperCode</strong> mở các tệp nhị phân .db, .sqlite, .sqlite3, .db3 và .s3db trên Android chỉ với một chạm bằng SQLite 3.54.1. Kiểm tra schema và metadata ngoại tuyến, tự động nhập tệp CSV, TSV và JSON tối đa 8 MB, đồng thời định dạng kết quả truy vấn qua 9 chế độ xuất linh hoạt.","table_caption":"MA TRẬN TRÌNH XEM .DB &amp; TRÌNH CHỈNH SỬA TRUY VẤN SQLITE ANDROID","th_0":"Khả năng SQLite","th_1":"SuperCode SQL Studio","th_2":"Trình xem DB Android cơ bản","th_3":"Ứng dụng bảng tính di động","th_4":"Trình xem SQLite trực tuyến","tr1_c0":"Phiên bản Engine","tr1_c1":"SQLite 3.54.1 ngoại tuyến (JSONB/FTS5 hiện đại)","tr1_c2":"SQLite 3.2x cũ của hệ điều hành Android","tr1_c3":"Không phải engine SQL quan hệ","tr1_c4":"Tải tệp .db riêng tư lên web","tr2_c0":"Kiểm tra Schema 1 chạm","tr2_c1":"Tự động .dbinfo + .tables + Full .schema DDL","tr2_c2":"Chỉ có menu thả xuống chọn bảng thủ công","tr2_c3":"Không thể mở .db/.db3 nhị phân","tr2_c4":"Giới hạn bộ nhớ trình duyệt","tr3_c0":"Định dạng đầu ra","tr3_c1":"9 chế độ (box, markdown, json, csv, insert+)","tr3_c2":"Lưới ô cố định chật hẹp","tr3_c3":"Chỉ hiển thị ô bảng tính","tr3_c4":"Bảng HTML cơ bản","tr4_c0":"Nhập CSV / TSV / JSON","tr4_c1":"Tự động tạo bảng SQL tối đa 8 MB","tr4_c2":"Hiếm có hoặc là tính năng trả phí","tr4_c3":"Chỉ mở một trang tính phẳng đơn lẻ","tr4_c4":"Yêu cầu tải lên qua internet","tr5_c0":"Tích hợp mã nguồn","tr5_c1":"Truy vấn cùng tệp .db từ Python, PHP, Java &amp; Lua","tr5_c2":"Trình xem độc lập biệt lập","tr5_c3":"Không có","tr5_c4":"Không có","faq_lead":"Giải đáp về việc mở tệp `.db`/`.sqlite3`, nhập tập dữ liệu CSV/JSON và xuất kết quả đã định dạng ngoại tuyến.","faq1_q":"SuperCode có thể mở trực tiếp những phần mở rộng tệp cơ sở dữ liệu SQLite nào?","faq1_a":"SuperCode nhận diện tệp `.db`, `.sqlite`, `.sqlite3`, `.db3` và `.s3db` chỉ với một chạm, tự động chạy kiểm tra ngoại tuyến `.dbinfo`, `.tables` và `.schema`.","faq2_q":"Tại sao SQLite 3.54.1 nhúng lại quan trọng hơn so với các trình xem SQLite Android thông thường?","faq2_a":"Phần lớn trình xem DB Android phụ thuộc vào bản SQLite hệ thống cũ của điện thoại, vốn thiếu bảng `STRICT`, `RETURNING`, `JSONB`, mệnh đề Window frame hiện đại và trình tối ưu truy vấn mới. SuperCode cung cấp SQLite 3.54.1 đồng nhất trên mọi thiết bị Android 8.0+.","faq3_q":"Tôi có thể nhập tệp `.csv` hoặc `.json` mà không cần viết `CREATE TABLE` trước không?","faq3_a":"Có! Chạy `.import --csv filename.csv tablename` (hoặc `--tsv` / `--json`) tối đa 8 MB &#8212; nếu `tablename` chưa tồn tại, SuperCode tự động tạo schema bảng từ tiêu đề CSV hoặc các khóa đối tượng JSON của bạn.","faq4_q":"Làm thế nào để xuất kết quả truy vấn SQL ra bảng Markdown hoặc tệp CSV?","faq4_a":"Thêm `.mode markdown` (hoặc `.mode csv` / `.mode json` / `.mode insert`) theo sau bởi `.once output.md` ngay phía trên lệnh `SELECT` của bạn và chạm Chạy &#8212; tệp sẽ xuất hiện ngay lập tức trong trình duyệt dự án.","cta_h2":"Mở, truy vấn &amp; xuất mọi tệp `.db` SQLite ngoại tuyến.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; SQLite 3.54.1, 9 định dạng xuất và nhập CSV/JSON tức thì."},"sql_analytics":{"metaTitle":"Ứng dụng luyện SQL ngoại tuyến cho Android — Window Functions, CTEs, JSONB & FTS5 | SuperCode","metaDesc":"Thực hành SQL phân tích thực tế và chinh phục phỏng vấn kỹ thuật ngoại tuyến trên Android. Chạy Window Functions (OVER, LAG, DENSE_RANK), Recursive CTEs, JSONB ->/->>, tìm kiếm FTS5 bm25() và MEDIAN/STDDEV với 6 mẫu SQL.","hero_tag":"WINDOW OVER() &#183; WITH RECURSIVE &#183; JSONB &#183; FTS5 BM25() &#183; MEDIAN &amp; STDDEV","hero_h1":"Thực hành <span class=\"text-gradient\">Window Functions, CTEs, JSONB &amp; FTS5</span> SQL ngoại tuyến trên Android.","hero_desc":"Vượt xa các ứng dụng thẻ ghi nhớ SQL điền vào chỗ trống. SuperCode mang đến cho chuyên viên phân tích dữ liệu, sinh viên CNTT và ứng viên phỏng vấn một <strong>engine SQL phân tích ngoại tuyến thực thụ</strong> hỗ trợ khung cửa sổ <strong><code>OVER (PARTITION BY ...)</code></strong>, cây <strong><code>WITH RECURSIVE</code></strong>, toán tử đường dẫn <strong>JSONB</strong>, tìm kiếm toàn văn <strong>FTS5 <code>bm25()</code></strong> cùng các hàm tích hợp <strong><code>MEDIAN()</code> / <code>PERCENTILE()</code> / <code>STDDEV()</code></strong>.","ana_s1":"Window Functions","ana_s2":"-&gt; / -&gt;&gt; + json_each","ana_s3":"Tìm kiếm bm25()","ana_s4":"Bài lab SQL mẫu","wb_eyebrow":"WORKBENCH PHÂN TÍCH WINDOW FUNCTIONS, TÌM KIẾM FTS5 &amp; JSONB","sec_cap_title":"Thiết kế cho phỏng vấn Data Engineering, bài lab DBMS đại học &amp; phân tích dữ liệu","sec_cap_lead":"Mọi cấu trúc SQL hiện đại thường gặp trong phỏng vấn dữ liệu FAANG/LeetCode &#8212; chạy mượt trong vài mili-giây ở chế độ máy bay.","f1_title":"Window Functions, LAG/LEAD &amp; khung cửa sổ trượt","f1_desc":"Giải quyết bài toán top-N theo nhóm, phân phiên (sessionization), cohort giữ chân người dùng và trung bình trượt 7 ngày ngoại tuyến bằng ROW_NUMBER(), DENSE_RANK(), NTILE(), LAG(), LEAD() và ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW.","f1_badge":"ROW_NUMBER &#183; DENSE_RANK &#183; LAG/LEAD &#183; Mệnh đề Frame","f2_title":"WITH RECURSIVE CTEs, STRICT &amp; RETURNING","f2_desc":"Tạo chuỗi ngày lịch, duyệt sơ đồ tổ chức phân cấp và cạnh đồ thị bằng WITH RECURSIVE, ép kiểu cột nghiêm ngặt với bảng STRICT và lấy lại các dòng vừa thay đổi chỉ trong một lượt qua UPSERT ... RETURNING *.","f2_badge":"WITH RECURSIVE &#183; Kiểu STRICT &#183; UPSERT RETURNING","f3_title":"JSON / JSONB gốc (-&gt;, -&gt;&gt;) &amp; json_each()","f3_desc":"Lưu trữ payload JSONB nhị phân và truy vấn thuộc tính lồng nhau bằng toán tử -&gt; và -&gt;&gt;. Trải phẳng mảng JSON thành dòng quan hệ với json_each() hoặc json_tree(), và tái tạo phản hồi JSON lồng nhau bằng json_group_object().","f3_badge":"JSONB nhị phân &#183; -&gt; / -&gt;&gt; &#183; Tách mảng json_each()","f4_title":"Tìm kiếm toàn văn FTS5 (bm25) &amp; không gian Geopoly","f4_desc":"Xây dựng bộ máy tìm kiếm nhanh ngoại tuyến bằng CREATE VIRTUAL TABLE ... USING fts5(...) với khớp logic/tiền tố, chấm điểm liên quan bm25() và highlight() &#8212; cùng chỉ mục đa chiều R*Tree và truy vấn đa giác Geopoly.","f4_badge":"FTS5 &#183; Xếp hạng bm25() &#183; highlight() &#183; R*Tree/Geopoly","f5_title":"MEDIAN(), PERCENTILE(), STDDEV() &amp; READ_STDIN()","f5_desc":"SQLite tiêu chuẩn thiếu các hàm tổng hợp thống kê &#8212; SuperCode bổ sung hàm gốc MEDIAN(), PERCENTILE(x, p) và STDDEV(), cùng biểu thức tương tác READ_STDIN('Prompt: ') để kiểm thử truy vấn tham số hóa linh hoạt.","f5_badge":"MEDIAN &#183; PERCENTILE &#183; STDDEV &#183; READ_STDIN() tương tác","f6_title":"6 mẫu SQL khởi đầu chạy được ngay &amp; xuất PDF A4","f6_desc":"Khởi chạy 6 mẫu lab SQL tích hợp sẵn (Joins, Window Analytics, Recursive CTEs, JSONB, FTS5, Triggers &amp; Views) không cần đăng nhập, và xuất bài tập SQL tô màu cú pháp thẳng ra PDF A4.","f6_badge":"6 bài lab SQL chọn lọc &#183; Không cần đăng nhập &#183; Xuất PDF A4","workflow_title":"Cách luyện phỏng vấn SQL &amp; phân tích dữ liệu ngoại tuyến trên điện thoại","workflow_lead":"Thành thạo SQL mọi lúc khi di chuyển với phản hồi bảng Unicode tức thì và hoàn toàn không phụ thuộc Wi-Fi.","wf1_title":"Chọn 1 trong 6 mẫu SQL phân tích tích hợp sẵn","wf1_desc":"Mở tệp .sql mới và chạm Mẫu (Templates) để tải schema mẫu chứa sẵn dữ liệu bán hàng, nhân sự, JSON hoặc FTS5 thực tế.","wf2_title":"Viết nhanh CTE phức tạp, Joins &amp; mệnh đề OVER()","wf2_desc":"Gõ dấu nháy đơn, ngoặc đơn, -&gt; và * dễ dàng trên thanh 21 phím cùng tính năng gợi ý từ khóa và định danh SQL ngoại tuyến.","wf3_title":"Kiểm tra bảng xếp hạng &amp; thời gian chạy dưới mili-giây","wf3_desc":"Chạm Chạy &#9654; để xem bảng Unicode box sắc nét, kiểm thử trường hợp biên trực tiếp với READ_STDIN() và tinh chỉnh các phân vùng cửa sổ.","wf4_title":"Lưu ghi chú học tập dạng Markdown hoặc PDF A4","wf4_desc":"Xuất kết quả truy vấn qua .mode markdown + .once notes.md hoặc in lời giải .sql ra PDF A4 để nộp bài trên trường.","wf_foot_note":"Sẵn sàng 100% chế độ máy bay &#183; 6 mẫu SQL tích hợp &#183; 8 giao diện Studio Sáng &amp; Tối","table_h2":"SuperCode SQL Analytics Studio vs. Ứng dụng đố vui SQL trò chơi hóa","snippet_p":"<strong>SuperCode Offline SQL Analytics &amp; Practice Studio</strong> trang bị cho người học Android và kỹ sư dữ liệu năng lực phân tích SQLite 3.54.1 hiện đại. Viết Window Functions, WITH RECURSIVE CTEs, bảng STRICT, mệnh đề UPSERT RETURNING, truy vấn đường dẫn JSONB, tìm kiếm toàn văn FTS5 bm25() và thống kê MEDIAN/PERCENTILE/STDDEV ngoại tuyến 100% với 6 mẫu khởi đầu tích hợp sẵn.","table_caption":"SO SÁNH CÔNG CỤ LUYỆN TẬP SQL &amp; PHỎNG VẤN TRÊN DI ĐỘNG","th_0":"Tính năng luyện SQL","th_1":"SuperCode SQL Studio","th_2":"Ứng dụng đố vui SQL trò chơi hóa","th_3":"Ứng dụng SQLite di động cũ","th_4":"LeetCode / DB Fiddles trực tuyến","tr1_c0":"Window Functions &amp; CTEs","tr1_c1":"Đầy đủ OVER(), LAG/LEAD &amp; WITH RECURSIVE","tr1_c2":"Trắc nghiệm điền vào chỗ trống","tr1_c3":"Thường lỗi với mệnh đề frame","tr1_c4":"Yêu cầu kết nối internet liên tục","tr2_c0":"Tìm kiếm JSONB &amp; FTS5","tr2_c1":"Gốc -&gt;/-&gt;&gt;, json_each &amp; FTS5 bm25()","tr2_c2":"Không hỗ trợ","tr2_c3":"Thiếu FTS5 / JSONB","tr2_c4":"Tùy thuộc vào web engine","tr3_c0":"Hàm tổng hợp thống kê","tr3_c1":"Tích hợp MEDIAN(), PERCENTILE(), STDDEV()","tr3_c2":"Chỉ có AVG / SUM cơ bản","tr3_c3":"Không có trong SQLite thuần","tr3_c4":"Phụ thuộc phương ngữ SQL","tr4_c0":"Tập dữ liệu tùy chỉnh","tr4_c1":"Tạo mọi Schema + Nhập CSV/JSON 8 MB","tr4_c2":"Khóa cứng trong các bảng mẫu nhỏ","tr4_c3":"Chỉ nhập lệnh INSERT thủ công","tr4_c4":"Mất phiên làm việc khi tải lại trang","tr5_c0":"Ngoại tuyến &amp; Gói cước","tr5_c1":"Nhân ngoại tuyến 100% + 6 mẫu miễn phí","tr5_c2":"Tường phí &amp; giới hạn tim mỗi ngày","tr5_c3":"Nhiều quảng cáo / giao diện lỗi thời","tr5_c4":"Không dùng được trên tàu xe/máy bay","faq_lead":"Các câu hỏi thường gặp từ người học SQL, sinh viên khoa học dữ liệu và ứng viên phỏng vấn backend.","faq1_q":"Tôi có thể luyện các bài toán SQL Window Function kiểu LeetCode (`DENSE_RANK`, `LAG`, tổng lũy kế) ngoại tuyến không?","faq1_a":"Có! Mọi hàm cửa sổ SQL chuẩn (`ROW_NUMBER`, `RANK`, `DENSE_RANK`, `NTILE`, `LAG`, `LEAD`, `FIRST_VALUE`, `LAST_VALUE`, `NTH_VALUE`) cùng các đặc tả khung `ROWS`/`RANGE`/`GROUPS` đều hoạt động ngoại tuyến 100%.","faq2_q":"SuperCode có hỗ trợ trực tiếp `MEDIAN()`, `PERCENTILE()` và `STDDEV()` trong SQL không?","faq2_a":"Có. Trong khi SQLite thuần thiếu các hàm tổng hợp thống kê, SuperCode đăng ký sẵn các hàm gốc `MEDIAN(col)`, `PERCENTILE(col, 95)` và `STDDEV(col)` để nhà phân tích dữ liệu tính toán phân phối chỉ trong một câu `SELECT`.","faq3_q":"`READ_STDIN()` hoạt động thế nào bên trong một truy vấn `.sql`?","faq3_a":"Hãy viết `WHERE department = READ_STDIN('Department name: ')` trong tệp `.sql` của bạn và chạm Chạy &#8212; SuperCode sẽ nhắc bạn nhập tương tác ngay trong console gắn liền để chạy lại truy vấn tham số hóa mà không cần sửa mã.","faq4_q":"Các mô-đun tìm kiếm toàn văn FTS5 và không gian R*Tree / Geopoly có được bật sẵn không?","faq4_a":"Có. Cả `USING fts5(...)` (bao gồm `bm25()`, `highlight()` và `snippet()`) lẫn tiện ích mở rộng không gian `USING rtree(...)` / Geopoly đều được biên dịch trực tiếp vào engine SQLite 3.54.1 ngoại tuyến của SuperCode.","cta_h2":"Làm chủ Window Functions, CTEs &amp; SQL phân tích ở bất cứ đâu.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; 6 mẫu SQL khởi đầu, SQLite 3.54.1 ngoại tuyến và kết quả bảng Unicode box sắc nét."},"sql_mysql_compat":{"metaTitle":"Chạy truy vấn MySQL & PostgreSQL trên Android — Tương thích ngoại tuyến + MySQL 8.0 | SuperCode","metaDesc":"Chạy bài tập MySQL và PostgreSQL ngay trên điện thoại Android. Thực thi AUTO_INCREMENT, SERIAL, ENUM, ILIKE, SHOW TABLES, DESCRIBE và hơn 50 hàm ngoại tuyến, cùng Cloud MySQL 8.0 cho stored procedure và DELIMITER.","hero_tag":"TƯƠNG THÍCH MYSQL/PG NGOẠI TUYẾN &#183; 50+ HÀM VÔ HƯỚNG &#183; CLOUD MYSQL 8.0 PROCEDURES","hero_h1":"Chạy bài tập <span class=\"text-gradient\">MySQL &amp; PostgreSQL</span> trên Android &#8212; Ngoại tuyến &amp; Cloud MySQL 8.0.","hero_desc":"Giáo trình đại học và hướng dẫn backend thường dạy <code>AUTO_INCREMENT</code>, <code>ENGINE=InnoDB</code>, <code>SHOW TABLES</code>, <code>DESCRIBE</code>, <code>SERIAL</code> và <code>ILIKE</code> &#8212; những cú pháp báo lỗi trên ứng dụng SQLite thuần. SuperCode chạy <strong>DDL MySQL &amp; PostgreSQL phổ biến cùng hơn 50 hàm ngoại tuyến</strong>, và chuyển mượt sang <strong>Cloud MySQL 8.0</strong> cho stored procedure dùng <code>DELIMITER</code>.","my_s1":"Lớp tương thích DDL ngoại tuyến","my_s2":"Hàm tích hợp sẵn","my_s3":"Cloud Procedures","my_s4":"Lệnh quản trị","wb_eyebrow":"WORKBENCH TƯƠNG THÍCH MYSQL/POSTGRES NGOẠI TUYẾN &amp; CLOUD MYSQL 8.0","sec_cap_title":"Mang cú pháp MySQL &amp; PostgreSQL chuẩn giáo trình lên điện thoại mượt mà","sec_cap_lead":"Ngừng việc phải viết lại thủ công từng dòng `AUTO_INCREMENT`, `DATE_FORMAT()` hay `DESCRIBE` chỉ để chạy thử bài tập ngoại tuyến.","f1_title":"Tương thích DDL MySQL &amp; PostgreSQL ngoại tuyến","f1_desc":"Dán script schema chứa INT PRIMARY KEY AUTO_INCREMENT, SERIAL, BIGSERIAL, UNSIGNED, ENUM('draft','live') hoặc ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 &#8212; SuperCode chuyển đổi gọn gàng để thực thi ngoại tuyến tức thì.","f1_badge":"AUTO_INCREMENT &#183; SERIAL &#183; ENUM &#183; ENGINE=InnoDB","f2_title":"SHOW TABLES, DESCRIBE, SHOW CREATE &amp; TRUNCATE","f2_desc":"Kiểm tra schema bằng đúng những lệnh được dạy trên giảng đường MySQL: SHOW TABLES, DESCRIBE users (hoặc DESC users), SHOW COLUMNS FROM orders, SHOW CREATE TABLE products và TRUNCATE TABLE logs đều chạy ngoại tuyến.","f2_badge":"SHOW TABLES &#183; DESCRIBE &#183; SHOW CREATE TABLE &#183; TRUNCATE","f3_title":"Hơn 50 hàm vô hướng MySQL &amp; Postgres tích hợp sẵn","f3_desc":"Thực thi DATE_FORMAT(), DATEDIFF(), NOW(), CURDATE(), CONCAT_WS(), LPAD(), RPAD(), REVERSE(), SUBSTRING_INDEX(), UUID(), MD5(), SHA256() và REGEXP_REPLACE() ngoại tuyến mà không cần biên dịch tiện ích mở rộng.","f3_badge":"Mã hóa &#183; Regex &#183; Ngày/Giờ &#183; Hàm chuỗi ngoại tuyến","f4_title":"Toán tử ILIKE &amp; lọc không phân biệt hoa thường chuẩn PostgreSQL","f4_desc":"Viết truy vấn PostgreSQL biểu cảm bằng khớp mẫu ILIKE, biểu thức chuẩn COALESCE/NULLIF/CASE, mệnh đề RETURNING và toán tử JSON -&gt; / -&gt;&gt; ngay trong workspace di động của bạn.","f4_badge":"ILIKE &#183; RETURNING &#183; Toán tử đường dẫn -&gt; / -&gt;&gt;","f5_title":"Tăng tốc Cloud MySQL 8.0 cho Stored Procedures","f5_desc":"Đang làm bài thực hành DBMS nâng cao yêu cầu DELIMITER //, CREATE PROCEDURE, CREATE FUNCTION, tham số IN/OUT/INOUT, con trỏ (cursor), CALL hoặc MySQL JSON_TABLE? Hãy chạy chúng trên engine Cloud MySQL 8.0 thực thụ.","f5_badge":"Cloud MySQL 8.0 &#183; DELIMITER &#183; CREATE PROCEDURE &#183; CALL","f6_title":"Định tuyến Dual-Engine thông minh &amp; tô màu cú pháp","f6_desc":"Soạn thảo mọi thứ trong một trình biên tập .sql thống nhất với gợi ý mã AST, 9 chế độ hiển thị kết quả, chẩn đoán lỗi SQL chính xác theo dòng và xuất PDF A4 gốc để nộp báo cáo thực hành.","f6_badge":".sql Studio thống nhất &#183; Chẩn đoán lỗi rõ ràng &#183; PDF A4","workflow_title":"Cách chạy script MySQL &amp; PostgreSQL trên Android","workflow_lead":"Luyện truy vấn hằng ngày ngoại tuyến, và gọi Cloud MySQL 8.0 bất cứ khi nào cần stored procedure.","wf1_title":"Dán hoặc viết Schema MySQL / PostgreSQL của bạn","wf1_desc":"Viết script CREATE TABLE chuẩn với AUTO_INCREMENT, SERIAL, ENUM hoặc ENGINE=InnoDB mà không phải dịch thủ công sang SQLite.","wf2_title":"Chạy truy vấn ngoại tuyến &amp; hơn 50 hàm tích hợp sẵn","wf2_desc":"Chạm Chạy &#9654; ngoại tuyến để thực thi SHOW TABLES, DESCRIBE, ILIKE, DATE_FORMAT(), CONCAT_WS(), SHA256() và JOIN nhiều bảng.","wf3_title":"Thực thi Stored Procedures trên Cloud MySQL 8.0","wf3_desc":"Khi script của bạn định nghĩa khối CREATE PROCEDURE, FUNCTION hoặc DELIMITER, chạy qua Cloud MySQL 8.0 và kiểm tra đầu ra của lệnh CALL.","wf4_title":"Xuất Schema &amp; bảng kết quả sạch đẹp cho lớp học","wf4_desc":"Định dạng kết quả ở chế độ box hoặc markdown và xuất báo cáo PDF A4 gọn gàng cho hệ thống LMS của trường.","wf_foot_note":"Lớp tương thích MySQL/Postgres ngoại tuyến + Cloud MySQL 8.0 thực thụ theo yêu cầu","table_h2":"SuperCode Hybrid MySQL/Postgres Studio vs. Các lựa chọn SQL di động khác","snippet_p":"<strong>Studio tương thích MySQL &amp; PostgreSQL của SuperCode</strong> giúp sinh viên và lập trình viên backend chạy bài tập SQL giáo trình ngay trên Android. Thực thi AUTO_INCREMENT, SERIAL, ENUM, ILIKE, SHOW TABLES, DESCRIBE cùng hơn 50 hàm mã hóa, regex và ngày tháng tích hợp ngoại tuyến, sau đó chuyển mượt sang Cloud MySQL 8.0 cho stored procedure, khối DELIMITER và JSON_TABLE.","table_caption":"MA TRẬN KHẢ NĂNG HỌC TẬP MYSQL &amp; POSTGRESQL TRÊN ANDROID","th_0":"Nhu cầu phương ngữ SQL","th_1":"SuperCode Hybrid SQL Studio","th_2":"Ứng dụng SQLite di động thuần","th_3":"Ứng dụng SSH / MySQL Client từ xa","th_4":"Trình biên dịch MySQL trên web","tr1_c0":"AUTO_INCREMENT &amp; SERIAL","tr1_c1":"Chạy ngoại tuyến liền mạch","tr1_c2":"Báo lỗi cú pháp ở AUTO_INCREMENT","tr1_c3":"Yêu cầu máy chủ DB từ xa đang chạy","tr1_c4":"Không chạy được khi mất mạng","tr2_c0":"SHOW TABLES &amp; DESCRIBE","tr2_c1":"Hỗ trợ ngoại tuyến gốc","tr2_c2":"Phải dùng lệnh PRAGMA thay thế","tr2_c3":"Chỉ chạy trực tuyến","tr2_c4":"Chỉ chạy trực tuyến","tr3_c0":"Hàm ngày tháng, Regex &amp; mã hóa","tr3_c1":"50+ hàm ngoại tuyến sẵn có (DATE_FORMAT, SHA256+)","tr3_c2":"Chỉ có vài hàm lõi tối thiểu","tr3_c3":"Phụ thuộc máy chủ từ xa","tr3_c4":"Bị giới hạn theo phiên","tr4_c0":"Stored Procedures / CALL","tr4_c1":"Engine Cloud MySQL 8.0 liền mạch","tr4_c2":"Không được hỗ trợ trong SQLite","tr4_c3":"Cần tự cài đặt máy chủ MySQL riêng","tr4_c4":"Thường chặn lệnh DELIMITER","tr5_c0":"Lưu trữ ngoại tuyến","tr5_c1":"Lưu cục bộ .db &amp; .sql trên điện thoại","tr5_c2":"Chỉ lưu cục bộ","tr5_c3":"Không có thực thi ngoại tuyến","tr5_c4":"Xóa sạch bảng sau khi hết phiên","faq_lead":"Giải đáp về chạy cú pháp MySQL và PostgreSQL ngoại tuyến so với stored procedure trên Cloud MySQL 8.0.","faq1_q":"Tôi có thể chạy script MySQL `CREATE TABLE ... AUTO_INCREMENT ENGINE=InnoDB` mà không cần internet không?","faq1_a":"Có! Lớp tương thích SQL ngoại tuyến của SuperCode tự động chuyển đổi các mệnh đề DDL MySQL và PostgreSQL phổ biến (`AUTO_INCREMENT`, `SERIAL`, `BIGSERIAL`, `UNSIGNED`, `ENUM`, `ENGINE=InnoDB`, `CHARSET`) để schema và truy vấn của bạn chạy ngoại tuyến trơn tru.","faq2_q":"`SHOW TABLES`, `DESCRIBE table_name` và `TRUNCATE TABLE` có chạy ngoại tuyến không?","faq2_a":"Có. Bạn không cần phải nhớ `.schema` hay `PRAGMA table_info(...)` khi học khóa MySQL &#8212; `SHOW TABLES`, `DESCRIBE` / `DESC`, `SHOW CREATE TABLE` và `TRUNCATE TABLE` hoạt động trực tiếp ngoại tuyến.","faq3_q":"Stored Procedures MySQL (`CREATE PROCEDURE` và `DELIMITER //`) chạy trên Android như thế nào?","faq3_a":"Vì các thủ tục `BEGIN ... END` và `DELIMITER` đòi hỏi engine thủ tục cấp máy chủ, SuperCode định tuyến các script đó liền mạch tới Cloud MySQL 8.0 và truyền trực tiếp tập kết quả `CALL` về console của bạn.","faq4_q":"Những hàm MySQL và PostgreSQL bổ sung nào khả dụng ngoại tuyến?","faq4_a":"Hơn 50 hàm vô hướng được tích hợp sẵn ngoại tuyến, bao gồm `DATE_FORMAT`, `DATEDIFF`, `NOW`, `CURDATE`, `CONCAT_WS`, `LPAD`, `RPAD`, `SUBSTRING_INDEX`, `ILIKE`, `REGEXP_REPLACE`, `UUID`, `MD5`, `SHA256`, `MEDIAN` và `STDDEV`.","cta_h2":"Chinh phục bài tập MySQL &amp; PostgreSQL ngay trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; tương thích MySQL/Postgres ngoại tuyến cùng thủ tục Cloud MySQL 8.0."},"sql_polyglot_db":{"metaTitle":"IDE SQLite đa ngôn ngữ trên Android — Truy vấn chung 1 tệp .db bằng SQL, Python, PHP, Java & Lua | SuperCode","metaDesc":"Xây dựng ứng dụng dùng cơ sở dữ liệu thật ngoại tuyến trên Android. Tạo dữ liệu app.db trong SQL Studio, rồi kết nối tới cùng tệp SQLite đó từ Python 3.11 sqlite3, PHP 8.2 PDO, Java 17 JDBC và Lua 5.4 — kèm chỉnh sửa tệp dump .sql nhiều GB.","hero_tag":"1 TỆP .DB DÙNG CHUNG &#183; SQL + PYTHON + PHP + JAVA + LUA &#183; TRÌNH SỬA DUMP .SQL CỠ GB","hero_h1":"Một tệp <code>.db</code> dùng chung cho <span class=\"text-gradient\">SQL, Python, PHP, Java 17 &amp; Lua</span> ngoại tuyến.","hero_desc":"Ứng dụng di động đơn ngôn ngữ cô lập dữ liệu trong sandbox riêng tư. Với SuperCode, hãy thiết kế và đánh chỉ mục <strong><code>app.db</code></strong> trong <strong>SQL Studio</strong>, rồi đọc ghi <strong>chính xác cùng cơ sở dữ liệu workspace đó ngoại tuyến</strong> từ <strong>Python 3.11 (<code>sqlite3</code>)</strong>, <strong>PHP 8.2 (<code>PDO</code>)</strong>, <strong>Java 17 (<code>jdbc:sqlite:</code>)</strong> và <strong>Lua 5.4 (<code>lsqlite3</code>)</strong> &#8212; hoặc kiểm tra các tệp dump <code>.sql</code> nhiều GB mà không bị sập.","poly_s1":"1 tệp .db chung","poly_s2":"Driver 0 cấu hình","poly_s3":"Trình sửa dump .sql","poly_s4":"Đồng bộ đĩa trực tiếp","wb_eyebrow":"CƠ SỞ DỮ LIỆU WORKSPACE ĐA NGÔN NGỮ: SQL + PYTHON + PHP + JAVA + LUA WORKBENCH","sec_cap_title":"Xây dựng kiến trúc đa dịch vụ hoàn chỉnh trong một thư mục dự án","sec_cap_lead":"Không cần tải driver, không đau đầu với classpath và không phải sao chép tệp thủ công giữa các ứng dụng di động riêng lẻ.","f1_title":"Tệp .db dùng chung &amp; kiểm tra trực tiếp trong SQL Studio","f1_desc":"Mọi runtime đều thao tác trực tiếp trên thư mục dự án thật của bạn. Chèn bản ghi từ Python scraper hoặc Java DAO, rồi chuyển sang tab .sql và chạy SELECT ở chế độ box để xác minh dữ liệu đã commit ngay lập tức.","f1_badge":"Thư mục dự án thống nhất &#183; Kiểm tra chéo tab tức thì","f2_title":"Python 3.11 sqlite3 &amp; Pandas read_sql_query()","f2_desc":"Chạy pipeline ETL, scraper BeautifulSoup hoặc bản thử nghiệm Flask ghi vào sqlite3.connect('app.db') &#8212; sau đó nạp bảng vào pandas.read_sql_query() để xuất biểu đồ Matplotlib thẳng ra workspace.","f2_badge":"sqlite3 Stdlib &#183; pandas.read_sql_query() &#183; Biểu đồ","f3_title":"Dashboard web PHP 8.2 new PDO('sqlite:app.db')","f3_desc":"Biến mọi tập dữ liệu SQLite thành ứng dụng web HTML5 + PHP 8.2 tương tác ngoại tuyến. Gửi biểu mẫu trình duyệt qua $_POST vào app.db bằng prepared statement và theo dõi thời gian HTTP trực tiếp trong Web DevTools.","f3_badge":"PHP 8.2 PDO &#183; CRUD toàn diện &#183; Localhost HTTP","f4_title":"Java 17 JDBC không cần Gradle &amp; Lua 5.4 lsqlite3 dưới 1 ms","f4_desc":"Viết DriverManager.getConnection(\"jdbc:sqlite:app.db\") trong Java 17 với org.sqlite.JDBC đã sẵn trên classpath ngoại tuyến, hoặc viết script trạng thái game/tự động hóa trong Lua 5.4 qua require('lsqlite3').","f4_badge":"Java 17 jdbc:sqlite &#183; Lua 5.4 lsqlite3 &#183; 0 thiết lập","f5_title":"Xem &amp; chỉnh sửa bằng Regex các tệp dump .sql nhiều GB","f5_desc":"Vừa tải bản sao lưu mysqldump hoặc pg_dump .sql nặng 2 GB? Trình sửa tệp lớn phân trang theo đĩa của SuperCode mở mượt mà tệp .sql nhiều GB với hơn 30 bảng mã, Tìm/Thay thế regex và nhảy tới byte-offset.","f5_badge":"Dump .sql GB+ phân trang đĩa &#183; Tìm/Thay thế Regex","f6_title":"Quản lý phiên bản schema bằng Git &amp; đồng bộ qua SFTP","f6_desc":"Theo dõi migration schema.sql cùng mã nguồn Python, PHP và Java trong Visual Git, hoặc pull/push cơ sở dữ liệu SQLite production và bản sao lưu .sql qua SFTP và FTPS.","f6_badge":"Theo dõi schema Visual Git &#183; Đồng bộ sao lưu .db SFTP","workflow_title":"Cách xây dựng ứng dụng SQLite đa ngôn ngữ trên Android","workflow_lead":"Một thư mục dự án, một tệp `app.db` và năm runtime ngoại tuyến phối hợp nhịp nhàng.","wf1_title":"Thiết kế bảng, chỉ mục &amp; dữ liệu mẫu trong SQL Studio","wf1_desc":"Tạo app.db ngay trong thư mục dự án bằng DDL SQLite 3.54.1, kiểu STRICT, chỉ mục FTS5 hoặc nhập CSV/JSON.","wf2_title":"Nạp hoặc xử lý bản ghi qua Python, Java hoặc Lua","wf2_desc":"Kết nối tới 'app.db' qua Python sqlite3, Java jdbc:sqlite:app.db hoặc Lua lsqlite3 mà không cần cài thêm driver.","wf3_title":"Phục vụ giao diện Web động qua PHP PDO Localhost","wf3_desc":"Mở dashboard.php và truy vấn new PDO('sqlite:app.db') để hiển thị biểu đồ thích ứng và biểu mẫu CRUD trên trình duyệt 3 khung nhìn.","wf4_title":"Kiểm tra bảng trực tiếp hoặc dọn bản sao lưu .sql cỡ GB","wf4_desc":"Chạm vào app.db bất kỳ lúc nào để kiểm tra trạng thái với 9 chế độ hiển thị, hoặc mở tệp dump .sql nhiều GB trong trình sửa tệp lớn phân trang đĩa.","wf_foot_note":"Không cần cấu hình driver &#183; Python 3.11 + PHP 8.2 + Java 17 + Lua 5.4 + SQLite 3.54.1 ngoại tuyến","table_h2":"SuperCode Polyglot SQLite Studio so với IDE di động đơn ngôn ngữ","snippet_p":"<strong>SuperCode Polyglot SQLite Studio</strong> kết nối năm runtime lập trình ngoại tuyến vào một tệp .db dùng chung trong workspace trên Android. Thiết kế schema và chỉ mục trong SQL Studio, rồi truy vấn ngoại tuyến chính xác cùng tệp chuẩn ACID đó từ Python 3.11 sqlite3, PHP 8.2 PDO, Java 17 JDBC và Lua 5.4 lsqlite3 đồng thời kiểm tra các tệp dump .sql nhiều GB.","table_caption":"PHÁT TRIỂN ỨNG DỤNG SQLITE ĐA NGÔN NGỮ TRÊN ANDROID","th_0":"Quy trình lập trình","th_1":"SuperCode Polyglot IDE","th_2":"IDE di động đơn ngôn ngữ","th_3":"Ứng dụng xem DB độc lập","th_4":"IDE trình duyệt đám mây","tr1_c0":"Tệp .db dùng chung","tr1_c1":"SQL + Python + PHP + Java 17 + Lua ngoại tuyến","tr1_c2":"Khóa cứng chỉ 1 ngôn ngữ","tr1_c3":"Chỉ xem bảng SQL (không có mã ứng dụng)","tr1_c4":"Cần VM đám mây trả phí","tr2_c0":"Java SQLite JDBC","tr2_c1":"Tích hợp sẵn jdbc:sqlite: (0 Maven/Gradle)","tr2_c2":"Tự tìm .jar &amp; chỉnh cờ thủ công","tr2_c3":"Không hỗ trợ","tr2_c4":"Khởi động container chậm","tr3_c0":"PHP PDO + Giao diện Web","tr3_c1":"PHP 8.2 PDO ngoại tuyến + HTTP 3 khung nhìn","tr3_c2":"Không kèm máy chủ PHP","tr3_c3":"Không hỗ trợ","tr3_c4":"Cần kết nối mạng","tr4_c0":"Python + Khoa học dữ liệu","tr4_c1":"sqlite3 + Pandas read_sql + Matplotlib","tr4_c2":"Không có SQL IDE hay xem trước PHP","tr4_c3":"Không hỗ trợ","tr4_c4":"Lưu trữ tạm thời","tr5_c0":"Dump .sql nhiều GB","tr5_c1":"Trình sửa GB phân trang đĩa + Thay thế Regex","tr5_c2":"Sập khi tải văn bản &gt;50 MB","tr5_c3":"Không sửa được dump .sql thô","tr5_c4":"Tab trình duyệt bị treo","faq_lead":"Câu hỏi thường gặp về dùng chung tệp `.db` giữa các ngôn ngữ và chỉnh sửa tệp dump `.sql` cực lớn trên Android.","faq1_q":"Tôi có cần tải tệp `.jar` để dùng `jdbc:sqlite:app.db` trong Java 17 không?","faq1_a":"Không! SuperCode tích hợp sẵn driver SQLite JDBC trực tiếp trên classpath Java 17 ngoại tuyến &#8212; chỉ cần viết `DriverManager.getConnection(\"jdbc:sqlite:app.db\")` và nhấn Chạy.","faq2_q":"Python, PHP, Java và Lua có thực sự đọc ghi cùng một tệp `app.db` được không?","faq2_a":"Có. Miễn là các tệp `.sql`, `.py`, `.php`, `.java` và `.lua` nằm trong cùng thư mục workspace (hoặc trỏ tới cùng đường dẫn tương đối), tất cả đều đọc và commit giao dịch ACID vào chính xác cùng tệp `app.db` trên đĩa.","faq3_q":"Làm sao dùng SQLite bên trong script Lua 5.4 trên SuperCode?","faq3_a":"Gọi `local sqlite3 = require('lsqlite3')` và `local db = sqlite3.open('app.db')`. `lsqlite3` được tích hợp sẵn ngay trong runtime Lua 5.4 ngoại tuyến của SuperCode với thời gian khởi chạy dưới 1 mili-giây.","faq4_q":"SuperCode có mở được tệp dump cơ sở dữ liệu `.sql` hơn 1 GB mà không làm sập điện thoại không?","faq4_a":"Có. Trình sửa tệp lớn cỡ GB của SuperCode truyền tải các tệp `.sql`, `.csv` và `.log` khổng lồ trực tiếp theo trang đĩa thay vì nạp toàn bộ vào RAM &#8212; đầy đủ tìm/thay thế regex và nhận diện bảng mã.","cta_h2":"Kết nối SQL, Python, PHP, Java &amp; Lua vào một cơ sở dữ liệu ngoại tuyến.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; SQLite studio đa ngôn ngữ, driver tích hợp sẵn và chỉnh sửa .sql cỡ GB."},"lua_game_oop":{"metaTitle":"Ứng dụng viết script game Lua trên Android — Metatable, Coroutine & chuẩn bị Love2D/Luau | SuperCode","metaDesc":"Thực hành viết script game Lua ngoại tuyến trên Android trong ~400µs. Thử nghiệm lớp OOP metatable, máy trạng thái coroutine và logic Luau/Roblox & Love2D dạng mô-đun với hoàn thành AST phân biệt . và : cùng 8 script mẫu.","hero_tag":"LUA 5.4.7 GỐC &#183; OOP METATABLE &#183; MÁY TRẠNG THÁI COROUTINE &#183; ~400&#181;s","hero_h1":"Thử nghiệm <span class=\"text-gradient\">Logic Game Lua, Metatable &amp; Coroutine</span> ngoại tuyến trên Android.","hero_desc":"Làm chủ các mẫu lập trình phía sau <strong>Roblox (Luau), Love2D, Defold và Solar2D</strong> bất cứ khi nào có cảm hứng. Thực thi <strong>Lua 5.4.7 gốc</strong> chỉ trong <strong>~400 micro-giây</strong> với đầy đủ <strong>OOP metatable</strong>, <strong>coroutine</strong> hợp tác và <strong>tự hoàn thành AST phân biệt phương thức <code>.</code> và <code>:</code></strong>.","lgo_s1":"Lua 5.4.7 gốc","lgo_s2":"OOP Metatable","lgo_s3":"FSM Coroutine","lgo_s4":"Bảo vệ AST phương thức","wb_eyebrow":"WORKBENCH TƯƠNG TÁC CHO LOGIC GAME LUA, OOP METATABLE &amp; COROUTINE","sec_cap_title":"Dành cho lập trình viên game, modder &amp; người thử nghiệm indie","sec_cap_lead":"Các engine game máy tính nặng hàng gigabyte, nhưng 90% kỹ thuật gameplay nằm ở kiến trúc table gọn sạch, metatable, máy trạng thái và toán học.","f1_title":"Lớp OOP Metatable &amp; nạp chồng toán tử Vector","f1_desc":"Xây dựng các lớp Entity, Inventory và Vec2 tái sử dụng bằng __index, __newindex, hàm tạo __call, trình gỡ lỗi __tostring và phương thức toán học (__add, __sub, __mul, __eq) chuẩn như các Lua engine thực tế.","f1_badge":"__index &#183; __call &#183; __add &#183; Phân cấp lớp tùy chỉnh","f2_title":"Máy trạng thái Coroutine hợp tác (coroutine.*)","f2_desc":"Viết script cho nhiều pha boss, cây hội thoại, dòng thời gian cắt cảnh và bộ đếm hồi chiêu gọn gàng bằng coroutine.create, resume, yield, wrap và status &#8212; không cần chuỗi callback rối rắm.","f2_badge":"coroutine.yield &#183; Hội thoại &amp; AI FSM &#183; Chạy ~400&#181;s","f3_title":"Tự hoàn thành AST ngoại tuyến phân biệt (. với :)","f3_desc":"Nhầm lẫn giữa hàm dấu chấm (Vec2.new) và phương thức dấu hai chấm (player:take_damage()) là lỗi Lua phổ biến nhất. Engine AST ngoại tuyến của SuperCode phân biệt rõ . và : trên cả stdlib Lua lẫn table của bạn.","f3_badge":"Chống lỗi nil self &#183; AST hiểu Table","f4_title":"Thư mục Entity-Component dạng mô-đun qua require()","f4_desc":"Tổ chức toán học chiến đấu, bảng vật phẩm rơi và hành vi kẻ địch thành các mô-đun riêng trong thư mục src/, core/ và modules/ &#8212; mô phỏng chuẩn bố cục Roblox ModuleScripts và Love2D.","f4_badge":"require() đa tệp &#183; Phân giải tab chưa lưu","f5_title":"8 script khởi đầu chạy được ngay, gồm adventure.lua","f5_desc":"Mở bộ chọn mẫu tích hợp sẵn để mổ xẻ ngay adventure.lua, metatables.lua, tables.lua và guess.lua khi ngoại tuyến, kèm lời nhắc nhập theo lượt tương tác io.read() trực tiếp.","f5_badge":"adventure.lua &#183; metatables.lua &#183; io.read() trực tiếp","f6_title":"Chống vòng lặp game vô hạn &amp; đo bộ nhớ VM","f6_desc":"Đang thử nghiệm vòng lặp while game.running do trên điện thoại? Giới hạn bộ nhớ VM cô lập và thời gian chờ thực thi sẽ dừng các tick chạy quá đà an toàn, đồng thời hiển thị thông số micro-giây và kilobyte.","f6_badge":"Bảo vệ vòng lặp &#183; Đo &#181;s &#183; Đo KB bộ nhớ VM","workflow_title":"Cách luyện tập logic lập trình game ngay trên điện thoại","workflow_lead":"Xây dựng, kiểm thử và tinh chỉnh hệ thống gameplay cốt lõi khi di chuyển, rồi đưa thẳng các mô-đun Lua thuần vào engine PC.","wf1_title":"Mở script game mẫu có sẵn hoặc tạo mô-đun Entity","wf1_desc":"Bắt đầu từ adventure.lua hoặc metatables.lua, hoặc sắp xếp các tệp mới như player.lua, combat.lua và main.lua trong workspace.","wf2_title":"Viết lớp Metatable với gợi ý phương thức dấu hai chấm","wf2_desc":"Gõ : trên thực thể để nhận gợi ý phương thức gắn self và chạm Định dạng để căn chỉnh các hàm tạo table lồng nhau.","wf3_title":"Mô phỏng lượt chơi &amp; nhịp Coroutine trong ~400 micro-giây","wf3_desc":"Chạm Chạy &#9654; để kiểm tra công thức sát thương, tỉ lệ rơi đồ RNG và lựa chọn người chơi io.read() trực tiếp với phản hồi dưới 1 mili-giây.","wf4_title":"Đồng bộ mô-đun Lua thuần sang Love2D, Defold hoặc GitHub","wf4_desc":"Commit các mô-đun gameplay tách biệt qua Visual Git để dự án Love2D, Defold hoặc Luau trên máy tính kéo về gọn gàng.","wf_foot_note":"Lua 5.4.7 ngoại tuyến 100% &#183; 8 mẫu khởi đầu &#183; Thanh ký hiệu Lua 21 phím","table_h2":"SuperCode Lua Game Lab so với trình sửa Lua di động thông thường","snippet_p":"<strong>SuperCode Lua Game Scripting Studio</strong> giúp lập trình viên Android thử nghiệm hệ thống gameplay ngoại tuyến bằng Lua 5.4.7 gốc với tốc độ khởi chạy dưới 1 mili-giây. Luyện tập lớp OOP metatable, nạp chồng toán tử vector và máy trạng thái coroutine cho Roblox/Luau và Love2D nhờ hoàn thành AST phân biệt dấu chấm với dấu hai chấm, <code>require()</code> đa tệp và tám script Lua tích hợp sẵn.","table_caption":"SO SÁNH VIẾT SCRIPT GAME LUA &amp; THỰC HÀNH TRÊN DI ĐỘNG","th_0":"Nhu cầu viết script game","th_1":"SuperCode Lua 5.4 Studio","th_2":"Ứng dụng Lua di động cũ","th_3":"REPL Lua trực tuyến","th_4":"Chỉ dùng Game Engine PC","tr1_c0":"Metatable &amp; Coroutine","tr1_c1":"Đầy đủ OOP Lua 5.4.7 + coroutine.yield (~400 &#181;s)","tr1_c2":"Tập con Lua 5.2 lỗi thời","tr1_c3":"Độ trễ mạng mỗi lần chạy","tr1_c4":"Engine đầy đủ","tr2_c0":"An toàn dấu chấm vs hai chấm","tr2_c1":"AST ngoại tuyến phân biệt hàm . và phương thức :","tr2_c2":"Chỉ văn bản thuần","tr2_c3":"Không có hoàn thành AST","tr2_c4":"Plugin máy tính","tr3_c0":"ModuleScripts dạng mô-đun","tr3_c1":"require() đa thư mục + điều hướng main.lua thông minh","tr3_c2":"Nháp đơn tệp","tr3_c3":"Một hộp đoạn mã","tr3_c4":"Được hỗ trợ","tr4_c0":"Kiểm thử theo lượt tương tác","tr4_c1":"Console io.read() trực tiếp + 8 mẫu có sẵn","tr4_c2":"Đầu vào tĩnh hoặc không có","tr4_c3":"Không hỗ trợ stdin tương tác","tr4_c4":"Cửa sổ GUI","tr5_c0":"Sẵn sàng ngoại tuyến khi di chuyển","tr5_c1":"100% chế độ máy bay + đồng bộ Visual Git","tr5_c2":"Tùy ứng dụng / khóa quảng cáo","tr5_c3":"Lỗi khi không có Wi-Fi","tr5_c4":"Không bỏ túi được","faq_lead":"Giải đáp về học Lua cho Roblox/Luau, Love2D, metatable và coroutine trên Android.","faq1_q":"Thực hành Lua 5.4 trong SuperCode có áp dụng thẳng cho Roblox (Luau) và Love2D không?","faq1_a":"Có! Các table Lua cốt lõi, closure, phạm vi từ vựng, metatable (`__index`, `__add`), coroutine, toán học và script mô-đun `return M` chính là nền tảng chung của Roblox Luau, Love2D, Defold, Solar2D và addon World of Warcraft / Garry's Mod.","faq2_q":"SuperCode có dựng trực tiếp thế giới 3D Roblox hoặc cửa sổ OpenGL Love2D không?","faq2_a":"SuperCode tập trung vào logic gameplay nhanh, tách biệt, hệ thống RPG hướng dữ liệu, lưu trữ kho đồ bằng SQLite/JSON và thử nghiệm thuật toán trong console gốc &#8212; giúp bạn hoàn thiện các module script cốt lõi mọi nơi rồi đồng bộ sang trình kết xuất trên PC qua Git.","faq3_q":"SuperCode giúp tránh lỗi phương thức `.` so với `:` trong OOP Lua như thế nào?","faq3_a":"Khi bạn gõ `entity:` thay vì `Entity.`, trình hoàn thành AST ngoại tuyến của SuperCode lọc gợi ý theo ngữ cảnh để hiển thị ngay các phương thức thực thể dùng dấu hai chấm tách biệt với hàm mô-đun tĩnh.","faq4_q":"Ứng dụng có kèm script game mẫu để học ngoại tuyến không?","faq4_a":"Có. Tám mẫu Lua chạy được ngay &#8212; gồm `adventure.lua`, `guess.lua`, `metatables.lua` và `tables.lua` &#8212; được tích hợp sẵn và hoạt động 100% ngoại tuyến.","cta_h2":"Nâng tầm kỹ năng viết script game Lua ở bất kỳ đâu.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; Lua 5.4.7 gốc ~400&#181;s, OOP metatable, coroutine và 8 mẫu tích hợp sẵn."},"lua_ext_mods":{"metaTitle":"Lua cjson, lsqlite3, lfs & socket.http trên Android — 11+ mô-đun tích hợp sẵn | SuperCode","metaDesc":"Gọi require cjson, lsqlite3, lfs (LuaFileSystem), crypto/sha2, regex, base64, socket.http và inspect ngoại tuyến trên Android không cần thiết lập luarocks trong IDE Lua 5.4.7 gốc của SuperCode.","hero_tag":"KHÔNG CẦN LUAROCKS &#183; CJSON &#183; LSQLITE3 &#183; LFS &#183; CRYPTO &#183; SOCKET.HTTP","hero_h1":"11+ <span class=\"text-gradient\">Mô-đun Lua ngoại tuyến tích hợp sẵn</span> qua <code>require()</code>.","hero_desc":"Lua chuẩn vốn tối giản, còn biên dịch C rock trên điện thoại lại nổi tiếng rắc rối. SuperCode đóng gói sẵn <strong><code>cjson</code>, <code>lsqlite3</code>, <code>lfs</code>, <code>crypto</code>, <code>regex</code>, <code>base64</code>, <code>socket.http</code> và <code>inspect</code></strong> trực tiếp vào runtime <strong>Lua 5.4.7</strong> ngoại tuyến.","lem_s1":"Mô-đun tích hợp sẵn","lem_s2":"&amp; định dạng đẹp dkjson","lem_s3":"lsqlite3 :named","lem_s4":"Không cần build C","wb_eyebrow":"WORKBENCH MÔ-ĐUN MỞ RỘNG LUA ĐẦY ĐỦ PIN TÍCH HỢP","sec_cap_title":"Viết script Lua thực chiến vượt xa thư viện chuẩn cơ bản","sec_cap_lead":"Xây dựng REST client, trình sửa tệp lưu SQLite cục bộ, công cụ xử lý thư mục hàng loạt và script JSON kiểu OpenResty/Redis mà không cần đụng trình biên dịch C.","f1_title":"Tuần tự hóa cjson &amp; dkjson dùng ngay lập tức","f1_desc":"Phân tích và xuất payload JSON tức thì khi ngoại tuyến bằng require('cjson') hoặc require('dkjson') &#8212; kèm cjson.encode_pretty() cho tệp cấu hình dễ đọc và gỡ lỗi API.","f1_badge":"cjson.encode &#183; encode_pretty &#183; cjson.decode","f2_title":"Bộ máy cơ sở dữ liệu nhúng lsqlite3 / sqlite3","f2_desc":"Mở :memory: hoặc tệp .db bền vững trong workspace qua require('lsqlite3') hoặc require('sqlite3'). Hỗ trợ prepared statement, liên kết tham số :named, trình lặp db:nrows() và giao dịch ACID.","f2_badge":"lsqlite3 &#183; Đồng bộ .db bền vững &#183; Dùng chung SQL IDE","f3_title":"Tự động hóa thư mục &amp; tệp với LuaFileSystem (lfs)","f3_desc":"Tự động đổi tên hàng loạt và kiểm tra tài nguyên trong thư mục dự án bằng require('lfs') &#8212; gồm lfs.dir(), lfs.mkdir(), lfs.currentdir() và kiểm tra kích thước/thời gian với lfs.attributes().","f3_badge":"lfs.dir &#183; lfs.mkdir &#183; lfs.attributes","f4_title":"Bộ bảo mật crypto, sha2, md5 &amp; base64","f4_desc":"Ký payload webhook, kiểm tra checksum tệp và tạo ID duy nhất ngoại tuyến với SHA-256, SHA-512, MD5, mã băm HMAC có khóa, crypto.uuid() cùng mã hóa/giải mã Base64 chuẩn RFC.","f4_badge":"SHA-256/512 &#183; HMAC &#183; crypto.uuid() &#183; base64","f5_title":"socket.http, Regex đầy đủ &amp; Table inspect","f5_desc":"Kiểm thử REST API thực tế qua require('socket.http'), chạy biểu thức chính quy PCRE/POSIX đầy đủ khi pattern của Lua chưa đủ qua require('regex') và in gọn table lồng nhau với require('inspect').","f5_badge":"socket.http &#183; Regex đầy đủ &#183; inspect(table)","f6_title":"Định tuyến Cloud Lua cho C-Rock lpeg &amp; luv","f6_desc":"Đang dùng bộ phân tích PEG trong lpeg hay vòng lặp bất đồng bộ libuv trong luv? SuperCode tự động đóng gói các mô-đun dự án lên runtime Cloud Lua và ánh xạ traceback 1:1 về trình soạn thảo.","f6_badge":"Cloud lpeg &amp; luv &#183; Tự động đóng gói đa tệp","workflow_title":"Cách xây dựng công cụ Lua hướng dữ liệu trên Android","workflow_lead":"Kết hợp JSON, SQLite, tự động hóa hệ thống tệp và kiểm tra SQL trong một workspace thống nhất.","wf1_title":"Nhập trực tiếp bất kỳ mô-đun nào trong 11+ mô-đun tích hợp","wf1_desc":"Viết chuẩn require('cjson'), require('lsqlite3'), require('lfs') hoặc require('crypto') ở đầu tệp .lua &#8212; không cần bước cài đặt nào.","wf2_title":"Đọc &amp; ghi tệp JSON và SQLite thật ngoại tuyến","wf2_desc":"Thực thi script trong vài mili-giây; mọi tệp .db, .json hoặc .log ghi xuống đĩa đều đồng bộ thẳng vào cây dự án Explorer.","wf3_title":"Kiểm tra chéo cơ sở dữ liệu lsqlite3 trực quan","wf3_desc":"Chạm vào tệp .db vừa tạo trong Explorer để duyệt schema và chạy truy vấn phân tích trong SQL Studio 9 chế độ của SuperCode.","wf4_title":"Mở rộng sang C-Rock chuyên dụng mượt mà khi cần","wf4_desc":"Nếu script nhập các C rock ngoài như lpeg hoặc luv, hãy chạy trực tuyến với tính năng tự động đóng gói mô-đun đa tệp.","wf_foot_note":"Mở rộng ngoại tuyến đóng gói sẵn &#183; 0 lỗi gcc/luarocks &#183; Đồng bộ workspace dùng chung","table_h2":"Mô-đun Lua tích hợp của SuperCode so với Lua gốc &amp; bản port di động","snippet_p":"<strong>SuperCode IDE cho Android</strong> cung cấp Lua 5.4.7 gốc với hơn mười một mô-đun mở rộng tích hợp sẵn ngoại tuyến qua <code>require()</code> &#8212; gồm <code>cjson</code>, <code>dkjson</code>, <code>lsqlite3</code>, <code>lfs</code> (LuaFileSystem), <code>crypto</code>, <code>sha2</code>, <code>md5</code>, <code>base64</code>, <code>regex</code>, <code>socket.http</code> và <code>inspect</code> &#8212; loại bỏ việc biên dịch luarocks trên di động.","table_caption":"MA TRẬN HỖ TRỢ MÔ-ĐUN MỞ RỘNG LUA TRÊN ANDROID","th_0":"Mô-đun mở rộng","th_1":"Tên require()","th_2":"Trạng thái ngoại tuyến SuperCode","th_3":"Lua CLI gốc","th_4":"Ứng dụng Java LuaJ","tr1_c0":"JSON nhanh + In đẹp","tr1_c1":"cjson / dkjson","tr1_c2":"Tích hợp sẵn ngoại tuyến","tr1_c3":"Cần luarocks gcc","tr1_c4":"Thiếu","tr2_c0":"SQLite 3 nhúng","tr2_c1":"lsqlite3 / sqlite3","tr2_c2":"Tích hợp sẵn ngoại tuyến (:named + .db)","tr2_c3":"Cần tệp header C","tr2_c4":"Thiếu","tr3_c0":"Hệ thống tệp &amp; Thư mục","tr3_c1":"lfs","tr3_c2":"Tích hợp sẵn ngoại tuyến (dir/mkdir/attr)","tr3_c3":"Cần luarocks","tr3_c4":"Thiếu","tr4_c0":"Băm, HMAC &amp; UUID","tr4_c1":"crypto / sha2 / md5 / base64","tr4_c2":"Tích hợp sẵn ngoại tuyến","tr4_c3":"Thư viện C ngoài","tr4_c4":"Thiếu","tr5_c0":"HTTP, Regex &amp; Gỡ lỗi","tr5_c1":"socket.http / regex / inspect","tr5_c2":"Tích hợp sẵn (+ Cloud lpeg/luv)","tr5_c3":"Biên dịch thủ công","tr5_c4":"Thiếu","faq_lead":"Câu hỏi thường gặp về sử dụng cjson, lsqlite3, LuaFileSystem và các mô-đun luarocks trên Android.","faq1_q":"Tôi có cần cài luarocks hay trình biên dịch C để dùng `cjson`, `lsqlite3` hoặc `lfs` không?","faq1_a":"Không. Toàn bộ 11+ bí danh mở rộng cốt lõi (`cjson`, `dkjson`, `lsqlite3`, `sqlite3`, `lfs`, `crypto`, `sha2`, `md5`, `base64`, `regex`, `socket.http` và `inspect`) đều được tích hợp trực tiếp vào SuperCode và chạy ngay qua `require()`.","faq2_q":"`lsqlite3` có thể dùng chung cùng tệp `.db` với Python, PHP hoặc SQL IDE của SuperCode không?","faq2_a":"Có! Cơ sở dữ liệu `.db` do `lsqlite3` tạo trong thư mục dự án là tệp nhị phân SQLite 3 chuẩn, có thể truy vấn trực tiếp trong SQL Studio của SuperCode, Python `sqlite3`, PHP `PDO` hoặc Java JDBC.","faq3_q":"`cjson` có hỗ trợ in định dạng đẹp cho tệp cấu hình không?","faq3_a":"Có. Ngoài `cjson.encode()` và `cjson.decode()` chuẩn, SuperCode còn cung cấp `cjson.encode_pretty()` giúp bạn kiểm tra hoặc lưu JSON thụt lề gọn gàng khi ngoại tuyến.","faq4_q":"Điều gì xảy ra nếu script của tôi yêu cầu `lpeg` hoặc `luv`?","faq4_a":"Khi có kết nối internet, SuperCode nhận diện các lệnh nhập C-rock gốc chuyên dụng như `lpeg` hoặc `luv` và tự động định tuyến dự án đa tệp của bạn sang môi trường Cloud Lua.","cta_h2":"Chạy Lua 5.4 đầy đủ tiện ích ngay trên Android.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; Lua 5.4.7 gốc tích hợp sẵn cjson, lsqlite3, lfs, crypto và socket.http."},"lua_54_modern":{"metaTitle":"Trình thông dịch Lua 5.4 cho Android — Bitwise 64-bit,  & require() đa tệp | SuperCode","metaDesc":"Nâng cấp từ các app Lua 5.2 cũ lên Lua 5.4.7 native thực thụ trên Android. Chạy toán tử bitwise 64-bit, chia lấy nguyên //, biến  & , string.pack, utf8 và require() đa thư mục.","hero_tag":"LUA 5.4.7 NATIVE THỰC THỤ &#183; BITWISE 64-BIT &#183; &lt;CONST&gt; &amp; &lt;CLOSE&gt; &#183; ĐA THƯ MỤC","hero_h1":"<span class=\"text-gradient\">Lua 5.4.7 Native thực thụ</span> vs. các app di động Lua 5.2 lỗi thời.","hero_desc":"Phần lớn ứng dụng Lua trên Google Play bọc nhân Java LuaJ 5.2 bị bỏ rơi và báo lỗi với cú pháp hiện đại. SuperCode chạy <strong>Lua 5.4.7 native thực thụ</strong> ngoại tuyến &#8212; mở khóa <strong>toán tử bitwise 64-bit (<code>&amp; | ~ &lt;&lt; &gt;&gt;</code>)</strong>, <strong>chia lấy nguyên <code>//</code></strong>, <strong><code>&lt;const&gt;</code> / <code>&lt;close&gt;</code></strong> và <strong><code>require()</code> đa thư mục</strong> không cần cấu hình.","l54_s1":"VM Native thực thụ","l54_s2":"// &amp; Toán tử Bitwise","l54_s3":"RAII theo phạm vi","l54_s4":"package.path tự động","wb_eyebrow":"BÀN LÀM VIỆC CÚ PHÁP LUA 5.4.7 HIỆN ĐẠI &amp; GÓI ĐA THƯ MỤC","sec_cap_title":"Mọi cải tiến ngôn ngữ Lua 5.3 &amp; 5.4 hiện đại, chạy ngoại tuyến","sec_cap_lead":"Viết mã Lua 5.4 chuẩn xác theo tài liệu gốc và gói đa thư mục mà không phải lách lỗi cú pháp.","f1_title":"Số nguyên 64-bit Native, phép chia // &amp; toán tử Bitwise","f1_desc":"Thao tác trực tiếp bitmask, cờ, hàm băm và tọa độ tile bằng &amp;, |, ~ (XOR/NOT), &lt;&lt;, &gt;&gt; và phép chia lấy nguyên // &#8212; dựa trên số nguyên có dấu 64-bit chính xác thay vì xấp xỉ dấu phẩy động.","f1_badge":"&amp; | ~ &lt;&lt; &gt;&gt; &#183; // Chia lấy nguyên &#183; math.type() 64-bit","f2_title":"&lt;const&gt; khi biên dịch &amp; dọn dẹp &lt;close&gt; theo phạm vi","f2_desc":"Ép biến cục bộ bất biến tại thời điểm biên dịch với &lt;const&gt; và gắn metamethod __close tất định qua &lt;close&gt; để tệp đang mở, khóa và câu lệnh SQLite tự giải phóng khi thoát phạm vi hoặc gặp lỗi.","f2_badge":"local x &lt;const&gt; &#183; local f &lt;close&gt; &#183; __close RAII","f3_title":"string.pack / unpack nhị phân &amp; utf8 tích hợp sẵn","f3_desc":"Mã hóa và giải mã cấu trúc nhị phân với chỉ định endianness qua string.pack, string.unpack, string.packsize, đồng thời duyệt chuỗi Unicode đa ngôn ngữ an toàn với utf8.codes, utf8.len và utf8.char.","f3_badge":"string.pack / unpack &#183; utf8.codes &#183; GC thế hệ mới","f4_title":"Tự động nối package.path qua 6 thư mục con chuẩn","f4_desc":"SuperCode tự động cấu hình package.path cho thư mục gốc cùng src/, lib/, modules/, core/ và utils/ (cả ?.lua lẫn ?/init.lua), phân giải cả tệp đã lưu lẫn tab chưa lưu trong trình soạn thảo.","f4_badge":"src/ &#183; lib/ &#183; modules/ &#183; core/ &#183; utils/ &#183; ?/init.lua","f5_title":"Phân giải điểm vào main.lua / init.lua thông minh","f5_desc":"Đang sửa module con kết thúc bằng return M? Chạm Chạy &#9654; ngay trong core/codec.lua mà không cần đổi tab &#8212; SuperCode tự phát hiện tệp main.lua hoặc init.lua của dự án và khởi chạy mượt mà.","f5_badge":"Chạy từ mọi tab module &#183; Tự nhận diện điểm vào","f6_title":"Traceback bấm nhảy 1:1 &amp; GC thế hệ mới","f6_desc":"Chạy trên bộ thu gom rác thế hệ mới độ trễ thấp của Lua 5.4.7 với thời gian khởi động dưới 1 ms và stack trace bấm để nhảy thẳng tới đúng tệp và dòng lỗi trên toàn dự án đa thư mục.","f6_badge":"Stack Trace xuyên module &#183; Khởi động ~400&#181;s","workflow_title":"Cách tổ chức gói Lua 5.4 đa tệp trên Android","workflow_lead":"Mở rộng gọn gàng từ một script đơn lẻ thành mã nguồn Lua đa thư mục có cấu trúc.","wf1_title":"Tạo thư mục module (src/, lib/, core/)","wf1_desc":"Đặt điểm vào tại main.lua và sắp xếp các module dùng lại vào src/, lib/, modules/, core/ hoặc utils/ &#8212; không cần chỉnh LUA_PATH.","wf2_title":"Viết mã Bitwise 64-bit, &lt;const&gt; và &lt;close&gt;","wf2_desc":"Dùng các cú pháp hiện đại //, &gt;&gt;, &amp;, &lt;const&gt; và &lt;close&gt; cùng kiểm tra cú pháp Error Radar trực tiếp và định dạng Lua ngoại tuyến.","wf3_title":"Chạy từ main.lua hoặc ngay trong module con","wf3_desc":"Nhấn Chạy ngay cả khi đang sửa tệp thư viện return M &#8212; bộ phân giải điểm vào tự động chạy main.lua bao gồm cả chỉnh sửa chưa lưu.","wf4_title":"Quản lý phiên bản &amp; phát hành gói Lua sạch đẹp","wf4_desc":"Xem diff trên toàn cây module trong Visual Git và push thẳng lên GitHub, GitLab hoặc máy chủ SFTP từ xa.","wf_foot_note":"Runtime C Lua 5.4.7 thực thụ &#183; Hỗ trợ ?.lua &amp; ?/init.lua &#183; Đồng bộ bộ đệm chưa lưu","table_h2":"Lua 5.4.7 Native (SuperCode) vs. App Android LuaJ 5.2 cũ","snippet_p":"<strong>Trình thông dịch Lua 5.4.7 Native của SuperCode</strong> vượt trội các app Android LuaJ 5.2 cũ nhờ thực thi Lua 5.4 64-bit thực thụ ngoại tuyến chỉ trong ~400 micro-giây. Hỗ trợ chia lấy nguyên (<code>//</code>), toán tử bitwise, biến <code>&lt;const&gt;</code> và <code>&lt;close&gt;</code>, <code>string.pack</code>, <code>utf8</code> và định tuyến điểm vào <code>require()</code> đa thư mục.","table_caption":"SO SÁNH LUA 5.4.7 VÀ CÁC TRÌNH THÔNG DỊCH LUA DI ĐỘNG CŨ","th_0":"Tính năng ngôn ngữ","th_1":"SuperCode (Lua 5.4.7 Native)","th_2":"App Android Java LuaJ 5.2","th_3":"Bản demo web đơn tệp","th_4":"Lua 5.4 trên Desktop","tr1_c0":"Bitwise &amp; phép chia //","tr1_c1":"&amp; | ~ &lt;&lt; &gt;&gt; Native và // 64-bit","tr1_c2":"Lỗi cú pháp (Cần bit32)","tr1_c3":"Chỉ chạy trực tuyến","tr1_c4":"Có hỗ trợ","tr2_c0":"&lt;const&gt; &amp; &lt;close&gt; RAII","tr2_c1":"Hỗ trợ đầy đủ Lua 5.4 (__close)","tr2_c2":"Không hỗ trợ","tr2_c3":"Tùy trang web","tr2_c4":"Có hỗ trợ","tr3_c0":"Pack nhị phân &amp; UTF-8","tr3_c1":"Tích hợp string.pack/unpack + utf8","tr3_c2":"Thiếu","tr3_c3":"Chỉ chạy trực tuyến","tr3_c4":"Có hỗ trợ","tr4_c0":"require() đa thư mục","tr4_c1":"Tự nối root, src/, lib/, core/, utils/","tr4_c2":"Lỗi với đường dẫn tương đối","tr4_c3":"Chỉ một tệp duy nhất","tr4_c4":"Chỉnh LUA_PATH thủ công","tr5_c0":"Chạy trong tab module","tr5_c1":"Tự phân giải main.lua / init.lua","tr5_c2":"Chạy module &amp; không in gì","tr5_c3":"Không áp dụng","tr5_c4":"Chỉ định CLI thủ công","faq_lead":"Giải đáp về toán tử bitwise Lua 5.4, biến `&lt;close&gt;` và `require()` đa thư mục trên Android.","faq1_q":"Vì sao `//` và `&amp;` báo lỗi cú pháp trên các app Lua Android khác?","faq1_a":"Nhiều app Lua di động cũ dựa trên LuaJ, một bản port Java bị đóng băng quanh Lua 5.2 trước khi số nguyên 64-bit native, phép chia lấy nguyên `//` và toán tử bitwise ra mắt ở Lua 5.3/5.4. SuperCode chạy Lua 5.4.7 native thực thụ.","faq2_q":"`require()` đa tệp hoạt động thế nào mà không cần đặt `LUA_PATH`?","faq2_a":"SuperCode tự động cấu hình `package.path` để tìm trong thư mục gốc dự án cùng `src/`, `lib/`, `modules/`, `core/` và `utils/` cho cả `?.lua` lẫn `?/init.lua` &#8212; đồng thời đồng bộ các tab đang mở chưa lưu trước khi chạy.","faq3_q":"Chuyện gì xảy ra nếu tôi nhấn Chạy khi đang sửa `lib/math_ext.lua` thay vì `main.lua`?","faq3_a":"Nếu tệp hiện tại trả về một bảng module (`return M`) và thư mục gốc có `main.lua` hoặc `init.lua`, SuperCode tự động chạy script điểm vào để bạn không phải chuyển tab qua lại.","faq4_q":"`&lt;close&gt;` trong Lua 5.4 có hoạt động khi có lỗi phát sinh trong khối lệnh không?","faq4_a":"Có. Giống hệt Lua 5.4.7 chuẩn trên desktop, mọi biến cục bộ gắn `&lt;close&gt;` sẽ gọi metamethod `__close(self, err)` trong metatable một cách tất định dù khối thoát bình thường hay bung ra qua `error()`.","cta_h2":"Trải nghiệm Lua 5.4.7 Native thực thụ trên Android.","cta_desc":"Cài đặt miễn phí SuperCode IDE trên Google Play &#8212; toán tử bitwise 64-bit, biến &lt;close&gt; và require() đa thư mục mượt mà."},"lua_learn":{"metaTitle":"Học Lua ngoại tuyến trên Android — App lập trình Lua miễn phí, Formatter & xuất PDF | SuperCode","metaDesc":"Học lập trình Lua ngoại tuyến trên điện thoại hoặc máy tính bảng Android. Không cần đăng nhập — gồm 8 ví dụ Lua chạy ngay, nhập io.read() trực tiếp, gợi ý . vs :, format Lua 1 chạm và xuất PDF A4.","hero_tag":"KHÔNG ĐĂNG NHẬP &#183; 100% NGOẠI TUYẾN &#183; 8 VÍ DỤ LUA &#183; FORMATTER &amp; PDF A4","hero_h1":"Học <span class=\"text-gradient\">lập trình Lua ngoại tuyến</span> ngay trên điện thoại Android.","hero_desc":"Bỏ qua màn hình đăng nhập, hàng đợi đám mây và mấy trò đố điền chỗ trống. Viết mã <strong>Lua 5.4</strong> thực thụ ở <strong>chế độ máy bay</strong> với <strong>8 ví dụ chạy ngay</strong>, hộp nhắc <strong><code>io.read()</code></strong> trực tiếp, <strong>trình định dạng Lua 1 chạm</strong> và <strong>xuất PDF A4 tô màu cú pháp</strong>.","lln_s1":"Chạy ở chế độ máy bay","lln_s2":"Script mẫu sẵn có","lln_s3":"Trình định dạng Lua","lln_s4":"Xuất bài tập PDF","wb_eyebrow":"BÀN HỌC LUA NGOẠI TUYẾN THÂN THIỆN CHO NGƯỜI MỚI BẮT ĐẦU","sec_cap_title":"Mọi thứ người tự học &amp; sinh viên cần để làm chủ Lua","sec_cap_lead":"Lua nổi tiếng với cú pháp sạch sẽ, dễ đọc &#8212; và SuperCode giúp việc gõ, định dạng và gỡ lỗi Lua trên màn hình cảm ứng trở nên tự nhiên.","f1_title":"Thực thi tức thì ở chế độ máy bay, không cần đăng nhập","f1_desc":"Mở SuperCode và chạy lệnh print('Hello, Lua!') đầu tiên chưa tới 1 giây &#8212; không tạo tài khoản, không cần mạng và phản hồi ~400 micro-giây mỗi lần chạm Chạy &#9654;.","f1_badge":"Không cần đăng ký &#183; Dùng tốt trên chuyến bay &amp; tàu xe","f2_title":"8 ví dụ Lua chạy được tích hợp sẵn trên thanh công cụ","f2_desc":"Khám phá mẫu thực hành gồm biến, vòng lặp, trò chơi đoán số (guess.lua), bảng hợp nhất (tables.lua), closure, metatable OOP (metatables.lua) và game phiêu lưu chữ (adventure.lua).","f2_badge":"guess.lua &#183; tables.lua &#183; metatables.lua &#183; adventure.lua","f3_title":"Console io.read() tương tác cho bài tập thực tế","f3_desc":"Xây dựng máy tính, trắc nghiệm và menu RPG tạm dừng gọn gàng để chờ người dùng nhập trực tiếp qua io.read('*l') và tonumber() trong console chia đôi màn hình có thể thu phóng.","f3_badge":"Nhập Stdin trực tiếp &#183; Thu phóng cỡ chữ Console","f4_title":"Định dạng khối lệnh &amp; bảng Lua ngoại tuyến 1 chạm","f4_desc":"Các khối if/then/elseif/end lồng nhau và bảng Lua nhiều dòng dễ rối trên màn hình nhỏ. Chạm Định dạng 1 lần để tự thụt lề hàm, vòng lặp, repeat/until và bảng {} ngoại tuyến.","f4_badge":"Formatter Lua 100% ngoại tuyến &#183; Thụt lề chuẩn đẹp","f5_title":"Error Radar &amp; hàng phím ký tự Lua chuyên dụng","f5_desc":"Phát hiện sớm lỗi thiếu end hoặc then với dấu báo Error Radar theo thời gian thực, và gõ nhanh toán tử Lua (~=, .., #, --, {}, []) chỉ một chạm qua thanh ký tự vuốt lên.","f5_badge":"~= &#183; .. &#183; # &#183; Bật/tắt chú thích -- &#183; Error Radar","f6_title":"Xuất PDF A4 tô màu cú pháp native","f6_desc":"Cần nộp bài tập lập trình hay lưu tài liệu ôn thi? Xuất thẳng mọi script .lua ra PDF A4 chữ đơn cách sắc nét ngoại tuyến và xem trước ngay trong trình đọc PDF tích hợp của SuperCode.","f6_badge":"Lưu dạng .pdf &#183; 8 giao diện sáng &amp; tối bảo vệ mắt","workflow_title":"Bắt đầu lập trình Lua trên Android dưới 60 giây","workflow_lead":"Không cần cấu hình, tải SDK hay gõ lệnh terminal.","wf1_title":"Mở mẫu có sẵn hoặc tạo tệp hello.lua","wf1_desc":"Tải một trong 8 ví dụ Lua tích hợp để xem cách bảng và hàm hoạt động, hoặc tạo tệp .lua mới tinh.","wf2_title":"Gõ nhanh với ~=, .. và gợi ý hoàn thành bảng","wf2_desc":"Dùng thanh ký tự 21 phím và gợi ý AST ngoại tuyến cho string./table./math. để viết mã sạch không lỗi chính tả.","wf3_title":"Chạy ngoại tuyến &amp; thử nhập liệu io.read() trực tiếp","wf3_desc":"Chạm Chạy &#9654; để xem kết quả tức thì, trả lời lời nhắc console trực tiếp và xem gợi ý lỗi kèm số dòng rõ ràng nếu gặp sự cố.","wf4_title":"Tự định dạng &amp; xuất ghi chú học tập PDF A4","wf4_desc":"Chạm Định dạng để căn chỉnh thụt lề khối mã, rồi xuất PDF A4 tô màu cú pháp hoặc đẩy tiến độ lên GitHub.","wf_foot_note":"Ứng dụng nhẹ 40.2 MB &#183; 8 giao diện Studio chuẩn quang học &#183; 32 ngôn ngữ giao diện","table_h2":"SuperCode vs. App trắc nghiệm &amp; trình sửa văn bản Lua thuần","snippet_p":"<strong>SuperCode</strong> là ứng dụng học lập trình Lua ngoại tuyến nhẹ, thân thiện cho người mới trên Android mà không cần đăng nhập. Ứng dụng kết hợp trình thông dịch Lua 5.4.7 native và console <code>io.read()</code> trực tiếp với 8 script mẫu chạy ngay, chẩn đoán Error Radar, định dạng mã Lua ngoại tuyến 1 chạm và xuất bài tập PDF A4 native.","table_caption":"HỌC LUA TRÊN ANDROID: SO SÁNH TÍNH NĂNG","th_0":"Tính năng học tập","th_1":"SuperCode Lua Studio","th_2":"App đố vui game hóa","th_3":"Trình sửa văn bản thuần","th_4":"Web Lua Playground","tr1_c0":"Thực thi ngoại tuyến","tr1_c1":"Lua 5.4.7 Native 100% ngoại tuyến (~400 &#181;s)","tr1_c2":"Bị khóa sau màn đăng nhập/mạng","tr1_c3":"Không thể chạy script","tr1_c4":"Cần kết nối Internet","tr2_c0":"Nhập liệu tương tác","tr2_c1":"Console chia màn hình io.read() trực tiếp","tr2_c2":"Chạm chọn trắc nghiệm","tr2_c3":"Không có","tr2_c4":"Tĩnh hoặc hay lỗi","tr3_c0":"Làm đẹp mã nguồn","tr3_c1":"Formatter khối &amp; bảng Lua ngoại tuyến 1 chạm","tr3_c2":"Không áp dụng","tr3_c3":"Gõ dấu cách thủ công","tr3_c4":"Hiếm khi có sẵn","tr4_c0":"Bài tập &amp; ghi chú","tr4_c1":"Tích hợp xuất PDF A4 đơn cách + Trình xem","tr4_c2":"Không có","tr4_c3":"Chia sẻ văn bản thuần","tr4_c4":"Chỉ in từ trình duyệt","tr5_c0":"Khả năng mở rộng","tr5_c1":"11+ Module (cjson/SQLite), Đa tệp &amp; Git","tr5_c2":"Dừng ở cú pháp cơ bản","tr5_c3":"Không có runtime","tr5_c4":"Không hỗ trợ tệp cục bộ","faq_lead":"Câu hỏi từ người mới và sinh viên học Lua ngoại tuyến trên Android.","faq1_q":"Lua có phải ngôn ngữ lập trình đầu tiên tốt để học trên điện thoại không?","faq1_a":"Có! Lua chỉ có 22 từ khóa dành riêng và dùng các từ tiếng Anh tự nhiên như `function`, `then`, `and`, `or` và `end` thay cho nhiều dấu câu nặng nề &#8212; giúp đọc và gõ trên di động cực kỳ nhanh.","faq2_q":"SuperCode có hoạt động hoàn toàn ngoại tuyến mà không cần tạo tài khoản không?","faq2_a":"100% có. Không hề có màn hình đăng nhập; nhân Lua 5.4.7 native, 8 mẫu khởi đầu, tự hoàn thành AST, trình định dạng Lua và xuất PDF A4 đều chạy ngoại tuyến ở chế độ máy bay.","faq3_q":"Làm sao gõ nhanh `~=` (khác) và `..` (nối chuỗi) trên Android?","faq3_a":"Thanh lập trình cảm ứng của SuperCode nằm ngay phía trên bàn phím với các toán tử Lua chuyên dụng, dấu ngoặc, phím thụt lề và nút bật/tắt chú thích `--` để bạn không phải mò vào màn hình ký tự phụ.","faq4_q":"Tôi có thể phát triển từ script cơ bản lên game đa tệp hoặc công cụ SQLite trong cùng ứng dụng không?","faq4_a":"Có. Bất cứ khi nào sẵn sàng, bạn có thể tách dự án qua nhiều thư mục với `require()`, dùng module `cjson` và `lsqlite3` tích hợp sẵn và push kho mã qua Visual Git.","cta_h2":"Viết script Lua đầu tiên ngoại tuyến ngay hôm nay.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; không đăng ký, 8 mẫu Lua, định dạng ngoại tuyến và xuất PDF."},"sh_noroot_runner":{"metaTitle":"Chạy script Shell .sh trên Android không cần Root — Không lỗi Permission Denied | SuperCode","metaDesc":"Thực thi script Linux .sh và .bash trực tiếp trong thư mục bộ nhớ dùng chung Android mà không cần root hay gặp lỗi 'chmod +x: Permission denied'. Hỗ trợ set -euo pipefail, getopts, read -p và source đa script.","hero_tag":"KHÔNG CẦN ROOT &#183; KHÔNG PERMISSION DENIED &#183; ĐỒNG BỘ $PWD &#183; READ STDIN TRỰC TIẾP","hero_h1":"Chạy <span class=\"text-gradient\">script Shell <code>.sh</code> trên Android không cần Root</span> hay lỗi <code>chmod</code>.","hero_desc":"Việc chạy <code>./script.sh</code> trên bộ nhớ trong Android thường thất bại với lỗi <strong><code>Permission denied</code></strong> do phân vùng gắn cờ <code>noexec</code> của hệ điều hành. SuperCode thực thi gọn gàng các script <strong><code>.sh</code>, <code>.bash</code>, <code>.zsh</code> và <code>.ksh</code></strong> không cần root đồng thời neo <strong><code>$PWD</code></strong> về đúng thư mục thật của bạn.","snr_s1":"Không lỗi chmod","snr_s2":"Đồng bộ thư mục thật","snr_s3":"Console Stdin trực tiếp","snr_s4":"Số dòng lỗi 1:1","wb_eyebrow":"BÀN CHẠY SCRIPT .SH ANDROID KHÔNG CẦN ROOT","sec_cap_title":"Vì sao app Terminal thông thường thất bại trên `/sdcard` &#8212; và cách SuperCode giải quyết","sec_cap_lead":"Soạn script trong các thư mục dự án dùng chung tiện lợi, truyền cờ CLI dễ dàng và chạy an toàn mà không phải root máy.","f1_title":"Vượt qua rào cản noexec của bộ nhớ dùng chung an toàn (Không Root)","f1_desc":"Android gắn /storage/emulated/0 và Downloads với cờ noexec, chặn chmod +x và ./script.sh. SuperCode bắc cầu thực thi bên trong sandbox sạch không cần root trong khi đồng bộ nguyên vẹn các tệp workspace của bạn.","f1_badge":"Không Root &#183; Chạy ngay trong thư mục dự án dùng chung","f2_title":"set -euo pipefail, trap, getopts &amp; phép tính số học","f2_desc":"Viết script tự động hóa nghiêm ngặt với cờ bắt lỗi (set -euo pipefail), hook dọn dẹp trap EXIT/ERR, vòng lặp cờ getopts, phép tính (( count++ )), hàm và mẫu heredoc &lt;&lt;EOF.","f2_badge":"set -euo pipefail &#183; trap &#183; getopts &#183; &lt;&lt;EOF","f3_title":"Chỉ thị CLI # @args &amp; nhập liệu read -p tương tác","f3_desc":"Kiểm thử tham số vị trí ($1, $@) mà không phải gõ lại lệnh bọc ngoài bằng cách thêm # @args --env prod ở đầu script, và trả lời lời nhắc read -r -p trực tiếp trong console chia đôi.","f3_badge":"Cờ # @args &#183; read -p Stdin trực tiếp &#183; 6 mẫu có sẵn","f4_title":"Liên kết source đa tệp &amp; phân giải điểm vào main.sh","f4_desc":"Tách hàm ghi log và biến cấu hình dùng chung vào lib/common.sh qua lệnh source hoặc dấu chấm (.). Nhấn Chạy trong tệp phụ trợ sẽ tự động phân giải và chạy main.sh hoặc run.sh.","f4_badge":"source ./lib.sh &#183; Tự định tuyến main.sh / run.sh","f5_title":"Chẩn đoán $LINENO 1:1 &amp; nút Dừng cây tiến trình","f5_desc":"Lỗi cú pháp Shell và dòng thoát khác 0 ánh xạ 1:1 về đúng tệp script đang mở, còn bộ giám sát cây tiến trình 120 giây cho phép ngắt gọn subshell chạy lạc chỉ bằng một chạm.","f5_badge":"Ánh xạ chính xác dòng lỗi &#183; Ngắt Subshell sạch sẽ","f6_title":"Formatter Shell ngoại tuyến 1 chạm &amp; gợi ý mở rộng biến","f6_desc":"Tự động thụt lề các khối if/elif/fi, case/esac và while/done lồng nhau ngoại tuyến chỉ với một chạm, kết hợp gợi ý AST mở rộng tham số ${var:-default} và phím ký tự nhanh | &amp;&amp; &gt;&amp;2.","f6_badge":"Formatter .sh ngoại tuyến &#183; AST ${var:-default}","workflow_title":"Cách sửa &amp; chạy script `.sh` trên Android không cần Root","workflow_lead":"Đi từ tệp `.sh` vừa tải về tới thực thi gọn gàng chỉ trong bốn chạm.","wf1_title":"Mở mọi script `.sh` trong bộ nhớ dùng chung hoặc Workspace","wf1_desc":"Mở thư mục trong Downloads hoặc Documents &#8212; không cần chép script vào thư mục riêng tư ẩn của app hay chạy chmod.","wf2_title":"Định dạng khối lệnh &amp; đặt tham số CLI tùy chọn","wf2_desc":"Chạm Định dạng để làm gọn thụt lề và tùy chọn thêm dòng chú thích `# @args` nhằm truyền các cờ `$1` / `getopts`.","wf3_title":"Chạy ngoại tuyến với read Stdin trực tiếp &amp; đồng bộ tệp","wf3_desc":"Chạm Chạy &#9654; để thực thi ngay, trả lời lời nhắc `read` tương tác và thấy các tệp đầu ra tự đồng bộ ngược về Explorer.","wf4_title":"Đẩy script đã kiểm chứng lên máy chủ Linux hoặc Git","wf4_desc":"Sau khi kiểm thử cục bộ, tải lên qua SFTP (giữ nguyên bit thực thi 0755) hoặc commit vào kho mã qua Visual Git.","wf_foot_note":"Hỗ trợ .sh &#183; .bash &#183; .zsh &#183; .ksh &#183; 6 mẫu Shell khởi đầu tích hợp sẵn","table_h2":"Trình chạy `.sh` không Root của SuperCode vs. cách lách Terminal thô","snippet_p":"<strong>Trình chạy Shell Script của SuperCode</strong> thực thi các script Linux <code>.sh</code>, <code>.bash</code>, <code>.zsh</code> và <code>.ksh</code> trên Android mà không cần quyền root hay dính lỗi <code>Permission denied</code> ở bộ nhớ dùng chung. Hỗ trợ đồng bộ <code>$PWD</code> thư mục dự án thật, <code>set -euo pipefail</code>, <code>getopts</code>, <code>read -p</code> stdin trực tiếp, <code>source</code> đa script và định dạng ngoại tuyến.","table_caption":"SO SÁNH CÁCH CHẠY SCRIPT SHELL .SH TRÊN ANDROID","th_0":"Yêu cầu Shell","th_1":"SuperCode .sh Studio","th_2":"CLI thô trên bộ nhớ chung","th_3":"App chạy script cần Root","th_4":"Trình sửa mã thuần túy","tr1_c0":"Có cần Root?","tr1_c1":"Thực thi 100% không cần Root","tr1_c2":"Thất bại với Permission denied","tr1_c3":"Yêu cầu máy đã mở khóa/root","tr1_c4":"Không thể thực thi","tr2_c0":"$PWD thư mục dùng chung","tr2_c1":"Chạy &amp; đồng bộ trực tiếp trong thư mục dự án","tr2_c2":"Bị chặn bởi phân vùng noexec","tr2_c3":"Ghi toàn hệ thống đầy rủi ro","tr2_c4":"Chỉ chỉnh sửa văn bản","tr3_c0":"Cờ CLI &amp; Stdin","tr3_c1":"Chỉ thị # @args + Console read -p trực tiếp","tr3_c2":"Gõ lệnh thủ công mỗi lần","tr3_c3":"Chạy nền không tương tác","tr3_c4":"Không có","tr4_c0":"Dự án đa script","tr4_c1":"source ./lib.sh + phân giải main.sh","tr4_c2":"cd &amp; gõ đường dẫn thủ công","tr4_c3":"Chỉ một script đơn lẻ","tr4_c4":"Không có","tr5_c0":"Định dạng script","tr5_c1":"Formatter Shell ngoại tuyến 1 chạm + AST","tr5_c2":"Chỉ soạn thô bằng nano / vi","tr5_c3":"Không có","tr5_c4":"Chỉ tô màu cú pháp","faq_lead":"Câu hỏi thường gặp về việc chạy script `.sh` không cần root và sửa lỗi `Permission denied` trên Android.","faq1_q":"Vì sao tôi bị lỗi `Permission denied` khi chạy tệp `.sh` từ thư mục Downloads trên Android?","faq1_a":"Để bảo mật, Android gắn bộ nhớ dùng chung (`/sdcard`, `Downloads`, `Documents`) với cờ hệ thống tệp `noexec`, nên ngay cả `chmod +x` cũng không thể đánh dấu tệp thực thi tại đó. SuperCode xử lý việc thực thi script sạch sẽ trong runtime native và tự động đồng bộ thư mục dự án của bạn.","faq2_q":"SuperCode có yêu cầu điện thoại Android đã root để chạy shell script không?","faq2_a":"Không. SuperCode hoạt động ngay trên các máy Android 8.0+ nguyên bản chưa root, điện thoại gập và máy tính bảng.","faq3_q":"Làm sao truyền tham số dòng lệnh như `./deploy.sh --env staging`?","faq3_a":"Thêm `# @args --env staging` ở gần đầu script (hoặc nhập tương tác qua `read -p`), và SuperCode sẽ truyền các tham số vị trí (`$1`, `$2`, `$@`) thẳng vào script khi Chạy.","faq4_q":"Script `.sh` có thể tạo tệp hoặc thư mục mới bên trong workspace của tôi không?","faq4_a":"Có. Mọi tệp, nhật ký hoặc gói nén được tạo tương đối theo `$PWD` trong khi chạy sẽ tự động đồng bộ ngược về thư mục dự án Android đang mở của bạn.","cta_h2":"Chạy script `.sh` nhẹ nhàng trên Android &#8212; Không cần Root.","cta_desc":"Tải miễn phí SuperCode IDE trên Google Play &#8212; chỉnh sửa, định dạng và thực thi shell script gọn gàng mọi lúc mọi nơi."},"sh_awk_sed_grep":{"metaTitle":"Linux awk, sed, grep & curl trên Android (+ Cloud GNU Bash 5.2) | SuperCode","metaDesc":"Chạy pipeline văn bản awk, sed, grep, sort, uniq, bc -l, curl, tar/gzip và sha256sum ngoại tuyến trên tệp thực tế ở Android — kèm Cloud Ubuntu GNU Bash 5.2 mượt mà cho declare -A và jq.","hero_tag":"AWK &#183; SED &#183; GREP &#183; CURL &#183; BC -L NGOẠI TUYẾN &#183; CLOUD UBUNTU BASH 5.2","hero_h1":"Làm chủ Pipeline Văn bản <span class=\"text-gradient\"><code>awk</code>, <code>sed</code>, <code>grep</code> &amp; Bash 5.2</span> trên Android.","hero_desc":"Biến log máy chủ thô và file CSV lộn xộn thành số liệu sạch ngay trên điện thoại. Kết nối pipeline <strong><code>awk</code>, <code>sed</code>, <code>grep</code>, <code>sort</code>, <code>uniq</code>, <code>bc -l</code>, <code>tar</code> và <code>sha256sum</code></strong> ngoại tuyến đồng bộ với thư mục dự án &#8212; kèm chuyển tự động sang <strong>Ubuntu GNU Bash 5.2</strong> cho <code>declare -A</code> và <code>jq</code>.","sas_s1":"&amp; grep -E Ngoại tuyến","sas_s2":"Tính số thực &amp; curl","sas_s3":"tar &#183; gzip &#183; base64","sas_s4":"declare -A &amp; jq","wb_eyebrow":"BÀN LÀM VIỆC PIPELINE VĂN BẢN LINUX &amp; GNU BASH 5.2 TƯƠNG TÁC","sec_cap_title":"Sức mạnh Xử lý Dữ liệu Unix Kinh điển Trong IDE Tối ưu Cảm ứng","sec_cap_lead":"Sao phải viết 80 dòng code rườm rà khi một pipeline 5 dòng `grep | sed | awk | sort` có thể phân tích file log chỉ trong vài mili-giây?","f1_title":"Động cơ Luồng awk, sed &amp; grep / egrep Ngoại tuyến","f1_desc":"Trích xuất nhóm bắt regex bằng sed -E, tính tổng và trung bình theo nhóm bằng awk, lọc log có cấu trúc qua grep -E, cut, tr, head, tail và column &#8212; 100% ngoại tuyến.","f1_badge":"awk &#183; sed -E &#183; grep -E &#183; cut &#183; tr &#183; column","f2_title":"Pipe Tổng hợp &amp; Tính toán Chính xác bc -l","f2_desc":"Xếp hạng tần suất với sort -nr | uniq -c | wc -l, ghi luồng trung gian ra ổ đĩa bằng tee, và tính tỷ lệ phần trăm hay độ trễ dấu phẩy động ngoại tuyến qua bc -l.","f2_badge":"sort &#183; uniq -c &#183; wc &#183; tee &#183; Toán bc -l","f3_title":"find, xargs, tar/gzip, curl &amp; Công cụ Checksum","f3_desc":"Xử lý hàng loạt cây thư mục lồng nhau bằng find và xargs, nén snapshot qua tar và gzip, mã hóa token với base64, kiểm tra mã băm bằng sha256sum/md5sum và kiểm thử endpoint với curl.","f3_badge":"find &#183; xargs &#183; tar/gzip &#183; sha256sum &#183; curl","f4_title":"Tự động Tăng tốc Cloud Ubuntu GNU Bash 5.2","f4_desc":"Đang dùng tính năng GNU Bash 5 như mảng kết hợp declare -A, bắt regex [[ $str =~ $pat ]], process substitution &lt;(...) hay cắt JSON bằng jq? SuperCode tự động định tuyến mượt mà lên Ubuntu Bash 5.2.","f4_badge":"Ubuntu GNU Bash 5.2 &#183; declare -A &#183; [[ =~ ]] &#183; jq","f5_title":"Kết nối Thẳng Tới Trình Phân trang File GB &amp; SQL Studio","f5_desc":"Cắt file dump máy chủ khổng lồ bằng awk/sed thành file .csv gọn gàng, rồi chạm vào file CSV đó trong Explorer để tự động nhập và truy vấn bằng Window Functions ngay trong SQL Studio của SuperCode.","f5_badge":"Log -&gt; CSV awk -&gt; Pipeline SQL Studio Ngoại tuyến","f6_title":"Chia đôi Tablet 55:45 &amp; Thanh Ký tự Thân thiện Pipe","f6_desc":"Chèn |, &gt;, &gt;&gt;, 2&gt;&amp;1, $1 và dấu nháy đơn/kép chỉ với một chạm mà không cần xoay xở bàn phím, đồng thời xem bảng kết quả rộng rõ nét ở chế độ ngang 55:45.","f6_badge":"Phím | &amp;&amp; 2&gt;&amp;1 1 Chạm &#183; Thu phóng Console 7sp&#8211;26sp","workflow_title":"Cách Phân tích Log &amp; CSV Bằng Shell Pipeline trên Android","workflow_lead":"Quy trình xử lý dữ liệu tái sử dụng, viết thành script và lưu ngay cùng tệp dự án của bạn.","wf1_title":"Đặt File `.log`, `.csv` hoặc `.json` Thô Vào Thư mục","wf1_desc":"Mở bất kỳ thư mục dự án nào chứa bản dump log hoặc tập dữ liệu &#8212; các tệp đi kèm được gắn tự động theo đường dẫn tương đối `$PWD`.","wf2_title":"Soạn Pipe Nhiều Chặng Với Hoàn tác &amp; Định dạng Đầy đủ","wf2_desc":"Khác với dòng lệnh terminal một dòng dễ gõ nhầm, hãy chỉnh sửa pipeline nhiều dòng nối `\\\\` trong trình soạn thảo code thực thụ có tô sáng cú pháp.","wf3_title":"Chạy Cục bộ Ngoại tuyến Hoặc Bật GNU Bash 5.2","wf3_desc":"Thực thi các pipeline POSIX chuẩn ngoại tuyến trong mili-giây, hoặc chạy script `declare -A` và `jq` mượt mà trên Ubuntu Bash 5.2.","wf4_title":"Kiểm tra Báo cáo, Kho nén &amp; Checksum Đã Đồng bộ","wf4_desc":"Mọi tệp CSV được chuyển hướng, kho lưu trữ `.tar.gz` hay bảng kê checksum đều xuất hiện ngay lập tức trong cây tệp workspace.","wf_foot_note":"Tiện ích POSIX Ngoại tuyến + Cloud Ubuntu GNU Bash 5.2 &#183; Tự động Đồng bộ Workspace","table_h2":"SuperCode Text Pipeline Studio so với Giải pháp Shell Di động Khác","snippet_p":"<strong>SuperCode Linux Pipeline Studio</strong> mang khả năng viết script <code>awk</code>, <code>sed</code>, <code>grep</code>, <code>sort</code>, <code>uniq</code>, <code>cut</code>, <code>tr</code>, <code>bc -l</code>, <code>curl</code>, <code>tar</code>, <code>gzip</code> và <code>sha256sum</code> ngoại tuyến lên Android kèm đồng bộ thư mục dự án tự động, cùng thực thi Cloud Ubuntu GNU Bash 5.2 mượt mà cho mảng kết hợp và <code>jq</code>.","table_caption":"BẢNG SO SÁNH XỬ LÝ VĂN BẢN LINUX &amp; BASH 5.2 TRÊN ANDROID","th_0":"Tính năng Pipeline","th_1":"SuperCode Shell Studio","th_2":"Shell Android Mặc định","th_3":"Trình biên dịch Bash Online","th_4":"Terminal CLI Thủ công","tr1_c0":"awk / sed / grep ngoại tuyến","tr1_c1":"Thực thi Đồng bộ Toàn bộ Workspace","tr1_c2":"Bị chặn trên bộ nhớ dùng chung","tr1_c3":"Yêu cầu Internet","tr1_c4":"Cần tự cài đặt gói","tr2_c0":"Toán học, Hash &amp; Nén","tr2_c1":"bc -l, sha256sum, md5sum, base64, tar/gzip","tr2_c2":"Chỉ có một phần nhỏ","tr2_c3":"Container tạm thời","tr2_c4":"Có hỗ trợ","tr3_c0":"GNU Bash 5.2 (declare -A)","tr3_c1":"Tự động chuyển sang Ubuntu GNU Bash 5.2 + jq","tr3_c2":"Không hỗ trợ (mksh)","tr3_c3":"Chỉ hỗ trợ một tệp đơn","tr3_c4":"Phải cài thủ công","tr4_c0":"Sửa Script Nhiều dòng","tr4_c1":"Trình sửa AST Đầy đủ + Định dạng Shell 1 Chạm","tr4_c2":"Không có trình soạn thảo","tr4_c3":"Ô nhập web cơ bản","tr4_c4":"vi/nano nhỏ trên terminal","tr5_c0":"Phân tích Tiếp theo","tr5_c1":"Tích hợp Phân trang File GB &amp; SQL Studio","tr5_c2":"Không có","tr5_c3":"Không có","tr5_c4":"Phải dùng công cụ rời","faq_lead":"Giải đáp về `awk`, `sed`, `grep`, `bc -l`, `curl` và khả năng tương thích GNU Bash 5.2 trên Android.","faq1_q":"`awk`, `sed`, `grep`, `sort` và `sha256sum` có chạy ngoại tuyến không cần mạng không?","faq1_a":"Có! Các pipeline văn bản, nén và checksum chuẩn POSIX (`awk`, `sed`, `grep`, `egrep`, `sort`, `uniq`, `wc`, `cut`, `tr`, `find`, `xargs`, `tar`, `gzip`, `base64`, `md5sum`, `sha256sum`, `bc -l`) chạy cục bộ ngoại tuyến ngay trên thiết bị của bạn.","faq2_q":"Vì sao mảng kết hợp `declare -A` bị lỗi trên shell mặc định của Android và SuperCode xử lý thế nào?","faq2_a":"Shell hệ thống tích hợp trên Android dựa trên POSIX/`mksh` chứ không phải GNU Bash 5. Khi SuperCode phát hiện cú pháp đặc thù của Bash (`#!/usr/bin/env bash` kèm `declare -A`, `[[ =~ ]]`, `mapfile` hoặc `jq`) hay `# @cloud`, hệ thống tự động chạy script trên Ubuntu GNU Bash 5.2.","faq3_q":"Script `awk` hoặc `sed` của tôi có thể đọc file `.csv` cục bộ và lưu thành file mới không?","faq3_a":"Có. Đường dẫn đầu vào tương đối và chuyển hướng đầu ra (`&gt; cleaned.csv` hoặc `| tee out.txt`) thao tác trực tiếp trên workspace và đồng bộ ngay các file mới tạo về thư mục Android của bạn.","faq4_q":"Nếu file log thô của máy chủ nặng hơn 1 GB thì sao?","faq4_a":"Hãy mở trực tiếp các file log nhiều gigabyte trong Trình soạn thảo Tệp lớn phân trang trên đĩa của SuperCode để duyệt mượt không giật lag và Thay thế Regex Luồng Toàn cục!","cta_h2":"Chạy Pipeline `awk`, `sed` &amp; Bash 5.2 Thực thụ trên Android.","cta_desc":"Tải SuperCode IDE miễn phí trên Google Play &#8212; công cụ văn bản POSIX ngoại tuyến, Ubuntu Bash 5.2 và phân trang log GB."},"sh_kotlin_ide":{"metaTitle":"Ứng dụng Lập trình Kotlin & Trình biên dịch .kt / .kts cho Android — OOP & DSA | SuperCode","metaDesc":"Viết, định dạng và biên dịch Kotlin (.kt và .kts) trên điện thoại hoặc máy tính bảng Android. Trang bị gợi ý AST ngoại tuyến, thanh 21 phím -> / ?: / ?., định dạng Kotlin 1 chạm, stdin nhiều dòng và thực thi nhanh.","hero_tag":"TRÌNH BIÊN DỊCH KOTLIN .KT &amp; .KTS &#183; AST &amp; ĐỊNH DẠNG NGOẠI TUYẾN &#183; THANH 21 PHÍM KÝ TỰ","hero_h1":"Ứng dụng <span class=\"text-gradient\">Lập trình Kotlin &amp; Trình biên dịch <code>.kt</code></span> Hiện đại cho Android.","hero_desc":"Luyện tập <strong>Kotlin OOP chuẩn mực, mô hình <code>data class</code>, phân cấp <code>sealed interface</code> và thuật toán phỏng vấn DSA</strong> mà không cần mang theo laptop 16 GB. Trải nghiệm <strong>gợi ý AST Kotlin ngoại tuyến</strong>, <strong>định dạng Kotlin 1 chạm</strong>, <strong>phím nhanh <code>-&gt;</code> / <code>?:</code> / <code>?.</code></strong> và biên dịch cloud tốc độ cao.","skt_s1":"Trình biên dịch Kotlin","skt_s2":"Thanh 21 phím Kotlin","skt_s3":"Định dạng Ngoại tuyến","skt_s4":"Thanh DSA Nhiều dòng","wb_eyebrow":"BÀN LÀM VIỆC KOTLIN OOP, COLLECTIONS DSA &amp; .KTS TƯƠNG TÁC","sec_cap_title":"Thiết kế Riêng cho Lập trình viên Android, Sinh viên CNTT &amp; Ôn Phỏng vấn Kotlin","sec_cap_lead":"Gõ các toán tử null-safety và lambda giàu biểu cảm của Kotlin trên bàn phím di động mặc định rất chậm &#8212; hồ sơ Kotlin tối ưu cảm ứng của SuperCode thay đổi hoàn toàn điều đó.","f1_title":"Biên dịch Kotlin Hiện đại (.kt &amp; .kts) Gọn gàng","f1_desc":"Chạy chương trình main() độc lập và script .kts dùng data class, value class, sealed interface, object singleton, extension function, generics, destructuring và biểu thức when bao quát hết nhánh.","f1_badge":"data class &#183; sealed interface &#183; Extension Functions","f2_title":"Collections Hàm, Sequences &amp; Lambdas","f2_desc":"Giải bài toán cấu trúc dữ liệu và lập trình hàm chuẩn chỉnh với mapNotNull, groupBy, associateBy, windowed, fold, bộ tạo lazy sequence { yield() } và tham chiếu hàm ::.","f2_badge":"Kotlin Collections &#183; Lazy sequence {} &#183; Tham chiếu ::","f3_title":"Thanh 21 Phím Ký tự Kotlin (-&gt;, ?:, ?., ::, {})","f3_desc":"Chèn mũi tên lambda (-&gt;), toán tử Elvis (?:), safe call (?.), tham chiếu phương thức (::), mẫu chuỗi (${}) và dấu ngoặc nhọn chỉ bằng một chạm qua hồ sơ bàn phím vuốt lên Kotlin của SuperCode.","f3_badge":"-&gt; &#183; ?: &#183; ?. &#183; :: &#183; ${} &#183; Không còn tìm phím","f4_title":"Tự động Hoàn thành AST Kotlin Ngoại tuyến &amp; Hỗ trợ .gradle.kts","f4_desc":"Chỉnh sửa tệp .kt, .kts và build.gradle.kts ngoại tuyến với gợi ý định danh và thư viện chuẩn theo AST, kết hợp tô sáng cú pháp sắc nét qua 8 giao diện studio tối và sáng.","f4_badge":".kt &#183; .kts &#183; .gradle.kts &#183; Gợi ý AST Ngoại tuyến","f5_title":"Thanh Stdin Nhiều dòng Ghim Cố định cho Kotlin DSA","f5_desc":"Đang luyện LeetCode, Codeforces hay phỏng vấn kỹ thuật bằng Kotlin? Giữ sẵn dữ liệu mẫu nhiều dòng cho readln() / readlnOrNull() trên thanh stdin và kiểm thử trường hợp biên cực nhanh.","f5_badge":"Ghim readln() Nhiều dòng &#183; Nhảy Dòng Lỗi 1:1","f6_title":"Định dạng Kotlin Ngoại tuyến 1 Chạm &amp; Quy trình Git/PDF","f6_desc":"Định dạng lớp Kotlin, chuỗi lambda trên collections và khối Gradle DSL 100% ngoại tuyến chỉ với một chạm &#8212; rồi đẩy repo DSA qua Visual Git hoặc xuất ghi chú học tập PDF A4.","f6_badge":"Định dạng Kotlin Ngoại tuyến &#183; Visual Git &#183; PDF A4","workflow_title":"Cách Luyện Kotlin &amp; Giải Bài tập DSA trên Android","workflow_lead":"Vòng phản hồi sửa-định dạng-biên dịch nhanh gọn, tối ưu cho điện thoại, máy gập và tablet.","wf1_title":"Tạo Tệp `.kt` hoặc `.kts` Trong Workspace","wf1_desc":"Sắp xếp các bài toán phỏng vấn hoặc thử nghiệm Kotlin thành từng thư mục gọn gàng &#8212; việc soạn thảo và định dạng hoạt động 100% ngoại tuyến.","wf2_title":"Viết Code An toàn Null &amp; Hàm Chuẩn Kotlin","wf2_desc":"Dùng phím 1 chạm `-&gt;`, `?:`, `?.` và `::` cùng gợi ý AST ngoại tuyến, sau đó chạm Định dạng để căn chỉnh các lambda thật gọn đẹp.","wf3_title":"Biên dịch &amp; Kiểm thử Với Đầu vào `readln()` Nhiều dòng","wf3_desc":"Nhập các bộ test mẫu vào thanh stdin ghim cố định rồi chạm Chạy &#9654; để biên dịch Kotlin trên cloud cực nhanh và chẩn đoán lỗi chính xác 1:1.","wf4_title":"Commit Lên GitHub Hoặc Đối chiếu Với Java 17 Ngoại tuyến","wf4_desc":"Đẩy bài giải Kotlin của bạn qua Visual Git, hoặc kiểm thử thuật toán JVM đi kèm hoàn toàn ngoại tuyến trong IDE Java 17 của SuperCode.","wf_foot_note":"Hỗ trợ .kt &#183; .kts &#183; .gradle.kts &#183; AST &amp; Định dạng Ngoại tuyến + Trình chạy Kotlin Cloud","table_h2":"SuperCode Kotlin Coding App so với Playground Web &amp; IDE Máy tính","snippet_p":"<strong>SuperCode Kotlin Coding Studio</strong> giúp lập trình viên Android và sinh viên viết, định dạng và biên dịch mã <code>.kt</code> và <code>.kts</code> trên điện thoại lẫn máy tính bảng. Ứng dụng kết hợp gợi ý AST Kotlin ngoại tuyến, thanh 21 phím ký tự chuyên biệt (<code>-&gt;</code>, <code>?:</code>, <code>?.</code>, <code>::</code>), định dạng Kotlin ngoại tuyến một chạm, thanh <code>stdin</code> nhiều dòng ghim cố định và Visual Git.","table_caption":"SO SÁNH HỌC &amp; LUYỆN KOTLIN TRÊN ANDROID","th_0":"Quy trình Kotlin","th_1":"SuperCode Kotlin Studio","th_2":"Kotlin Playground Web","th_3":"Trình soạn Di động Thuần","th_4":"Android Studio Máy tính","tr1_c0":"Trải nghiệm Gõ Di động","tr1_c1":"Thanh 21 phím (-&gt; ?: ?. ::) + AST Ngoại tuyến","tr1_c2":"Ô nhập trình duyệt chật hẹp","tr1_c3":"Không có thanh ký tự Kotlin","tr1_c4":"Bàn phím vật lý","tr2_c0":"Định dạng Mã nguồn","tr2_c1":"100% Ngoại tuyến 1 chạm Kotlin &amp; .gradle.kts","tr2_c2":"Chỉ dùng trực tuyến","tr2_c3":"Không có","tr2_c4":"Ngoại tuyến","tr3_c0":"Kiểm thử Stdin DSA","tr3_c1":"Thanh Stdin readln() Nhiều dòng Ghim Cố định","tr3_c2":"Hạn chế / nhập args thủ công","tr3_c3":"Không biên dịch được","tr3_c4":"Có hỗ trợ","tr4_c0":"Tệp Cục bộ &amp; Git","tr4_c1":"Cây Dự án Đầy đủ + Visual Git + PDF A4","tr4_c2":"Đoạn mã tạm đơn lẻ","tr4_c3":"Chỉ lưu tệp cục bộ","tr4_c4":"Tốn hơn 10 GB ổ đĩa &amp; RAM","tr5_c0":"JVM Ngoại tuyến Đi kèm","tr5_c1":"Tích hợp sẵn Java 17 + SQLite 100% Ngoại tuyến","tr5_c2":"Chỉ đoạn mã Kotlin","tr5_c3":"Không có","tr5_c4":"Đầy đủ SDK","faq_lead":"Các câu hỏi thường gặp về biên dịch tệp `.kt` / `.kts`, soạn thảo ngoại tuyến và đóng gói APK.","faq1_q":"Biên dịch Kotlin trong SuperCode có cần kết nối Internet không?","faq1_a":"Soạn thảo, tô sáng cú pháp, tự động hoàn thành AST, định dạng `.kt`/`.gradle.kts`, Visual Git và xuất PDF A4 đều hoạt động 100% ngoại tuyến. Riêng biên dịch và chạy mã `.kt` và `.kts` sử dụng trình biên dịch Kotlin cloud tốc độ cao của SuperCode (trong khi Java 17 biên dịch 100% ngoại tuyến ngay trên máy).","faq2_q":"Tôi có thể truyền dữ liệu test nhiều dòng cho `readln()` hoặc `Scanner` trong Kotlin không?","faq2_a":"Có! Hãy nhập hoặc dán bộ test nhiều dòng vào thanh nhập `stdin` ghim cố định của console trước khi chạm Chạy, giúp việc luyện thi lập trình và phỏng vấn trở nên nhẹ nhàng.","faq3_q":"SuperCode có build gói `.apk` Android Gradle đa module hoàn chỉnh không?","faq3_a":"SuperCode được thiết kế cho lập trình Kotlin độc lập (`.kt`/`.kts`), mô hình OOP, pipeline hàm, luyện DSA và chỉnh sửa tệp `.gradle.kts` qua Git &#8212; không dùng để đóng gói `.apk` Android SDK nặng nhiều gigabyte.","faq4_q":"Tôi có thể định dạng các tệp `build.gradle.kts` ngoại tuyến không?","faq4_a":"Có. Cả tệp mã nguồn `.kt`/`.kts` lẫn script Gradle Kotlin DSL `.gradle.kts` đều được trình tô sáng cú pháp và công cụ định dạng 1 chạm ngoại tuyến của SuperCode hỗ trợ.","cta_h2":"Luyện tập Kotlin Hiện đại Mọi nơi trên Android.","cta_desc":"Cài đặt SuperCode IDE miễn phí trên Google Play &#8212; trình chạy Kotlin .kt/.kts, thanh 21 phím ký tự, định dạng ngoại tuyến và Visual Git."},"sh_devops_sftp":{"metaTitle":"Ứng dụng Linux DevOps cho Android — Script .sh, SFTP (0755), Log GB & Git | SuperCode","metaDesc":"Xử lý tác vụ trực sự cố quản trị Linux & DevOps ngay trên Android. Chạy thử pipeline .sh cục bộ, xem log máy chủ nhiều GB, commit qua Visual Git và sửa script từ xa qua SFTP giữ nguyên quyền POSIX 0755.","hero_tag":"TRỰC SỰ CỐ LINUX DEVOPS &#183; LƯU ATOMIC SFTP 0755 &#183; PHÂN TRANG LOG GB &#183; VISUAL GIT","hero_h1":"<span class=\"text-gradient\">Trạm làm việc Linux DevOps</span> Bỏ túi: Shell, SFTP, Log GB &amp; Git.","hero_desc":"Ngừng chuyển qua lại giữa bốn ứng dụng di động rời rạc khi xảy ra sự cố. Chạy thử <strong>script <code>.sh</code></strong> cục bộ, kiểm tra <strong>log production nhiều GB</strong> không giật đơ, commit bản vá IaC trong <strong>Visual Git</strong> và lưu qua <strong>SFTP</strong> bằng cơ chế <strong>ghi atomic 3 pha giữ nguyên quyền POSIX <code>0755</code></strong>.","sdo_s1":"Giữ nguyên Quyền POSIX","sdo_s2":"SFTP Keystore SSH","sdo_s3":"Trình xem Log Phân trang","sdo_s4":"Visual Diff &amp; Push","wb_eyebrow":"BÀN LÀM VIỆC QUẢN TRỊ LINUX, SFTP &amp; LOG GB TÍCH HỢP","sec_cap_title":"Chế tạo cho SRE, Quản trị Hệ thống &amp; Kỹ sư Homelab Tự vận hành","sec_cap_lead":"Mọi chi tiết đều được gia cố trước mạng di động chập chờn, file log khổng lồ và rủi ro hỏng quyền truy cập trên máy chủ Linux từ xa.","f1_title":"Lưu SFTP Atomic 3 Pha Giữ nguyên POSIX 0755","f1_desc":"Lưu tệp /usr/local/bin/backup.sh đang chạy qua mạng di động chập chờn sẽ không làm cắt cụt script hay mất bit +x. SuperCode ghi vào tệp tạm, kiểm tra toàn vẹn, đổi tên atomic và giữ nguyên chuẩn quyền 0755/0644.","f1_badge":"Không bao giờ Ghi dở Cấu hình &#183; Giữ nguyên POSIX 0755","f2_title":"Kho khóa SSH AES-256 Phần cứng &amp; Danh bạ Host","f2_desc":"Kết nối máy chủ Ubuntu, Debian, Rocky hoặc Alpine qua SFTP, FTPS và FTP bằng khóa riêng tư SSH Ed25519/RSA mã hóa qua Android Keystore AES-256, hỗ trợ truyền song song và nối tiếp khi đứt mạng.","f2_badge":"Khóa Ed25519 / RSA &#183; Keystore AES-256 &#183; Nối tiếp Truyền tải","f3_title":"Chạy thử Logic .sh &amp; awk/sed Trước khi Triển khai","f3_desc":"Đừng bao giờ thử regex chưa kiểm chứng trên prod! Xác thực logic .sh, awk, sed, grep và set -euo pipefail cục bộ trên Android (hoặc Ubuntu GNU Bash 5.2) trước khi lưu ngược lên máy chủ.","f3_badge":"Chạy thử Sandbox Cục bộ &#183; Xác minh Bash 5.2","f4_title":"Phân trang Log Máy chủ Nhiều GB &amp; Ẩn dữ liệu Regex Luồng","f4_desc":"Tải bản dump Nginx, Docker hoặc systemd journal 2 GB và lướt các trang dữ liệu từ ổ đĩa ở 120Hz không tăng RAM đột biến &#8212; hoặc chạy Thay thế Regex Luồng Toàn cục để che bí mật trên toàn bộ tệp.","f4_badge":"Phân trang Tức thì GB+ &#183; Regex Luồng $1 &#183; 34 Bảng mã","f5_title":"Định dạng YAML, JSON, Dockerfile, Makefile &amp; Nginx","f5_desc":"Chỉnh sửa docker-compose.yml, manifest Kubernetes, playbook Ansible, Dockerfile, Makefile, TOML và tệp .env với tô sáng cú pháp, Error Radar và định dạng ngoại tuyến 1 chạm.","f5_badge":"YAML &#183; JSON &#183; Dockerfile &#183; Makefile &#183; .conf","f6_title":"Visual Git cho Kho mã Infrastructure-as-Code","f6_desc":"Giữ GitOps gọn gàng ngay từ điện thoại: xem unified diff tô màu từng dòng, stage từng hunk, xử lý xung đột gộp song song và push commit HTTPS/token lên GitHub, GitLab hoặc Gitea.","f6_badge":"Unified Diff Tô màu &#183; Phân nhánh &#183; Giải quyết Xung đột","workflow_title":"Quy trình Xử lý Sự cố Trực &amp; Cập nhật Cấu hình trên Android","workflow_lead":"Chẩn đoán, chạy thử, triển khai atomic và commit lên Git mà không cần mở bốn ứng dụng riêng lẻ.","wf1_title":"Kết nối Bằng Khóa SSH &amp; Kiểm tra Log Production","wf1_desc":"Mở máy chủ Linux trong SFTP Explorer và xem các tệp `.log` khổng lồ bằng Trình xem GB phân trang đĩa hoặc lọc từng phần bằng `grep`/`awk`.","wf2_title":"Sửa Hook Shell, Docker Compose hoặc Cấu hình Nginx","wf2_desc":"Chỉnh sửa tệp `.sh`, `.yml` hoặc `.conf` với trình định dạng ngoại tuyến và kiểm thử logic pipeline shell cục bộ trước khi tải lên.","wf3_title":"Xuất bản An toàn Qua SFTP Giữ nguyên Quyền 0755","wf3_desc":"Lưu thẳng về máy chủ từ xa &#8212; bước ghi tạm atomic ngăn ngừa ghi dở tệp và giữ trọn vẹn quyền thực thi `0755`.","wf4_title":"Commit Thay đổi Hạ tầng Vào Kho Git Của Bạn","wf4_desc":"Kiểm tra lại chính xác unified diff trong Visual Git và push commit vá nóng để production và mã nguồn luôn đồng bộ.","wf_foot_note":"APK Tất cả trong Một 40.2 MB &#183; SFTP + FTPS + Visual Git + Shell + Phân trang Log GB","table_h2":"SuperCode DevOps Workstation so với Bộ Ứng dụng Quản trị Rời rạc","snippet_p":"<strong>SuperCode Linux DevOps Workstation</strong> hợp nhất kiểm thử script <code>.sh</code> cục bộ, phân trang log máy chủ nhiều gigabyte, quản lý phiên bản Visual Git và chỉnh sửa từ xa SFTP trong một ứng dụng Android duy nhất. Quản trị viên có xác thực SSH Android Keystore AES-256, lưu từ xa atomic ba pha giữ nguyên quyền thực thi POSIX <code>0755</code> và định dạng YAML/Shell ngoại tuyến.","table_caption":"SO SÁNH CHUỖI CÔNG CỤ LINUX DEVOPS &amp; SYSADMIN DI ĐỘNG","th_0":"Tác vụ DevOps","th_1":"SuperCode IDE Tất cả trong Một","th_2":"Trình quản lý Tệp SFTP Cơ bản","th_3":"Chỉ có Terminal SSH","th_4":"Combo 4 Ứng dụng Rời rạc","tr1_c0":"Độ An toàn Khi Lưu Từ xa","tr1_c1":"Đổi tên Atomic 3 Pha + Giữ POSIX 0755","tr1_c2":"Ghi đè trực tiếp (cắt cụt khi rớt mạng)","tr1_c3":"Dùng file swp vim thủ công","tr1_c4":"Xuất/nhập tệp thủ công","tr2_c0":"Thử .sh Trước Triển khai","tr2_c1":"Chạy thử .sh Không Root Cục bộ + Cloud Bash 5.2","tr2_c2":"Không chạy được script","tr2_c3":"Chạy thẳng trên prod!","tr2_c4":"Bất tiện sao chép-dán","tr3_c0":"Log Prod Lớn 1GB+","tr3_c1":"Trình xem Phân trang Đĩa Tức thì + Regex Luồng","tr3_c2":"Đơ / văng ứng dụng","tr3_c3":"Chậm qua mạng di động","tr3_c4":"Lỗi khi tệp &gt;50 MB","tr4_c0":"Sửa Cấu hình IaC","tr4_c1":"Định dạng Shell, YAML, JSON &amp; Dockerfile Ngoại tuyến","tr4_c2":"Khung văn bản thuần","tr4_c3":"nano nhỏ trên terminal","tr4_c4":"Giao diện thiếu đồng nhất","tr5_c0":"Quản lý Phiên bản GitOps","tr5_c1":"Tích hợp Visual Git Diff, Merge &amp; Push","tr5_c2":"Không có","tr5_c3":"Chỉ có git CLI","tr5_c4":"Phải cài app Git riêng","faq_lead":"Giải đáp cho quản trị viên Linux, SRE và kỹ sư homelab dùng SuperCode trên Android.","faq1_q":"Chỉnh sửa script `.sh` từ xa qua SFTP có làm mất bit thực thi `chmod 0755` không?","faq1_a":"Không bao giờ. SuperCode kiểm tra sẵn chế độ POSIX hiện có của tệp từ xa trước khi lưu và bảo toàn `0755` (hoặc quyền tùy chỉnh) xuyên suốt quá trình đổi tên tạm atomic 3 pha.","faq2_q":"SuperCode bảo vệ khóa riêng tư SSH và mật khẩu SFTP của tôi bằng cách nào?","faq2_a":"Mọi thông tin đăng nhập SFTP/FTPS, hồ sơ máy chủ và khóa riêng tư SSH đã nhập (`Ed25519`, `RSA`, `ECDSA`) đều được mã hóa ngay trên thiết bị bằng lớp bảo vệ phần cứng Android Keystore AES-256.","faq3_q":"Điều gì xảy ra nếu sóng di động bị rớt giữa chừng khi đang lưu `nginx.conf`?","faq3_a":"Do SuperCode tải lên một tệp tạm trước và chỉ đổi tên atomic phía máy chủ sau khi xác minh truyền tải thành công, tệp `nginx.conf` đang chạy của bạn không bao giờ bị ghi dở hoặc trống rỗng.","faq4_q":"Tôi có thể kiểm tra tệp log máy chủ 1.5 GB tải từ SFTP mà không làm treo máy không?","faq4_a":"Có! Trình soạn thảo Tệp lớn của SuperCode nạp các tệp nhiều gigabyte theo từng trang từ ổ đĩa thay vì đưa toàn bộ vào RAM, kèm sẵn Thay thế Regex Luồng Toàn cục.","cta_h2":"Mang Trọn Bộ Studio Linux DevOps Trong Túi Quần.","cta_desc":"Tải SuperCode IDE miễn phí trên Google Play &#8212; lưu atomic SFTP, pipeline .sh cục bộ, phân trang log GB và Visual Git."}};
